(* Standalone Rocq/Coq 8.20.1 non-halting proof for BB(6) holdout 608:#121 / 797:#164
   Machine: 1RB0RE_1LC0LB_1RD0LB_1RF0LA_1RC---_0RA0LD
   Ported from Lean 4 (is_does_not_halt.lean) to BusyCoq Individual62 framework. *)

From BusyCoq Require Import Individual62.
From Coq Require Import String Bool List Lists.Streams Lia ZifyNat NArith ZArith PArith PeanoNat.
Import ListNotations.

Set Default Goal Selector "!".

(* ========================================================================= *)
(* Machine Definition & Primitive Step Infrastructure (Section 1)            *)
(* ========================================================================= *)

Definition tm : TM := TM_from_str "1RB0RE_1LC0LB_1RD0LB_1RF0LA_1RC---_0RA0LD".
Arguments tm _ : simpl never.

Notation "c --> c'" := (c -[ tm ]-> c') (at level 40).
Notation "c -->* c'" := (c -[ tm ]->* c') (at level 40).
Notation "c -->+ c'" := (c -[ tm ]->+ c') (at level 40).

Close Scope sym_scope.
Open Scope list_scope.
Open Scope bool_scope.
Open Scope N_scope.

Local Notation "'0inf'" := (const S0).

(* Compact binary-doubled nat fuel constants so proof terms stay tiny while vm_compute runs in O(fuel) *)
Fixpoint pow2_nat (d : nat) : nat :=
  match d with
  | 0%nat => 1%nat
  | S d' => (pow2_nat d' + pow2_nat d')%nat
  end.
Definition fuel_4 : nat := 4%nat.
Definition fuel_8 : nat := 8%nat.
Definition fuel_12 : nat := 12%nat.
Definition fuel_16 : nat := 16%nat.
Definition fuel_32 : nat := 32%nat.
Definition fuel_512 : nat := pow2_nat 9.
Definition fuel_1024 : nat := pow2_nat 10.
Definition fuel_2048 : nat := pow2_nat 11.
Definition fuel_4096 : nat := pow2_nat 12.
Definition fuel_16384 : nat := pow2_nat 14.

Ltac fast_simpl_tape :=
  try rewrite move_left_const;
  try rewrite move_right_const;
  cbn [move_left move_right Streams.hd Streams.tl Str_app].
Ltac fast_step :=
  (eapply evstep_step || eapply progress_step);
  [prove_step | fast_simpl_tape].
Ltac fast_finish :=
  lazymatch goal with
  | |- (?q1, _) -->* (?q2, _) =>
    constr_eq q1 q2; apply evstep_refl'; cbn [Streams.hd Streams.tl];
    repeat rewrite <- const_unfold; reflexivity
  | |- _ => finish_progress
  end.
Ltac fast_execute := intros; repeat (try solve [fast_finish]; fast_step).
Ltac fast_start_progress := eapply progress_intro; [prove_step | fast_simpl_tape]; fast_execute.

Inductive RMode := RM_A | RM_D.
Inductive LMode := LM_B | LM_C.
Inductive Mode := M_R (m : RMode) | M_L (m : LMode).

Definition StateX : Type := Mode * list bool * list bool.

Definition b2s (b : bool) : Sym := if b then S1 else S0.

Fixpoint to_side (xs : list bool) : side :=
  match xs with
  | [] => 0inf
  | b :: rest => b2s b >> to_side rest
  end.

Definition mkCfg (q : Q) (h : bool) (l r : list bool) : Q * tape :=
  (q, (to_side l, b2s h, to_side r)).

Definition pop (xs : list bool) : bool * list bool :=
  match xs with
  | [] => (false, [])
  | b :: rest => (b, rest)
  end.

Definition encode (s : StateX) : Q * tape :=
  match s with
  | (M_R RM_A, l, r) => mkCfg A (fst (pop r)) l (snd (pop r))
  | (M_R RM_D, l, r) => mkCfg D (fst (pop r)) l (snd (pop r))
  | (M_L LM_B, l, r) => mkCfg B (fst (pop l)) (snd (pop l)) r
  | (M_L LM_C, l, r) => mkCfg C (fst (pop l)) (snd (pop l)) r
  end.

Lemma encode_init : encode (M_R RM_A, [], []) = c0.
Proof. reflexivity. Qed.

Definition EqBits (a b : list bool) : Prop := to_side a = to_side b.

Lemma to_side_pop (xs : list bool) :
  to_side xs = b2s (fst (pop xs)) >> to_side (snd (pop xs)).
Proof.
  destruct xs as [|b rest]; [exact (const_unfold Sym S0) | reflexivity].
Qed.

Lemma eqBits_refl (a : list bool) : EqBits a a. Proof. reflexivity. Qed.
Lemma eqBits_symm {a b : list bool} (h : EqBits a b) : EqBits b a. Proof. symmetry; exact h. Qed.
Lemma eqBits_trans {a b c : list bool} (h1 : EqBits a b) (h2 : EqBits b c) : EqBits a c.
Proof. transitivity (to_side b); assumption. Qed.
Lemma eqBits_cons (x : bool) {a b : list bool} (h : EqBits a b) : EqBits (x :: a) (x :: b).
Proof. unfold EqBits in *; cbn; rewrite h; reflexivity. Qed.
Lemma eqBits_append_left (p : list bool) {a b : list bool} (h : EqBits a b) : EqBits (p ++ a) (p ++ b).
Proof. induction p as [|x xs ih]; [exact h | exact (eqBits_cons x ih)]. Qed.
Lemma eqBits_zero_nil : EqBits [false] [].
Proof. unfold EqBits; cbn; symmetry; exact (const_unfold Sym S0). Qed.
Lemma eqBits_pop {a b : list bool} (h : EqBits a b) :
  fst (pop a) = fst (pop b) /\ EqBits (snd (pop a)) (snd (pop b)).
Proof.
  unfold EqBits in *.
  rewrite (to_side_pop a), (to_side_pop b) in h.
  inversion h as [[Hhd Htl]].
  split; [destruct (fst (pop a)), (fst (pop b)); discriminate || reflexivity | reflexivity].
Qed.

Lemma encode_congr {m : Mode} {l1 l2 r1 r2 : list bool}
  (hl : EqBits l1 l2) (hr : EqBits r1 r2) :
  encode (m, l1, r1) = encode (m, l2, r2).
Proof.
  destruct m as [[|]|[|]];
  [ destruct (eqBits_pop hr) as [H1 H2]; unfold encode, mkCfg; rewrite H1, hl, H2; reflexivity
  | destruct (eqBits_pop hr) as [H1 H2]; unfold encode, mkCfg; rewrite H1, hl, H2; reflexivity
  | destruct (eqBits_pop hl) as [H1 H2]; unfold encode, mkCfg; rewrite H1, H2, hr; reflexivity
  | destruct (eqBits_pop hl) as [H1 H2]; unfold encode, mkCfg; rewrite H1, H2, hr; reflexivity ].
Qed.

Definition RPlus (s1 s2 : StateX) : Prop := encode s1 -->+ encode s2.
Definition RStar (s1 s2 : StateX) : Prop := encode s1 -->* encode s2.

Lemma rPlus_trans {a b c : StateX} (h1 : RPlus a b) (h2 : RPlus b c) : RPlus a c.
Proof. exact (progress_trans tm _ _ _ h1 h2). Qed.
Lemma rPlus_trans_star {a b c : StateX} (h1 : RPlus a b) (h2 : RStar b c) : RPlus a c.
Proof. exact (progress_evstep_trans tm _ _ _ h1 h2). Qed.
Lemma rStar_trans_plus {a b c : StateX} (h1 : RStar a b) (h2 : RPlus b c) : RPlus a c.
Proof. exact (evstep_progress_trans tm _ _ _ h1 h2). Qed.
Lemma rStar_trans {a b c : StateX} (h1 : RStar a b) (h2 : RStar b c) : RStar a c.
Proof. exact (evstep_trans tm _ _ _ h1 h2). Qed.
Lemma rStar_refl (a : StateX) : RStar a a. Proof. apply evstep_refl. Qed.
Lemma rPlus_to_star {a b : StateX} (h : RPlus a b) : RStar a b.
Proof. exact (progress_evstep tm _ _ h). Qed.

Lemma rPlus_congr {m1 m2 : Mode} {l1 l1' r1 r1' l2 l2' r2 r2' : list bool}
  (hl1 : EqBits l1 l1') (hr1 : EqBits r1 r1') (hl2 : EqBits l2 l2') (hr2 : EqBits r2 r2')
  (h : RPlus (m1, l1', r1') (m2, l2', r2')) : RPlus (m1, l1, r1) (m2, l2, r2).
Proof. unfold RPlus in *; rewrite (encode_congr hl1 hr1), (encode_congr hl2 hr2); exact h. Qed.

Lemma rStar_congr {m1 m2 : Mode} {l1 l1' r1 r1' l2 l2' r2 r2' : list bool}
  (hl1 : EqBits l1 l1') (hr1 : EqBits r1 r1') (hl2 : EqBits l2 l2') (hr2 : EqBits r2 r2')
  (h : RStar (m1, l1', r1') (m2, l2', r2')) : RStar (m1, l1, r1) (m2, l2, r2).
Proof. unfold RStar in *; rewrite (encode_congr hl1 hr1), (encode_congr hl2 hr2); exact h. Qed.

Lemma rPlus_congr_L {m : Mode} {l1 l2 r : list bool} {s' : StateX}
  (hEq : EqBits l1 l2) (h : RPlus (m, l2, r) s') : RPlus (m, l1, r) s'.
Proof. unfold RPlus in *; rewrite (encode_congr hEq (eqBits_refl _)); exact h. Qed.

Lemma rStar_congr_L {m : Mode} {l1 l2 r : list bool} {s' : StateX}
  (hEq : EqBits l1 l2) (h : RStar (m, l2, r) s') : RStar (m, l1, r) s'.
Proof. unfold RStar in *; rewrite (encode_congr hEq (eqBits_refl _)); exact h. Qed.

Lemma rPlus_congr_end {s1 : StateX} {m2 : Mode} {l2 l2' r2 r2' : list bool}
  (hL : EqBits l2 l2') (hR : EqBits r2 r2') (h : RPlus s1 (m2, l2', r2')) :
  RPlus s1 (m2, l2, r2).
Proof. unfold RPlus in *; rewrite (encode_congr hL hR); exact h. Qed.

(* 18 primitive atomic transitions *)
Lemma step_LB_nil (r : list bool) : RPlus (M_L LM_B, [], r) (M_R RM_D, [true], true :: r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop r); fast_start_progress. Qed.
Lemma step_LC_nil (r : list bool) : RPlus (M_L LM_C, [], r) (M_R RM_D, [true], r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop r); fast_start_progress. Qed.
Lemma step_LB_0 (l r : list bool) : RPlus (M_L LM_B, false :: l, r) (M_L LM_C, l, true :: r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop l); fast_start_progress. Qed.
Lemma step_LB_1 (l r : list bool) : RPlus (M_L LM_B, true :: l, r) (M_L LM_B, l, false :: r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop l); fast_start_progress. Qed.
Lemma step_LC_0 (l r : list bool) : RPlus (M_L LM_C, false :: l, r) (M_R RM_D, true :: l, r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop r); fast_start_progress. Qed.
Lemma step_LC_1 (l r : list bool) : RPlus (M_L LM_C, true :: l, r) (M_L LM_B, l, false :: r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop l); fast_start_progress. Qed.
Lemma step_RD_nil (l : list bool) : RPlus (M_R RM_D, l, []) (M_L LM_C, true :: false :: true :: l, [true]).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; fast_start_progress. Qed.
Lemma step_RD_00 (l r : list bool) : RPlus (M_R RM_D, l, false :: false :: r) (M_R RM_A, false :: true :: l, r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop r); fast_start_progress. Qed.
Lemma step_RD_01_0 (l r : list bool) : RPlus (M_R RM_D, false :: l, false :: true :: r) (M_L LM_B, l, false :: true :: false :: r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop l); fast_start_progress. Qed.
Lemma step_RD_01_1 (l r : list bool) : RPlus (M_R RM_D, true :: l, false :: true :: r) (M_R RM_D, true :: true :: false :: l, r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop r); fast_start_progress. Qed.
Lemma step_RD_10_0 (l r : list bool) : RPlus (M_R RM_D, false :: l, true :: false :: r) (M_L LM_B, l, false :: true :: false :: r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop l); fast_start_progress. Qed.
Lemma step_RD_10_1 (l r : list bool) : RPlus (M_R RM_D, true :: l, true :: false :: r) (M_R RM_D, true :: true :: false :: l, r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop r); fast_start_progress. Qed.
Lemma step_RD_11_0 (l r : list bool) : RPlus (M_R RM_D, false :: l, true :: true :: r) (M_L LM_B, l, false :: true :: true :: r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop l); fast_start_progress. Qed.
Lemma step_RD_11_1 (l r : list bool) : RPlus (M_R RM_D, true :: l, true :: true :: r) (M_L LM_B, true :: false :: l, false :: r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; fast_start_progress. Qed.
Lemma step_RA_00 (l r : list bool) : RPlus (M_R RM_A, l, false :: false :: r) (M_L LM_C, true :: l, true :: r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; fast_start_progress. Qed.
Lemma step_RA_01 (l r : list bool) : RPlus (M_R RM_A, l, false :: true :: r) (M_L LM_B, true :: l, false :: r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; fast_start_progress. Qed.
Lemma step_RA_100 (l r : list bool) : RPlus (M_R RM_A, l, true :: false :: false :: r) (M_R RM_D, true :: true :: false :: l, r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; rewrite (to_side_pop r); fast_start_progress. Qed.
Lemma step_RA_101 (l r : list bool) : RPlus (M_R RM_A, l, true :: false :: true :: r) (M_L LM_B, true :: false :: l, false :: r).
Proof. unfold RPlus, encode, mkCfg; cbn [pop fst snd to_side b2s]; fast_start_progress. Qed.

(* Short/empty R primitive steps derived via EqBits *)
Lemma step_RD_b0 (l : list bool) : RPlus (M_R RM_D, l, [false]) (M_R RM_A, false :: true :: l, []).
Proof.
  exact (rPlus_congr (eqBits_refl _) (eqBits_cons false (eqBits_symm eqBits_zero_nil))
    (eqBits_refl _) (eqBits_refl _) (step_RD_00 l [])).
Qed.
Lemma step_RD_b1_1 (l : list bool) : RPlus (M_R RM_D, true :: l, [true]) (M_R RM_D, true :: true :: false :: l, []).
Proof.
  exact (rPlus_congr (eqBits_refl _) (eqBits_cons true (eqBits_symm eqBits_zero_nil))
    (eqBits_refl _) (eqBits_refl _) (step_RD_10_1 l [])).
Qed.
Lemma step_RD_b1_0 (l : list bool) : RPlus (M_R RM_D, false :: l, [true]) (M_L LM_B, l, [false; true]).
Proof.
  exact (rPlus_congr (eqBits_refl _) (eqBits_cons true (eqBits_symm eqBits_zero_nil))
    (eqBits_refl _) (eqBits_cons false (eqBits_cons true (eqBits_symm eqBits_zero_nil))) (step_RD_10_0 l [])).
Qed.
Lemma step_RA_nil (l : list bool) : RPlus (M_R RM_A, l, []) (M_L LM_C, true :: l, [true]).
Proof.
  exact (rPlus_congr (eqBits_refl _)
    (eqBits_trans (eqBits_symm eqBits_zero_nil) (eqBits_cons false (eqBits_symm eqBits_zero_nil)))
    (eqBits_refl _) (eqBits_refl _) (step_RA_00 l [])).
Qed.
Lemma step_RA_b0 (l : list bool) : RPlus (M_R RM_A, l, [false]) (M_L LM_C, true :: l, [true]).
Proof.
  exact (rPlus_congr (eqBits_refl _) (eqBits_cons false (eqBits_symm eqBits_zero_nil))
    (eqBits_refl _) (eqBits_refl _) (step_RA_00 l [])).
Qed.
Lemma step_RA_b1 (l : list bool) : RPlus (M_R RM_A, l, [true]) (M_R RM_D, true :: true :: false :: l, []).
Proof.
  exact (rPlus_congr (eqBits_refl _)
    (eqBits_cons true (eqBits_trans (eqBits_symm eqBits_zero_nil) (eqBits_cons false (eqBits_symm eqBits_zero_nil))))
    (eqBits_refl _) (eqBits_refl _) (step_RA_100 l [])).
Qed.
Lemma step_RA_b10 (l : list bool) : RPlus (M_R RM_A, l, [true; false]) (M_R RM_D, true :: true :: false :: l, []).
Proof.
  exact (rPlus_congr (eqBits_refl _) (eqBits_cons true (eqBits_cons false (eqBits_symm eqBits_zero_nil)))
    (eqBits_refl _) (eqBits_refl _) (step_RA_100 l [])).
Qed.

(* ========================================================================= *)
(* Section 2: Tokenized Engine (LTok / RTok), copy_id, and localGoTok        *)
(* ========================================================================= *)

Definition bitsA : list bool := [false; true].
Definition bitsB : list bool := [false; true; true; true].
Definition bitsC : list bool := [false; false; true; true; true].
Definition bitsAR : list bool := [false; true].
Definition bitsBR : list bool := [false; false; false; true].

Fixpoint bitsARn (m : nat) : list bool :=
  match m with
  | 0%nat => []
  | S m' => false :: true :: bitsARn m'
  end.

Lemma bitsARn_add (a b : nat) : bitsARn (a + b)%nat = bitsARn a ++ bitsARn b.
Proof.
  induction a as [|a ih]; [reflexivity | cbn [Nat.add bitsARn app]; rewrite ih; reflexivity].
Qed.

Lemma bitsARn_succ_r (k : nat) : bitsARn (S k) = bitsARn k ++ [false; true].
Proof.
  replace (S k) with (k + 1)%nat by lia.
  apply bitsARn_add.
Qed.

Fixpoint powBits (blk : list bool) (n : nat) : list bool :=
  match n with
  | 0%nat => []
  | S n' => blk ++ powBits blk n'
  end.

Lemma powBits_add (blk : list bool) (a b : nat) :
  powBits blk (a + b)%nat = powBits blk a ++ powBits blk b.
Proof.
  induction a as [|a ih]; [reflexivity | cbn [Nat.add powBits]; rewrite ih, app_assoc; reflexivity].
Qed.

Lemma powBits_comm_one (blk : list bool) (n : nat) :
  blk ++ powBits blk n = powBits blk n ++ blk.
Proof.
  induction n as [|n ih]; [cbn; rewrite app_nil_r; reflexivity |].
  cbn [powBits].
  rewrite <- app_assoc, <- ih, app_assoc; reflexivity.
Qed.

Lemma powBits_comm (blk : list bool) (m n : nat) :
  powBits blk m ++ powBits blk n = powBits blk n ++ powBits blk m.
Proof.
  rewrite <- !powBits_add; f_equal; lia.
Qed.

Definition powBitsN (blk : list bool) (n : N) : list bool := powBits blk (N.to_nat n).

Lemma powBitsN_zero (blk : list bool) : powBitsN blk 0 = [].
Proof. reflexivity. Qed.

Lemma powBitsN_one (blk : list bool) : powBitsN blk 1 = blk.
Proof. unfold powBitsN; cbn; apply app_nil_r. Qed.

Lemma powBitsN_add (blk : list bool) (a b : N) :
  powBitsN blk (a + b) = powBitsN blk a ++ powBitsN blk b.
Proof. unfold powBitsN; rewrite N2Nat.inj_add; apply powBits_add. Qed.

Lemma powBitsN_succ (blk : list bool) (n : N) :
  powBitsN blk (n + 1) = blk ++ powBitsN blk n.
Proof.
  replace (n + 1) with (1 + n) by lia.
  rewrite powBitsN_add, powBitsN_one; reflexivity.
Qed.

Lemma powBitsN_comm (blk : list bool) (m n : N) :
  powBitsN blk m ++ powBitsN blk n = powBitsN blk n ++ powBitsN blk m.
Proof. rewrite <- !powBitsN_add; f_equal; lia. Qed.

Inductive SymKind := S_P | S_Q3 | S_Q3_2 | S_R5 | S_W5 | S_Q8.

Definition symKind_eqb (a b : SymKind) : bool :=
  match a, b with
  | S_P, S_P | S_Q3, S_Q3 | S_Q3_2, S_Q3_2 | S_R5, S_R5 | S_W5, S_W5 | S_Q8, S_Q8 => true
  | _, _ => false
  end.

Lemma symKind_eqb_eq (a b : SymKind) : symKind_eqb a b = true <-> a = b.
Proof. destruct a, b; split; intro H; discriminate || reflexivity. Qed.

Definition blkBitsL (k : SymKind) : list bool :=
  match k with
  | S_P => bitsA ++ bitsB ++ bitsB
  | S_Q3 => bitsARn 3 ++ bitsB
  | S_Q3_2 => bitsARn 3 ++ bitsB ++ bitsARn 3 ++ bitsB
  | S_R5 => bitsARn 5 ++ bitsB ++ bitsA ++ bitsB
  | S_W5 => bitsB ++ bitsA ++ bitsB ++ bitsARn 3 ++ bitsB
  | S_Q8 => bitsARn 8 ++ bitsB
  end.

Definition blkBitsR (k : SymKind) : list bool :=
  match k with
  | S_P => bitsBR ++ bitsBR ++ bitsAR
  | S_Q3 => bitsBR ++ bitsARn 3
  | S_Q3_2 => bitsBR ++ bitsARn 3 ++ bitsBR ++ bitsARn 3
  | S_R5 => bitsBR ++ bitsAR ++ bitsBR ++ bitsARn 5
  | S_W5 => bitsBR ++ bitsARn 3 ++ bitsBR ++ bitsAR ++ bitsBR
  | S_Q8 => bitsBR ++ bitsARn 8
  end.

Inductive LTok :=
  | L_b0
  | L_b1
  | L_A (k : nat)
  | L_B
  | L_C
  | L_sym (k : SymKind) (v : bool).

Inductive RTok :=
  | R_b0
  | R_b1
  | R_AR (k : nat)
  | R_BR
  | R_sym (k : SymKind) (v : bool).

Fixpoint evalL (n0 n1 : N) (xs : list LTok) : list bool :=
  match xs with
  | [] => []
  | L_b0 :: rest => false :: evalL n0 n1 rest
  | L_b1 :: rest => true :: evalL n0 n1 rest
  | L_A k :: rest => bitsARn (S k) ++ evalL n0 n1 rest
  | L_B :: rest => bitsB ++ evalL n0 n1 rest
  | L_C :: rest => bitsC ++ evalL n0 n1 rest
  | L_sym k v :: rest => powBitsN (blkBitsL k) (if v then n1 else n0) ++ evalL n0 n1 rest
  end.

Fixpoint evalR (n0 n1 : N) (xs : list RTok) : list bool :=
  match xs with
  | [] => []
  | R_b0 :: rest => false :: evalR n0 n1 rest
  | R_b1 :: rest => true :: evalR n0 n1 rest
  | R_AR k :: rest => bitsARn (S k) ++ evalR n0 n1 rest
  | R_BR :: rest => bitsBR ++ evalR n0 n1 rest
  | R_sym k v :: rest => powBitsN (blkBitsR k) (if v then n1 else n0) ++ evalR n0 n1 rest
  end.

Lemma evalL_append (n0 n1 : N) (xs ys : list LTok) :
  evalL n0 n1 (xs ++ ys) = evalL n0 n1 xs ++ evalL n0 n1 ys.
Proof.
  induction xs as [|x xs ih]; [reflexivity |].
  destruct x; cbn [app evalL]; rewrite ?ih, ?app_assoc; reflexivity.
Qed.

Lemma evalR_append (n0 n1 : N) (xs ys : list RTok) :
  evalR n0 n1 (xs ++ ys) = evalR n0 n1 xs ++ evalR n0 n1 ys.
Proof.
  induction xs as [|x xs ih]; [reflexivity |].
  destruct x; cbn [app evalR]; rewrite ?ih, ?app_assoc; reflexivity.
Qed.

(* Elementary macro sweeps on bits *)
Lemma sweepLB_A (l r : list bool) :
  RPlus (M_L LM_B, bitsA ++ l, r) (M_L LM_B, l, bitsAR ++ r).
Proof. exact (rPlus_trans (step_LB_0 (true :: l) r) (step_LC_1 l (true :: r))). Qed.

Lemma sweepLB_ARn (k : nat) (l r : list bool) :
  RStar (M_L LM_B, bitsARn k ++ l, r) (M_L LM_B, l, bitsARn k ++ r).
Proof.
  revert r; induction k as [|k ih]; intro r; [apply rStar_refl |].
  change (bitsARn (S k) ++ l) with (bitsA ++ (bitsARn k ++ l)).
  pose proof (rPlus_to_star (sweepLB_A (bitsARn k ++ l) r)) as h1.
  pose proof (ih (bitsAR ++ r)) as h2.
  rewrite app_assoc in h2.
  replace (bitsARn k ++ bitsAR) with (bitsARn (S k)) in h2 by exact (bitsARn_succ_r k).
  exact (rStar_trans h1 h2).
Qed.

Lemma sweepLB_B (l r : list bool) :
  RPlus (M_L LM_B, bitsB ++ l, r) (M_L LM_B, l, bitsBR ++ r).
Proof.
  exact (rPlus_trans (step_LB_0 (true :: true :: true :: l) r)
    (rPlus_trans (step_LC_1 (true :: true :: l) (true :: r))
      (rPlus_trans (step_LB_1 (true :: l) (false :: true :: r))
        (step_LB_1 l (false :: false :: true :: r))))).
Qed.

Lemma sweepLB_C (l r : list bool) :
  RPlus (M_L LM_B, bitsC ++ l, r) (M_R RM_D, true :: true :: true :: true :: l, true :: r).
Proof.
  exact (rPlus_trans (step_LB_0 (false :: true :: true :: true :: l) r)
    (step_LC_0 (true :: true :: true :: l) (true :: r))).
Qed.

Lemma sweepLB_blk (k : SymKind) (l r : list bool) :
  RPlus (M_L LM_B, blkBitsL k ++ l, r) (M_L LM_B, l, blkBitsR k ++ r).
Proof.
  destruct k; unfold blkBitsL, blkBitsR; rewrite <- !app_assoc.
  - eapply rPlus_trans; [apply sweepLB_A |]; eapply rPlus_trans; [apply sweepLB_B | apply sweepLB_B].
  - eapply rStar_trans_plus; [apply (sweepLB_ARn 3) | apply sweepLB_B].
  - eapply rStar_trans_plus; [apply (sweepLB_ARn 3) |]; eapply rPlus_trans; [apply sweepLB_B |];
    eapply rStar_trans_plus; [apply (sweepLB_ARn 3) | apply sweepLB_B].
  - eapply rStar_trans_plus; [apply (sweepLB_ARn 5) |]; eapply rPlus_trans; [apply sweepLB_B |];
    eapply rPlus_trans; [apply sweepLB_A | apply sweepLB_B].
  - eapply rPlus_trans; [apply sweepLB_B |]; eapply rPlus_trans; [apply sweepLB_A |];
    eapply rPlus_trans; [apply sweepLB_B |]; eapply rStar_trans_plus; [apply (sweepLB_ARn 3) | apply sweepLB_B].
  - eapply rStar_trans_plus; [apply (sweepLB_ARn 8) | apply sweepLB_B].
Qed.

Lemma sweepLB_powBlk (k : SymKind) (n : nat) (l r : list bool) :
  RStar (M_L LM_B, powBits (blkBitsL k) n ++ l, r) (M_L LM_B, l, powBits (blkBitsR k) n ++ r).
Proof.
  revert r; induction n as [|n ih]; intro r; [apply rStar_refl |].
  cbn [powBits]; rewrite <- app_assoc.
  eapply rStar_trans; [exact (rPlus_to_star (sweepLB_blk k _ r)) |].
  pose proof (ih (blkBitsR k ++ r)) as h2.
  rewrite app_assoc, <- powBits_comm_one in h2.
  exact h2.
Qed.

Lemma sweepLB_powBlkN (k : SymKind) (n : N) (l r : list bool) :
  RStar (M_L LM_B, powBitsN (blkBitsL k) n ++ l, r) (M_L LM_B, l, powBitsN (blkBitsR k) n ++ r).
Proof. apply sweepLB_powBlk. Qed.

Lemma sweepRD_ARn (k : nat) (l r : list bool) :
  RStar (M_R RM_D, true :: l, bitsARn (S k) ++ r) (M_R RM_D, true :: true :: bitsARn k ++ false :: l, r).
Proof.
  revert l; induction k as [|k ih]; intro l.
  - exact (rPlus_to_star (step_RD_01_1 l r)).
  - change (bitsARn (S (S k)) ++ r) with (false :: true :: bitsARn (S k) ++ r).
    eapply rStar_trans; [exact (rPlus_to_star (step_RD_01_1 l (bitsARn (S k) ++ r))) |].
    pose proof (ih (true :: false :: l)) as h2.
    replace (bitsARn k ++ false :: true :: false :: l) with (bitsARn (S k) ++ false :: l) in h2
      by (rewrite bitsARn_succ_r, <- app_assoc; reflexivity).
    exact h2.
Qed.

Lemma sweepRD_ARn_any (m : nat) (l r : list bool) :
  RStar (M_R RM_D, true :: true :: l, bitsARn m ++ r) (M_R RM_D, true :: true :: bitsARn m ++ l, r).
Proof.
  destruct m as [|k]; [apply rStar_refl |].
  pose proof (sweepRD_ARn k (true :: l) r) as h.
  replace (bitsARn k ++ false :: true :: l) with (bitsARn (S k) ++ l) in h
    by (rewrite bitsARn_succ_r, <- app_assoc; reflexivity).
  exact h.
Qed.

Lemma sweepRD_1_ARn (k : nat) (l r : list bool) :
  RStar (M_R RM_D, true :: l, true :: bitsARn (S k) ++ r) (M_R RM_D, true :: true :: bitsARn k ++ false :: l, true :: r).
Proof.
  revert l; induction k as [|k ih]; intro l.
  - exact (rPlus_to_star (step_RD_10_1 l (true :: r))).
  - change (true :: bitsARn (S (S k)) ++ r) with (true :: false :: true :: bitsARn (S k) ++ r).
    eapply rStar_trans; [exact (rPlus_to_star (step_RD_10_1 l (true :: bitsARn (S k) ++ r))) |].
    pose proof (ih (true :: false :: l)) as h2.
    replace (bitsARn k ++ false :: true :: false :: l) with (bitsARn (S k) ++ false :: l) in h2
      by (rewrite bitsARn_succ_r, <- app_assoc; reflexivity).
    exact h2.
Qed.

Lemma step_1C_AR2 (rem r : list bool) :
  RPlus (M_L LM_B, true :: bitsC ++ rem, false :: false :: true :: false :: true :: r)
        (M_L LM_B, true :: bitsC ++ bitsB ++ rem, false :: r).
Proof.
  eapply rPlus_trans; [exact (step_LB_1 (bitsC ++ rem) _) |].
  eapply rPlus_trans; [exact (sweepLB_C rem _) |].
  eapply rPlus_trans; [exact (step_RD_10_1 _ _) |].
  eapply rPlus_trans; [exact (step_RD_00 _ _) |].
  exact (step_RA_101 (bitsB ++ bitsB ++ rem) r).
Qed.

Lemma sweepRD_1_ARn_BR (k : nat) (l r : list bool) :
  RPlus (M_R RM_D, true :: true :: true :: true :: l, true :: bitsARn k ++ bitsBR ++ r)
        (M_R RM_A, bitsB ++ bitsARn k ++ bitsB ++ l, true :: r).
Proof.
  destruct k as [|k'].
  - cbn [bitsARn app bitsBR bitsB].
    exact (rPlus_trans (step_RD_10_1 _ _) (step_RD_00 _ _)).
  - eapply rStar_trans_plus; [exact (sweepRD_1_ARn k' (true :: true :: true :: l) (bitsBR ++ r)) |].
    cbn [bitsBR app].
    eapply rPlus_trans; [exact (step_RD_10_1 _ _) |].
    pose proof (step_RD_00 (true :: true :: false :: true :: bitsARn k' ++ false :: true :: true :: true :: l) (true :: r)) as h2.
    exact h2.
Qed.

Lemma copy_step_B (k m : nat) (rem r' : list bool) :
  RPlus (M_L LM_B, true :: bitsB ++ bitsARn k ++ bitsC ++ rem, false :: bitsARn m ++ bitsBR ++ r')
        (M_L LM_B, true :: bitsB ++ bitsARn m ++ bitsC ++ bitsARn k ++ bitsB ++ rem, false :: r').
Proof.
  eapply rPlus_trans; [exact (step_LB_1 _ _) |].
  eapply rPlus_trans; [exact (sweepLB_B _ _) |].
  eapply rStar_trans_plus; [exact (sweepLB_ARn k _ _) |].
  eapply rPlus_trans; [exact (sweepLB_C rem _) |].
  change (bitsARn k ++ bitsBR ++ false :: false :: bitsARn m ++ bitsBR ++ r')
    with (bitsARn k ++ bitsBR ++ (false :: false :: bitsARn m ++ bitsBR ++ r')).
  eapply rPlus_trans; [exact (sweepRD_1_ARn_BR k rem _) |].
  eapply rPlus_trans; [exact (step_RA_100 _ _) |].
  change (true :: true :: false :: bitsB ++ bitsARn k ++ bitsB ++ rem)
    with (true :: true :: bitsC ++ bitsARn k ++ bitsB ++ rem).
  eapply rStar_trans_plus; [exact (sweepRD_ARn_any m (bitsC ++ bitsARn k ++ bitsB ++ rem) (bitsBR ++ r')) |].
  cbn [bitsBR app].
  eapply rPlus_trans; [exact (step_RD_00 _ _) |].
  exact (step_RA_01 (bitsB ++ bitsARn m ++ bitsC ++ bitsARn k ++ bitsB ++ rem) r').
Qed.

Lemma copy_base_A (k m : nat) (rem : list bool) :
  RPlus (M_L LM_B, true :: bitsB ++ bitsARn k ++ bitsC ++ rem, false :: bitsARn (S m))
        (M_L LM_B, true :: bitsC ++ bitsARn (S m) ++ bitsB ++ bitsARn k ++ bitsB ++ rem, []).
Proof.
  eapply rPlus_trans; [exact (step_LB_1 _ _) |].
  eapply rPlus_trans; [exact (sweepLB_B _ _) |].
  eapply rStar_trans_plus; [exact (sweepLB_ARn k _ _) |].
  eapply rPlus_trans; [exact (sweepLB_C rem _) |].
  eapply rPlus_trans; [exact (sweepRD_1_ARn_BR k rem (false :: false :: bitsARn (S m))) |].
  eapply rPlus_trans; [exact (step_RA_100 _ _) |].
  change (true :: true :: false :: bitsB ++ bitsARn k ++ bitsB ++ rem)
    with (true :: true :: bitsC ++ bitsARn k ++ bitsB ++ rem).
  pose proof (sweepRD_ARn_any (S m) (bitsC ++ bitsARn k ++ bitsB ++ rem) []) as h4.
  rewrite app_nil_r in h4.
  eapply rStar_trans_plus; [exact h4 |].
  eapply rPlus_trans; [exact (step_RD_nil _) |].
  change (true :: false :: true :: true :: true :: bitsARn (S m) ++ bitsC ++ bitsARn k ++ bitsB ++ rem)
    with (true :: bitsB ++ bitsARn (S m) ++ bitsC ++ bitsARn k ++ bitsB ++ rem).
  eapply rPlus_trans; [exact (step_LC_1 _ _) |].
  eapply rPlus_trans; [exact (sweepLB_B _ _) |].
  eapply rStar_trans_plus; [exact (sweepLB_ARn (S m) _ _) |].
  eapply rPlus_trans; [exact (sweepLB_C _ _) |].
  eapply rPlus_trans; [exact (sweepRD_1_ARn_BR (S m) (bitsARn k ++ bitsB ++ rem) [false; true]) |].
  pose proof (step_RA_101 (bitsB ++ bitsARn (S m) ++ bitsB ++ bitsARn k ++ bitsB ++ rem) []) as h8.
  exact (rPlus_congr (eqBits_refl _) (eqBits_refl _) (eqBits_refl _) (eqBits_symm eqBits_zero_nil) h8).
Qed.

Inductive ABWord := AB_A | AB_B.

Fixpoint evalABL (xs : list ABWord) : list bool :=
  match xs with
  | [] => []
  | AB_A :: rest => bitsA ++ evalABL rest
  | AB_B :: rest => bitsB ++ evalABL rest
  end.

Fixpoint evalABR (xs : list ABWord) : list bool :=
  match xs with
  | [] => []
  | AB_A :: rest => bitsAR ++ evalABR rest
  | AB_B :: rest => bitsBR ++ evalABR rest
  end.

Lemma evalABL_append (a b : list ABWord) : evalABL (a ++ b) = evalABL a ++ evalABL b.
Proof. induction a as [|[|] xs ih]; cbn [app evalABL]; rewrite ?ih, <- ?app_assoc; reflexivity. Qed.

Lemma evalABR_append (a b : list ABWord) : evalABR (a ++ b) = evalABR a ++ evalABR b.
Proof. induction a as [|[|] xs ih]; cbn [app evalABR]; rewrite ?ih, <- ?app_assoc; reflexivity. Qed.

Fixpoint peelAs (xs : list ABWord) : nat * list ABWord :=
  match xs with
  | AB_A :: rest => let p := peelAs rest in (S (fst p), snd p)
  | _ => (0%nat, xs)
  end.

Lemma peelAs_spec (w : list ABWord) :
  evalABR w = bitsARn (fst (peelAs w)) ++ evalABR (snd (peelAs w)) /\
  evalABL (rev w) = evalABL (rev (snd (peelAs w))) ++ bitsARn (fst (peelAs w)) /\
  (length (snd (peelAs w)) <= length w)%nat /\
  (snd (peelAs w) = [] \/ exists rest, snd (peelAs w) = AB_B :: rest).
Proof.
  induction w as [|[|] xs [hR [hL [hlen hcase]]]].
  - cbn; repeat split; [lia | left; reflexivity].
  - cbn [peelAs fst snd evalABR rev].
    split; [rewrite hR; reflexivity |].
    split; [rewrite evalABL_append, hL; cbn [evalABL app]; rewrite <- app_assoc, <- bitsARn_succ_r; reflexivity |].
    split; [cbn [length]; lia | exact hcase].
  - cbn [peelAs fst snd bitsARn app].
    split; [reflexivity |].
    split; [rewrite app_nil_r; reflexivity |].
    split; [lia | right; exists xs; reflexivity].
Qed.

Lemma peelAs_endA (w u : list ABWord) (hu : w = u ++ [AB_A])
  (rest : list ABWord) (hrest : snd (peelAs w) = AB_B :: rest) :
  exists u', rest = u' ++ [AB_A].
Proof.
  revert u hu hrest; induction w as [|[|] xs ih]; intros u hu hrest.
  - destruct u; discriminate.
  - destruct u as [|a u'].
    + inversion hu; subst; discriminate.
    + inversion hu; subst; apply (ih u' eq_refl hrest).
  - cbn [peelAs snd] in hrest; inversion hrest; subst rest.
    destruct u as [|b u']; [discriminate | inversion hu; exists u'; reflexivity].
Qed.

Lemma copy_id_ab (w : list ABWord) (hw : exists u, w = u ++ [AB_A])
  (k : nat) (rem : list bool) :
  RPlus (M_L LM_B, true :: bitsB ++ bitsARn k ++ bitsC ++ rem, false :: evalABR w)
        (M_L LM_B, true :: bitsC ++ evalABL (rev w) ++ bitsB ++ bitsARn k ++ bitsB ++ rem, []).
Proof.
  assert (Hgen : forall (n : nat) (w0 : list ABWord),
    (length w0 <= n)%nat -> (exists u, w0 = u ++ [AB_A]) ->
    forall k0 rem0,
      RPlus (M_L LM_B, true :: bitsB ++ bitsARn k0 ++ bitsC ++ rem0, false :: evalABR w0)
            (M_L LM_B, true :: bitsC ++ evalABL (rev w0) ++ bitsB ++ bitsARn k0 ++ bitsB ++ rem0, [])).
  { induction n as [|n ih]; intros w0 hlen [u hu] k0 rem0.
    - subst w0; rewrite length_app in hlen; cbn in hlen; lia.
    - destruct (peelAs_spec w0) as [hR [hL [hplen [hnil | [rest hrest]]]]].
      + assert (hpos : (1 <= fst (peelAs w0))%nat).
        { destruct (fst (peelAs w0)) as [|m] eqn:Hm; [|lia].
          assert (Hne : evalABR w0 <> []) by (subst w0; rewrite evalABR_append; destruct (evalABR u); discriminate).
          rewrite hR, hnil in Hne; cbn in Hne; congruence. }
        destruct (fst (peelAs w0)) as [|m] eqn:Hm; [lia |].
        rewrite hR, hL, hnil; cbn [evalABR rev evalABL app]; rewrite app_nil_r.
        exact (copy_base_A k0 m rem0).
      + destruct (peelAs_endA w0 u hu rest hrest) as [u' hu'].
        assert (hrlen : (length rest <= n)%nat) by (rewrite hrest in hplen; cbn in hplen; lia).
        pose proof (copy_step_B k0 (fst (peelAs w0)) rem0 (evalABR rest)) as hstep.
        pose proof (ih rest hrlen (ex_intro _ u' hu') (fst (peelAs w0)) (bitsARn k0 ++ bitsB ++ rem0)) as hrec.
        rewrite hR, hL, hrest; cbn [evalABR rev]; rewrite evalABL_append; cbn [evalABL].
        rewrite ?app_nil_r; repeat rewrite <- app_assoc.
        exact (rPlus_trans hstep hrec). }
  exact (Hgen (length w) w (Nat.le_refl _) hw k rem).
Qed.

(* ========================================================================= *)
(* Section 2b: localGoTok Soundness                                          *)
(* ========================================================================= *)

Definition pushLA (k : nat) (xs : list LTok) : list LTok :=
  match xs with
  | L_A j :: rest => L_A (S k + j)%nat :: rest
  | _ => L_A k :: xs
  end.

Definition pushRAR (k : nat) (xs : list RTok) : list RTok :=
  match xs with
  | R_AR j :: rest => R_AR (S k + j)%nat :: rest
  | _ => R_AR k :: xs
  end.

Lemma evalL_pushLA (n0 n1 : N) (k : nat) (l : list LTok) :
  evalL n0 n1 (pushLA k l) = bitsARn (S k) ++ evalL n0 n1 l.
Proof.
  destruct l as [|[| |j| | | ] rest]; try reflexivity.
  cbn [pushLA evalL].
  rewrite app_assoc, <- bitsARn_add; f_equal; f_equal; lia.
Qed.

Lemma evalR_pushRAR (n0 n1 : N) (k : nat) (r : list RTok) :
  evalR n0 n1 (pushRAR k r) = bitsARn (S k) ++ evalR n0 n1 r.
Proof.
  destruct r as [|[| |j| | ] rest]; try reflexivity.
  cbn [pushRAR evalR].
  rewrite app_assoc, <- bitsARn_add; f_equal; f_equal; lia.
Qed.

Definition pushL0 (allowEmpty : bool) (l : list LTok) : list LTok :=
  match l with
  | [] => if allowEmpty then [] else [L_b0]
  | L_b1 :: L_b1 :: L_b1 :: xs => L_B :: xs
  | L_b1 :: xs => pushLA 0 xs
  | L_B :: xs => L_C :: xs
  | xs => L_b0 :: xs
  end.

Definition pushR0 (r : list RTok) : list RTok :=
  match r with
  | R_b0 :: R_b0 :: R_b1 :: xs => R_BR :: xs
  | R_b1 :: xs => pushRAR 0 xs
  | xs => R_b0 :: xs
  end.

Lemma evalL_pushL0 {allowEmpty : bool} {n0 n1 : N} {l : list LTok} {lBot : list bool}
  (hBot : allowEmpty = true -> lBot = []) :
  EqBits (evalL n0 n1 (pushL0 allowEmpty l) ++ lBot) (false :: (evalL n0 n1 l ++ lBot)).
Proof.
  destruct l as [|t1 l1].
  - destruct allowEmpty; [rewrite (hBot eq_refl); exact (eqBits_symm eqBits_zero_nil) | apply eqBits_refl].
  - destruct t1; try apply eqBits_refl.
    destruct l1 as [|t2 l2]; [cbn; apply eqBits_refl |].
    destruct t2; try (cbn [pushL0]; rewrite evalL_pushLA; apply eqBits_refl).
    destruct l2 as [|t3 l3]; [cbn; apply eqBits_refl |].
    destruct t3; try (cbn [pushL0]; rewrite evalL_pushLA; apply eqBits_refl).
    apply eqBits_refl.
Qed.

Lemma evalR_pushR0 (n0 n1 : N) (r : list RTok) :
  evalR n0 n1 (pushR0 r) = false :: evalR n0 n1 r.
Proof.
  destruct r as [|t1 r1]; [reflexivity |].
  destruct t1; try reflexivity.
  - destruct r1 as [|t2 r2]; [reflexivity |].
    destruct t2; try reflexivity.
    destruct r2 as [|t3 r3]; [reflexivity |].
    destruct t3; reflexivity.
  - cbn [pushR0]; rewrite evalR_pushRAR; reflexivity.
Qed.

Definition popL0 (allowEmpty : bool) (l : list LTok) : option (list LTok) :=
  match l with
  | [] => if allowEmpty then Some [] else None
  | L_b0 :: xs => Some xs
  | L_A 0 :: xs => Some (L_b1 :: xs)
  | L_A (S k) :: xs => Some (L_b1 :: L_A k :: xs)
  | L_B :: xs => Some (L_b1 :: L_b1 :: L_b1 :: xs)
  | L_C :: xs => Some (L_b0 :: L_b1 :: L_b1 :: L_b1 :: xs)
  | _ => None
  end.

Lemma evalL_popL0 {allowEmpty : bool} {n0 n1 : N} {l l' : list LTok} {lBot : list bool}
  (hBot : allowEmpty = true -> lBot = []) (h : popL0 allowEmpty l = Some l') :
  EqBits (evalL n0 n1 l ++ lBot) (false :: (evalL n0 n1 l' ++ lBot)).
Proof.
  destruct l as [|[| |[|k]| | | ] xs]; cbn [popL0] in h; try discriminate.
  - destruct allowEmpty; [inversion h; subst l'; rewrite (hBot eq_refl); exact (eqBits_symm eqBits_zero_nil) | discriminate].
  - inversion h; subst l'; apply eqBits_refl.
  - inversion h; subst l'; apply eqBits_refl.
  - inversion h; subst l'; apply eqBits_refl.
  - inversion h; subst l'; apply eqBits_refl.
  - inversion h; subst l'; apply eqBits_refl.
Qed.

Inductive TStep :=
  | T_toR (m : bool) (l : list LTok) (r : list RTok)
  | T_toL (m : bool) (l : list LTok) (r : list RTok)
  | T_done (out : list LTok)
  | T_fail.

Fixpoint revRToLTok (r : list RTok) (acc : list LTok) : option (list LTok) :=
  match r with
  | [] => Some acc
  | R_AR k :: rest => revRToLTok rest (pushLA k acc)
  | R_BR :: rest => revRToLTok rest (L_B :: acc)
  | _ => None
  end.

Fixpoint abWordA (k : nat) : list ABWord :=
  match k with
  | 0%nat => [AB_A]
  | S k' => AB_A :: abWordA k'
  end.

Lemma evalABR_abWordA (k : nat) : evalABR (abWordA k) = bitsARn (S k).
Proof. induction k as [|k ih]; [reflexivity | cbn [abWordA evalABR bitsAR bitsARn]; rewrite ih; reflexivity]. Qed.

Lemma evalABL_abWordA_rev (k : nat) : evalABL (rev (abWordA k)) = bitsARn (S k).
Proof.
  induction k as [|k ih]; [reflexivity |].
  cbn [abWordA rev]; rewrite evalABL_append, ih; cbn [evalABL app].
  symmetry; apply bitsARn_succ_r.
Qed.

Lemma revRToLTok_spec {r : list RTok} {acc out : list LTok} (h : revRToLTok r acc = Some out) :
  exists w : list ABWord,
    evalR 0 0 r = evalABR w /\
    evalL 0 0 out = evalABL (rev w) ++ evalL 0 0 acc.
Proof.
  revert acc h; induction r as [|x xs ih]; intros acc h.
  - cbn in h; inversion h; subst out; exists ([] : list ABWord); split; reflexivity.
  - destruct x as [| |k| | ]; cbn [revRToLTok] in h; try discriminate.
    + destruct (ih _ h) as [w [hR hL]].
      exists (abWordA k ++ w); split.
      * cbn [evalR]; rewrite evalABR_append, evalABR_abWordA, hR; reflexivity.
      * rewrite rev_app_distr, evalABL_append, evalABL_abWordA_rev, hL, evalL_pushLA, <- !app_assoc; reflexivity.
    + destruct (ih _ h) as [w [hR hL]].
      exists (AB_B :: w); split.
      * cbn [evalR evalABR]; rewrite hR; reflexivity.
      * cbn [rev]; rewrite evalABL_append, hL; cbn [evalABL evalL]; rewrite <- !app_assoc; reflexivity.
Qed.

Fixpoint pushBs (k : nat) (rem : list LTok) (rRest : list RTok) : TStep :=
  match k with
  | 0%nat => T_toL false (L_b1 :: L_C :: rem) (R_b0 :: rRest)
  | 1%nat => T_toL false (L_b1 :: L_C :: rem) (R_b0 :: R_AR 0 :: rRest)
  | S (S k') => pushBs k' (L_B :: rem) rRest
  end.

Lemma pushBs_sound : forall (k : nat) (rem : list LTok) (rRest : list RTok) (lBot rBot : list bool),
  exists l' r',
    pushBs k rem rRest = T_toL false l' r' /\
    RStar (M_L LM_B, true :: bitsC ++ evalL 0 0 rem ++ lBot, false :: bitsARn k ++ evalR 0 0 rRest ++ rBot)
          (M_L LM_B, evalL 0 0 l' ++ lBot, evalR 0 0 r' ++ rBot).
Proof.
  fix ih 1; intros [|[|k']] rem rRest lBot rBot.
  - exists (L_b1 :: L_C :: rem), (R_b0 :: rRest); split; [reflexivity |].
    cbn [evalL evalR bitsARn app]; rewrite <- !app_assoc; apply rStar_refl.
  - exists (L_b1 :: L_C :: rem), (R_b0 :: R_AR 0 :: rRest); split; [reflexivity |].
    cbn [evalL evalR bitsARn app]; rewrite <- !app_assoc; apply rStar_refl.
  - destruct (ih k' (L_B :: rem) rRest lBot rBot) as [l' [r' [hEq hR]]].
    exists l', r'; split; [exact hEq |].
    pose proof (step_1C_AR2 (evalL 0 0 rem ++ lBot) (bitsARn k' ++ evalR 0 0 rRest ++ rBot)) as h1.
    cbn [evalL bitsARn app] in h1, hR |- *.
    repeat rewrite <- app_assoc in h1; repeat rewrite <- app_assoc in hR; repeat rewrite <- app_assoc.
    exact (rStar_trans (rPlus_to_star h1) hR).
Qed.

Definition finishLB (doCopy : bool) (l : list LTok) (r : list RTok) : TStep :=
  if doCopy then
    match l, r with
    | L_b1 :: L_B :: L_C :: rem, R_b0 :: rRest =>
        match revRToLTok rRest (L_B :: L_B :: rem) with
        | Some out => T_done out
        | None => T_toL false l r
        end
    | L_b1 :: L_B :: L_A k :: L_C :: rem, R_b0 :: rRest =>
        match revRToLTok rRest (L_B :: L_A k :: L_B :: rem) with
        | Some out => T_done out
        | None => T_toL false l r
        end
    | L_b1 :: L_C :: rem, R_b0 :: R_AR (S k) :: rRest =>
        pushBs k (L_B :: rem) rRest
    | _, _ => T_toL false l r
    end
  else T_toL false l r.

Fixpoint sweepLB (allowEmpty : bool) (l : list LTok) (r : list RTok) {struct l} : TStep :=
  match l with
  | [] => if allowEmpty then T_toR false [L_b1] (R_b1 :: r) else T_fail
  | L_A k :: l1 => sweepLB allowEmpty l1 (pushRAR k r)
  | L_B :: l1 => sweepLB allowEmpty l1 (R_BR :: r)
  | L_C :: l1 => T_toR false (L_b1 :: L_b1 :: L_b1 :: L_b1 :: l1) (R_b1 :: r)
  | L_b1 :: l1 => sweepLB allowEmpty l1 (pushR0 r)
  | L_b0 :: l1 =>
      match l1 with
      | [] => if allowEmpty then T_toR false [L_b1] (R_b1 :: r) else T_fail
      | L_b0 :: l2 => T_toR false (L_b1 :: l2) (R_b1 :: r)
      | L_b1 :: l2 => sweepLB allowEmpty l2 (pushRAR 0 r)
      | L_A 0 :: l2 => T_toR false (L_b1 :: L_b1 :: l2) (R_b1 :: r)
      | L_A (S k) :: l2 => T_toR false (L_b1 :: L_b1 :: L_A k :: l2) (R_b1 :: r)
      | L_B :: l2 => T_toR false (L_b1 :: L_b1 :: L_b1 :: L_b1 :: l2) (R_b1 :: r)
      | L_C :: l2 => T_toR false (L_b1 :: L_b0 :: L_b1 :: L_b1 :: L_b1 :: l2) (R_b1 :: r)
      | L_sym _ _ :: _ => T_fail
      end
  | L_sym _ _ :: _ => T_fail
  end.

Definition sweepLC (allowEmpty : bool) (l : list LTok) (r : list RTok) : TStep :=
  match l with
  | [] => if allowEmpty then T_toR false [L_b1] r else T_fail
  | L_b0 :: l1 => T_toR false (L_b1 :: l1) r
  | L_b1 :: l1 => sweepLB allowEmpty l1 (pushR0 r)
  | L_A 0 :: l1 => T_toR false (L_b1 :: L_b1 :: l1) r
  | L_A (S k) :: l1 => T_toR false (L_b1 :: L_b1 :: L_A k :: l1) r
  | L_B :: l1 => T_toR false (L_b1 :: L_b1 :: L_b1 :: L_b1 :: l1) r
  | L_C :: l1 => T_toR false (L_b1 :: L_b0 :: L_b1 :: L_b1 :: L_b1 :: l1) r
  | L_sym _ _ :: _ => T_fail
  end.

Fixpoint sweepR (allowEmpty doCopy : bool) (fuel : nat) (m : bool) (l : list LTok) (r : list RTok) : TStep :=
  match fuel with
  | 0%nat => T_fail
  | S f =>
      if m then
        match r with
        | R_BR :: r2 => T_toL true (L_b1 :: l) (R_b1 :: pushRAR 0 r2)
        | R_AR k :: r2 =>
            let rRem := match k with 0%nat => r2 | S k' => R_AR k' :: r2 end in
            finishLB doCopy (L_b1 :: l) (pushR0 rRem)
        | R_b0 :: R_b0 :: r2 => T_toL true (L_b1 :: l) (R_b1 :: r2)
        | R_b0 :: R_b1 :: r2 => finishLB doCopy (L_b1 :: l) (pushR0 r2)
        | R_b0 :: R_AR 0 :: r2 => T_toL true (L_b1 :: l) (R_b1 :: R_b1 :: r2)
        | R_b0 :: R_AR (S k) :: r2 => T_toL true (L_b1 :: l) (R_b1 :: R_b1 :: R_AR k :: r2)
        | R_b0 :: R_BR :: r2 => T_toL true (L_b1 :: l) (R_b1 :: R_b0 :: pushRAR 0 r2)
        | R_b1 :: R_b0 :: R_b0 :: r3 => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushL0 allowEmpty l) r3
        | R_b1 :: R_b0 :: R_b1 :: r3 => finishLB doCopy (L_b1 :: pushL0 allowEmpty l) (pushR0 r3)
        | R_b1 :: R_b0 :: R_AR 0 :: r3 => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushL0 allowEmpty l) (R_b1 :: r3)
        | R_b1 :: R_b0 :: R_AR (S k) :: r3 => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushL0 allowEmpty l) (R_b1 :: R_AR k :: r3)
        | R_b1 :: R_b0 :: R_BR :: r3 => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushL0 allowEmpty l) (R_b0 :: pushRAR 0 r3)
        | R_b1 :: R_AR 0 :: r3 => finishLB doCopy (L_b1 :: pushL0 allowEmpty l) (pushR0 r3)
        | R_b1 :: R_AR (S k) :: r3 => finishLB doCopy (L_b1 :: pushL0 allowEmpty l) (pushR0 (R_AR k :: r3))
        | R_b1 :: R_BR :: r3 => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushL0 allowEmpty l) (pushRAR 0 r3)
        | _ => T_fail
        end
      else
        match r with
        | R_BR :: r2 => finishLB doCopy (L_b1 :: pushL0 allowEmpty (L_b1 :: l)) (pushR0 r2)
        | R_AR k :: r2 =>
            match l with
            | L_b1 :: l1 =>
                match k with
                | 0%nat => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushL0 allowEmpty l1) r2
                | S k' => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushLA k' (pushL0 allowEmpty l1)) r2
                end
            | _ =>
                match popL0 allowEmpty l with
                | Some l' =>
                    let rRem := match k with 0%nat => r2 | S k' => R_AR k' :: r2 end in
                    finishLB doCopy l' (pushRAR 0 (pushR0 rRem))
                | None => T_fail
                end
            end
        | R_b0 :: R_b0 :: r2 => sweepR allowEmpty doCopy f true (pushL0 allowEmpty (L_b1 :: l)) r2
        | R_b0 :: R_b1 :: r2 =>
            match l with
            | L_b1 :: l1 => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushL0 allowEmpty l1) r2
            | _ =>
                match popL0 allowEmpty l with
                | Some l' => finishLB doCopy l' (pushRAR 0 (pushR0 r2))
                | None => T_fail
                end
            end
        | R_b0 :: R_AR 0 :: r2 => sweepR allowEmpty doCopy f true (pushL0 allowEmpty (L_b1 :: l)) (R_b1 :: r2)
        | R_b0 :: R_AR (S k) :: r2 => sweepR allowEmpty doCopy f true (pushL0 allowEmpty (L_b1 :: l)) (R_b1 :: R_AR k :: r2)
        | R_b0 :: R_BR :: r2 => T_toL true (L_b1 :: pushL0 allowEmpty (L_b1 :: l)) (R_b1 :: R_b1 :: r2)
        | R_b1 :: R_b0 :: r2 =>
            match l with
            | L_b1 :: l1 => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushL0 allowEmpty l1) r2
            | _ =>
                match popL0 allowEmpty l with
                | Some l' => finishLB doCopy l' (pushRAR 0 (pushR0 r2))
                | None => T_fail
                end
            end
        | R_b1 :: R_AR k :: r2 =>
            match l with
            | L_b1 :: l1 =>
                match k with
                | 0%nat => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushL0 allowEmpty l1) (R_b1 :: r2)
                | S k' => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushLA k' (pushL0 allowEmpty l1)) (R_b1 :: r2)
                end
            | _ =>
                match popL0 allowEmpty l with
                | Some l' =>
                    let rRem := match k with 0%nat => R_b1 :: r2 | S k' => R_b1 :: R_AR k' :: r2 end in
                    finishLB doCopy l' (pushRAR 0 (pushR0 rRem))
                | None => T_fail
                end
            end
        | R_b1 :: R_BR :: r2 =>
            match l with
            | L_b1 :: l1 => sweepR allowEmpty doCopy f false (L_b1 :: L_b1 :: pushL0 allowEmpty l1) (R_b0 :: pushRAR 0 r2)
            | _ =>
                match popL0 allowEmpty l with
                | Some l' => finishLB doCopy l' (pushRAR 0 (R_BR :: r2))
                | None => T_fail
                end
            end
        | R_b1 :: R_b1 :: r2 =>
            match l with
            | L_b1 :: l1 => finishLB doCopy (L_b1 :: pushL0 allowEmpty l1) (pushR0 r2)
            | _ =>
                match popL0 allowEmpty l with
                | Some l' => T_toL false l' (pushRAR 0 (R_b1 :: r2))
                | None => T_fail
                end
            end
        | _ => T_fail
        end
  end.

Definition stepToState (lBot rBot : list bool) (prefAB : list ABWord) (st : TStep) : option StateX :=
  match st with
  | T_toL false l r => Some (M_L LM_B, evalL 0 0 l ++ lBot, evalR 0 0 r ++ rBot)
  | T_toL true l r => Some (M_L LM_C, evalL 0 0 l ++ lBot, evalR 0 0 r ++ rBot)
  | T_toR false l r => Some (M_R RM_D, evalL 0 0 l ++ lBot, evalR 0 0 r ++ rBot)
  | T_toR true l r => Some (M_R RM_A, evalL 0 0 l ++ lBot, evalR 0 0 r ++ rBot)
  | T_done out => Some (M_L LM_B, true :: bitsC ++ blkBitsL S_P ++ evalABL prefAB ++ evalL 0 0 out, [])
  | T_fail => None
  end.

Lemma finishLB_sound {doCopy : bool} {l : list LTok} {r : list RTok}
  {lBot rBot : list bool} {prefAB : list ABWord} {s' : StateX}
  (hBot : doCopy = true -> lBot = [])
  (hr : doCopy = true -> rBot = evalABR (rev prefAB ++ [AB_B; AB_B; AB_A]))
  (h : stepToState lBot rBot prefAB (finishLB doCopy l r) = Some s') :
  RStar (M_L LM_B, evalL 0 0 l ++ lBot, evalR 0 0 r ++ rBot) s'.
Proof.
  destruct doCopy; [| cbn in h; inversion h; apply rStar_refl].
  rewrite (hBot eq_refl), (hr eq_refl) in h |- *; rewrite app_nil_r.
  assert (Hrefl : forall st0, st0 = T_toL false l r ->
    stepToState [] (evalABR (rev prefAB ++ [AB_B; AB_B; AB_A])) prefAB st0 = Some s' ->
    RStar (M_L LM_B, evalL 0 0 l, evalR 0 0 r ++ evalABR (rev prefAB ++ [AB_B; AB_B; AB_A])) s').
  { intros st0 Hst0 Hh; subst st0; cbn in Hh; inversion Hh; rewrite app_nil_r; apply rStar_refl. }
  unfold finishLB in h.
  destruct l as [|t1 l1]; [exact (Hrefl _ eq_refl h) |].
  destruct t1; try exact (Hrefl _ eq_refl h).
  destruct l1 as [|t2 l2]; [exact (Hrefl _ eq_refl h) |].
  destruct t2; try exact (Hrefl _ eq_refl h).
  - (* L_b1 :: L_B :: ... *)
    destruct l2 as [|t3 l3]; [exact (Hrefl _ eq_refl h) |].
    destruct t3; try exact (Hrefl _ eq_refl h).
    + (* L_b1 :: L_B :: L_A k :: ... *)
      destruct l3 as [|t4 rem]; [exact (Hrefl _ eq_refl h) |].
      destruct t4; try exact (Hrefl _ eq_refl h).
      destruct r as [|rt1 rRest]; [exact (Hrefl _ eq_refl h) |].
      destruct rt1; try exact (Hrefl _ eq_refl h).
      destruct (revRToLTok rRest (L_B :: L_A k :: L_B :: rem)) as [out|] eqn:Hrev; [| exact (Hrefl _ eq_refl h)].
      injection h as Hs'; subst s'.
      destruct (revRToLTok_spec Hrev) as [w [hwR hwL]].
      assert (hEnd : exists u, (w ++ rev prefAB ++ [AB_B; AB_B; AB_A]) = u ++ [AB_A])
        by (exists (w ++ rev prefAB ++ [AB_B; AB_B]); repeat rewrite <- app_assoc; reflexivity).
      pose proof (copy_id_ab _ hEnd (S k) (evalL 0 0 rem)) as hcp.
      assert (Heq : true :: bitsC ++ evalABL (rev (w ++ rev prefAB ++ [AB_B; AB_B; AB_A])) ++ bitsB ++ bitsARn (S k) ++ bitsB ++ evalL 0 0 rem
                  = true :: bitsC ++ blkBitsL S_P ++ evalABL prefAB ++ evalL 0 0 out).
      { rewrite hwL, !rev_app_distr, rev_involutive, !evalABL_append; cbn [rev evalABL evalL blkBitsL app]; rewrite ?app_nil_r; repeat rewrite <- app_assoc; reflexivity. }
      rewrite Heq in hcp; cbn [evalR evalL app] in *; repeat rewrite <- app_assoc in hcp; repeat rewrite <- app_assoc.
      rewrite hwR, <- evalABR_append; exact (rPlus_to_star hcp).
    + (* L_b1 :: L_B :: L_C :: rem *)
      destruct r as [|rt1 rRest]; [exact (Hrefl _ eq_refl h) |].
      destruct rt1; try exact (Hrefl _ eq_refl h).
      destruct (revRToLTok rRest (L_B :: L_B :: l3)) as [out|] eqn:Hrev; [| exact (Hrefl _ eq_refl h)].
      injection h as Hs'; subst s'.
      destruct (revRToLTok_spec Hrev) as [w [hwR hwL]].
      assert (hEnd : exists u, (w ++ rev prefAB ++ [AB_B; AB_B; AB_A]) = u ++ [AB_A])
        by (exists (w ++ rev prefAB ++ [AB_B; AB_B]); repeat rewrite <- app_assoc; reflexivity).
      pose proof (copy_id_ab _ hEnd 0 (evalL 0 0 l3)) as hcp.
      assert (Heq : true :: bitsC ++ evalABL (rev (w ++ rev prefAB ++ [AB_B; AB_B; AB_A])) ++ bitsB ++ bitsARn 0 ++ bitsB ++ evalL 0 0 l3
                  = true :: bitsC ++ blkBitsL S_P ++ evalABL prefAB ++ evalL 0 0 out).
      { rewrite hwL, !rev_app_distr, rev_involutive, !evalABL_append; cbn [rev evalABL evalL blkBitsL bitsARn app]; rewrite ?app_nil_r; repeat rewrite <- app_assoc; reflexivity. }
      rewrite Heq in hcp; cbn [evalR evalL bitsARn app] in *; repeat rewrite <- app_assoc in hcp; repeat rewrite <- app_assoc.
      rewrite hwR, <- evalABR_append; exact (rPlus_to_star hcp).
  - (* L_b1 :: L_C :: l2 *)
    destruct r as [|rt1 r1]; [exact (Hrefl _ eq_refl h) |].
    destruct rt1; try exact (Hrefl _ eq_refl h).
    destruct r1 as [|rt2 rRest]; [exact (Hrefl _ eq_refl h) |].
    destruct rt2 as [| |[|k]| | ]; try exact (Hrefl _ eq_refl h).
    destruct (pushBs_sound k (L_B :: l2) rRest [] (evalABR (rev prefAB ++ [AB_B; AB_B; AB_A]))) as [l' [r' [hEq hR]]].
    rewrite hEq in h; injection h as Hs'; subst s'.
    pose proof (step_1C_AR2 (evalL 0 0 l2) (bitsARn k ++ evalR 0 0 rRest ++ evalABR (rev prefAB ++ [AB_B; AB_B; AB_A]))) as h1.
    cbn [evalL evalR bitsARn app] in h1, hR |- *;
    repeat rewrite app_nil_r in h1; repeat rewrite app_nil_r in hR; repeat rewrite app_nil_r;
    repeat rewrite <- app_assoc in h1; repeat rewrite <- app_assoc in hR; repeat rewrite <- app_assoc.
    exact (rStar_trans (rPlus_to_star h1) hR).
Qed.

Lemma sweepLB_sound {allowEmpty : bool} {lBot rBot : list bool} {prefAB : list ABWord}
  (hBot : allowEmpty = true -> lBot = []) :
  forall (l : list LTok) (r : list RTok) (s' : StateX),
    stepToState lBot rBot prefAB (sweepLB allowEmpty l r) = Some s' ->
    RPlus (M_L LM_B, evalL 0 0 l ++ lBot, evalR 0 0 r ++ rBot) s'.
Proof.
  fix ih 1; intros [|x l1] r s' h.
  - clear ih; cbn [sweepLB] in h; destruct allowEmpty; [| discriminate].
    cbn in h; inversion h; subst s'; rewrite (hBot eq_refl); apply step_LB_nil.
  - destruct x as [| |k| | |ks vs].
    + destruct l1 as [|[| |[|k]| | | ] l2]; cbn [sweepLB] in h.
      * clear ih; destruct allowEmpty; [| discriminate].
        cbn in h; inversion h; subst s'; rewrite (hBot eq_refl); cbn [evalL evalR app].
        exact (rPlus_trans (step_LB_0 _ _) (step_LC_nil _)).
      * cbn in h; inversion h; subst s'; cbn [evalL evalR app].
        exact (rPlus_trans (step_LB_0 _ _) (step_LC_0 _ _)).
      * pose proof (sweepLB_A (evalL 0 0 l2 ++ lBot) (evalR 0 0 r ++ rBot)) as h1.
        pose proof (ih l2 (pushRAR 0 r) s' h) as h2.
        rewrite evalR_pushRAR in h2; cbn [evalL bitsA bitsAR bitsARn app] in h1, h2 |- *.
        exact (rPlus_trans h1 h2).
      * cbn in h; inversion h; subst s'; cbn [evalL evalR bitsARn app].
        exact (rPlus_trans (step_LB_0 _ _) (step_LC_0 _ _)).
      * cbn in h; inversion h; subst s'; cbn [evalL evalR bitsARn app].
        exact (rPlus_trans (step_LB_0 _ _) (step_LC_0 _ _)).
      * cbn in h; inversion h; subst s'; cbn [evalL evalR bitsB app].
        exact (rPlus_trans (step_LB_0 _ _) (step_LC_0 _ _)).
      * cbn in h; inversion h; subst s'; cbn [evalL evalR bitsC app].
        exact (rPlus_trans (step_LB_0 _ _) (step_LC_0 _ _)).
      * discriminate.
    + cbn [sweepLB] in h.
      pose proof (step_LB_1 (evalL 0 0 l1 ++ lBot) (evalR 0 0 r ++ rBot)) as h1.
      pose proof (ih l1 (pushR0 r) s' h) as h2.
      rewrite evalR_pushR0 in h2; cbn [evalL app] in h1, h2 |- *.
      exact (rPlus_trans h1 h2).
    + cbn [sweepLB] in h.
      pose proof (sweepLB_ARn (S k) (evalL 0 0 l1 ++ lBot) (evalR 0 0 r ++ rBot)) as h1.
      pose proof (ih l1 (pushRAR k r) s' h) as h2.
      rewrite evalR_pushRAR in h2; cbn [evalL]; rewrite <- app_assoc; rewrite <- app_assoc in h2.
      exact (rStar_trans_plus h1 h2).
    + cbn [sweepLB] in h.
      pose proof (sweepLB_B (evalL 0 0 l1 ++ lBot) (evalR 0 0 r ++ rBot)) as h1.
      pose proof (ih l1 (R_BR :: r) s' h) as h2.
      cbn [evalL evalR] in h2 |- *; rewrite <- app_assoc in h2 |- *.
      exact (rPlus_trans h1 h2).
    + cbn [sweepLB stepToState] in h; inversion h; subst s'.
      cbn [evalL evalR]; rewrite <- app_assoc; apply sweepLB_C.
    + discriminate.
Qed.

Lemma sweepLC_sound {allowEmpty : bool} {l : list LTok} {r : list RTok}
  {lBot rBot : list bool} {prefAB : list ABWord} {s' : StateX}
  (hBot : allowEmpty = true -> lBot = [])
  (h : stepToState lBot rBot prefAB (sweepLC allowEmpty l r) = Some s') :
  RPlus (M_L LM_C, evalL 0 0 l ++ lBot, evalR 0 0 r ++ rBot) s'.
Proof.
  destruct l as [|[| |[|k]| | | ] l1]; cbn [sweepLC] in h; try discriminate.
  - destruct allowEmpty; [| discriminate].
    cbn in h; inversion h; subst s'; rewrite (hBot eq_refl); apply step_LC_nil.
  - cbn in h; inversion h; subst s'; apply step_LC_0.
  - pose proof (step_LC_1 (evalL 0 0 l1 ++ lBot) (evalR 0 0 r ++ rBot)) as h1.
    pose proof (sweepLB_sound hBot l1 (pushR0 r) s' h) as h2.
    rewrite evalR_pushR0 in h2; cbn [evalL app] in h1, h2 |- *; exact (rPlus_trans h1 h2).
  - cbn in h; inversion h; subst s'; cbn [evalL bitsARn app]; apply step_LC_0.
  - cbn in h; inversion h; subst s'; cbn [evalL bitsARn app]; apply step_LC_0.
  - cbn in h; inversion h; subst s'; cbn [evalL bitsB app]; apply step_LC_0.
  - cbn in h; inversion h; subst s'; cbn [evalL bitsC app]; apply step_LC_0.
Qed.

Lemma sweepR_sound {allowEmpty doCopy : bool} {lBot rBot : list bool} {prefAB : list ABWord}
  (hAE : allowEmpty = true -> lBot = [])
  (hDC1 : doCopy = true -> lBot = [])
  (hDC2 : doCopy = true -> rBot = evalABR (rev prefAB ++ [AB_B; AB_B; AB_A])) :
  forall (fuel : nat) (m : bool) (l : list LTok) (r : list RTok) (s' : StateX),
    stepToState lBot rBot prefAB (sweepR allowEmpty doCopy fuel m l r) = Some s' ->
    RPlus (if m then M_R RM_A else M_R RM_D, evalL 0 0 l ++ lBot, evalR 0 0 r ++ rBot) s'.
Proof.
  induction fuel as [|f ih]; intros m l r s' h; [discriminate |].
  destruct m.
  - (* m = true (RM_A) *)
    cbn [sweepR] in h.
    destruct r as [|[| |k| | ] r2]; try discriminate.
    + (* R_b0 :: r2 *)
      destruct r2 as [|[| |[|k]| | ] r3]; try discriminate.
      * cbn in h; inversion h; subst s'; apply step_RA_00.
      * pose proof (finishLB_sound hDC1 hDC2 h) as h3.
        pose proof (step_RA_01 (evalL 0 0 l ++ lBot) (evalR 0 0 r3 ++ rBot)) as h1.
        rewrite evalR_pushR0 in h3; exact (rPlus_trans_star h1 h3).
      * cbn in h; inversion h; subst s'; cbn [evalL evalR bitsARn app]; apply step_RA_00.
      * cbn in h; inversion h; subst s'; cbn [evalL evalR bitsARn app]; apply step_RA_00.
      * cbn in h; inversion h; subst s'; rewrite evalR_pushRAR; cbn [evalL evalR bitsBR bitsARn app]; apply step_RA_00.
    + (* R_b1 :: r2 *)
      destruct r2 as [|[| |[|k]| | ] r3]; try discriminate.
      * (* R_b1 :: R_b0 :: r3 *)
        destruct r3 as [|[| |[|k]| | ] r4]; try discriminate.
        -- pose proof (step_RA_100 (evalL 0 0 l ++ lBot) (evalR 0 0 r4 ++ rBot)) as h1.
           pose proof (ih false _ _ _ h) as h2.
           assert (hEq : EqBits (true :: true :: false :: (evalL 0 0 l ++ lBot))
             (evalL 0 0 (L_b1 :: L_b1 :: pushL0 allowEmpty l) ++ lBot))
             by exact (eqBits_cons true (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE)))).
           exact (rPlus_trans h1 (rPlus_congr_L hEq h2)).
        -- pose proof (step_RA_101 (evalL 0 0 l ++ lBot) (evalR 0 0 r4 ++ rBot)) as h1.
           pose proof (finishLB_sound hDC1 hDC2 h) as h3.
           rewrite evalR_pushR0 in h3.
           assert (hEq : EqBits (true :: false :: (evalL 0 0 l ++ lBot))
             (evalL 0 0 (L_b1 :: pushL0 allowEmpty l) ++ lBot))
             by exact (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE))).
           exact (rPlus_trans_star h1 (rStar_congr_L hEq h3)).
        -- pose proof (step_RA_100 (evalL 0 0 l ++ lBot) (true :: (evalR 0 0 r4 ++ rBot))) as h1.
           pose proof (ih false _ _ _ h) as h2.
           assert (hEq : EqBits (true :: true :: false :: (evalL 0 0 l ++ lBot))
             (evalL 0 0 (L_b1 :: L_b1 :: pushL0 allowEmpty l) ++ lBot))
             by exact (eqBits_cons true (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE)))).
           exact (rPlus_trans h1 (rPlus_congr_L hEq h2)).
        -- pose proof (step_RA_100 (evalL 0 0 l ++ lBot) (true :: bitsARn (S k) ++ (evalR 0 0 r4 ++ rBot))) as h1.
           pose proof (ih false _ _ _ h) as h2.
           assert (hEq : EqBits (true :: true :: false :: (evalL 0 0 l ++ lBot))
             (evalL 0 0 (L_b1 :: L_b1 :: pushL0 allowEmpty l) ++ lBot))
             by exact (eqBits_cons true (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE)))).
           cbn [evalR bitsARn app] in h2 |- *; rewrite <- app_assoc in h2 |- *.
           exact (rPlus_trans h1 (rPlus_congr_L hEq h2)).
        -- pose proof (step_RA_100 (evalL 0 0 l ++ lBot) (false :: false :: true :: (evalR 0 0 r4 ++ rBot))) as h1.
           pose proof (ih false _ _ _ h) as h2.
           assert (hEq : EqBits (true :: true :: false :: (evalL 0 0 l ++ lBot))
             (evalL 0 0 (L_b1 :: L_b1 :: pushL0 allowEmpty l) ++ lBot))
             by exact (eqBits_cons true (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE)))).
           cbn [evalR bitsBR app] in h2 |- *; rewrite evalR_pushRAR in h2; cbn [bitsARn app] in h2.
           exact (rPlus_trans h1 (rPlus_congr_L hEq h2)).
      * (* R_b1 :: R_AR 0 :: r3 *)
        pose proof (step_RA_101 (evalL 0 0 l ++ lBot) (evalR 0 0 r3 ++ rBot)) as h1.
        pose proof (finishLB_sound hDC1 hDC2 h) as h3.
        rewrite evalR_pushR0 in h3.
        assert (hEq : EqBits (true :: false :: (evalL 0 0 l ++ lBot))
          (evalL 0 0 (L_b1 :: pushL0 allowEmpty l) ++ lBot))
          by exact (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE))).
        exact (rPlus_trans_star h1 (rStar_congr_L hEq h3)).
      * (* R_b1 :: R_AR (S k) :: r3 *)
        pose proof (step_RA_101 (evalL 0 0 l ++ lBot) (bitsARn (S k) ++ (evalR 0 0 r3 ++ rBot))) as h1.
        pose proof (finishLB_sound hDC1 hDC2 h) as h3.
        rewrite evalR_pushR0 in h3; cbn [evalR bitsARn app] in h3 |- *; rewrite <- app_assoc in h3 |- *.
        assert (hEq : EqBits (true :: false :: (evalL 0 0 l ++ lBot))
          (evalL 0 0 (L_b1 :: pushL0 allowEmpty l) ++ lBot))
          by exact (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE))).
        exact (rPlus_trans_star h1 (rStar_congr_L hEq h3)).
      * (* R_b1 :: R_BR :: r3 *)
        pose proof (step_RA_100 (evalL 0 0 l ++ lBot) (false :: true :: (evalR 0 0 r3 ++ rBot))) as h1.
        pose proof (ih false _ _ _ h) as h2.
        rewrite evalR_pushRAR in h2; cbn [evalR bitsBR bitsARn app] in h2 |- *.
        assert (hEq : EqBits (true :: true :: false :: (evalL 0 0 l ++ lBot))
          (evalL 0 0 (L_b1 :: L_b1 :: pushL0 allowEmpty l) ++ lBot))
          by exact (eqBits_cons true (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE)))).
        exact (rPlus_trans h1 (rPlus_congr_L hEq h2)).
    + (* R_AR k :: r2 *)
      pose proof (finishLB_sound hDC1 hDC2 h) as h3.
      destruct k as [|k'].
      * pose proof (step_RA_01 (evalL 0 0 l ++ lBot) (evalR 0 0 r2 ++ rBot)) as h1.
        rewrite evalR_pushR0 in h3; exact (rPlus_trans_star h1 h3).
      * pose proof (step_RA_01 (evalL 0 0 l ++ lBot) (bitsARn (S k') ++ (evalR 0 0 r2 ++ rBot))) as h1.
        rewrite evalR_pushR0 in h3; cbn [evalR bitsARn app] in h3 |- *; rewrite <- app_assoc in h3 |- *.
        exact (rPlus_trans_star h1 h3).
    + (* R_BR :: r2 *)
      cbn in h; inversion h; subst s'; rewrite evalR_pushRAR; cbn [evalL evalR bitsBR bitsARn app]; apply step_RA_00.
  - (* m = false (RM_D) *)
    cbn [sweepR] in h.
    assert (Hnotb1 : forall (l0 : list LTok) (rRem rOrig : list RTok),
      stepToState lBot rBot prefAB
        (match popL0 allowEmpty l0 with Some l' => finishLB doCopy l' (pushRAR 0 (pushR0 rRem)) | None => T_fail end) = Some s' ->
      (evalR 0 0 rOrig ++ rBot = false :: true :: (evalR 0 0 rRem ++ rBot) \/
       evalR 0 0 rOrig ++ rBot = true :: false :: (evalR 0 0 rRem ++ rBot)) ->
      RPlus (M_R RM_D, evalL 0 0 l0 ++ lBot, evalR 0 0 rOrig ++ rBot) s').
    { intros l0 rRem rOrig Hh HrOrig.
      destruct (popL0 allowEmpty l0) as [l'|] eqn:Hpop; [| discriminate].
      pose proof (evalL_popL0 (n0 := 0) (n1 := 0) hAE Hpop) as hEqL.
      pose proof (finishLB_sound hDC1 hDC2 Hh) as h3.
      rewrite evalR_pushRAR, evalR_pushR0 in h3; cbn [bitsARn app] in h3.
      destruct HrOrig as [Hr0 | Hr0]; rewrite Hr0.
      - exact (rPlus_congr_L hEqL (rPlus_trans_star (step_RD_01_0 _ _) h3)).
      - exact (rPlus_congr_L hEqL (rPlus_trans_star (step_RD_10_0 _ _) h3)). }
    assert (Hb1b1 : forall (l0 : list LTok) (rRem : list RTok),
      stepToState lBot rBot prefAB
        (match popL0 allowEmpty l0 with Some l' => T_toL false l' (pushRAR 0 (R_b1 :: rRem)) | None => T_fail end) = Some s' ->
      RPlus (M_R RM_D, evalL 0 0 l0 ++ lBot, evalR 0 0 (R_b1 :: R_b1 :: rRem) ++ rBot) s').
    { intros l0 rRem Hh.
      destruct (popL0 allowEmpty l0) as [l'|] eqn:Hpop; [| discriminate].
      cbn [stepToState] in Hh; inversion Hh; subst s'.
      cbn [pushRAR evalR bitsARn app].
      exact (rPlus_congr_L (evalL_popL0 (n0 := 0) (n1 := 0) hAE Hpop) (step_RD_11_0 _ _)). }
    assert (Hb1BR : forall (l0 : list LTok) (rRem : list RTok),
      stepToState lBot rBot prefAB
        (match popL0 allowEmpty l0 with Some l' => finishLB doCopy l' (pushRAR 0 (R_BR :: rRem)) | None => T_fail end) = Some s' ->
      RPlus (M_R RM_D, evalL 0 0 l0 ++ lBot, evalR 0 0 (R_b1 :: R_BR :: rRem) ++ rBot) s').
    { intros l0 rRem Hh.
      destruct (popL0 allowEmpty l0) as [l'|] eqn:Hpop; [| discriminate].
      pose proof (finishLB_sound hDC1 hDC2 Hh) as h3.
      cbn [pushRAR evalR bitsBR bitsARn app] in h3 |- *.
      exact (rPlus_congr_L (evalL_popL0 (n0 := 0) (n1 := 0) hAE Hpop) (rPlus_trans_star (step_RD_10_0 _ _) h3)). }
    destruct r as [|[| |k| | ] r2]; try discriminate.
    + (* R_b0 :: r2 *)
      destruct r2 as [|[| |[|k]| | ] r3]; try discriminate.
      * pose proof (step_RD_00 (evalL 0 0 l ++ lBot) (evalR 0 0 r3 ++ rBot)) as h1.
        pose proof (ih true _ _ _ h) as h2.
        exact (rPlus_trans h1 (rPlus_congr_L (eqBits_symm (evalL_pushL0 (l := L_b1 :: l) hAE)) h2)).
      * destruct l as [|[| |kl| | |ks vs] l1];
          try solve [apply (Hnotb1 _ r3 _); [exact h | left; reflexivity]].
        pose proof (step_RD_01_1 (evalL 0 0 l1 ++ lBot) (evalR 0 0 r3 ++ rBot)) as h1.
        pose proof (ih false _ _ _ h) as h2.
        assert (hEq : EqBits (true :: true :: false :: (evalL 0 0 l1 ++ lBot))
          (evalL 0 0 (L_b1 :: L_b1 :: pushL0 allowEmpty l1) ++ lBot))
          by exact (eqBits_cons true (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE)))).
        exact (rPlus_trans h1 (rPlus_congr_L hEq h2)).
      * pose proof (step_RD_00 (evalL 0 0 l ++ lBot) (true :: (evalR 0 0 r3 ++ rBot))) as h1.
        pose proof (ih true _ _ _ h) as h2.
        exact (rPlus_trans h1 (rPlus_congr_L (eqBits_symm (evalL_pushL0 (l := L_b1 :: l) hAE)) h2)).
      * pose proof (step_RD_00 (evalL 0 0 l ++ lBot) (true :: bitsARn (S k) ++ (evalR 0 0 r3 ++ rBot))) as h1.
        pose proof (ih true _ _ _ h) as h2.
        cbn [evalR bitsARn app] in h2 |- *; rewrite <- app_assoc in h2 |- *.
        exact (rPlus_trans h1 (rPlus_congr_L (eqBits_symm (evalL_pushL0 (l := L_b1 :: l) hAE)) h2)).
      * cbn [stepToState] in h; inversion h; subst s'.
        pose proof (rPlus_trans (step_RD_00 (evalL 0 0 l ++ lBot) (false :: false :: true :: (evalR 0 0 r3 ++ rBot)))
          (step_RA_00 (false :: true :: (evalL 0 0 l ++ lBot)) (true :: (evalR 0 0 r3 ++ rBot)))) as h12.
        exact (rPlus_congr_end (eqBits_cons true (evalL_pushL0 (l := L_b1 :: l) hAE)) (eqBits_refl _) h12).
    + (* R_b1 :: r2 *)
      destruct r2 as [|[| |k| | ] r3]; try discriminate.
      * (* R_b1 :: R_b0 :: r3 *)
        destruct l as [|[| |kl| | |ks vs] l1];
          try solve [apply (Hnotb1 _ r3 _); [exact h | right; reflexivity]].
        pose proof (step_RD_10_1 (evalL 0 0 l1 ++ lBot) (evalR 0 0 r3 ++ rBot)) as h1.
        pose proof (ih false _ _ _ h) as h2.
        assert (hEq : EqBits (true :: true :: false :: (evalL 0 0 l1 ++ lBot))
          (evalL 0 0 (L_b1 :: L_b1 :: pushL0 allowEmpty l1) ++ lBot))
          by exact (eqBits_cons true (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE)))).
        exact (rPlus_trans h1 (rPlus_congr_L hEq h2)).
      * (* R_b1 :: R_b1 :: r3 *)
        destruct l as [|[| |kl| | |ks vs] l1];
          try solve [apply (Hb1b1 _ r3); exact h].
        pose proof (step_RD_11_1 (evalL 0 0 l1 ++ lBot) (evalR 0 0 r3 ++ rBot)) as h1.
        pose proof (finishLB_sound hDC1 hDC2 h) as h3.
        rewrite evalR_pushR0 in h3.
        assert (hEq : EqBits (true :: false :: (evalL 0 0 l1 ++ lBot))
          (evalL 0 0 (L_b1 :: pushL0 allowEmpty l1) ++ lBot))
          by exact (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE))).
        exact (rPlus_trans_star h1 (rStar_congr_L hEq h3)).
      * (* R_b1 :: R_AR k :: r3 *)
        destruct l as [|[| |kl| | |ks vs] l1];
          try solve [apply (Hnotb1 _ (match k with 0%nat => R_b1 :: r3 | S k' => R_b1 :: R_AR k' :: r3 end) _);
               [exact h | right; destruct k; cbn [evalR bitsARn app]; rewrite <- ?app_assoc; reflexivity]].
        pose proof (sweepRD_1_ARn k (evalL 0 0 l1 ++ lBot) (evalR 0 0 r3 ++ rBot)) as h1.
        destruct k as [|k'].
        -- pose proof (ih false _ _ _ h) as h2.
           assert (hEq : EqBits (true :: true :: bitsARn 0 ++ false :: (evalL 0 0 l1 ++ lBot))
             (evalL 0 0 (L_b1 :: L_b1 :: pushL0 allowEmpty l1) ++ lBot))
             by exact (eqBits_cons true (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE)))).
           exact (rStar_trans_plus h1 (rPlus_congr_L hEq h2)).
        -- pose proof (ih false _ _ _ h) as h2.
           assert (hEq : EqBits (true :: true :: bitsARn (S k') ++ false :: (evalL 0 0 l1 ++ lBot))
             (evalL 0 0 (L_b1 :: L_b1 :: pushLA k' (pushL0 allowEmpty l1)) ++ lBot)).
           { cbn [evalL app]; rewrite evalL_pushLA, <- app_assoc.
             exact (eqBits_cons true (eqBits_cons true (eqBits_append_left (bitsARn (S k'))
               (eqBits_symm (evalL_pushL0 hAE))))). }
           cbn [evalR bitsARn app]; rewrite <- ?app_assoc.
           exact (rStar_trans_plus h1 (rPlus_congr_L hEq h2)).
      * (* R_b1 :: R_BR :: r3 *)
        destruct l as [|[| |kl| | |ks vs] l1];
          try solve [apply (Hb1BR _ r3); exact h].
        pose proof (step_RD_10_1 (evalL 0 0 l1 ++ lBot) (false :: false :: true :: (evalR 0 0 r3 ++ rBot))) as h1.
        pose proof (ih false _ _ _ h) as h2.
        cbn [evalR bitsBR app] in h2 |- *; rewrite evalR_pushRAR in h2; cbn [bitsARn app] in h2.
        assert (hEq : EqBits (true :: true :: false :: (evalL 0 0 l1 ++ lBot))
          (evalL 0 0 (L_b1 :: L_b1 :: pushL0 allowEmpty l1) ++ lBot))
          by exact (eqBits_cons true (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE)))).
        exact (rPlus_trans h1 (rPlus_congr_L hEq h2)).
    + (* R_AR k :: r2 *)
      destruct l as [|[| |kl| | |ks vs] l1];
        try solve [apply (Hnotb1 _ (match k with 0%nat => r2 | S k' => R_AR k' :: r2 end) _);
             [exact h | left; destruct k; cbn [evalR bitsARn app]; rewrite <- ?app_assoc; reflexivity]].
      pose proof (sweepRD_ARn k (evalL 0 0 l1 ++ lBot) (evalR 0 0 r2 ++ rBot)) as h1.
      destruct k as [|k'].
      * pose proof (ih false _ _ _ h) as h2.
        assert (hEq : EqBits (true :: true :: bitsARn 0 ++ false :: (evalL 0 0 l1 ++ lBot))
          (evalL 0 0 (L_b1 :: L_b1 :: pushL0 allowEmpty l1) ++ lBot))
          by exact (eqBits_cons true (eqBits_cons true (eqBits_symm (evalL_pushL0 hAE)))).
        cbn [evalR bitsARn app]; rewrite <- ?app_assoc.
        exact (rStar_trans_plus h1 (rPlus_congr_L hEq h2)).
      * pose proof (ih false _ _ _ h) as h2.
        assert (hEq : EqBits (true :: true :: bitsARn (S k') ++ false :: (evalL 0 0 l1 ++ lBot))
          (evalL 0 0 (L_b1 :: L_b1 :: pushLA k' (pushL0 allowEmpty l1)) ++ lBot)).
        { cbn [evalL app]; rewrite evalL_pushLA, <- app_assoc.
          exact (eqBits_cons true (eqBits_cons true (eqBits_append_left (bitsARn (S k'))
            (eqBits_symm (evalL_pushL0 hAE))))). }
        cbn [evalR bitsARn app]; rewrite <- ?app_assoc.
        exact (rStar_trans_plus h1 (rPlus_congr_L hEq h2)).
    + (* R_BR :: r2 *)
      pose proof (rPlus_trans (step_RD_00 (evalL 0 0 l ++ lBot) (false :: true :: (evalR 0 0 r2 ++ rBot)))
        (step_RA_01 (false :: true :: (evalL 0 0 l ++ lBot)) (evalR 0 0 r2 ++ rBot))) as h12.
      pose proof (finishLB_sound hDC1 hDC2 h) as h3.
      rewrite evalR_pushR0 in h3.
      assert (hEq : EqBits (true :: false :: true :: (evalL 0 0 l ++ lBot))
        (evalL 0 0 (L_b1 :: pushL0 allowEmpty (L_b1 :: l)) ++ lBot))
        by exact (eqBits_cons true (eqBits_symm (evalL_pushL0 (l := L_b1 :: l) hAE))).
      exact (rPlus_trans_star h12 (rStar_congr_L hEq h3)).
Qed.

Fixpoint runTStep (allowEmpty doCopy : bool) (n : nat) (st : TStep) : TStep :=
  match n with
  | 0%nat => st
  | S n' =>
      match st with
      | T_toL false l r => runTStep allowEmpty doCopy n' (sweepLB allowEmpty l r)
      | T_toL true l r => runTStep allowEmpty doCopy n' (sweepLC allowEmpty l r)
      | T_toR m l r => runTStep allowEmpty doCopy n' (sweepR allowEmpty doCopy fuel_4096 m l r)
      | T_done out => T_done out
      | T_fail => T_fail
      end
  end.

Lemma runTStep_fail (allowEmpty doCopy : bool) (n : nat) :
  runTStep allowEmpty doCopy n T_fail = T_fail.
Proof. destruct n; reflexivity. Qed.

Lemma stepToState_none_eq_fail {lBot rBot : list bool} {prefAB : list ABWord} {st : TStep}
  (h : stepToState lBot rBot prefAB st = None) : st = T_fail.
Proof. destruct st as [[|] l r | [|] l r | out | ]; try discriminate; reflexivity. Qed.

Lemma runTStep_sound {allowEmpty doCopy : bool} {lBot rBot : list bool} {prefAB : list ABWord}
  (hAE : allowEmpty = true -> lBot = [])
  (hDC1 : doCopy = true -> lBot = [])
  (hDC2 : doCopy = true -> rBot = evalABR (rev prefAB ++ [AB_B; AB_B; AB_A])) :
  forall (n : nat) (st : TStep) (s0 s' : StateX),
    stepToState lBot rBot prefAB st = Some s0 ->
    stepToState lBot rBot prefAB (runTStep allowEmpty doCopy n st) = Some s' ->
    RStar s0 s'.
Proof.
  induction n as [|n ih]; intros st s0 s' h0 h1.
  - cbn in h1; rewrite h0 in h1; inversion h1; apply rStar_refl.
  - destruct st as [m l r | m l r | out | ]; [| | cbn [runTStep] in h1; rewrite h0 in h1; inversion h1; apply rStar_refl | discriminate].
    + (* T_toR *)
      cbn [runTStep] in h1.
      destruct (stepToState lBot rBot prefAB (sweepR allowEmpty doCopy fuel_4096 m l r)) as [s1|] eqn:Hm.
      * pose proof (sweepR_sound hAE hDC1 hDC2 fuel_4096 m l r s1 Hm) as hs1.
        destruct m; cbn in h0; inversion h0; subst s0; exact (rStar_trans (rPlus_to_star hs1) (ih _ _ _ Hm h1)).
      * rewrite (stepToState_none_eq_fail Hm), runTStep_fail in h1; discriminate.
    + (* T_toL *)
      destruct m; cbn [runTStep] in h1; cbn in h0; inversion h0; subst s0.
      * destruct (stepToState lBot rBot prefAB (sweepLC allowEmpty l r)) as [s1|] eqn:Hm.
        -- exact (rStar_trans (rPlus_to_star (sweepLC_sound hAE Hm)) (ih _ _ _ Hm h1)).
        -- rewrite (stepToState_none_eq_fail Hm), runTStep_fail in h1; discriminate.
      * destruct (stepToState lBot rBot prefAB (sweepLB allowEmpty l r)) as [s1|] eqn:Hm.
        -- exact (rStar_trans (rPlus_to_star (sweepLB_sound hAE l r s1 Hm)) (ih _ _ _ Hm h1)).
        -- rewrite (stepToState_none_eq_fail Hm), runTStep_fail in h1; discriminate.
Qed.

Lemma step_1C_init (w : list bool) :
  RPlus (M_L LM_B, true :: bitsC ++ w, []) (M_L LM_B, w, blkBitsR S_P).
Proof.
  eapply rPlus_trans.
  - exact (rPlus_congr (eqBits_refl _) (eqBits_refl _) (eqBits_refl _) (eqBits_symm eqBits_zero_nil) (step_LB_1 (bitsC ++ w) [])).
  - eapply rPlus_trans; [exact (sweepLB_C w []) |].
    eapply rPlus_trans.
    + exact (rPlus_congr (eqBits_refl _) (eqBits_cons true (eqBits_symm eqBits_zero_nil)) (eqBits_refl _) (eqBits_refl _)
        (step_RD_10_1 (true :: true :: true :: w) [])).
    + eapply rPlus_trans; [exact (step_RD_nil _) |].
      eapply rPlus_trans; [exact (step_LC_1 _ _) |].
      change (false :: true :: true :: true :: false :: true :: true :: true :: w) with (bitsB ++ bitsB ++ w).
      eapply rPlus_trans; [exact (sweepLB_B (bitsB ++ w) [false; true]) |].
      exact (sweepLB_B w (bitsBR ++ [false; true])).
Qed.

Lemma sweepLB_AB (prefAB : list ABWord) (w r : list bool) :
  RStar (M_L LM_B, evalABL prefAB ++ w, r) (M_L LM_B, w, evalABR (rev prefAB) ++ r).
Proof.
  revert r; induction prefAB as [|[|] xs ih]; intro r; [apply rStar_refl | |].
  - cbn [evalABL rev]; rewrite evalABR_append, <- !app_assoc; cbn [evalABR app].
    exact (rStar_trans (rPlus_to_star (sweepLB_A _ r)) (ih (bitsAR ++ r))).
  - cbn [evalABL rev]; rewrite evalABR_append, <- !app_assoc; cbn [evalABR app].
    exact (rStar_trans (rPlus_to_star (sweepLB_B _ r)) (ih (bitsBR ++ r))).
Qed.

Definition localGoTok (fuel : nat) (suf : list LTok) : option (list LTok) :=
  match runTStep true true fuel (T_toL false suf []) with
  | T_done out => Some out
  | _ => None
  end.

Lemma localGoTok_sound {fuel : nat} {suf out : list LTok}
  (h : localGoTok fuel suf = Some out) (prefAB : list ABWord) :
  RPlus (M_L LM_B, true :: bitsC ++ evalABL prefAB ++ evalL 0 0 suf, [])
        (M_L LM_B, true :: bitsC ++ blkBitsL S_P ++ evalABL prefAB ++ evalL 0 0 out, []).
Proof.
  unfold localGoTok in h.
  destruct (runTStep true true fuel (T_toL false suf [])) as [| |out'|] eqn:Hrun; try discriminate.
  inversion h; subst out'.
  eapply rPlus_trans_star; [exact (step_1C_init (evalABL prefAB ++ evalL 0 0 suf)) |].
  eapply rStar_trans; [exact (sweepLB_AB prefAB (evalL 0 0 suf) (blkBitsR S_P)) |].
  replace (evalABR (rev prefAB) ++ blkBitsR S_P) with (evalABR (rev prefAB ++ [AB_B; AB_B; AB_A]))
    by (rewrite evalABR_append; reflexivity).
  pose proof (runTStep_sound (allowEmpty := true) (doCopy := true)
    (lBot := []) (rBot := evalABR (rev prefAB ++ [AB_B; AB_B; AB_A])) (prefAB := prefAB)
    (fun _ => eq_refl) (fun _ => eq_refl) (fun _ => eq_refl)
    fuel (T_toL false suf [])
    (M_L LM_B, evalL 0 0 suf ++ [], evalABR (rev prefAB ++ [AB_B; AB_B; AB_A]))
    (M_L LM_B, true :: bitsC ++ blkBitsL S_P ++ evalABL prefAB ++ evalL 0 0 out, [])
    eq_refl (ltac:(rewrite Hrun; reflexivity))) as h3.
  rewrite app_nil_r in h3; exact h3.
Qed.

(* ========================================================================= *)
(* Section 2c: The 4 Algebraic Block Rules (P->Q3, Q3_2->R5, R5->W5, R5->Q8) *)
(* ========================================================================= *)

Lemma powBits_Q32_eq (n : nat) :
  powBits (blkBitsR S_Q3_2) n = powBits (blkBitsR S_Q3) (n + n)%nat.
Proof.
  induction n as [|n ih]; [reflexivity |].
  replace (S n + S n)%nat with ((n + n) + 2)%nat by lia.
  rewrite powBits_add, <- ih.
  change (powBits (blkBitsR S_Q3) 2) with (blkBitsR S_Q3_2 ++ []).
  rewrite app_nil_r, <- powBits_comm_one; reflexivity.
Qed.

Lemma powBitsN_Q3_Q32_comm (j n : N) :
  powBitsN (blkBitsR S_Q3) j ++ powBitsN (blkBitsR S_Q3_2) n =
  powBitsN (blkBitsR S_Q3_2) n ++ powBitsN (blkBitsR S_Q3) j.
Proof.
  unfold powBitsN; rewrite powBits_Q32_eq, powBits_comm; reflexivity.
Qed.

Lemma powBitsN_Q32_L_eq (n : N) :
  powBitsN (blkBitsL S_Q3_2) n = powBitsN (blkBitsL S_Q3) (2 * n).
Proof.
  unfold powBitsN.
  replace (N.to_nat (2 * n)) with (N.to_nat n + N.to_nat n)%nat by lia.
  induction (N.to_nat n) as [|m ih]; [reflexivity |].
  replace (S m + S m)%nat with (2 + (m + m))%nat by lia.
  rewrite powBits_add, <- ih; reflexivity.
Qed.

Lemma openStep_sound {fuel : nat} {l0 l1 : list LTok} {r0 r1 : list RTok}
  (h : runTStep false false fuel (T_toL false l0 r0) = T_toL false l1 r1)
  (lBot rBot : list bool) :
  RStar (M_L LM_B, evalL 0 0 l0 ++ lBot, evalR 0 0 r0 ++ rBot)
        (M_L LM_B, evalL 0 0 l1 ++ lBot, evalR 0 0 r1 ++ rBot).
Proof.
  exact (runTStep_sound (allowEmpty := false) (doCopy := false)
    (lBot := lBot) (rBot := rBot) (prefAB := [])
    (fun hc => ltac:(discriminate)) (fun hc => ltac:(discriminate)) (fun hc => ltac:(discriminate))
    fuel (T_toL false l0 r0) _ _ eq_refl (ltac:(rewrite h; reflexivity))).
Qed.

Lemma pass_block_n {lPat rPat outBlk inBlk : list bool}
  (h1 : forall lBot rBot, RStar (M_L LM_B, lPat ++ lBot, rPat ++ inBlk ++ rBot)
                                (M_L LM_B, lPat ++ outBlk ++ lBot, rPat ++ rBot))
  (n : nat) (lBot rBot : list bool) :
  RStar (M_L LM_B, lPat ++ lBot, rPat ++ powBits inBlk n ++ rBot)
        (M_L LM_B, lPat ++ powBits outBlk n ++ lBot, rPat ++ rBot).
Proof.
  revert lBot; induction n as [|n ih]; intro lBot; [cbn [powBits app]; apply rStar_refl |].
  cbn [powBits]; rewrite <- app_assoc.
  eapply rStar_trans; [exact (h1 lBot (powBits inBlk n ++ rBot)) |].
  pose proof (ih (outBlk ++ lBot)) as hb.
  rewrite (app_assoc (powBits outBlk n) outBlk lBot), <- powBits_comm_one in hb; exact hb.
Qed.

Lemma pass_P_Q3_one (lBot rBot : list bool) :
  RStar (M_L LM_B, (true :: bitsC ++ bitsARn 3 ++ bitsC) ++ lBot, [false] ++ blkBitsR S_P ++ rBot)
        (M_L LM_B, (true :: bitsC ++ bitsARn 3 ++ bitsC) ++ blkBitsL S_Q3 ++ lBot, [false] ++ rBot).
Proof.
  apply (openStep_sound (fuel := fuel_4)
    (l0 := [L_b1; L_C; L_A 2; L_C]) (r0 := [R_b0; R_BR; R_BR; R_AR 0])
    (l1 := [L_b1; L_C; L_A 2; L_C; L_A 2; L_B]) (r1 := [R_b0]));
  vm_compute; reflexivity.
Qed.

Lemma pass_P_Q3 (j n : N) (lBot rBot : list bool) :
  RStar (M_L LM_B, (true :: bitsC ++ bitsARn 3 ++ bitsC) ++ lBot,
         [false] ++ powBitsN (blkBitsR S_P) j ++ powBitsN (blkBitsR S_P) n ++ rBot)
        (M_L LM_B, (true :: bitsC ++ bitsARn 3 ++ bitsC) ++ powBitsN (blkBitsL S_Q3) n ++ lBot,
         [false] ++ powBitsN (blkBitsR S_P) j ++ rBot).
Proof.
  pose proof (pass_block_n pass_P_Q3_one (N.to_nat n) lBot (powBitsN (blkBitsR S_P) j ++ rBot)) as h.
  fold (powBitsN (blkBitsR S_P) n) (powBitsN (blkBitsL S_Q3) n) in h.
  rewrite (app_assoc (powBitsN (blkBitsR S_P) n) (powBitsN (blkBitsR S_P) j) rBot), powBitsN_comm,
          <- (app_assoc (powBitsN (blkBitsR S_P) j) (powBitsN (blkBitsR S_P) n) rBot) in h; exact h.
Qed.

Lemma pass_Q32_R5_one (lBot rBot : list bool) :
  RStar (M_L LM_B, (true :: bitsC ++ bitsARn 5 ++ bitsC ++ bitsA ++ bitsB) ++ lBot,
         (false :: bitsARn 2) ++ blkBitsR S_Q3_2 ++ rBot)
        (M_L LM_B, (true :: bitsC ++ bitsARn 5 ++ bitsC ++ bitsA ++ bitsB) ++ blkBitsL S_R5 ++ lBot,
         (false :: bitsARn 2) ++ rBot).
Proof.
  apply (openStep_sound (fuel := fuel_8)
    (l0 := [L_b1; L_C; L_A 4; L_C; L_A 0; L_B]) (r0 := [R_b0; R_AR 1; R_BR; R_AR 2; R_BR; R_AR 2])
    (l1 := [L_b1; L_C; L_A 4; L_C; L_A 0; L_B; L_A 4; L_B; L_A 0; L_B]) (r1 := [R_b0; R_AR 1]));
  vm_compute; reflexivity.
Qed.

Lemma pass_Q32_R5 (j n : N) (lBot rBot : list bool) :
  RStar (M_L LM_B, (true :: bitsC ++ bitsARn 5 ++ bitsC ++ bitsA ++ bitsB) ++ lBot,
         (false :: bitsARn 2) ++ powBitsN (blkBitsR S_Q3) j ++ powBitsN (blkBitsR S_Q3_2) n ++ rBot)
        (M_L LM_B, (true :: bitsC ++ bitsARn 5 ++ bitsC ++ bitsA ++ bitsB) ++ powBitsN (blkBitsL S_R5) n ++ lBot,
         (false :: bitsARn 2) ++ powBitsN (blkBitsR S_Q3) j ++ rBot).
Proof.
  pose proof (pass_block_n pass_Q32_R5_one (N.to_nat n) lBot (powBitsN (blkBitsR S_Q3) j ++ rBot)) as h.
  fold (powBitsN (blkBitsR S_Q3_2) n) (powBitsN (blkBitsL S_R5) n) in h.
  rewrite (app_assoc (powBitsN (blkBitsR S_Q3_2) n) (powBitsN (blkBitsR S_Q3) j) rBot), <- powBitsN_Q3_Q32_comm,
          <- (app_assoc (powBitsN (blkBitsR S_Q3) j) (powBitsN (blkBitsR S_Q3_2) n) rBot) in h; exact h.
Qed.

Lemma pass_R5_W5_one (lBot rBot : list bool) :
  RStar (M_L LM_B, (true :: bitsC ++ bitsARn 3 ++ bitsC) ++ lBot,
         (false :: bitsARn 4) ++ blkBitsR S_R5 ++ rBot)
        (M_L LM_B, (true :: bitsC ++ bitsARn 3 ++ bitsC) ++ blkBitsL S_W5 ++ lBot,
         (false :: bitsARn 4) ++ rBot).
Proof.
  apply (openStep_sound (fuel := fuel_12)
    (l0 := [L_b1; L_C; L_A 2; L_C]) (r0 := [R_b0; R_AR 3; R_BR; R_AR 0; R_BR; R_AR 4])
    (l1 := [L_b1; L_C; L_A 2; L_C; L_B; L_A 0; L_B; L_A 2; L_B]) (r1 := [R_b0; R_AR 3]));
  vm_compute; reflexivity.
Qed.

Lemma pass_R5_W5 (j n : N) (lBot rBot : list bool) :
  RStar (M_L LM_B, (true :: bitsC ++ bitsARn 3 ++ bitsC) ++ lBot,
         (false :: bitsARn 4) ++ powBitsN (blkBitsR S_R5) j ++ powBitsN (blkBitsR S_R5) n ++ rBot)
        (M_L LM_B, (true :: bitsC ++ bitsARn 3 ++ bitsC) ++ powBitsN (blkBitsL S_W5) n ++ lBot,
         (false :: bitsARn 4) ++ powBitsN (blkBitsR S_R5) j ++ rBot).
Proof.
  pose proof (pass_block_n pass_R5_W5_one (N.to_nat n) lBot (powBitsN (blkBitsR S_R5) j ++ rBot)) as h.
  fold (powBitsN (blkBitsR S_R5) n) (powBitsN (blkBitsL S_W5) n) in h.
  rewrite (app_assoc (powBitsN (blkBitsR S_R5) n) (powBitsN (blkBitsR S_R5) j) rBot), powBitsN_comm,
          <- (app_assoc (powBitsN (blkBitsR S_R5) j) (powBitsN (blkBitsR S_R5) n) rBot) in h; exact h.
Qed.

Lemma pass_R5_Q8_one (lBot rBot : list bool) :
  RStar (M_L LM_B, (true :: bitsC ++ bitsARn 8 ++ bitsC) ++ lBot,
         (false :: bitsBR ++ bitsARn 5) ++ blkBitsR S_R5 ++ rBot)
        (M_L LM_B, (true :: bitsC ++ bitsARn 8 ++ bitsC) ++ blkBitsL S_Q8 ++ lBot,
         (false :: bitsBR ++ bitsARn 5) ++ rBot).
Proof.
  apply (openStep_sound (fuel := fuel_4)
    (l0 := [L_b1; L_C; L_A 7; L_C]) (r0 := [R_b0; R_BR; R_AR 4; R_BR; R_AR 0; R_BR; R_AR 4])
    (l1 := [L_b1; L_C; L_A 7; L_C; L_A 7; L_B]) (r1 := [R_b0; R_BR; R_AR 4]));
  vm_compute; reflexivity.
Qed.

Lemma pass_R5_Q8 (j n : N) (lBot rBot : list bool) :
  RStar (M_L LM_B, (true :: bitsC ++ bitsARn 8 ++ bitsC) ++ lBot,
         (false :: bitsBR ++ bitsARn 5) ++ powBitsN (blkBitsR S_R5) j ++ powBitsN (blkBitsR S_R5) n ++ rBot)
        (M_L LM_B, (true :: bitsC ++ bitsARn 8 ++ bitsC) ++ powBitsN (blkBitsL S_Q8) n ++ lBot,
         (false :: bitsBR ++ bitsARn 5) ++ powBitsN (blkBitsR S_R5) j ++ rBot).
Proof.
  pose proof (pass_block_n pass_R5_Q8_one (N.to_nat n) lBot (powBitsN (blkBitsR S_R5) j ++ rBot)) as h.
  fold (powBitsN (blkBitsR S_R5) n) (powBitsN (blkBitsL S_Q8) n) in h.
  rewrite (app_assoc (powBitsN (blkBitsR S_R5) n) (powBitsN (blkBitsR S_R5) j) rBot), powBitsN_comm,
          <- (app_assoc (powBitsN (blkBitsR S_R5) j) (powBitsN (blkBitsR S_R5) n) rBot) in h; exact h.
Qed.

(* ========================================================================= *)
(* Section 3: 2-Bit Binary Base-4 Codec, O(1) P32768 Trees & SufBucket Table *)
(* ========================================================================= *)

Fixpoint pos2_ind (P : positive -> Prop)
  (h1 : P xH) (h2 : P (xO xH)) (h3 : P (xI xH))
  (h1q : forall q, P q -> P (xI (xO q)))
  (h2q : forall q, P q -> P (xO (xI q)))
  (h3q : forall q, P q -> P (xI (xI q)))
  (h0q : forall q, P (xO (xO q)))
  (p : positive) {struct p} : P p :=
  match p with
  | xH => h1
  | xO xH => h2
  | xI xH => h3
  | xI (xO q) => h1q q (pos2_ind P h1 h2 h3 h1q h2q h3q h0q q)
  | xO (xI q) => h2q q (pos2_ind P h1 h2 h3 h1q h2q h3q h0q q)
  | xI (xI q) => h3q q (pos2_ind P h1 h2 h3 h1q h2q h3q h0q q)
  | xO (xO q) => h0q q
  end.

Definition mul4Add1 (q : N) : N :=
  match q with N0 => 1 | Npos p => Npos (xI (xO p)) end.
Definition mul4Add2 (q : N) : N :=
  match q with N0 => 2 | Npos p => Npos (xO (xI p)) end.
Definition mul4Add3 (q : N) : N :=
  match q with N0 => 3 | Npos p => Npos (xI (xI p)) end.

Fixpoint decBitsPos (p : positive) : list bool :=
  match p with
  | xH => bitsA
  | xO xH => bitsB
  | xI xH => bitsC
  | xI (xO q) => bitsA ++ decBitsPos q
  | xO (xI q) => bitsB ++ decBitsPos q
  | xI (xI q) => bitsC ++ decBitsPos q
  | xO (xO _) => []
  end.

Definition decBits (n : N) : list bool :=
  match n with N0 => [] | Npos p => decBitsPos p end.

Lemma decBits_zero : decBits 0 = [].
Proof. reflexivity. Qed.

Lemma decBits_mul4Add1 (q : N) : decBits (mul4Add1 q) = bitsA ++ decBits q.
Proof. destruct q as [|p]; reflexivity. Qed.

Lemma decBits_mul4Add2 (q : N) : decBits (mul4Add2 q) = bitsB ++ decBits q.
Proof. destruct q as [|p]; reflexivity. Qed.

Lemma decBits_mul4Add3 (q : N) : decBits (mul4Add3 q) = bitsC ++ decBits q.
Proof. destruct q as [|p]; reflexivity. Qed.

Fixpoint decLTokPos (p : positive) : list LTok :=
  match p with
  | xH => [L_A 0]
  | xO xH => [L_B]
  | xI xH => [L_C]
  | xI (xO q) => pushLA 0 (decLTokPos q)
  | xO (xI q) => L_B :: decLTokPos q
  | xI (xI q) => L_C :: decLTokPos q
  | xO (xO _) => []
  end.

Definition decLTok (n : N) : list LTok :=
  match n with N0 => [] | Npos p => decLTokPos p end.

Lemma evalL_decLTok (n0 n1 c : N) : evalL n0 n1 (decLTok c) = decBits c.
Proof.
  destruct c as [|p]; [reflexivity |].
  cbn [decLTok decBits].
  induction p as [| | |q ih|q ih|q ih|q] using pos2_ind;
    cbn [decLTokPos decBitsPos evalL];
    try rewrite evalL_pushLA;
    try rewrite ih;
    try rewrite app_nil_r;
    reflexivity.
Qed.

Fixpoint prependAs (k : nat) (acc : N) : N :=
  match k with
  | 0%nat => mul4Add1 acc
  | S k' => mul4Add1 (prependAs k' acc)
  end.

Lemma decBits_prependAs (k : nat) (acc : N) :
  decBits (prependAs k acc) = bitsARn (S k) ++ decBits acc.
Proof.
  induction k as [|k ih].
  - cbn [prependAs bitsARn app]; apply decBits_mul4Add1.
  - cbn [prependAs]; rewrite decBits_mul4Add1, ih; reflexivity.
Qed.

Fixpoint encLTok (l : list LTok) : option N :=
  match l with
  | [] => Some 0
  | L_A k :: xs =>
      match encLTok xs with
      | Some a => Some (prependAs k a)
      | None => None
      end
  | L_B :: xs =>
      match encLTok xs with
      | Some a => Some (mul4Add2 a)
      | None => None
      end
  | L_C :: xs =>
      match encLTok xs with
      | Some a => Some (mul4Add3 a)
      | None => None
      end
  | _ => None
  end.

Lemma encLTok_evalL (n0 n1 : N) {l : list LTok} {c : N} (h : encLTok l = Some c) :
  evalL n0 n1 l = decBits c.
Proof.
  revert c h; induction l as [|x xs ih]; intros c h.
  - inversion h; subst; reflexivity.
  - destruct x as [| |k| | |kv vv]; cbn [encLTok] in h; try discriminate;
    destruct (encLTok xs) as [a|] eqn:he; try discriminate;
    inversion h; subst c; cbn [evalL].
    + rewrite decBits_prependAs, (ih a eq_refl); reflexivity.
    + rewrite decBits_mul4Add2, (ih a eq_refl); reflexivity.
    + rewrite decBits_mul4Add3, (ih a eq_refl); reflexivity.
Qed.

Lemma encLTok_sound {l : list LTok} {c : N} (h : encLTok l = Some c) :
  evalL 0 0 l = decBits c.
Proof. exact (encLTok_evalL 0 0 h). Qed.

Fixpoint isABPos (p : positive) : bool :=
  match p with
  | xH | xO xH => true
  | xI (xO q) | xO (xI q) => isABPos q
  | _ => false
  end.

Definition isABCode (c : N) : bool :=
  match c with N0 => true | Npos p => isABPos p end.

Fixpoint decABPos (p : positive) : list ABWord :=
  match p with
  | xH => [AB_A]
  | xO xH => [AB_B]
  | xI (xO q) => AB_A :: decABPos q
  | xO (xI q) => AB_B :: decABPos q
  | _ => []
  end.

Definition decAB (c : N) : list ABWord :=
  match c with N0 => [] | Npos p => decABPos p end.

Fixpoint prependPos (p : positive) (q : N) : N :=
  match p with
  | xH => mul4Add1 q
  | xO xH => mul4Add2 q
  | xI xH => mul4Add3 q
  | xI (xO r) => mul4Add1 (prependPos r q)
  | xO (xI r) => mul4Add2 (prependPos r q)
  | xI (xI r) => mul4Add3 (prependPos r q)
  | xO (xO _) => q
  end.

Definition prependCode (c q : N) : N :=
  match c with N0 => q | Npos p => prependPos p q end.

Lemma evalABL_decAB (c : N) (h : isABCode c = true) :
  evalABL (decAB c) = decBits c.
Proof.
  destruct c as [|p]; [reflexivity |].
  cbn [isABCode decAB decBits] in *.
  induction p as [| | |q ih|q ih|q ih|q] using pos2_ind;
    cbn [isABPos decABPos decBitsPos evalABL] in *;
    try discriminate;
    try rewrite (ih h);
    try rewrite app_nil_r;
    reflexivity.
Qed.

Lemma decBits_prependCode_ab (c q : N) (h : isABCode c = true) :
  decBits (prependCode c q) = evalABL (decAB c) ++ decBits q.
Proof.
  destruct c as [|p]; [reflexivity |].
  cbn [isABCode prependCode decAB] in *.
  induction p as [| | |r ih|r ih|r ih|r] using pos2_ind;
    cbn [isABPos prependPos decABPos evalABL] in *;
    try discriminate.
  - rewrite decBits_mul4Add1; reflexivity.
  - rewrite decBits_mul4Add2; reflexivity.
  - rewrite decBits_mul4Add1, (ih h), app_assoc; reflexivity.
  - rewrite decBits_mul4Add2, (ih h), app_assoc; reflexivity.
Qed.

Definition peelDigit1 (w : N) : option N :=
  match w with
  | Npos xH => Some 0
  | Npos (xI (xO r)) => Some (Npos r)
  | _ => None
  end.

Definition peelDigit2 (w : N) : option N :=
  match w with
  | Npos (xO xH) => Some 0
  | Npos (xO (xI r)) => Some (Npos r)
  | _ => None
  end.

Lemma peelDigit1_sound {w r : N} (h : peelDigit1 w = Some r) :
  decBits w = bitsA ++ decBits r.
Proof.
  destruct w as [|[p|p|]]; try destruct p; cbn [peelDigit1] in h; try discriminate;
  inversion h; subst; cbn [decBits decBitsPos]; rewrite ?app_nil_r; reflexivity.
Qed.

Lemma peelDigit2_sound {w r : N} (h : peelDigit2 w = Some r) :
  decBits w = bitsB ++ decBits r.
Proof.
  destruct w as [|[p|p|]]; try destruct p; cbn [peelDigit2] in h; try discriminate;
  inversion h; subst; cbn [decBits decBitsPos]; rewrite ?app_nil_r; reflexivity.
Qed.

Fixpoint peelABDigits (cut : nat) (w : N) : option (list ABWord * N) :=
  match cut with
  | 0%nat => Some ([], w)
  | S c =>
      match peelDigit1 w with
      | Some w1 =>
          match peelABDigits c w1 with
          | Some (ab, suf) => Some (AB_A :: ab, suf)
          | None => None
          end
      | None =>
          match peelDigit2 w with
          | Some w2 =>
              match peelABDigits c w2 with
              | Some (ab, suf) => Some (AB_B :: ab, suf)
              | None => None
              end
          | None => None
          end
      end
  end.

Lemma peelABDigits_sound {cut : nat} {w : N} {ab : list ABWord} {suf : N}
  (h : peelABDigits cut w = Some (ab, suf)) :
  decBits w = evalABL ab ++ decBits suf.
Proof.
  revert w ab suf h; induction cut as [|c ih]; intros w ab suf h.
  - inversion h; subst; reflexivity.
  - cbn [peelABDigits] in h.
    destruct (peelDigit1 w) as [w1|] eqn:hd1.
    + destruct (peelABDigits c w1) as [[ab1 suf1]|] eqn:hrec; try discriminate.
      inversion h; subst ab suf.
      rewrite (peelDigit1_sound hd1), (ih _ _ _ hrec); cbn [evalABL]; rewrite app_assoc; reflexivity.
    + destruct (peelDigit2 w) as [w2|] eqn:hd2; try discriminate.
      destruct (peelABDigits c w2) as [[ab2 suf2]|] eqn:hrec; try discriminate.
      inversion h; subst ab suf.
      rewrite (peelDigit2_sound hd2), (ih _ _ _ hrec); cbn [evalABL]; rewrite app_assoc; reflexivity.
Qed.

Fixpoint prependABWord (ab : list ABWord) (q : N) : N :=
  match ab with
  | [] => q
  | AB_A :: xs => mul4Add1 (prependABWord xs q)
  | AB_B :: xs => mul4Add2 (prependABWord xs q)
  end.

Lemma decBits_prependABWord (ab : list ABWord) (q : N) :
  decBits (prependABWord ab q) = evalABL ab ++ decBits q.
Proof.
  induction ab as [|x xs ih]; [reflexivity |].
  destruct x; cbn [prependABWord evalABL];
  [rewrite decBits_mul4Add1 | rewrite decBits_mul4Add2];
  rewrite ih, app_assoc; reflexivity.
Qed.

Definition blkKind (bt : bool) : SymKind := if bt then S_W5 else S_Q8.

Definition prependOneBlk (bt : bool) (q : N) : N :=
  if bt then
    mul4Add2 (mul4Add1 (mul4Add2 (mul4Add1 (mul4Add1 (mul4Add1 (mul4Add2 q))))))
  else
    mul4Add1 (mul4Add1 (mul4Add1 (mul4Add1 (mul4Add1 (mul4Add1 (mul4Add1 (mul4Add1 (mul4Add2 q)))))))).

Lemma decBits_prependOneBlk (bt : bool) (q : N) :
  decBits (prependOneBlk bt q) = blkBitsL (blkKind bt) ++ decBits q.
Proof.
  destruct bt; unfold prependOneBlk, blkKind, blkBitsL;
  repeat (rewrite decBits_mul4Add1 || rewrite decBits_mul4Add2);
  cbn [bitsARn bitsA bitsB app]; reflexivity.
Qed.

Fixpoint prependBlksNat (bt : bool) (k : nat) (w : N) : N :=
  match k with
  | 0%nat => w
  | S k' => prependOneBlk bt (prependBlksNat bt k' w)
  end.

Definition prependBlks (bt : bool) (k w : N) : N :=
  prependBlksNat bt (N.to_nat k) w.

Lemma decBits_prependBlks (bt : bool) (k w : N) :
  decBits (prependBlks bt k w) = powBitsN (blkBitsL (blkKind bt)) k ++ decBits w.
Proof.
  unfold prependBlks, powBitsN.
  induction (N.to_nat k) as [|m ih]; [reflexivity |].
  cbn [prependBlksNat powBits].
  rewrite decBits_prependOneBlk, ih, app_assoc; reflexivity.
Qed.

Definition bindOpt {A B : Type} (x : option A) (f : A -> option B) : option B :=
  match x with Some a => f a | None => None end.

Definition stripOneBlk (bt : bool) (w : N) : option N :=
  if bt then
    bindOpt (peelDigit2 w) (fun w1 =>
    bindOpt (peelDigit1 w1) (fun w2 =>
    bindOpt (peelDigit2 w2) (fun w3 =>
    bindOpt (peelDigit1 w3) (fun w4 =>
    bindOpt (peelDigit1 w4) (fun w5 =>
    bindOpt (peelDigit1 w5) peelDigit2)))))
  else
    bindOpt (peelDigit1 w) (fun w1 =>
    bindOpt (peelDigit1 w1) (fun w2 =>
    bindOpt (peelDigit1 w2) (fun w3 =>
    bindOpt (peelDigit1 w3) (fun w4 =>
    bindOpt (peelDigit1 w4) (fun w5 =>
    bindOpt (peelDigit1 w5) (fun w6 =>
    bindOpt (peelDigit1 w6) (fun w7 =>
    bindOpt (peelDigit1 w7) peelDigit2))))))).

Lemma stripOneBlk_sound {bt : bool} {w w' : N} (h : stripOneBlk bt w = Some w') :
  decBits w = blkBitsL (blkKind bt) ++ decBits w'.
Proof.
  destruct bt; unfold stripOneBlk, bindOpt in h.
  - destruct (peelDigit2 w) as [w1|] eqn:e1; try discriminate.
    destruct (peelDigit1 w1) as [w2|] eqn:e2; try discriminate.
    destruct (peelDigit2 w2) as [w3|] eqn:e3; try discriminate.
    destruct (peelDigit1 w3) as [w4|] eqn:e4; try discriminate.
    destruct (peelDigit1 w4) as [w5|] eqn:e5; try discriminate.
    destruct (peelDigit1 w5) as [w6|] eqn:e6; try discriminate.
    rewrite (peelDigit2_sound e1), (peelDigit1_sound e2), (peelDigit2_sound e3),
            (peelDigit1_sound e4), (peelDigit1_sound e5), (peelDigit1_sound e6),
            (peelDigit2_sound h).
    cbn [blkKind blkBitsL bitsARn bitsA bitsB app]; reflexivity.
  - destruct (peelDigit1 w) as [w1|] eqn:e1; try discriminate.
    destruct (peelDigit1 w1) as [w2|] eqn:e2; try discriminate.
    destruct (peelDigit1 w2) as [w3|] eqn:e3; try discriminate.
    destruct (peelDigit1 w3) as [w4|] eqn:e4; try discriminate.
    destruct (peelDigit1 w4) as [w5|] eqn:e5; try discriminate.
    destruct (peelDigit1 w5) as [w6|] eqn:e6; try discriminate.
    destruct (peelDigit1 w6) as [w7|] eqn:e7; try discriminate.
    destruct (peelDigit1 w7) as [w8|] eqn:e8; try discriminate.
    rewrite (peelDigit1_sound e1), (peelDigit1_sound e2), (peelDigit1_sound e3),
            (peelDigit1_sound e4), (peelDigit1_sound e5), (peelDigit1_sound e6),
            (peelDigit1_sound e7), (peelDigit1_sound e8), (peelDigit2_sound h).
    cbn [blkKind blkBitsL bitsARn bitsA bitsB app]; reflexivity.
Qed.

Fixpoint stripBlks (bt : bool) (f : nat) (acc w : N) : N * N :=
  match f with
  | 0%nat => (acc, w)
  | S f' =>
      match stripOneBlk bt w with
      | Some w1 => stripBlks bt f' (acc + 1) w1
      | None => (acc, w)
      end
  end.

Lemma stripBlks_sound (bt : bool) (f : nat) (acc w : N) :
  let res := stripBlks bt f acc w in
  decBits w = powBitsN (blkBitsL (blkKind bt)) (fst res - acc) ++ decBits (snd res) /\
  acc <= fst res.
Proof.
  revert acc w; induction f as [|f ih]; intros acc w.
  - cbn [stripBlks fst snd]; replace (acc - acc) with 0 by lia; split; [reflexivity | lia].
  - cbn [stripBlks].
    destruct (stripOneBlk bt w) as [w1|] eqn:hs.
    + specialize (ih (acc + 1) w1); destruct ih as [hdec hle].
      split; [| lia].
      rewrite (stripOneBlk_sound hs), hdec.
      replace (fst (stripBlks bt f (acc + 1) w1) - acc)
        with (1 + (fst (stripBlks bt f (acc + 1) w1) - (acc + 1))) by lia.
      rewrite powBitsN_add, powBitsN_one, app_assoc; reflexivity.
    + cbn [fst snd]; replace (acc - acc) with 0 by lia; split; [reflexivity | lia].
Qed.

(* Balanced MSB-first 4-ary trees *)
Record P2 (A : Type) := P2C { p2_0 : A; p2_1 : A }.
Arguments P2C {A} _ _.
Arguments p2_0 {A} _.
Arguments p2_1 {A} _.

Record P4 (A : Type) := P4C { p4_0 : A; p4_1 : A; p4_2 : A; p4_3 : A }.
Arguments P4C {A} _ _ _ _.
Arguments p4_0 {A} _.
Arguments p4_1 {A} _.
Arguments p4_2 {A} _.
Arguments p4_3 {A} _.

Definition P16 (A : Type) : Type := P4 (P4 A).
Definition P64 (A : Type) : Type := P4 (P16 A).
Definition P256 (A : Type) : Type := P4 (P64 A).
Definition P1024 (A : Type) : Type := P4 (P256 A).
Definition P4096 (A : Type) : Type := P4 (P1024 A).
Definition P16384 (A : Type) : Type := P4 (P4096 A).
Definition P32768 (A : Type) : Type := P2 (P16384 A).

Definition get4 {A : Type} (t : P4 A) (b1 b0 : bool) : A :=
  if b1 then (if b0 then p4_3 t else p4_2 t) else (if b0 then p4_1 t else p4_0 t).

Definition get16 {A : Type} (t : P16 A) (idx : N) : A :=
  get4 (get4 t (N.testbit idx 3) (N.testbit idx 2)) (N.testbit idx 1) (N.testbit idx 0).

Definition get64 {A : Type} (t : P64 A) (idx : N) : A :=
  get16 (get4 t (N.testbit idx 5) (N.testbit idx 4)) idx.

Definition get256 {A : Type} (t : P256 A) (idx : N) : A :=
  get64 (get4 t (N.testbit idx 7) (N.testbit idx 6)) idx.

Definition get1024 {A : Type} (t : P1024 A) (idx : N) : A :=
  get256 (get4 t (N.testbit idx 9) (N.testbit idx 8)) idx.

Definition get4096 {A : Type} (t : P4096 A) (idx : N) : A :=
  get1024 (get4 t (N.testbit idx 11) (N.testbit idx 10)) idx.

Definition get16384 {A : Type} (t : P16384 A) (idx : N) : A :=
  get4096 (get4 t (N.testbit idx 13) (N.testbit idx 12)) idx.

Definition get32768 {A : Type} (t : P32768 A) (idx : N) : A :=
  get16384 (if N.testbit idx 14 then p2_1 t else p2_0 t) idx.

(* Unpacked hash bucket of active suffixes *)
Inductive SufBucket :=
  | SBN
  | SBC (suf osuf : N) (rest : SufBucket).

Fixpoint checkSufBucket (b : SufBucket) : bool :=
  match b with
  | SBN => true
  | SBC suf osuf rest =>
      match localGoTok fuel_1024 (decLTok suf) with
      | Some out =>
          match encLTok out with
          | Some o => N.eqb o osuf && checkSufBucket rest
          | None => false
          end
      | None => false
      end
  end.

Fixpoint lookupInBucket (b : SufBucket) (target : N) : option N :=
  match b with
  | SBN => None
  | SBC suf osuf rest =>
      if N.eqb suf target then Some osuf else lookupInBucket rest target
  end.

Lemma lookupInBucket_sound {b : SufBucket} {target osuf : N}
  (hchk : checkSufBucket b = true)
  (hlook : lookupInBucket b target = Some osuf)
  (prefAB : list ABWord) :
  RPlus (M_L LM_B, true :: bitsC ++ evalABL prefAB ++ decBits target, [])
        (M_L LM_B, true :: bitsC ++ blkBitsL S_P ++ evalABL prefAB ++ decBits osuf, []).
Proof.
  induction b as [|suf osuf0 rest ih]; [discriminate |].
  cbn [checkSufBucket] in hchk; cbn [lookupInBucket] in hlook.
  destruct (localGoTok fuel_1024 (decLTok suf)) as [out|] eqn:hloc; try discriminate.
  destruct (encLTok out) as [o|] eqn:henc; try discriminate.
  apply Bool.andb_true_iff in hchk; destruct hchk as [ho hrest].
  apply N.eqb_eq in ho.
  destruct (N.eqb suf target) eqn:hhit.
  - apply N.eqb_eq in hhit; inversion hlook; subst target osuf0 o.
    pose proof (localGoTok_sound hloc prefAB) as hrun.
    rewrite (evalL_decLTok 0 0 suf), (encLTok_sound henc) in hrun.
    exact hrun.
  - exact (ih hrest hlook).
Qed.

Definition sufPrime : N := 32749.

Definition lookupSuf (tbl : P32768 SufBucket) (target : N) : option N :=
  lookupInBucket (get32768 tbl (N.modulo target sufPrime)) target.

Definition ValidSufTbl (tbl : P32768 SufBucket) : Prop :=
  forall i : N, i < sufPrime -> checkSufBucket (get32768 tbl i) = true.

Lemma lookupSuf_sound {tbl : P32768 SufBucket} (hV : ValidSufTbl tbl)
  {target osuf : N} (hlook : lookupSuf tbl target = Some osuf)
  (prefAB : list ABWord) :
  RPlus (M_L LM_B, true :: bitsC ++ evalABL prefAB ++ decBits target, [])
        (M_L LM_B, true :: bitsC ++ blkBitsL S_P ++ evalABL prefAB ++ decBits osuf, []).
Proof.
  unfold lookupSuf in hlook.
  assert (hlt : N.modulo target sufPrime < sufPrime)
    by (apply N.mod_lt; unfold sufPrime; lia).
  exact (lookupInBucket_sound (hV _ hlt) hlook prefAB).
Qed.

Fixpoint checkSufRange (tbl : P32768 SufBucket) (lo : N) (c : nat) : bool :=
  match c with
  | 0%nat => true
  | S c' => checkSufBucket (get32768 tbl lo) && checkSufRange tbl (lo + 1) c'
  end.

Lemma checkSufRange_sound {tbl : P32768 SufBucket} {lo : N} {c : nat}
  (h : checkSufRange tbl lo c = true) :
  forall i : N, lo <= i -> i < lo + N.of_nat c -> checkSufBucket (get32768 tbl i) = true.
Proof.
  revert lo h; induction c as [|c ih]; intros lo h i h1 h2; [lia |].
  cbn [checkSufRange] in h; apply Bool.andb_true_iff in h; destruct h as [h0 hr].
  destruct (N.eq_dec i lo) as [-> | hne].
  - exact h0.
  - apply (ih (lo + 1) hr i); lia.
Qed.

(* Compact 12-bit and 16-bit hint list unpackers (witness decompression only; zero soundness burden) *)
Fixpoint unpackHintsFuel (sh : N) (mask : N) (fuel : nat) (n : N) : list N :=
  match fuel with
  | 0%nat => []
  | S f =>
      match n with
      | N0 => []
      | _ => (N.land n mask - 1) :: unpackHintsFuel sh mask f (N.shiftr n sh)
      end
  end.

Definition unpackHints (n : N) : list N := unpackHintsFuel 12 4095 fuel_1024 n.
Definition unpackHints16 (n : N) : list N := unpackHintsFuel 16 65535 fuel_1024 n.

(* ========================================================================= *)
(* Section 4: Aff Monoid & Symbolic Hub Engine                               *)
(* ========================================================================= *)

Record Aff := mkAff { aff_need : N; aff_add : N }.

Definition affId : Aff := mkAff 0 0.

Definition affComp (f g : Aff) : Aff :=
  mkAff (f.(aff_need) + (g.(aff_need) - f.(aff_add)))
        (g.(aff_add) + (f.(aff_add) - g.(aff_need))).

Lemma affComp_spec (f g : Aff) (x : N) (h : (affComp f g).(aff_need) <= x) :
  f.(aff_need) <= x /\
  g.(aff_need) <= x - f.(aff_need) + f.(aff_add) /\
  (x - f.(aff_need) + f.(aff_add)) - g.(aff_need) + g.(aff_add) =
    x - (affComp f g).(aff_need) + (affComp f g).(aff_add).
Proof.
  destruct f as [n1 a1], g as [n2 a2]; cbn in *; lia.
Qed.

Lemma affComp_assoc (a b c : Aff) : affComp (affComp a b) c = affComp a (affComp b c).
Proof.
  destruct a as [n1 a1], b as [n2 a2], c as [n3 a3]; unfold affComp; cbn; f_equal; lia.
Qed.

Lemma affComp_id_left (a : Aff) : affComp affId a = a.
Proof. destruct a as [n1 a1]; unfold affComp, affId; cbn; f_equal; lia. Qed.

Lemma affComp_id_right (a : Aff) : affComp a affId = a.
Proof. destruct a as [n1 a1]; unfold affComp, affId; cbn; f_equal; lia. Qed.

Definition blkLTok (k : SymKind) : list LTok :=
  match k with
  | S_P => [L_A 0; L_B; L_B]
  | S_Q3 => [L_A 2; L_B]
  | S_Q3_2 => [L_A 2; L_B; L_A 2; L_B]
  | S_R5 => [L_A 4; L_B; L_A 0; L_B]
  | S_W5 => [L_B; L_A 0; L_B; L_A 2; L_B]
  | S_Q8 => [L_A 7; L_B]
  end.

Definition blkRTok (k : SymKind) : list RTok :=
  match k with
  | S_P => [R_BR; R_BR; R_AR 0]
  | S_Q3 => [R_BR; R_AR 2]
  | S_Q3_2 => [R_BR; R_AR 2; R_BR; R_AR 2]
  | S_R5 => [R_BR; R_AR 0; R_BR; R_AR 4]
  | S_W5 => [R_BR; R_AR 2; R_BR; R_AR 0; R_BR]
  | S_Q8 => [R_BR; R_AR 7]
  end.

Definition blkAB (k : SymKind) : list ABWord :=
  match k with
  | S_P => [AB_A; AB_B; AB_B]
  | S_Q3 => [AB_A; AB_A; AB_A; AB_B]
  | S_Q3_2 => [AB_A; AB_A; AB_A; AB_B; AB_A; AB_A; AB_A; AB_B]
  | S_R5 => [AB_A; AB_A; AB_A; AB_A; AB_A; AB_B; AB_A; AB_B]
  | S_W5 => [AB_B; AB_A; AB_B; AB_A; AB_A; AB_A; AB_B]
  | S_Q8 => [AB_A; AB_A; AB_A; AB_A; AB_A; AB_A; AB_A; AB_A; AB_B]
  end.

Lemma evalL_blkLTok (n0 n1 : N) (k : SymKind) : evalL n0 n1 (blkLTok k) = blkBitsL k.
Proof. destruct k; reflexivity. Qed.

Lemma evalR_blkRTok (n0 n1 : N) (k : SymKind) : evalR n0 n1 (blkRTok k) = blkBitsR k.
Proof. destruct k; reflexivity. Qed.

Lemma evalABL_blkAB (k : SymKind) : evalABL (blkAB k) = blkBitsL k.
Proof. destruct k; reflexivity. Qed.

Lemma evalABR_blkAB_rev (k : SymKind) : evalABR (rev (blkAB k)) = blkBitsR k.
Proof. destruct k; reflexivity. Qed.

Fixpoint powList {A : Type} (b : list A) (n : nat) : list A :=
  match n with
  | 0%nat => []
  | S n' => b ++ powList b n'
  end.

Lemma powList_comm_one {A : Type} (b : list A) (n : nat) :
  b ++ powList b n = powList b n ++ b.
Proof.
  induction n as [|n ih]; [cbn; rewrite app_nil_r; reflexivity |].
  cbn [powList]; rewrite <- app_assoc, <- ih, app_assoc; reflexivity.
Qed.

Lemma powList_reverse {A : Type} (b : list A) (n : nat) :
  rev (powList (rev b) n) = powList b n.
Proof.
  induction n as [|n ih]; [reflexivity |].
  cbn [powList]; rewrite rev_app_distr, rev_involutive, ih, powList_comm_one; reflexivity.
Qed.

Definition powListN {A : Type} (b : list A) (n : N) : list A := powList b (N.to_nat n).

Lemma powListN_reverse {A : Type} (b : list A) (n : N) :
  rev (powListN (rev b) n) = powListN b n.
Proof. apply powList_reverse. Qed.

Lemma evalABL_powListN (k : SymKind) (n : N) :
  evalABL (powListN (blkAB k) n) = powBitsN (blkBitsL k) n.
Proof.
  unfold powListN, powBitsN; induction (N.to_nat n) as [|m ih]; [reflexivity |].
  cbn [powList powBits]; rewrite evalABL_append, evalABL_blkAB, ih; reflexivity.
Qed.

Lemma evalABR_powListN_rev (k : SymKind) (n : N) :
  evalABR (powListN (rev (blkAB k)) n) = powBitsN (blkBitsR k) n.
Proof.
  unfold powListN, powBitsN; induction (N.to_nat n) as [|m ih]; [reflexivity |].
  cbn [powList powBits]; rewrite evalABR_append, evalABR_blkAB_rev, ih; reflexivity.
Qed.

Fixpoint noVarL (v : bool) (l : list LTok) : bool :=
  match l with
  | [] => true
  | L_sym _ v' :: xs => negb (Bool.eqb v v') && noVarL v xs
  | _ :: xs => noVarL v xs
  end.

Fixpoint noVarR (v : bool) (r : list RTok) : bool :=
  match r with
  | [] => true
  | R_sym _ v' :: xs => negb (Bool.eqb v v') && noVarR v xs
  | _ :: xs => noVarR v xs
  end.

Lemma evalL_noVar_false {n0 n0' n1 : N} {l : list LTok} (h : noVarL false l = true) :
  evalL n0 n1 l = evalL n0' n1 l.
Proof.
  induction l as [|x xs ih]; [reflexivity |].
  destruct x as [| |k| | |k v]; cbn [noVarL evalL] in *;
    try (rewrite (ih h); reflexivity).
  destruct v; [cbn in h; rewrite (ih h); reflexivity | discriminate].
Qed.

Lemma evalL_noVar_true {n0 n1 n1' : N} {l : list LTok} (h : noVarL true l = true) :
  evalL n0 n1 l = evalL n0 n1' l.
Proof.
  induction l as [|x xs ih]; [reflexivity |].
  destruct x as [| |k| | |k v]; cbn [noVarL evalL] in *;
    try (rewrite (ih h); reflexivity).
  destruct v; [discriminate | cbn in h; rewrite (ih h); reflexivity].
Qed.

Lemma evalR_noVar_false {n0 n0' n1 : N} {r : list RTok} (h : noVarR false r = true) :
  evalR n0 n1 r = evalR n0' n1 r.
Proof.
  induction r as [|x xs ih]; [reflexivity |].
  destruct x as [| |k| |k v]; cbn [noVarR evalR] in *;
    try (rewrite (ih h); reflexivity).
  destruct v; [cbn in h; rewrite (ih h); reflexivity | discriminate].
Qed.

Lemma evalR_noVar_true {n0 n1 n1' : N} {r : list RTok} (h : noVarR true r = true) :
  evalR n0 n1 r = evalR n0 n1' r.
Proof.
  induction r as [|x xs ih]; [reflexivity |].
  destruct x as [| |k| |k v]; cbn [noVarR evalR] in *;
    try (rewrite (ih h); reflexivity).
  destruct v; [discriminate | cbn in h; rewrite (ih h); reflexivity].
Qed.

Lemma evalL_peel {k : SymKind} {v : bool} {xs : list LTok} (h : noVarL v xs = true)
  (n0 n1 : N) (hge : if v then 1 <= n1 else 1 <= n0) :
  evalL n0 n1 (L_sym k v :: xs) =
    evalL (if v then n0 else n0 - 1) (if v then n1 - 1 else n1) (blkLTok k ++ L_sym k v :: xs).
Proof.
  destruct v.
  - rewrite evalL_append, evalL_blkLTok; cbn [evalL].
    replace n1 with ((n1 - 1) + 1) at 1 by lia.
    rewrite powBitsN_succ, <- app_assoc.
    f_equal; f_equal; exact (evalL_noVar_true (n1 := n1) (n1' := n1 - 1) h).
  - rewrite evalL_append, evalL_blkLTok; cbn [evalL].
    replace n0 with ((n0 - 1) + 1) at 1 by lia.
    rewrite powBitsN_succ, <- app_assoc.
    f_equal; f_equal; exact (evalL_noVar_false (n0 := n0) (n0' := n0 - 1) h).
Qed.

Lemma evalR_peel {k : SymKind} {v : bool} {xs : list RTok} (h : noVarR v xs = true)
  (n0 n1 : N) (hge : if v then 1 <= n1 else 1 <= n0) :
  evalR n0 n1 (R_sym k v :: xs) =
    evalR (if v then n0 else n0 - 1) (if v then n1 - 1 else n1) (blkRTok k ++ R_sym k v :: xs).
Proof.
  destruct v.
  - rewrite evalR_append, evalR_blkRTok; cbn [evalR].
    replace n1 with ((n1 - 1) + 1) at 1 by lia.
    rewrite powBitsN_succ, <- app_assoc.
    f_equal; f_equal; exact (evalR_noVar_true (n1 := n1) (n1' := n1 - 1) h).
  - rewrite evalR_append, evalR_blkRTok; cbn [evalR].
    replace n0 with ((n0 - 1) + 1) at 1 by lia.
    rewrite powBitsN_succ, <- app_assoc.
    f_equal; f_equal; exact (evalR_noVar_false (n0 := n0) (n0' := n0 - 1) h).
Qed.

Fixpoint appendLTok (xs ys : list LTok) : list LTok :=
  match xs with
  | [] => ys
  | L_A k :: [] => pushLA k ys
  | x :: xs' => x :: appendLTok xs' ys
  end.

Lemma evalL_appendLTok (n0 n1 : N) (xs ys : list LTok) :
  evalL n0 n1 (appendLTok xs ys) = evalL n0 n1 xs ++ evalL n0 n1 ys.
Proof.
  induction xs as [|x xs ih]; [reflexivity |].
  destruct x as [| |k| | |kv vv];
    try (cbn [appendLTok evalL app]; rewrite ih, ?app_assoc; reflexivity).
  destruct xs as [|y zs].
  - cbn [appendLTok evalL]; rewrite evalL_pushLA, app_nil_r; reflexivity.
  - change (appendLTok (L_A k :: y :: zs) ys) with (L_A k :: appendLTok (y :: zs) ys).
    cbn [evalL]; rewrite ih, app_assoc; reflexivity.
Qed.

Definition pushR0C (r : list RTok) : list RTok :=
  match r with
  | [] => []
  | R_b0 :: R_b0 :: R_b1 :: xs => R_BR :: xs
  | R_b0 :: R_AR 0 :: xs => R_BR :: xs
  | R_b0 :: R_AR (S k) :: xs => R_BR :: R_AR k :: xs
  | R_b1 :: xs => pushRAR 0 xs
  | xs => R_b0 :: xs
  end.

Lemma evalR_pushR0C (n0 n1 : N) (r : list RTok) :
  EqBits (evalR n0 n1 (pushR0C r)) (false :: evalR n0 n1 r).
Proof.
  destruct r as [|[| |[|k]| |kv vv] r1]; [exact (eqBits_symm eqBits_zero_nil) | ..];
    try (cbn [pushR0C evalR]; apply eqBits_refl).
  - destruct r1 as [|[| |[|k]| |kv vv] r2]; try (cbn [pushR0C evalR]; apply eqBits_refl).
    destruct r2 as [|[| |k| |kv vv] r3]; cbn [pushR0C evalR bitsBR app]; apply eqBits_refl.
  - cbn [pushR0C]; rewrite evalR_pushRAR; apply eqBits_refl.
Qed.

Definition popL0C (l : list LTok) : option (list LTok) :=
  match l with
  | [] => Some []
  | L_b0 :: xs => Some xs
  | L_A 0 :: xs => Some (L_b1 :: xs)
  | L_A (S k) :: xs => Some (L_b1 :: L_A k :: xs)
  | L_B :: xs => Some (L_b1 :: L_b1 :: L_b1 :: xs)
  | L_C :: xs => Some (L_B :: xs)
  | _ => None
  end.

Lemma evalL_popL0C {n0 n1 : N} {l l' : list LTok} (h : popL0C l = Some l') :
  EqBits (evalL n0 n1 l) (false :: evalL n0 n1 l').
Proof.
  destruct l as [|[| |[|k]| | |kv vv] xs]; cbn [popL0C] in h; try discriminate;
  inversion h; subst l';
  [exact (eqBits_symm eqBits_zero_nil) | apply eqBits_refl ..].
Qed.

Lemma evalL_pushL0_closed (n0 n1 : N) (l : list LTok) :
  EqBits (evalL n0 n1 (pushL0 true l)) (false :: evalL n0 n1 l).
Proof.
  pose proof (evalL_pushL0 (allowEmpty := true) (n0 := n0) (n1 := n1) (l := l) (lBot := []) (fun _ => eq_refl)) as h.
  rewrite !app_nil_r in h; exact h.
Qed.

(* Symbolic hub step results & validity predicate *)
Inductive SymStep :=
  | SS_toL (isC : bool) (l : list LTok) (r : list RTok) (p0 p1 : N)
  | SS_toR (isA : bool) (l : list LTok) (r : list RTok) (p0 p1 : N)
  | SS_done (out : list LTok) (p0 p1 dM : N)
  | SS_fail.

Definition addPeel (v : bool) (st : SymStep) : SymStep :=
  match st with
  | SS_toL m l r p0 p1 => if v then SS_toL m l r p0 (p1 + 1) else SS_toL m l r (p0 + 1) p1
  | SS_toR m l r p0 p1 => if v then SS_toR m l r p0 (p1 + 1) else SS_toR m l r (p0 + 1) p1
  | SS_done out p0 p1 dM => if v then SS_done out p0 (p1 + 1) dM else SS_done out (p0 + 1) p1 dM
  | SS_fail => SS_fail
  end.

Definition SymStepValid (m : Mode) (l : list LTok) (r : list RTok) (st : SymStep) : Prop :=
  match st with
  | SS_toL m' l' r' p0 p1 =>
      forall n0 n1 : N, p0 <= n0 -> p1 <= n1 ->
        RPlus (m, evalL n0 n1 l, evalR n0 n1 r)
              (M_L (if m' then LM_C else LM_B), evalL (n0 - p0) (n1 - p1) l', evalR (n0 - p0) (n1 - p1) r')
  | SS_toR m' l' r' p0 p1 =>
      forall n0 n1 : N, p0 <= n0 -> p1 <= n1 ->
        RPlus (m, evalL n0 n1 l, evalR n0 n1 r)
              (M_R (if m' then RM_A else RM_D), evalL (n0 - p0) (n1 - p1) l', evalR (n0 - p0) (n1 - p1) r')
  | SS_done out p0 p1 dM =>
      forall n0 n1 : N, p0 <= n0 -> p1 <= n1 ->
        RPlus (m, evalL n0 n1 l, evalR n0 n1 r)
              (M_L LM_B, evalL (n0 - p0 + dM) (n1 - p1) out, [])
  | SS_fail => True
  end.

Lemma symStepValid_of_rPlus {m1 m2 : Mode} {l1 l2 : list LTok} {r1 r2 : list RTok} {st : SymStep}
  (h1 : forall n0 n1 : N, RPlus (m1, evalL n0 n1 l1, evalR n0 n1 r1) (m2, evalL n0 n1 l2, evalR n0 n1 r2))
  (h2 : SymStepValid m2 l2 r2 st) :
  SymStepValid m1 l1 r1 st.
Proof.
  destruct st; [.. | exact I]; intros n0 n1 h0 h1'; exact (rPlus_trans (h1 n0 n1) (h2 n0 n1 h0 h1')).
Qed.

Lemma symStepValid_of_rStar {m1 m2 : Mode} {l1 l2 : list LTok} {r1 r2 : list RTok} {st : SymStep}
  (h1 : forall n0 n1 : N, RStar (m1, evalL n0 n1 l1, evalR n0 n1 r1) (m2, evalL n0 n1 l2, evalR n0 n1 r2))
  (h2 : SymStepValid m2 l2 r2 st) :
  SymStepValid m1 l1 r1 st.
Proof.
  destruct st; [.. | exact I]; intros n0 n1 h0 h1'; exact (rStar_trans_plus (h1 n0 n1) (h2 n0 n1 h0 h1')).
Qed.

Lemma addPeel_valid {m : Mode} {l l' : list LTok} {r r' : list RTok} {v : bool} {st : SymStep}
  (hL : forall n0 n1 : N, (if v then 1 <= n1 else 1 <= n0) ->
    evalL n0 n1 l = evalL (if v then n0 else n0 - 1) (if v then n1 - 1 else n1) l')
  (hR : forall n0 n1 : N, (if v then 1 <= n1 else 1 <= n0) ->
    evalR n0 n1 r = evalR (if v then n0 else n0 - 1) (if v then n1 - 1 else n1) r')
  (h : SymStepValid m l' r' st) :
  SymStepValid m l r (addPeel v st).
Proof.
  destruct st as [m2 l2 r2 p0 p1 | m2 l2 r2 p0 p1 | out p0 p1 dM |]; [.. | exact I];
  destruct v; cbn [addPeel SymStepValid] in *; intros n0 n1 h0 h1.
  - assert (hge : 1 <= n1) by lia.
    rewrite (hL n0 n1 hge), (hR n0 n1 hge).
    pose proof (h n0 (n1 - 1) h0 ltac:(lia)) as hr.
    replace (n1 - 1 - p1) with (n1 - (p1 + 1)) in hr by lia; exact hr.
  - assert (hge : 1 <= n0) by lia.
    rewrite (hL n0 n1 hge), (hR n0 n1 hge).
    pose proof (h (n0 - 1) n1 ltac:(lia) h1) as hr.
    replace (n0 - 1 - p0) with (n0 - (p0 + 1)) in hr by lia; exact hr.
  - assert (hge : 1 <= n1) by lia.
    rewrite (hL n0 n1 hge), (hR n0 n1 hge).
    pose proof (h n0 (n1 - 1) h0 ltac:(lia)) as hr.
    replace (n1 - 1 - p1) with (n1 - (p1 + 1)) in hr by lia; exact hr.
  - assert (hge : 1 <= n0) by lia.
    rewrite (hL n0 n1 hge), (hR n0 n1 hge).
    pose proof (h (n0 - 1) n1 ltac:(lia) h1) as hr.
    replace (n0 - 1 - p0) with (n0 - (p0 + 1)) in hr by lia; exact hr.
  - assert (hge : 1 <= n1) by lia.
    rewrite (hL n0 n1 hge), (hR n0 n1 hge).
    pose proof (h n0 (n1 - 1) h0 ltac:(lia)) as hr.
    replace (n1 - 1 - p1) with (n1 - (p1 + 1)) in hr by lia; exact hr.
  - assert (hge : 1 <= n0) by lia.
    rewrite (hL n0 n1 hge), (hR n0 n1 hge).
    pose proof (h (n0 - 1) n1 ltac:(lia) h1) as hr.
    replace (n0 - 1 - p0) with (n0 - (p0 + 1)) in hr by lia; exact hr.
Qed.

Fixpoint isCleanBodyL (l : list LTok) : bool :=
  match l with
  | [] => true
  | L_A _ :: xs | L_B :: xs | L_C :: xs | L_sym _ _ :: xs => isCleanBodyL xs
  | _ => false
  end.

Definition isCleanHubL (l : list LTok) : bool :=
  match l with
  | L_b1 :: xs => isCleanBodyL xs
  | xs => isCleanBodyL xs
  end.

Fixpoint revRToSymLTok (r : list RTok) (acc : list LTok) : option (list LTok) :=
  match r with
  | [] => Some acc
  | R_AR k :: r' => revRToSymLTok r' (pushLA k acc)
  | R_BR :: r' => revRToSymLTok r' (L_B :: acc)
  | R_sym k v :: r' => revRToSymLTok r' (L_sym k v :: acc)
  | _ => None
  end.

Fixpoint endsWithAR (r : list RTok) : bool :=
  match r with
  | [] => false
  | R_AR _ :: [] => true
  | _ :: xs => endsWithAR xs
  end.

Lemma revRToSymLTok_spec (n0 n1 : N) {r : list RTok} {acc out : list LTok}
  (h : revRToSymLTok r acc = Some out) :
  exists w : list ABWord,
    (endsWithAR r = true -> exists u, w = u ++ [AB_A]) /\
    evalR n0 n1 r = evalABR w /\
    evalL n0 n1 out = evalABL (rev w) ++ evalL n0 n1 acc.
Proof.
  revert acc h; induction r as [|x xs ih]; intros acc h.
  - inversion h; subst; exists (@nil ABWord); repeat split; intro hc; discriminate.
  - destruct x as [| |k| |k v]; cbn [revRToSymLTok] in h; try discriminate.
    + destruct (ih _ h) as [w [hEnd [hR hL]]].
      exists (abWordA k ++ w); repeat split.
      * intro he.
        destruct xs as [|y ys].
        -- cbn [revRToSymLTok] in h.
           assert (hw0 : evalABR w = []) by (rewrite <- hR; reflexivity).
           destruct w as [|[|] ws]; try discriminate.
           clear h hR hL hEnd hw0 he.
           assert (hA : exists u, abWordA k = u ++ [AB_A]).
           { induction k as [|k' [u hu]]; [exists (@nil ABWord); reflexivity | exists (AB_A :: u); cbn; rewrite hu; reflexivity]. }
           destruct hA as [u hu]; exists u; rewrite app_nil_r; exact hu.
        -- destruct (hEnd he) as [u hu]; exists (abWordA k ++ u); rewrite hu, app_assoc; reflexivity.
      * cbn [evalR]; rewrite evalABR_append, evalABR_abWordA, hR; reflexivity.
      * rewrite rev_app_distr, evalABL_append, evalABL_abWordA_rev, hL, evalL_pushLA, app_assoc; reflexivity.
    + destruct (ih _ h) as [w [hEnd [hR hL]]].
      exists (AB_B :: w); repeat split.
      * intro he; destruct (hEnd he) as [u hu]; exists (AB_B :: u); rewrite hu; reflexivity.
      * cbn [evalR evalABR]; rewrite hR; reflexivity.
      * cbn [rev]; rewrite evalABL_append, hL; cbn [evalABL evalL app]; rewrite <- app_assoc; reflexivity.
    + destruct (ih _ h) as [w [hEnd [hR hL]]].
      exists (powListN (rev (blkAB k)) (if v then n1 else n0) ++ w); repeat split.
      * intro he; destruct (hEnd he) as [u hu].
        exists (powListN (rev (blkAB k)) (if v then n1 else n0) ++ u); rewrite hu, app_assoc; reflexivity.
      * cbn [evalR]; rewrite evalABR_append, evalABR_powListN_rev, hR; reflexivity.
      * rewrite rev_app_distr, powListN_reverse, evalABL_append, evalABL_powListN, hL;
        cbn [evalL]; rewrite app_assoc; reflexivity.
Qed.

Fixpoint stripRP (r : list RTok) : option (bool * list RTok) :=
  match r with
  | R_sym S_P v :: rRest => Some (v, rRest)
  | R_BR :: R_BR :: R_AR 0 :: r1 =>
      match stripRP r1 with
      | Some (v, rRest) => Some (v, R_BR :: R_BR :: R_AR 0 :: rRest)
      | None => None
      end
  | _ => None
  end.

Lemma stripRP_spec (n0 n1 : N) {r rOut : list RTok} {v : bool} (h : stripRP r = Some (v, rOut)) :
  exists (j : N) (rRest : list bool),
    evalR n0 n1 r = powBitsN (blkBitsR S_P) j ++ powBitsN (blkBitsR S_P) (if v then n1 else n0) ++ rRest /\
    evalR n0 n1 rOut = powBitsN (blkBitsR S_P) j ++ rRest.
Proof.
  assert (Hgen : forall (m : nat) (rx rOutx : list RTok) (vx : bool),
    (length rx <= m)%nat -> stripRP rx = Some (vx, rOutx) ->
    exists (j : N) (rRest : list bool),
      evalR n0 n1 rx = powBitsN (blkBitsR S_P) j ++ powBitsN (blkBitsR S_P) (if vx then n1 else n0) ++ rRest /\
      evalR n0 n1 rOutx = powBitsN (blkBitsR S_P) j ++ rRest).
  { induction m as [|m ih]; intros rx rOutx vx hlen hx.
    - destruct rx; [discriminate | cbn in hlen; lia].
    - destruct rx as [|[| |k1| |ks1 v1] r1]; cbn [stripRP] in hx; try discriminate.
      + destruct r1 as [|[| |k2| |ks2 v2] r2]; try discriminate.
        destruct r2 as [|[| |[|k3]| |ks3 v3] r3]; try discriminate.
        destruct (stripRP r3) as [[v' rRest']|] eqn:hs; try discriminate.
        inversion hx; subst vx rOutx.
        destruct (ih r3 rRest' v' ltac:(cbn in hlen; lia) hs) as [j [rRest [h1 h2]]].
        exists (j + 1), rRest; split;
          cbn [evalR]; rewrite ?h1, ?h2, powBitsN_succ; cbn [blkBitsR bitsARn bitsAR app]; reflexivity.
      + destruct ks1; try discriminate.
        inversion hx; subst v1 r1.
        exists 0, (evalR n0 n1 rOutx); split; reflexivity. }
  exact (Hgen (length r) r rOut v (Nat.le_refl _) h).
Qed.

Fixpoint stripRQ3 (r : list RTok) : option (bool * list RTok) :=
  match r with
  | R_sym S_Q3_2 v :: rRest => Some (v, rRest)
  | R_BR :: R_AR 2 :: r1 =>
      match stripRQ3 r1 with
      | Some (v, rRest) => Some (v, R_BR :: R_AR 2 :: rRest)
      | None => None
      end
  | _ => None
  end.

Lemma stripRQ3_spec (n0 n1 : N) {r rOut : list RTok} {v : bool} (h : stripRQ3 r = Some (v, rOut)) :
  exists (j : N) (rRest : list bool),
    evalR n0 n1 r = powBitsN (blkBitsR S_Q3) j ++ powBitsN (blkBitsR S_Q3_2) (if v then n1 else n0) ++ rRest /\
    evalR n0 n1 rOut = powBitsN (blkBitsR S_Q3) j ++ rRest.
Proof.
  assert (Hgen : forall (m : nat) (rx rOutx : list RTok) (vx : bool),
    (length rx <= m)%nat -> stripRQ3 rx = Some (vx, rOutx) ->
    exists (j : N) (rRest : list bool),
      evalR n0 n1 rx = powBitsN (blkBitsR S_Q3) j ++ powBitsN (blkBitsR S_Q3_2) (if vx then n1 else n0) ++ rRest /\
      evalR n0 n1 rOutx = powBitsN (blkBitsR S_Q3) j ++ rRest).
  { induction m as [|m ih]; intros rx rOutx vx hlen hx.
    - destruct rx; [discriminate | cbn in hlen; lia].
    - destruct rx as [|[| |k1| |ks1 v1] r1]; cbn [stripRQ3] in hx; try discriminate.
      + destruct r1 as [|[| |[|[|[|k2]]]| |ks2 v2] r2]; try discriminate.
        destruct (stripRQ3 r2) as [[v' rRest']|] eqn:hs; try discriminate.
        inversion hx; subst vx rOutx.
        destruct (ih r2 rRest' v' ltac:(cbn in hlen; lia) hs) as [j [rRest [h1 h2]]].
        exists (j + 1), rRest; split;
          cbn [evalR]; rewrite ?h1, ?h2, powBitsN_succ; cbn [blkBitsR bitsARn app]; reflexivity.
      + destruct ks1; try discriminate.
        inversion hx; subst v1 r1.
        exists 0, (evalR n0 n1 rOutx); split; reflexivity. }
  exact (Hgen (length r) r rOut v (Nat.le_refl _) h).
Qed.

Fixpoint stripRR5 (r : list RTok) : option (bool * list RTok) :=
  match r with
  | R_sym S_R5 v :: rRest => Some (v, rRest)
  | R_BR :: R_AR 0 :: R_BR :: R_AR 4 :: r1 =>
      match stripRR5 r1 with
      | Some (v, rRest) => Some (v, R_BR :: R_AR 0 :: R_BR :: R_AR 4 :: rRest)
      | None => None
      end
  | _ => None
  end.

Lemma stripRR5_spec (n0 n1 : N) {r rOut : list RTok} {v : bool} (h : stripRR5 r = Some (v, rOut)) :
  exists (j : N) (rRest : list bool),
    evalR n0 n1 r = powBitsN (blkBitsR S_R5) j ++ powBitsN (blkBitsR S_R5) (if v then n1 else n0) ++ rRest /\
    evalR n0 n1 rOut = powBitsN (blkBitsR S_R5) j ++ rRest.
Proof.
  assert (Hgen : forall (m : nat) (rx rOutx : list RTok) (vx : bool),
    (length rx <= m)%nat -> stripRR5 rx = Some (vx, rOutx) ->
    exists (j : N) (rRest : list bool),
      evalR n0 n1 rx = powBitsN (blkBitsR S_R5) j ++ powBitsN (blkBitsR S_R5) (if vx then n1 else n0) ++ rRest /\
      evalR n0 n1 rOutx = powBitsN (blkBitsR S_R5) j ++ rRest).
  { induction m as [|m ih]; intros rx rOutx vx hlen hx.
    - destruct rx; [discriminate | cbn in hlen; lia].
    - destruct rx as [|[| |k1| |ks1 v1] r1]; cbn [stripRR5] in hx; try discriminate.
      + destruct r1 as [|[| |[|k2]| |ks2 v2] r2]; try discriminate.
        destruct r2 as [|[| |k3| |ks3 v3] r3]; try discriminate.
        destruct r3 as [|[| |[|[|[|[|[|k4]]]]]| |ks4 v4] r4]; try discriminate.
        destruct (stripRR5 r4) as [[v' rRest']|] eqn:hs; try discriminate.
        inversion hx; subst vx rOutx.
        destruct (ih r4 rRest' v' ltac:(cbn in hlen; lia) hs) as [j [rRest [h1 h2]]].
        exists (j + 1), rRest; split;
          cbn [evalR]; rewrite ?h1, ?h2, powBitsN_succ; cbn [blkBitsR bitsARn bitsAR app]; reflexivity.
      + destruct ks1; try discriminate.
        inversion hx; subst v1 r1.
        exists 0, (evalR n0 n1 rOutx); split; reflexivity. }
  exact (Hgen (length r) r rOut v (Nat.le_refl _) h).
Qed.

Definition symApplyRuleOnce (l : list LTok) (r : list RTok) : option (list LTok * list RTok) :=
  match l, r with
  | L_b1 :: L_C :: L_A 2 :: L_C :: lRest, R_b0 :: r1 =>
      match stripRP r1 with
      | Some (v, rOut) => Some (L_b1 :: L_C :: L_A 2 :: L_C :: L_sym S_Q3 v :: lRest, pushR0C rOut)
      | None =>
          match r1 with
          | R_AR 3 :: r2 =>
              match stripRR5 r2 with
              | Some (v, rOut) => Some (L_b1 :: L_C :: L_A 2 :: L_C :: L_sym S_W5 v :: lRest, R_b0 :: R_AR 3 :: rOut)
              | None => None
              end
          | _ => None
          end
      end
  | L_b1 :: L_C :: L_A 4 :: L_C :: L_A 0 :: L_B :: lRest, R_b0 :: R_AR 1 :: r1 =>
      match stripRQ3 r1 with
      | Some (v, rOut) => Some (L_b1 :: L_C :: L_A 4 :: L_C :: L_A 0 :: L_B :: L_sym S_R5 v :: lRest, R_b0 :: R_AR 1 :: rOut)
      | None => None
      end
  | L_b1 :: L_C :: L_A 7 :: L_C :: lRest, R_b0 :: R_BR :: R_AR 4 :: r1 =>
      match stripRR5 r1 with
      | Some (v, rOut) => Some (L_b1 :: L_C :: L_A 7 :: L_C :: L_sym S_Q8 v :: lRest, R_b0 :: R_BR :: R_AR 4 :: rOut)
      | None => None
      end
  | _, _ => None
  end.

Lemma symApplyRuleOnce_sound (n0 n1 : N) {l l' : list LTok} {r r' : list RTok}
  (h : symApplyRuleOnce l r = Some (l', r')) :
  RStar (M_L LM_B, evalL n0 n1 l, evalR n0 n1 r) (M_L LM_B, evalL n0 n1 l', evalR n0 n1 r').
Proof.
  destruct l as [|[| | | | | ] l1]; try discriminate.
  destruct l1 as [|[| | | | | ] l2]; try discriminate.
  destruct l2 as [|[| |k| | | ] l3]; try discriminate.
  destruct k as [|[|[|k']]].
  - discriminate.
  - discriminate.
  - (* k = 2: P->Q3 or R5->W5 *)
    destruct l3 as [|[| | | | | ] lRest]; try discriminate.
    destruct r as [|[| | | | ] r1]; try discriminate.
    cbn [symApplyRuleOnce] in h.
    destruct (stripRP r1) as [[v rOut]|] eqn:hs.
    + inversion h; subst l' r'.
      destruct (stripRP_spec n0 n1 hs) as [j [rRest [h1 h2]]].
      pose proof (pass_P_Q3 j (if v then n1 else n0) (evalL n0 n1 lRest) rRest) as hp.
      assert (hEqR : EqBits (evalR n0 n1 (pushR0C rOut)) (false :: (powBitsN (blkBitsR S_P) j ++ rRest)))
        by (rewrite <- h2; apply evalR_pushR0C).
      cbn [evalL evalR]; rewrite h1.
      cbn [app] in hp |- *; repeat rewrite <- app_assoc in hp; repeat rewrite <- app_assoc.
      exact (rStar_congr (eqBits_refl _) (eqBits_refl _) (eqBits_refl _) hEqR hp).
    + destruct r1 as [|[| |[|[|[|[|]]]]| | ] r2]; try discriminate.
      destruct (stripRR5 r2) as [[v rOut]|] eqn:hs5; try discriminate.
      inversion h; subst l' r'.
      destruct (stripRR5_spec n0 n1 hs5) as [j [rRest [h1 h2]]].
      pose proof (pass_R5_W5 j (if v then n1 else n0) (evalL n0 n1 lRest) rRest) as hp.
      cbn [evalL evalR]; rewrite h1, h2.
      cbn [app] in hp |- *; repeat rewrite <- app_assoc in hp; repeat rewrite <- app_assoc; exact hp.
  - (* k = 3.. *)
    destruct k' as [|[|k'']].
    + discriminate.
    + (* k = 4: Q3_2 -> R5 *)
      destruct l3 as [|[| | | | | ] l4]; try discriminate.
      destruct l4 as [|[| |[|]| | | ] l5]; try discriminate.
      destruct l5 as [|[| | | | | ] lRest]; try discriminate.
      destruct r as [|[| | | | ] r0]; try discriminate.
      destruct r0 as [|[| |[|[|]]| | ] r1]; try discriminate.
      cbn [symApplyRuleOnce] in h.
      destruct (stripRQ3 r1) as [[v rOut]|] eqn:hs; try discriminate.
      inversion h; subst l' r'.
      destruct (stripRQ3_spec n0 n1 hs) as [j [rRest [h1 h2]]].
      pose proof (pass_Q32_R5 j (if v then n1 else n0) (evalL n0 n1 lRest) rRest) as hp.
      cbn [evalL evalR]; rewrite h1, h2.
      cbn [bitsA bitsARn app] in hp |- *; repeat rewrite <- app_assoc in hp; repeat rewrite <- app_assoc; exact hp.
    + destruct k'' as [|[|[|]]]; try discriminate.
      (* k = 7: R5 -> Q8 *)
      destruct l3 as [|[| | | | | ] lRest]; try discriminate.
      destruct r as [|[| | | | ] r0]; try discriminate.
      destruct r0 as [|[| | | | ] r0']; try discriminate.
      destruct r0' as [|[| |[|[|[|[|[|]]]]]| | ] r1]; try discriminate.
      cbn [symApplyRuleOnce] in h.
      destruct (stripRR5 r1) as [[v rOut]|] eqn:hs; try discriminate.
      inversion h; subst l' r'.
      destruct (stripRR5_spec n0 n1 hs) as [j [rRest [h1 h2]]].
      pose proof (pass_R5_Q8 j (if v then n1 else n0) (evalL n0 n1 lRest) rRest) as hp.
      cbn [evalL evalR]; rewrite h1, h2.
      cbn [app] in hp |- *; repeat rewrite <- app_assoc in hp; repeat rewrite <- app_assoc; exact hp.
Qed.

Fixpoint symApplyRulesLoop (k : nat) (l : list LTok) (r : list RTok) : list LTok * list RTok :=
  match k with
  | 0%nat => (l, r)
  | S k' =>
      match symApplyRuleOnce l r with
      | Some (l', r') => symApplyRulesLoop k' l' r'
      | None => (l, r)
      end
  end.

Lemma symApplyRulesLoop_sound (n0 n1 : N) (k : nat) (l : list LTok) (r : list RTok) :
  RStar (M_L LM_B, evalL n0 n1 l, evalR n0 n1 r)
        (M_L LM_B, evalL n0 n1 (fst (symApplyRulesLoop k l r)), evalR n0 n1 (snd (symApplyRulesLoop k l r))).
Proof.
  revert l r; induction k as [|k ih]; intros l r; [apply rStar_refl |].
  cbn [symApplyRulesLoop].
  destruct (symApplyRuleOnce l r) as [[l' r']|] eqn:hs.
  - exact (rStar_trans (symApplyRuleOnce_sound n0 n1 hs) (ih l' r')).
  - apply rStar_refl.
Qed.

Definition isEmpty {A : Type} (xs : list A) : bool :=
  match xs with [] => true | _ => false end.

Definition symAbsorbOrOut (absorbP0 : bool) (out : list LTok) : SymStep :=
  if absorbP0 then
    match out with
    | L_A 0 :: L_B :: L_B :: L_sym S_P false :: rest =>
        if noVarL false rest then SS_done (L_b1 :: L_C :: L_sym S_P false :: rest) 0 0 1
        else SS_done (L_b1 :: L_C :: out) 0 0 0
    | _ => SS_done (L_b1 :: L_C :: out) 0 0 0
    end
  else
    SS_done (L_b1 :: L_C :: out) 0 0 0.

Definition symFinishLBTail (absorbP0 : bool) (l : list LTok) (r : list RTok) : SymStep :=
  match l, r with
  | L_b1 :: L_B :: L_C :: rem, R_b0 :: rRest =>
      if isCleanBodyL rem && endsWithAR rRest then
        match revRToSymLTok rRest (L_B :: L_B :: rem) with
        | Some out => symAbsorbOrOut absorbP0 out
        | None => SS_toL false (L_b1 :: L_B :: L_C :: rem) (R_b0 :: rRest) 0 0
        end
      else SS_toL false (L_b1 :: L_B :: L_C :: rem) (R_b0 :: rRest) 0 0
  | L_b1 :: L_B :: L_A k :: L_C :: rem, R_b0 :: rRest =>
      if isCleanBodyL rem && endsWithAR rRest then
        match revRToSymLTok rRest (L_B :: L_A k :: L_B :: rem) with
        | Some out => symAbsorbOrOut absorbP0 out
        | None => SS_toL false (L_b1 :: L_B :: L_A k :: L_C :: rem) (R_b0 :: rRest) 0 0
        end
      else SS_toL false (L_b1 :: L_B :: L_A k :: L_C :: rem) (R_b0 :: rRest) 0 0
  | l1, r1 => SS_toL false l1 r1 0 0
  end.

Definition symFinishLB (absorbP0 : bool) (l : list LTok) (r : list RTok) : SymStep :=
  if isEmpty r && isCleanHubL l then SS_done l 0 0 0
  else
    let p := symApplyRulesLoop fuel_4 l r in
    let l1 := fst p in
    let r1 := snd p in
    if isEmpty r1 && isCleanHubL l1 then SS_done l1 0 0 0
    else symFinishLBTail absorbP0 l1 r1.

Lemma symFinishLB_sound (absorbP0 : bool) (l : list LTok) (r : list RTok) (n0 n1 : N) :
  match symFinishLB absorbP0 l r with
  | SS_toL m' l' r' p0 p1 =>
      p0 = 0 /\ p1 = 0 /\
      RStar (M_L LM_B, evalL n0 n1 l, evalR n0 n1 r)
            (M_L (if m' then LM_C else LM_B), evalL n0 n1 l', evalR n0 n1 r')
  | SS_done out p0 p1 dM =>
      p0 = 0 /\ p1 = 0 /\
      RStar (M_L LM_B, evalL n0 n1 l, evalR n0 n1 r)
            (M_L LM_B, evalL (n0 + dM) n1 out, [])
  | SS_toR _ _ _ _ _ => False
  | SS_fail => True
  end.
Proof.
  unfold symFinishLB.
  destruct (isEmpty r && isCleanHubL l) eqn:hc0.
  - apply Bool.andb_true_iff in hc0; destruct hc0 as [hr0 _].
    destruct r; [|discriminate]; replace (n0 + 0) with n0 by lia; repeat split; apply rStar_refl.
  - pose proof (symApplyRulesLoop_sound n0 n1 fuel_4 l r) as hloop.
    set (l1 := fst (symApplyRulesLoop fuel_4 l r)) in *.
    set (r1 := snd (symApplyRulesLoop fuel_4 l r)) in *.
    destruct (isEmpty r1 && isCleanHubL l1) eqn:hc1.
    + apply Bool.andb_true_iff in hc1; destruct hc1 as [hr1 _].
      destruct r1; [|discriminate]; replace (n0 + 0) with n0 by lia; repeat split; exact hloop.
    + assert (hAbsorb : forall out : list LTok,
        RStar (M_L LM_B, evalL n0 n1 l, evalR n0 n1 r) (M_L LM_B, true :: bitsC ++ evalL n0 n1 out, []) ->
        match symAbsorbOrOut absorbP0 out with
        | SS_toL m' l' r' p0 p1 => p0 = 0 /\ p1 = 0 /\
            RStar (M_L LM_B, evalL n0 n1 l, evalR n0 n1 r)
                  (M_L (if m' then LM_C else LM_B), evalL n0 n1 l', evalR n0 n1 r')
        | SS_done out' p0 p1 dM => p0 = 0 /\ p1 = 0 /\
            RStar (M_L LM_B, evalL n0 n1 l, evalR n0 n1 r)
                  (M_L LM_B, evalL (n0 + dM) n1 out', [])
        | SS_toR _ _ _ _ _ => False
        | SS_fail => True
        end).
      { intros out hR; unfold symAbsorbOrOut.
        destruct absorbP0; [| replace (n0 + 0) with n0 by lia; repeat split; exact hR].
        destruct out as [|[| |[|]| | | ] o1];
          try (replace (n0 + 0) with n0 by lia; repeat split; exact hR).
        destruct o1 as [|[| | | | | ] o2];
          try (replace (n0 + 0) with n0 by lia; repeat split; exact hR).
        destruct o2 as [|[| | | | | ] o3];
          try (replace (n0 + 0) with n0 by lia; repeat split; exact hR).
        destruct o3 as [|[| | | | |[| | | | | ] [|]] rest];
          try (replace (n0 + 0) with n0 by lia; repeat split; exact hR).
        destruct (noVarL false rest) eqn:hnv;
          [| replace (n0 + 0) with n0 by lia; repeat split; exact hR].
        repeat split.
        replace (evalL (n0 + 1) n1 (L_b1 :: L_C :: L_sym S_P false :: rest))
          with (true :: bitsC ++ evalL n0 n1 (L_A 0 :: L_B :: L_B :: L_sym S_P false :: rest)); [exact hR |].
        cbn [evalL]; rewrite powBitsN_succ, (evalL_noVar_false (n0 := n0 + 1) (n0' := n0) hnv).
        cbn [blkBitsL bitsARn bitsA app]; repeat rewrite <- app_assoc; reflexivity. }
      unfold symFinishLBTail.
      destruct l1 as [|[| | | | | ] la]; [repeat split; exact hloop | ..];
        try (repeat split; exact hloop).
      destruct la as [|[| | | | | ] lb]; try (repeat split; exact hloop).
      destruct lb as [|[| |k| | | ] rem]; try (repeat split; exact hloop).
      * (* L_b1 :: L_B :: L_A k :: ... *)
        destruct rem as [|[| | | | | ] rem']; try (repeat split; exact hloop).
        destruct r1 as [|[| | | | ] rRest]; try (repeat split; exact hloop).
        destruct (isCleanBodyL rem' && endsWithAR rRest) eqn:hchk; [| repeat split; exact hloop].
        apply Bool.andb_true_iff in hchk; destruct hchk as [_ hend].
        destruct (revRToSymLTok rRest (L_B :: L_A k :: L_B :: rem')) as [out|] eqn:hrev;
          [| repeat split; exact hloop].
        destruct (revRToSymLTok_spec n0 n1 hrev) as [w [hEnd [hR hL]]].
        pose proof (copy_id_ab w (hEnd hend) (S k) (evalL n0 n1 rem')) as hcp.
        apply hAbsorb.
        assert (h1eq : evalL n0 n1 (L_b1 :: L_B :: L_A k :: L_C :: rem') =
                       true :: bitsB ++ bitsARn (S k) ++ bitsC ++ evalL n0 n1 rem')
          by (cbn [evalL]; repeat rewrite <- app_assoc; reflexivity).
        assert (h2eq : evalR n0 n1 (R_b0 :: rRest) = false :: evalABR w)
          by (cbn [evalR]; rewrite hR; reflexivity).
        assert (h3eq : true :: bitsC ++ evalABL (rev w) ++ bitsB ++ bitsARn (S k) ++ bitsB ++ evalL n0 n1 rem' =
                       true :: bitsC ++ evalL n0 n1 out)
          by (rewrite hL; cbn [evalL]; repeat rewrite <- app_assoc; reflexivity).
        rewrite h1eq, h2eq in hloop; rewrite h3eq in hcp.
        exact (rStar_trans hloop (rPlus_to_star hcp)).
      * (* L_b1 :: L_B :: L_C :: rem *)
        destruct r1 as [|[| | | | ] rRest]; try (repeat split; exact hloop).
        destruct (isCleanBodyL rem && endsWithAR rRest) eqn:hchk; [| repeat split; exact hloop].
        apply Bool.andb_true_iff in hchk; destruct hchk as [_ hend].
        destruct (revRToSymLTok rRest (L_B :: L_B :: rem)) as [out|] eqn:hrev;
          [| repeat split; exact hloop].
        destruct (revRToSymLTok_spec n0 n1 hrev) as [w [hEnd [hR hL]]].
        pose proof (copy_id_ab w (hEnd hend) 0 (evalL n0 n1 rem)) as hcp.
        apply hAbsorb.
        assert (h1eq : evalL n0 n1 (L_b1 :: L_B :: L_C :: rem) =
                       true :: bitsB ++ bitsARn 0 ++ bitsC ++ evalL n0 n1 rem)
          by (cbn [evalL bitsARn]; repeat rewrite <- app_assoc; reflexivity).
        assert (h2eq : evalR n0 n1 (R_b0 :: rRest) = false :: evalABR w)
          by (cbn [evalR]; rewrite hR; reflexivity).
        assert (h3eq : true :: bitsC ++ evalABL (rev w) ++ bitsB ++ bitsARn 0 ++ bitsB ++ evalL n0 n1 rem =
                       true :: bitsC ++ evalL n0 n1 out)
          by (rewrite hL; cbn [evalL bitsARn]; repeat rewrite <- app_assoc; reflexivity).
        rewrite h1eq, h2eq in hloop; rewrite h3eq in hcp.
        exact (rStar_trans hloop (rPlus_to_star hcp)).
Qed.

Lemma symFinishLB_of_rPlus (absorbP0 : bool) {m : Mode} {l0 l : list LTok} {r0 r : list RTok}
  (h : forall n0 n1 : N, RPlus (m, evalL n0 n1 l0, evalR n0 n1 r0) (M_L LM_B, evalL n0 n1 l, evalR n0 n1 r)) :
  SymStepValid m l0 r0 (symFinishLB absorbP0 l r).
Proof.
  pose proof (symFinishLB_sound absorbP0 l r) as hf.
  destruct (symFinishLB absorbP0 l r) as [m' l' r' p0 p1 | m' l' r' p0 p1 | out p0 p1 dM |].
  - intros n0 n1 _ _; destruct (hf n0 n1) as [-> [-> hstar]]; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia.
    exact (rPlus_trans_star (h n0 n1) hstar).
  - destruct (hf 0 0).
  - intros n0 n1 _ _; destruct (hf n0 n1) as [-> [-> hstar]]; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia.
    exact (rPlus_trans_star (h n0 n1) hstar).
  - exact I.
Qed.

(* Symbolic Left Sweep *)
Fixpoint symSweepL (fuel : nat) (isC : bool) (l : list LTok) (r : list RTok) : SymStep :=
  match fuel with
  | 0%nat => SS_fail
  | S f =>
      if isC then
        match l with
        | [] => SS_toR false [L_b1] r 0 0
        | L_b0 :: xs => SS_toR false (L_b1 :: xs) r 0 0
        | L_b1 :: xs => symSweepL f false xs (pushR0C r)
        | L_A 0 :: xs => SS_toR false (L_b1 :: L_b1 :: xs) r 0 0
        | L_A (S k) :: xs => SS_toR false (L_b1 :: L_b1 :: L_A k :: xs) r 0 0
        | L_B :: xs => SS_toR false (L_b1 :: L_b1 :: L_b1 :: L_b1 :: xs) r 0 0
        | L_C :: xs => SS_toR false (L_b1 :: L_B :: xs) r 0 0
        | L_sym k v :: xs =>
            if noVarL v xs && noVarR v r then
              addPeel v (symSweepL f true (blkLTok k ++ L_sym k v :: xs) r)
            else SS_fail
        end
      else
        match l with
        | [] => SS_toR false [L_b1] (R_b1 :: r) 0 0
        | L_A k :: xs => symSweepL f false xs (pushRAR k r)
        | L_B :: xs => symSweepL f false xs (R_BR :: r)
        | L_C :: xs => SS_toR false (L_b1 :: L_b1 :: L_b1 :: L_b1 :: xs) (R_b1 :: r) 0 0
        | L_sym k v :: xs => symSweepL f false xs (R_sym k v :: r)
        | L_b1 :: xs => symSweepL f false xs (pushR0C r)
        | L_b0 :: xs => symSweepL f true xs (R_b1 :: r)
        end
  end.

Lemma symSweepL_sound (fuel : nat) (isC : bool) (l : list LTok) (r : list RTok) :
  SymStepValid (M_L (if isC then LM_C else LM_B)) l r (symSweepL fuel isC l r).
Proof.
  revert isC l r; induction fuel as [|f ih]; intros isC l r; [exact I |].
  destruct isC; cbn [symSweepL].
  - (* isC = true *)
    destruct l as [|[| |[|k]| | |k v] xs].
    + intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; apply step_LC_nil.
    + intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; apply step_LC_0.
    + refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false xs (pushR0C r))).
      exact (rPlus_congr_end (eqBits_refl _) (evalR_pushR0C n0 n1 r) (step_LC_1 _ _)).
    + intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; cbn [evalL bitsARn app]; apply step_LC_0.
    + intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; cbn [evalL bitsARn app]; apply step_LC_0.
    + intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; cbn [evalL bitsB app]; apply step_LC_0.
    + intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; cbn [evalL bitsC bitsB app]; apply step_LC_0.
    + destruct (noVarL v xs && noVarR v r) eqn:hnv; [| exact I].
      apply Bool.andb_true_iff in hnv; destruct hnv as [hnvL hnvR].
      refine (addPeel_valid (fun n0 n1 hge => evalL_peel hnvL n0 n1 hge) (fun n0 n1 _ => _) (ih true _ r)).
      destruct v; [exact (evalR_noVar_true hnvR) | exact (evalR_noVar_false hnvR)].
  - (* isC = false *)
    destruct l as [|[| |k| | |k v] xs].
    + intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; apply step_LB_nil.
    + refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih true xs (R_b1 :: r))).
      apply step_LB_0.
    + refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false xs (pushR0C r))).
      exact (rPlus_congr_end (eqBits_refl _) (evalR_pushR0C n0 n1 r) (step_LB_1 _ _)).
    + refine (symStepValid_of_rStar (fun n0 n1 => _) (ih false xs (pushRAR k r))).
      cbn [evalL]; rewrite evalR_pushRAR; apply sweepLB_ARn.
    + refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false xs (R_BR :: r))).
      cbn [evalL evalR]; apply sweepLB_B.
    + intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; apply sweepLB_C.
    + refine (symStepValid_of_rStar (fun n0 n1 => _) (ih false xs (R_sym k v :: r))).
      cbn [evalL evalR]; apply sweepLB_powBlkN.
Qed.

(* Symbolic Right Sweep *)
Fixpoint symSweepR (absorbP0 : bool) (fuel : nat) (isA : bool) (l : list LTok) (r : list RTok) : SymStep :=
  match fuel with
  | 0%nat => SS_fail
  | S f =>
      if isA then
        match r with
        | [] => SS_toL true (L_b1 :: l) [R_b1] 0 0
        | [R_b0] => SS_toL true (L_b1 :: l) [R_b1] 0 0
        | [R_b1] => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l) []
        | [R_b1; R_b0] => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l) []
        | R_sym k v :: r2 =>
            if noVarL v l && noVarR v r2 then
              addPeel v (symSweepR absorbP0 f true l (blkRTok k ++ R_sym k v :: r2))
            else SS_fail
        | R_b0 :: R_sym k v :: r2 =>
            if noVarL v l && noVarR v r2 then
              addPeel v (symSweepR absorbP0 f true l (R_b0 :: blkRTok k ++ R_sym k v :: r2))
            else SS_fail
        | R_b1 :: R_sym k v :: r2 =>
            if noVarL v l && noVarR v r2 then
              addPeel v (symSweepR absorbP0 f true l (R_b1 :: blkRTok k ++ R_sym k v :: r2))
            else SS_fail
        | R_b1 :: R_b0 :: R_sym k v :: r2 =>
            if noVarL v l && noVarR v r2 then
              addPeel v (symSweepR absorbP0 f true l (R_b1 :: R_b0 :: blkRTok k ++ R_sym k v :: r2))
            else SS_fail
        | R_BR :: r2 => SS_toL true (L_b1 :: l) (R_b1 :: pushRAR 0 r2) 0 0
        | R_AR k :: r2 =>
            let rRem := match k with 0%nat => r2 | S k' => R_AR k' :: r2 end in
            symFinishLB absorbP0 (L_b1 :: l) (pushR0C rRem)
        | R_b0 :: R_b0 :: r2 => SS_toL true (L_b1 :: l) (R_b1 :: r2) 0 0
        | R_b0 :: R_b1 :: r2 => symFinishLB absorbP0 (L_b1 :: l) (pushR0C r2)
        | R_b0 :: R_AR 0 :: r2 => SS_toL true (L_b1 :: l) (R_b1 :: R_b1 :: r2) 0 0
        | R_b0 :: R_AR (S k) :: r2 => SS_toL true (L_b1 :: l) (R_b1 :: R_b1 :: R_AR k :: r2) 0 0
        | R_b0 :: R_BR :: r2 => SS_toL true (L_b1 :: l) (R_b1 :: R_b0 :: pushRAR 0 r2) 0 0
        | R_b1 :: R_b0 :: R_b0 :: r3 => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l) r3
        | R_b1 :: R_b0 :: R_b1 :: r3 => symFinishLB absorbP0 (L_b1 :: pushL0 true l) (pushR0C r3)
        | R_b1 :: R_b0 :: R_AR 0 :: r3 => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l) (R_b1 :: r3)
        | R_b1 :: R_b0 :: R_AR (S k) :: r3 => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l) (R_b1 :: R_AR k :: r3)
        | R_b1 :: R_b0 :: R_BR :: r3 => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l) (R_b0 :: pushRAR 0 r3)
        | R_b1 :: R_AR 0 :: r3 => symFinishLB absorbP0 (L_b1 :: pushL0 true l) (pushR0C r3)
        | R_b1 :: R_AR (S k) :: r3 => symFinishLB absorbP0 (L_b1 :: pushL0 true l) (pushR0C (R_AR k :: r3))
        | R_b1 :: R_BR :: r3 => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l) (pushRAR 0 r3)
        | R_b1 :: R_b1 :: _ => SS_fail
        end
      else
        match r with
        | [] => SS_toL true (L_b1 :: pushL0 true (L_b1 :: l)) [R_b1] 0 0
        | R_sym k v :: r2 =>
            if noVarL v l && noVarR v r2 then
              addPeel v (symSweepR absorbP0 f false l (blkRTok k ++ R_sym k v :: r2))
            else SS_fail
        | R_b0 :: R_sym k v :: r2 =>
            if noVarL v l && noVarR v r2 then
              addPeel v (symSweepR absorbP0 f false l (R_b0 :: blkRTok k ++ R_sym k v :: r2))
            else SS_fail
        | R_b1 :: R_sym k v :: r2 =>
            if noVarL v l && noVarR v r2 then
              addPeel v (symSweepR absorbP0 f false l (R_b1 :: blkRTok k ++ R_sym k v :: r2))
            else SS_fail
        | [R_b0] => symSweepR absorbP0 f true (pushL0 true (L_b1 :: l)) []
        | [R_b1] =>
            match l with
            | L_b1 :: l1 => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l1) []
            | L_sym k v :: l1 =>
                if noVarL v l1 && noVarR v [R_b1] then
                  addPeel v (symSweepR absorbP0 f false (blkLTok k ++ L_sym k v :: l1) [R_b1])
                else SS_fail
            | _ =>
                match popL0C l with
                | Some l' => symFinishLB absorbP0 l' [R_AR 0]
                | None => SS_fail
                end
            end
        | R_BR :: r2 => symFinishLB absorbP0 (L_b1 :: pushL0 true (L_b1 :: l)) (pushR0C r2)
        | R_AR k :: r2 =>
            match l with
            | L_b1 :: l1 =>
                match k with
                | 0%nat => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l1) r2
                | S k' => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushLA k' (pushL0 true l1)) r2
                end
            | L_sym ks v :: l1 =>
                if noVarL v l1 && noVarR v (R_AR k :: r2) then
                  addPeel v (symSweepR absorbP0 f false (blkLTok ks ++ L_sym ks v :: l1) (R_AR k :: r2))
                else SS_fail
            | _ =>
                match popL0C l with
                | Some l' =>
                    let rRem := match k with 0%nat => r2 | S k' => R_AR k' :: r2 end in
                    symFinishLB absorbP0 l' (pushRAR 0 (pushR0C rRem))
                | None => SS_fail
                end
            end
        | R_b0 :: R_b0 :: r2 => symSweepR absorbP0 f true (pushL0 true (L_b1 :: l)) r2
        | R_b0 :: R_b1 :: r2 =>
            match l with
            | L_b1 :: l1 => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l1) r2
            | L_sym ks v :: l1 =>
                if noVarL v l1 && noVarR v (R_b0 :: R_b1 :: r2) then
                  addPeel v (symSweepR absorbP0 f false (blkLTok ks ++ L_sym ks v :: l1) (R_b0 :: R_b1 :: r2))
                else SS_fail
            | _ =>
                match popL0C l with
                | Some l' => symFinishLB absorbP0 l' (pushRAR 0 (pushR0C r2))
                | None => SS_fail
                end
            end
        | R_b0 :: R_AR 0 :: r2 => symSweepR absorbP0 f true (pushL0 true (L_b1 :: l)) (R_b1 :: r2)
        | R_b0 :: R_AR (S k) :: r2 => symSweepR absorbP0 f true (pushL0 true (L_b1 :: l)) (R_b1 :: R_AR k :: r2)
        | R_b0 :: R_BR :: r2 => SS_toL true (L_b1 :: pushL0 true (L_b1 :: l)) (R_b1 :: R_b1 :: r2) 0 0
        | R_b1 :: R_b0 :: r2 =>
            match l with
            | L_b1 :: l1 => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l1) r2
            | L_sym ks v :: l1 =>
                if noVarL v l1 && noVarR v (R_b1 :: R_b0 :: r2) then
                  addPeel v (symSweepR absorbP0 f false (blkLTok ks ++ L_sym ks v :: l1) (R_b1 :: R_b0 :: r2))
                else SS_fail
            | _ =>
                match popL0C l with
                | Some l' => symFinishLB absorbP0 l' (pushRAR 0 (pushR0C r2))
                | None => SS_fail
                end
            end
        | R_b1 :: R_AR k :: r2 =>
            match l with
            | L_b1 :: l1 =>
                match k with
                | 0%nat => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l1) (R_b1 :: r2)
                | S k' => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushLA k' (pushL0 true l1)) (R_b1 :: r2)
                end
            | L_sym ks v :: l1 =>
                if noVarL v l1 && noVarR v (R_b1 :: R_AR k :: r2) then
                  addPeel v (symSweepR absorbP0 f false (blkLTok ks ++ L_sym ks v :: l1) (R_b1 :: R_AR k :: r2))
                else SS_fail
            | _ =>
                match popL0C l with
                | Some l' =>
                    let rRem := match k with 0%nat => R_b1 :: r2 | S k' => R_b1 :: R_AR k' :: r2 end in
                    symFinishLB absorbP0 l' (pushRAR 0 (pushR0C rRem))
                | None => SS_fail
                end
            end
        | R_b1 :: R_BR :: r2 =>
            match l with
            | L_b1 :: l1 => symSweepR absorbP0 f false (L_b1 :: L_b1 :: pushL0 true l1) (R_b0 :: pushRAR 0 r2)
            | L_sym ks v :: l1 =>
                if noVarL v l1 && noVarR v (R_b1 :: R_BR :: r2) then
                  addPeel v (symSweepR absorbP0 f false (blkLTok ks ++ L_sym ks v :: l1) (R_b1 :: R_BR :: r2))
                else SS_fail
            | _ =>
                match popL0C l with
                | Some l' => symFinishLB absorbP0 l' (pushRAR 0 (R_BR :: r2))
                | None => SS_fail
                end
            end
        | R_b1 :: R_b1 :: r2 =>
            match l with
            | L_b1 :: l1 => symFinishLB absorbP0 (L_b1 :: pushL0 true l1) (pushR0C r2)
            | L_sym ks v :: l1 =>
                if noVarL v l1 && noVarR v (R_b1 :: R_b1 :: r2) then
                  addPeel v (symSweepR absorbP0 f false (blkLTok ks ++ L_sym ks v :: l1) (R_b1 :: R_b1 :: r2))
                else SS_fail
            | _ =>
                match popL0C l with
                | Some l' => symFinishLB absorbP0 l' (pushRAR 0 (R_b1 :: r2))
                | None => SS_fail
                end
            end
        end
  end.

Lemma peelL_symSweepR_valid {m : Mode} {ks : SymKind} {v : bool} {l1 : list LTok} {r : list RTok}
  {st : SymStep} (hnv : noVarL v l1 && noVarR v r = true)
  (h : SymStepValid m (blkLTok ks ++ L_sym ks v :: l1) r st) :
  SymStepValid m (L_sym ks v :: l1) r (addPeel v st).
Proof.
  apply Bool.andb_true_iff in hnv; destruct hnv as [hL hR].
  refine (addPeel_valid (fun n0 n1 hge => evalL_peel hL n0 n1 hge) (fun n0 n1 _ => _) h).
  destruct v; [exact (evalR_noVar_true hR) | exact (evalR_noVar_false hR)].
Qed.

Lemma peelR_symSweepR_valid {m : Mode} {k : SymKind} {v : bool} {l : list LTok} {pre r2 : list RTok}
  {st : SymStep} (hpre : noVarR v pre = true) (hnv : noVarL v l && noVarR v r2 = true)
  (h : SymStepValid m l (pre ++ blkRTok k ++ R_sym k v :: r2) st) :
  SymStepValid m l (pre ++ R_sym k v :: r2) (addPeel v st).
Proof.
  apply Bool.andb_true_iff in hnv; destruct hnv as [hL hR].
  refine (addPeel_valid (fun n0 n1 _ => _) (fun n0 n1 hge => _) h).
  - destruct v; [exact (evalL_noVar_true hL) | exact (evalL_noVar_false hL)].
  - rewrite !evalR_append, app_assoc.
    pose proof (evalR_peel (k := k) hR n0 n1 hge) as hp.
    rewrite evalR_append in hp; rewrite hp, <- app_assoc.
    f_equal; destruct v; [exact (evalR_noVar_true hpre) | exact (evalR_noVar_false hpre)].
Qed.

Lemma symSweepR_sound (absorbP0 : bool) (fuel : nat) (isA : bool) (l : list LTok) (r : list RTok) :
  SymStepValid (M_R (if isA then RM_A else RM_D)) l r (symSweepR absorbP0 fuel isA l r).
Proof.
  revert isA l r; induction fuel as [|f ih]; intros isA l r; [exact I |].
  destruct isA; cbn [symSweepR].
  - (* isA = true (RM_A) *)
    destruct r as [|[| |k| |k v] r1].
    + intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; apply step_RA_nil.
    + (* R_b0 :: r1 *)
      destruct r1 as [|[| |[|k]| |k v] r2].
      * intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; apply step_RA_b0.
      * intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; apply step_RA_00.
      * refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
        exact (rPlus_congr_end (eqBits_refl _) (evalR_pushR0C n0 n1 r2) (step_RA_01 _ _)).
      * intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; cbn [evalL evalR bitsARn app]; apply step_RA_00.
      * intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia; cbn [evalL evalR bitsARn app]; apply step_RA_00.
      * intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia;
        cbn [evalL evalR bitsBR]; rewrite evalR_pushRAR; cbn [bitsARn app]; apply step_RA_00.
      * destruct (noVarL v l && noVarR v r2) eqn:hnv; [| exact I].
        exact (peelR_symSweepR_valid (pre := [R_b0]) eq_refl hnv (ih true l _)).
    + (* R_b1 :: r1 *)
      destruct r1 as [|[| |[|k]| |k v] r2].
      * refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l) [])).
        exact (rPlus_congr_end (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l)))
          (eqBits_refl _) (step_RA_b1 _)).
      * (* R_b1 :: R_b0 :: r2 *)
        destruct r2 as [|[| |[|k]| |k v] r3].
        -- refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l) [])).
           exact (rPlus_congr_end (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l)))
             (eqBits_refl _) (step_RA_b10 _)).
        -- refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l) r3)).
           exact (rPlus_congr_end (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l)))
             (eqBits_refl _) (step_RA_100 _ _)).
        -- refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
           exact (rPlus_congr_end (eqBits_cons true (evalL_pushL0_closed n0 n1 l))
             (evalR_pushR0C n0 n1 r3) (step_RA_101 _ _)).
        -- refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l) (R_b1 :: r3))).
           cbn [evalR bitsARn app].
           exact (rPlus_congr_end (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l)))
             (eqBits_refl _) (step_RA_100 _ _)).
        -- refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l) (R_b1 :: R_AR k :: r3))).
           cbn [evalR bitsARn app].
           exact (rPlus_congr_end (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l)))
             (eqBits_refl _) (step_RA_100 _ _)).
        -- refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l) (R_b0 :: pushRAR 0 r3))).
           cbn [evalR bitsBR]; rewrite evalR_pushRAR; cbn [bitsARn app].
           exact (rPlus_congr_end (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l)))
             (eqBits_refl _) (step_RA_100 _ _)).
        -- destruct (noVarL v l && noVarR v r3) eqn:hnv; [| exact I].
           exact (peelR_symSweepR_valid (pre := [R_b1; R_b0]) eq_refl hnv (ih true l _)).
      * exact I.
      * refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
        cbn [evalR bitsARn app].
        exact (rPlus_congr_end (eqBits_cons true (evalL_pushL0_closed n0 n1 l))
          (evalR_pushR0C n0 n1 r2) (step_RA_101 _ _)).
      * refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
        cbn [evalR bitsARn app].
        exact (rPlus_congr_end (eqBits_cons true (evalL_pushL0_closed n0 n1 l))
          (evalR_pushR0C n0 n1 (R_AR k :: r2)) (step_RA_101 _ _)).
      * refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l) (pushRAR 0 r2))).
        cbn [evalR bitsBR]; rewrite evalR_pushRAR; cbn [bitsARn app].
        exact (rPlus_congr_end (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l)))
          (eqBits_refl _) (step_RA_100 _ _)).
      * destruct (noVarL v l && noVarR v r2) eqn:hnv; [| exact I].
        exact (peelR_symSweepR_valid (pre := [R_b1]) eq_refl hnv (ih true l _)).
    + (* R_AR k :: r1 *)
      refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
      destruct k as [|k']; cbn [evalR bitsARn app];
        [exact (rPlus_congr_end (eqBits_refl _) (evalR_pushR0C n0 n1 r1) (step_RA_01 _ _)) |
         exact (rPlus_congr_end (eqBits_refl _) (evalR_pushR0C n0 n1 (R_AR k' :: r1)) (step_RA_01 _ _))].
    + (* R_BR :: r1 *)
      intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia.
      cbn [evalL evalR bitsBR]; rewrite evalR_pushRAR; cbn [bitsARn app]; apply step_RA_00.
    + (* R_sym k v :: r1 *)
      destruct (noVarL v l && noVarR v r1) eqn:hnv; [| exact I].
      exact (peelR_symSweepR_valid (pre := []) eq_refl hnv (ih true l _)).
  - (* isA = false (RM_D) *)
    assert (Hnot1 : forall (P : list LTok -> SymStep) (f1 : list LTok -> SymStep)
      (f2 : SymKind -> bool -> list LTok -> SymStep),
      (forall l', popL0C l = Some l' -> SymStepValid (M_R RM_D) l r (P l')) ->
      (forall l1, l = L_b1 :: l1 -> SymStepValid (M_R RM_D) (L_b1 :: l1) r (f1 l1)) ->
      (forall ks v l1, l = L_sym ks v :: l1 -> SymStepValid (M_R RM_D) (L_sym ks v :: l1) r (f2 ks v l1)) ->
      SymStepValid (M_R RM_D) l r
        match l with
        | L_b1 :: l1 => f1 l1
        | L_sym ks v :: l1 => f2 ks v l1
        | _ => match popL0C l with Some l' => P l' | None => SS_fail end
        end).
    { intros P f1 f2 hp hf1 hf2.
      destruct l as [|[| |kl| | |ks v] l1];
        [| | exact (hf1 l1 eq_refl) | | | | exact (hf2 ks v l1 eq_refl)];
        (destruct (popL0C _) as [l'|] eqn:hpop; [exact (hp l' eq_refl) | exact I]). }
    destruct r as [|[| |k| |k v] r1].
    + intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia.
      exact (rPlus_congr_end (eqBits_cons true (evalL_pushL0_closed n0 n1 (L_b1 :: l))) (eqBits_refl _) (step_RD_nil _)).
    + (* R_b0 :: r1 *)
      destruct r1 as [|[| |[|k]| |k v] r2].
      * refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih true (pushL0 true (L_b1 :: l)) [])).
        exact (rPlus_congr_end (evalL_pushL0_closed n0 n1 (L_b1 :: l)) (eqBits_refl _) (step_RD_b0 _)).
      * refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih true (pushL0 true (L_b1 :: l)) r2)).
        exact (rPlus_congr_end (evalL_pushL0_closed n0 n1 (L_b1 :: l)) (eqBits_refl _) (step_RD_00 _ _)).
      * apply Hnot1; clear Hnot1.
        -- intros l' hpop; refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
           pose proof (rPlus_congr_L (evalL_popL0C hpop) (step_RD_01_0 (evalL n0 n1 l') (evalR n0 n1 r2))) as h1.
           rewrite evalR_pushRAR; cbn [bitsARn app].
           exact (rPlus_congr_end (eqBits_refl _) (eqBits_cons false (eqBits_cons true (evalR_pushR0C n0 n1 r2))) h1).
        -- intros l1 _; refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l1) r2)).
           exact (rPlus_congr_end (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l1)))
             (eqBits_refl _) (step_RD_01_1 _ _)).
        -- intros ks v l1 _; destruct (noVarL v l1 && noVarR v (R_b0 :: R_b1 :: r2)) eqn:hnv; [| exact I].
           exact (peelL_symSweepR_valid hnv (ih false _ (R_b0 :: R_b1 :: r2))).
      * refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih true (pushL0 true (L_b1 :: l)) (R_b1 :: r2))).
        cbn [evalR bitsARn app].
        exact (rPlus_congr_end (evalL_pushL0_closed n0 n1 (L_b1 :: l)) (eqBits_refl _) (step_RD_00 _ _)).
      * refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih true (pushL0 true (L_b1 :: l)) (R_b1 :: R_AR k :: r2))).
        cbn [evalR bitsARn app].
        exact (rPlus_congr_end (evalL_pushL0_closed n0 n1 (L_b1 :: l)) (eqBits_refl _) (step_RD_00 _ _)).
      * intros n0 n1 _ _; replace (n0 - 0) with n0 by lia; replace (n1 - 0) with n1 by lia.
        pose proof (rPlus_trans (step_RD_00 (evalL n0 n1 l) (false :: false :: true :: evalR n0 n1 r2))
                                (step_RA_00 (false :: true :: evalL n0 n1 l) (true :: evalR n0 n1 r2))) as h12.
        exact (rPlus_congr_end (eqBits_cons true (evalL_pushL0_closed n0 n1 (L_b1 :: l))) (eqBits_refl _) h12).
      * destruct (noVarL v l && noVarR v r2) eqn:hnv; [| exact I].
        exact (peelR_symSweepR_valid (pre := [R_b0]) eq_refl hnv (ih false l _)).
    + (* R_b1 :: r1 *)
      destruct r1 as [|[| |k| |k v] r2].
      * (* [R_b1] *)
        apply Hnot1; clear Hnot1.
        -- intros l' hpop; refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
           exact (rPlus_congr_L (evalL_popL0C hpop) (step_RD_b1_0 (evalL n0 n1 l'))).
        -- intros l1 _; refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l1) [])).
           exact (rPlus_congr_end (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l1)))
             (eqBits_refl _) (step_RD_b1_1 _)).
        -- intros ks v l1 _; destruct (noVarL v l1 && noVarR v [R_b1]) eqn:hnv; [| exact I].
           exact (peelL_symSweepR_valid hnv (ih false _ [R_b1])).
      * (* R_b1 :: R_b0 :: r2 *)
        apply Hnot1; clear Hnot1.
        -- intros l' hpop; refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
           pose proof (rPlus_congr_L (evalL_popL0C hpop) (step_RD_10_0 (evalL n0 n1 l') (evalR n0 n1 r2))) as h1.
           rewrite evalR_pushRAR; cbn [bitsARn app].
           exact (rPlus_congr_end (eqBits_refl _) (eqBits_cons false (eqBits_cons true (evalR_pushR0C n0 n1 r2))) h1).
        -- intros l1 _; refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l1) r2)).
           exact (rPlus_congr_end (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l1)))
             (eqBits_refl _) (step_RD_10_1 _ _)).
        -- intros ks v l1 _; destruct (noVarL v l1 && noVarR v (R_b1 :: R_b0 :: r2)) eqn:hnv; [| exact I].
           exact (peelL_symSweepR_valid hnv (ih false _ (R_b1 :: R_b0 :: r2))).
      * (* R_b1 :: R_b1 :: r2 *)
        apply Hnot1; clear Hnot1.
        -- intros l' hpop; refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
           rewrite evalR_pushRAR; cbn [bitsARn evalR app].
           exact (rPlus_congr_L (evalL_popL0C hpop) (step_RD_11_0 (evalL n0 n1 l') (evalR n0 n1 r2))).
        -- intros l1 _; refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
           exact (rPlus_congr_end (eqBits_cons true (evalL_pushL0_closed n0 n1 l1))
             (evalR_pushR0C n0 n1 r2) (step_RD_11_1 _ _)).
        -- intros ks v l1 _; destruct (noVarL v l1 && noVarR v (R_b1 :: R_b1 :: r2)) eqn:hnv; [| exact I].
           exact (peelL_symSweepR_valid hnv (ih false _ (R_b1 :: R_b1 :: r2))).
      * (* R_b1 :: R_AR k :: r2 *)
        apply Hnot1; clear Hnot1.
        -- intros l' hpop; refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
           destruct k as [|k']; rewrite evalR_pushRAR; cbn [bitsARn evalR app].
           ++ pose proof (rPlus_congr_L (evalL_popL0C hpop) (step_RD_10_0 (evalL n0 n1 l') (true :: evalR n0 n1 r2))) as h1.
              exact (rPlus_congr_end (eqBits_refl _) (eqBits_cons false (eqBits_cons true (evalR_pushR0C n0 n1 (R_b1 :: r2)))) h1).
           ++ pose proof (rPlus_congr_L (evalL_popL0C hpop) (step_RD_10_0 (evalL n0 n1 l') (true :: bitsARn (S k') ++ evalR n0 n1 r2))) as h1.
              exact (rPlus_congr_end (eqBits_refl _) (eqBits_cons false (eqBits_cons true (evalR_pushR0C n0 n1 (R_b1 :: R_AR k' :: r2)))) h1).
        -- intros l1 _; destruct k as [|k'].
           ++ refine (symStepValid_of_rStar (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l1) (R_b1 :: r2))).
              exact (rStar_congr (eqBits_refl _) (eqBits_refl _)
                (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l1))) (eqBits_refl _)
                (sweepRD_1_ARn 0 (evalL n0 n1 l1) (evalR n0 n1 r2))).
           ++ refine (symStepValid_of_rStar (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushLA k' (pushL0 true l1)) (R_b1 :: r2))).
              assert (hEq : EqBits (evalL n0 n1 (L_b1 :: L_b1 :: pushLA k' (pushL0 true l1)))
                                   (true :: true :: bitsARn (S k') ++ false :: evalL n0 n1 l1)).
              { cbn [evalL]; rewrite evalL_pushLA.
                exact (eqBits_cons true (eqBits_cons true (eqBits_append_left (bitsARn (S k')) (evalL_pushL0_closed n0 n1 l1)))). }
              exact (rStar_congr (eqBits_refl _) (eqBits_refl _) hEq (eqBits_refl _)
                (sweepRD_1_ARn (S k') (evalL n0 n1 l1) (evalR n0 n1 r2))).
        -- intros ks v l1 _; destruct (noVarL v l1 && noVarR v (R_b1 :: R_AR k :: r2)) eqn:hnv; [| exact I].
           exact (peelL_symSweepR_valid hnv (ih false _ (R_b1 :: R_AR k :: r2))).
      * (* R_b1 :: R_BR :: r2 *)
        apply Hnot1; clear Hnot1.
        -- intros l' hpop; refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
           rewrite evalR_pushRAR; cbn [bitsARn evalR bitsBR app].
           exact (rPlus_congr_L (evalL_popL0C hpop) (step_RD_10_0 (evalL n0 n1 l') (false :: false :: true :: evalR n0 n1 r2))).
        -- intros l1 _; refine (symStepValid_of_rPlus (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l1) (R_b0 :: pushRAR 0 r2))).
           cbn [evalR bitsBR]; rewrite evalR_pushRAR; cbn [bitsARn app].
           exact (rPlus_congr_end (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l1)))
             (eqBits_refl _) (step_RD_10_1 (evalL n0 n1 l1) (false :: false :: true :: evalR n0 n1 r2))).
        -- intros ks v l1 _; destruct (noVarL v l1 && noVarR v (R_b1 :: R_BR :: r2)) eqn:hnv; [| exact I].
           exact (peelL_symSweepR_valid hnv (ih false _ (R_b1 :: R_BR :: r2))).
      * (* R_b1 :: R_sym k v :: r2 *)
        destruct (noVarL v l && noVarR v r2) eqn:hnv; [| exact I].
        exact (peelR_symSweepR_valid (pre := [R_b1]) eq_refl hnv (ih false l _)).
    + (* R_AR k :: r1 *)
      apply Hnot1; clear Hnot1.
      * intros l' hpop; refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
        destruct k as [|k']; rewrite evalR_pushRAR; cbn [bitsARn evalR app].
        -- pose proof (rPlus_congr_L (evalL_popL0C hpop) (step_RD_01_0 (evalL n0 n1 l') (evalR n0 n1 r1))) as h1.
           exact (rPlus_congr_end (eqBits_refl _) (eqBits_cons false (eqBits_cons true (evalR_pushR0C n0 n1 r1))) h1).
        -- pose proof (rPlus_congr_L (evalL_popL0C hpop) (step_RD_01_0 (evalL n0 n1 l') (bitsARn (S k') ++ evalR n0 n1 r1))) as h1.
           exact (rPlus_congr_end (eqBits_refl _) (eqBits_cons false (eqBits_cons true (evalR_pushR0C n0 n1 (R_AR k' :: r1)))) h1).
      * intros l1 _; destruct k as [|k'].
        -- refine (symStepValid_of_rStar (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushL0 true l1) r1)).
           exact (rStar_congr (eqBits_refl _) (eqBits_refl _)
             (eqBits_cons true (eqBits_cons true (evalL_pushL0_closed n0 n1 l1))) (eqBits_refl _)
             (sweepRD_ARn 0 (evalL n0 n1 l1) (evalR n0 n1 r1))).
        -- refine (symStepValid_of_rStar (fun n0 n1 => _) (ih false (L_b1 :: L_b1 :: pushLA k' (pushL0 true l1)) r1)).
           assert (hEq : EqBits (evalL n0 n1 (L_b1 :: L_b1 :: pushLA k' (pushL0 true l1)))
                                (true :: true :: bitsARn (S k') ++ false :: evalL n0 n1 l1)).
           { cbn [evalL]; rewrite evalL_pushLA.
             exact (eqBits_cons true (eqBits_cons true (eqBits_append_left (bitsARn (S k')) (evalL_pushL0_closed n0 n1 l1)))). }
           exact (rStar_congr (eqBits_refl _) (eqBits_refl _) hEq (eqBits_refl _)
             (sweepRD_ARn (S k') (evalL n0 n1 l1) (evalR n0 n1 r1))).
      * intros ks v l1 _; destruct (noVarL v l1 && noVarR v (R_AR k :: r1)) eqn:hnv; [| exact I].
        exact (peelL_symSweepR_valid hnv (ih false _ (R_AR k :: r1))).
    + (* R_BR :: r1 *)
      refine (symFinishLB_of_rPlus absorbP0 (fun n0 n1 => _)).
      pose proof (rPlus_trans (step_RD_00 (evalL n0 n1 l) (false :: true :: evalR n0 n1 r1))
                              (step_RA_01 (false :: true :: evalL n0 n1 l) (evalR n0 n1 r1))) as h12.
      exact (rPlus_congr_end (eqBits_cons true (evalL_pushL0_closed n0 n1 (L_b1 :: l)))
        (evalR_pushR0C n0 n1 r1) h12).
    + (* R_sym k v :: r1 *)
      destruct (noVarL v l && noVarR v r1) eqn:hnv; [| exact I].
      exact (peelR_symSweepR_valid (pre := []) eq_refl hnv (ih false l _)).
Qed.

(* Multi-sweep non-local symbolic hub runner *)
Fixpoint symRunLoop (absorbP0 : bool) (n : nat) (st : SymStep) : option (list LTok * Aff * N) :=
  match n with
  | 0%nat => None
  | S n' =>
      match st with
      | SS_fail => None
      | SS_done out p0 p1 dM => Some (out, mkAff p0 dM, p1)
      | SS_toL isC l r p0 p1 =>
          match symRunLoop absorbP0 n' (symSweepL fuel_16384 isC l r) with
          | Some (out, aff, q1) => Some (out, affComp (mkAff p0 0) aff, p1 + q1)
          | None => None
          end
      | SS_toR isA l r p0 p1 =>
          match symRunLoop absorbP0 n' (symSweepR absorbP0 fuel_16384 isA l r) with
          | Some (out, aff, q1) => Some (out, affComp (mkAff p0 0) aff, p1 + q1)
          | None => None
          end
      end
  end.

Lemma symRunLoop_sound {absorbP0 : bool} {n : nat} {m : Mode} {l : list LTok} {r : list RTok}
  {st : SymStep} {out : list LTok} {aff : Aff} {p1 : N}
  (hV : SymStepValid m l r st)
  (h : symRunLoop absorbP0 n st = Some (out, aff, p1)) :
  forall n0 n1 : N, aff.(aff_need) <= n0 -> p1 <= n1 ->
    RPlus (m, evalL n0 n1 l, evalR n0 n1 r)
          (M_L LM_B, evalL (n0 - aff.(aff_need) + aff.(aff_add)) (n1 - p1) out, []).
Proof.
  revert m l r st out aff p1 hV h; induction n as [|n ih]; intros m l r st out aff p1 hV h; [discriminate |].
  destruct st as [isC l1 r1 dp0 dp1 | isA l1 r1 dp0 dp1 | o0 dp0 dp1 dM |]; cbn [symRunLoop] in h; try discriminate.
  - destruct (symRunLoop absorbP0 n (symSweepL fuel_16384 isC l1 r1)) as [[[r_out r_aff] r_p1]|] eqn:hrec; try discriminate.
    inversion h; subst out aff p1.
    intros n0 n1 h0 h1.
    destruct (affComp_spec (mkAff dp0 0) r_aff n0 h0) as [hdp0 [haff0 hEq0]].
    cbn [aff_need aff_add] in hdp0, haff0, hEq0; replace (n0 - dp0 + 0) with (n0 - dp0) in haff0, hEq0 by lia.
    pose proof (hV n0 n1 hdp0 ltac:(lia)) as hs1.
    pose proof (ih _ _ _ _ _ _ _ (symSweepL_sound fuel_16384 isC l1 r1) hrec (n0 - dp0) (n1 - dp1) haff0 ltac:(lia)) as hs2.
    replace (n1 - dp1 - r_p1) with (n1 - (dp1 + r_p1)) in hs2 by lia.
    rewrite hEq0 in hs2; exact (rPlus_trans hs1 hs2).
  - destruct (symRunLoop absorbP0 n (symSweepR absorbP0 fuel_16384 isA l1 r1)) as [[[r_out r_aff] r_p1]|] eqn:hrec; try discriminate.
    inversion h; subst out aff p1.
    intros n0 n1 h0 h1.
    destruct (affComp_spec (mkAff dp0 0) r_aff n0 h0) as [hdp0 [haff0 hEq0]].
    cbn [aff_need aff_add] in hdp0, haff0, hEq0; replace (n0 - dp0 + 0) with (n0 - dp0) in haff0, hEq0 by lia.
    pose proof (hV n0 n1 hdp0 ltac:(lia)) as hs1.
    pose proof (ih _ _ _ _ _ _ _ (symSweepR_sound absorbP0 fuel_16384 isA l1 r1) hrec (n0 - dp0) (n1 - dp1) haff0 ltac:(lia)) as hs2.
    replace (n1 - dp1 - r_p1) with (n1 - (dp1 + r_p1)) in hs2 by lia.
    rewrite hEq0 in hs2; exact (rPlus_trans hs1 hs2).
  - inversion h; subst; exact hV.
Qed.

Fixpoint splitABPrefix (c : nat) (body : list LTok) : option (list LTok * list LTok) :=
  match c with
  | 0%nat => Some ([], body)
  | S c' =>
      match body with
      | L_B :: xs =>
          match splitABPrefix c' xs with
          | Some (p, s) => Some (L_B :: p, s)
          | None => None
          end
      | L_sym k v :: xs =>
          match splitABPrefix c' xs with
          | Some (p, s) => Some (L_sym k v :: p, s)
          | None => None
          end
      | L_A 0 :: xs =>
          match splitABPrefix c' xs with
          | Some (p, s) => Some (L_A 0 :: p, s)
          | None => None
          end
      | L_A (S m) :: xs =>
          match splitABPrefix c' (L_A m :: xs) with
          | Some (p, s) => Some (pushLA 0 p, s)
          | None => None
          end
      | _ => None
      end
  end.

Lemma splitABPrefix_spec (n0 n1 : N) {c : nat} {body pref suf : list LTok}
  (h : splitABPrefix c body = Some (pref, suf)) :
  (exists prefAB : list ABWord, evalL n0 n1 pref = evalABL prefAB) /\
  evalL n0 n1 body = evalL n0 n1 pref ++ evalL n0 n1 suf.
Proof.
  revert body pref suf h; induction c as [|c ih]; intros body pref suf h.
  - inversion h; subst; split; [exists (@nil ABWord); reflexivity | reflexivity].
  - destruct body as [|[| |[|m]| | |k v] xs]; cbn [splitABPrefix] in h; try discriminate.
    + destruct (splitABPrefix c xs) as [[p s]|] eqn:hs; try discriminate.
      inversion h; subst pref suf.
      destruct (ih _ _ _ hs) as [[ab hab] hEq].
      split; [exists (AB_A :: ab); cbn [evalL evalABL bitsARn bitsA]; rewrite hab; reflexivity |
              cbn [evalL]; rewrite hEq, ?app_assoc; reflexivity].
    + destruct (splitABPrefix c (L_A m :: xs)) as [[p s]|] eqn:hs; try discriminate.
      inversion h; subst pref suf.
      destruct (ih _ _ _ hs) as [[ab hab] hEq].
      split; [exists (AB_A :: ab); rewrite evalL_pushLA, hab; reflexivity |
              rewrite evalL_pushLA; cbn [evalL bitsARn bitsA app] in hEq |- *; rewrite hEq, ?app_assoc; reflexivity].
    + destruct (splitABPrefix c xs) as [[p s]|] eqn:hs; try discriminate.
      inversion h; subst pref suf.
      destruct (ih _ _ _ hs) as [[ab hab] hEq].
      split; [exists (AB_B :: ab); cbn [evalL evalABL]; rewrite hab; reflexivity |
              cbn [evalL]; rewrite hEq, ?app_assoc; reflexivity].
    + destruct (splitABPrefix c xs) as [[p s]|] eqn:hs; try discriminate.
      inversion h; subst pref suf.
      destruct (ih _ _ _ hs) as [[ab hab] hEq].
      split; [exists (powListN (blkAB k) (if v then n1 else n0) ++ ab);
              cbn [evalL]; rewrite evalABL_append, evalABL_powListN, hab; reflexivity |
              cbn [evalL]; rewrite hEq, ?app_assoc; reflexivity].
Qed.

Definition symHubStep (sufTbl : P32768 SufBucket) (absorbP0 : bool) (cutHint : N) (w : list LTok) :
  option (list LTok * Aff * N) :=
  if N.eqb cutHint 0 then
    symRunLoop absorbP0 fuel_4096 (symSweepL fuel_16384 false w [])
  else
    match w with
    | L_b1 :: L_C :: body =>
        match splitABPrefix (N.to_nat (cutHint - 1)) body with
        | Some (pref, suf) =>
            match encLTok suf with
            | Some sufCode =>
                match lookupSuf sufTbl sufCode with
                | Some osuf =>
                    let outBody := appendLTok pref (decLTok osuf) in
                    if absorbP0 then
                      match outBody with
                      | L_sym S_P false :: rest =>
                          if noVarL false rest then Some (L_b1 :: L_C :: outBody, mkAff 0 1, 0)
                          else Some (L_b1 :: L_C :: L_A 0 :: L_B :: L_B :: outBody, affId, 0)
                      | _ => Some (L_b1 :: L_C :: L_A 0 :: L_B :: L_B :: outBody, affId, 0)
                      end
                    else
                      Some (L_b1 :: L_C :: L_A 0 :: L_B :: L_B :: outBody, affId, 0)
                | None => None
                end
            | None => None
            end
        | None => None
        end
    | _ => None
    end.

Lemma symHubStep_sound {sufTbl : P32768 SufBucket} (hV : ValidSufTbl sufTbl)
  {absorbP0 : bool} {cutHint : N} {w out : list LTok} {aff : Aff} {p1 : N}
  (h : symHubStep sufTbl absorbP0 cutHint w = Some (out, aff, p1)) :
  forall n0 n1 : N, aff.(aff_need) <= n0 -> p1 <= n1 ->
    RPlus (M_L LM_B, evalL n0 n1 w, [])
          (M_L LM_B, evalL (n0 - aff.(aff_need) + aff.(aff_add)) (n1 - p1) out, []).
Proof.
  unfold symHubStep in h.
  destruct (N.eqb cutHint 0) eqn:hz.
  - exact (symRunLoop_sound (symSweepL_sound fuel_16384 false w []) h).
  - destruct w as [|[| | | | | ] w1]; try discriminate.
    destruct w1 as [|[| | | | | ] body]; try discriminate.
    destruct (splitABPrefix (N.to_nat (cutHint - 1)) body) as [[pref suf]|] eqn:hsp; try discriminate.
    destruct (encLTok suf) as [sufCode|] eqn:henc; try discriminate.
    destruct (lookupSuf sufTbl sufCode) as [osuf|] eqn:hlook; try discriminate.
    intros n0 n1 _ _.
    destruct (splitABPrefix_spec n0 n1 hsp) as [[prefAB hprefAB] hbody].
    pose proof (lookupSuf_sound hV hlook prefAB) as hrun.
    assert (hIn : evalL n0 n1 (L_b1 :: L_C :: body) =
                  true :: bitsC ++ evalABL prefAB ++ decBits sufCode)
      by (cbn [evalL]; rewrite hbody, hprefAB, (encLTok_evalL n0 n1 henc), app_assoc; reflexivity).
    set (outBody := appendLTok pref (decLTok osuf)) in *.
    assert (hOutBase : true :: bitsC ++ blkBitsL S_P ++ evalABL prefAB ++ decBits osuf =
                       true :: bitsC ++ blkBitsL S_P ++ evalL n0 n1 outBody)
      by (unfold outBody; rewrite evalL_appendLTok, hprefAB, (evalL_decLTok n0 n1 osuf); reflexivity).
    rewrite <- hIn, hOutBase in hrun.
    assert (hDefault :
      out = L_b1 :: L_C :: L_A 0 :: L_B :: L_B :: outBody -> aff = affId -> p1 = 0 ->
      RPlus (M_L LM_B, evalL n0 n1 (L_b1 :: L_C :: body), [])
            (M_L LM_B, evalL (n0 - aff.(aff_need) + aff.(aff_add)) (n1 - p1) out, [])).
    { intros -> -> ->; cbn [affId aff_need aff_add].
      replace (n0 - 0 + 0) with n0 by lia; replace (n1 - 0) with n1 by lia.
      cbn [evalL blkBitsL bitsARn bitsA app] in hrun |- *; repeat rewrite <- app_assoc in hrun; repeat rewrite <- app_assoc; exact hrun. }
    destruct absorbP0; [| inversion h; subst; exact (hDefault eq_refl eq_refl eq_refl)].
    destruct outBody as [|[| | | | |[| | | | | ] [|]] rest];
      try (inversion h; subst; exact (hDefault eq_refl eq_refl eq_refl)).
    destruct (noVarL false rest) eqn:hnv;
      [| inversion h; subst; exact (hDefault eq_refl eq_refl eq_refl)].
    inversion h; subst out aff p1; cbn [aff_need aff_add].
    replace (n0 - 0 + 1) with (n0 + 1) by lia; replace (n1 - 0) with n1 by lia.
    replace (evalL (n0 + 1) n1 (L_b1 :: L_C :: L_sym S_P false :: rest))
      with (true :: bitsC ++ blkBitsL S_P ++ evalL n0 n1 (L_sym S_P false :: rest)); [exact hrun |].
    cbn [evalL]; rewrite powBitsN_succ, (evalL_noVar_false (n0 := n0 + 1) (n0' := n0) hnv); repeat rewrite <- app_assoc; reflexivity.
Qed.

Fixpoint runSymSeq (sufTbl : P32768 SufBucket) (absorbP0 : bool)
  (hs : list N) (w : list LTok) : option (list LTok * Aff * N) :=
  match hs with
  | [] => Some (w, affId, 0)
  | h :: rest =>
      match symHubStep sufTbl absorbP0 h w with
      | Some (w1, aff1, p1) =>
          match runSymSeq sufTbl absorbP0 rest w1 with
          | Some (w2, aff2, p2) => Some (w2, affComp aff1 aff2, p1 + p2)
          | None => None
          end
      | None => None
      end
  end.

Lemma runSymSeq_sound {sufTbl : P32768 SufBucket} (hV : ValidSufTbl sufTbl)
  {absorbP0 : bool} {hs : list N} {w out : list LTok} {aff : Aff} {p1 : N}
  (h : runSymSeq sufTbl absorbP0 hs w = Some (out, aff, p1)) :
  forall n0 n1 : N, aff.(aff_need) <= n0 -> p1 <= n1 ->
    RStar (M_L LM_B, evalL n0 n1 w, [])
          (M_L LM_B, evalL (n0 - aff.(aff_need) + aff.(aff_add)) (n1 - p1) out, []) /\
    (hs <> [] ->
      RPlus (M_L LM_B, evalL n0 n1 w, [])
            (M_L LM_B, evalL (n0 - aff.(aff_need) + aff.(aff_add)) (n1 - p1) out, [])).
Proof.
  revert w out aff p1 h; induction hs as [|hd tl ih]; intros w out aff p1 h.
  - inversion h; subst; intros n0 n1 _ _; cbn [affId aff_need aff_add].
    replace (n0 - 0 + 0) with n0 by lia; replace (n1 - 0) with n1 by lia.
    split; [apply rStar_refl | intro hc; congruence].
  - cbn [runSymSeq] in h.
    destruct (symHubStep sufTbl absorbP0 hd w) as [[[w1 aff1] p1a]|] eqn:h1; try discriminate.
    destruct (runSymSeq sufTbl absorbP0 tl w1) as [[[w2 aff2] p1b]|] eqn:h2; try discriminate.
    inversion h; subst out aff p1.
    intros n0 n1 h0 h1p.
    destruct (affComp_spec aff1 aff2 n0 h0) as [hn1 [hn2 hEq0]].
    pose proof (symHubStep_sound hV h1 n0 n1 hn1 ltac:(lia)) as hs1.
    destruct (ih _ _ _ _ h2 (n0 - aff1.(aff_need) + aff1.(aff_add)) (n1 - p1a) hn2 ltac:(lia)) as [hs2 _].
    replace (n1 - p1a - p1b) with (n1 - (p1a + p1b)) in hs2 by lia.
    rewrite hEq0 in hs2.
    pose proof (rPlus_trans_star hs1 hs2) as hplus.
    split; [exact (rPlus_to_star hplus) | intros _; exact hplus].
Qed.

(* Fast 2-bit constructors for P, Q3, AAB, AAAAB, AABB *)
Definition pCode : N := 41.
Definition q3Code : N := 149.
Definition aabCode : N := 37.
Definition aaaabCode : N := 597.
Definition aabbCode : N := 165.

Definition prependOneP (q : N) : N := mul4Add1 (mul4Add2 (mul4Add2 q)).
Definition prependOneQ3 (q : N) : N := mul4Add1 (mul4Add1 (mul4Add1 (mul4Add2 q))).
Definition prependAAB (q : N) : N := mul4Add1 (mul4Add1 (mul4Add2 q)).
Definition prependAAAAB (q : N) : N := mul4Add1 (mul4Add1 (mul4Add1 (mul4Add1 (mul4Add2 q)))).

Lemma decBits_prependOneP (q : N) : decBits (prependOneP q) = blkBitsL S_P ++ decBits q.
Proof. unfold prependOneP, blkBitsL; rewrite !decBits_mul4Add1, !decBits_mul4Add2; cbn [bitsARn bitsA bitsB app]; reflexivity. Qed.

Lemma decBits_prependOneQ3 (q : N) : decBits (prependOneQ3 q) = blkBitsL S_Q3 ++ decBits q.
Proof. unfold prependOneQ3, blkBitsL; rewrite !decBits_mul4Add1, !decBits_mul4Add2; cbn [bitsARn bitsA bitsB app]; reflexivity. Qed.

Lemma decBits_prependAAB (q : N) : decBits (prependAAB q) = bitsA ++ bitsA ++ bitsB ++ decBits q.
Proof. unfold prependAAB; rewrite !decBits_mul4Add1, !decBits_mul4Add2; reflexivity. Qed.

Lemma decBits_prependAAAAB (q : N) : decBits (prependAAAAB q) = bitsARn 4 ++ bitsB ++ decBits q.
Proof. unfold prependAAAAB; rewrite !decBits_mul4Add1, !decBits_mul4Add2; cbn [bitsARn bitsA bitsB app]; reflexivity. Qed.

Lemma decBits_aabbCode : decBits aabbCode = evalABL [AB_A; AB_A; AB_B; AB_B].
Proof. reflexivity. Qed.

Lemma decBits_q3Code : decBits q3Code = bitsARn 3 ++ bitsB.
Proof. reflexivity. Qed.

Lemma decBits_aaaabCode : decBits aaaabCode = bitsARn 4 ++ bitsB.
Proof. reflexivity. Qed.

Fixpoint prependPNat (k : nat) (w : N) : N :=
  match k with
  | 0%nat => w
  | S k' => prependOneP (prependPNat k' w)
  end.

Definition prependP (k w : N) : N := prependPNat (N.to_nat k) w.

Lemma decBits_prependP (k w : N) :
  decBits (prependP k w) = powBitsN (blkBitsL S_P) k ++ decBits w.
Proof.
  unfold prependP, powBitsN; induction (N.to_nat k) as [|m ih]; [reflexivity |].
  cbn [prependPNat powBits]; rewrite decBits_prependOneP, ih, app_assoc; reflexivity.
Qed.

Fixpoint prependQ3Nat (k : nat) (w : N) : N :=
  match k with
  | 0%nat => w
  | S k' => prependOneQ3 (prependQ3Nat k' w)
  end.

Definition prependQ3 (k w : N) : N := prependQ3Nat (N.to_nat k) w.

Lemma decBits_prependQ3 (k w : N) :
  decBits (prependQ3 k w) = powBitsN (blkBitsL S_Q3) k ++ decBits w.
Proof.
  unfold prependQ3, powBitsN; induction (N.to_nat k) as [|m ih]; [reflexivity |].
  cbn [prependQ3Nat powBits]; rewrite decBits_prependOneQ3, ih, app_assoc; reflexivity.
Qed.

Fixpoint splitAtSym (k : SymKind) (v : bool) (l : list LTok) : option (list LTok * list LTok) :=
  match l with
  | [] => None
  | L_sym k' v' :: xs =>
      if symKind_eqb k k' && Bool.eqb v v' then Some ([], xs) else None
  | x :: xs =>
      match splitAtSym k v xs with
      | Some (a, b) => Some (x :: a, b)
      | None => None
      end
  end.

Lemma splitAtSym_spec (n0 n1 : N) {k : SymKind} {v : bool} {l a b : list LTok}
  (h : splitAtSym k v l = Some (a, b)) :
  evalL n0 n1 l = evalL n0 n1 a ++ powBitsN (blkBitsL k) (if v then n1 else n0) ++ evalL n0 n1 b.
Proof.
  revert a b h; induction l as [|x xs ih]; intros a b h; [discriminate |].
  destruct x as [| |ka| | |k' v']; cbn [splitAtSym] in h;
    try (destruct (splitAtSym k v xs) as [[a1 b1]|] eqn:hs; try discriminate;
         inversion h; subst a b; cbn [evalL app]; rewrite (ih _ _ eq_refl); repeat rewrite <- app_assoc; reflexivity).
  destruct (symKind_eqb k k' && Bool.eqb v v') eqn:heq; [| discriminate].
  apply Bool.andb_true_iff in heq; destruct heq as [hk hv].
  apply symKind_eqb_eq in hk; apply Bool.eqb_prop in hv; subst k' v'.
  inversion h; subst a b; reflexivity.
Qed.

Fixpoint prependBlksLTokNat (bt : bool) (k : nat) (xs : list LTok) : list LTok :=
  match k with
  | 0%nat => xs
  | S k' => appendLTok (blkLTok (blkKind bt)) (prependBlksLTokNat bt k' xs)
  end.

Definition prependBlksLTok (bt : bool) (k : N) (xs : list LTok) : list LTok :=
  prependBlksLTokNat bt (N.to_nat k) xs.

Lemma evalL_prependBlksLTok (n0 n1 : N) (bt : bool) (k : N) (xs : list LTok) :
  evalL n0 n1 (prependBlksLTok bt k xs) = powBitsN (blkBitsL (blkKind bt)) k ++ evalL n0 n1 xs.
Proof.
  unfold prependBlksLTok, powBitsN; induction (N.to_nat k) as [|m ih]; [reflexivity |].
  cbn [prependBlksLTokNat powBits]; rewrite evalL_appendLTok, evalL_blkLTok, ih, app_assoc; reflexivity.
Qed.

(* 1. Rule1Blk & check1Blk *)
Record Rule1Blk := mkR1 {
  r1_bt : bool;
  r1_midCode : N;
  r1_kr : N;
  r1_tlCode : N;
  r1_outRestCode : N;
  r1_need0 : N;
  r1_add0 : N
}.

Definition check1Blk (sufTbl : P32768 SufBucket) (r : Rule1Blk) (preQ postQ : N) (hints : list N) : bool :=
  if isEmpty hints then false
  else
    let w0 := L_b1 :: L_C :: L_sym S_P false ::
      appendLTok (decLTok r.(r1_midCode)) (prependBlksLTok r.(r1_bt) r.(r1_kr) (decLTok r.(r1_tlCode))) in
    match runSymSeq sufTbl true hints w0 with
    | Some (L_b1 :: L_C :: L_A 2 :: L_C :: rest0, aff, 0) =>
        match splitAtSym S_Q3 false rest0 with
        | Some (beforeQ, afterQ) =>
            match encLTok beforeQ, encLTok afterQ with
            | Some bCode, Some aCode =>
                N.eqb bCode (prependQ3 preQ 0) &&
                N.eqb aCode (prependQ3 postQ r.(r1_outRestCode)) &&
                N.eqb aff.(aff_need) r.(r1_need0) &&
                N.eqb (aff.(aff_add) + (preQ + postQ)) r.(r1_add0)
            | _, _ => false
            end
        | None => false
        end
    | _ => false
    end.

Lemma check1Blk_sound {sufTbl : P32768 SufBucket} (hV : ValidSufTbl sufTbl)
  {r : Rule1Blk} {preQ postQ : N} {hints : list N}
  (h : check1Blk sufTbl r preQ postQ hints = true) :
  forall M : N, r.(r1_need0) <= M ->
    RPlus (M_L LM_B, true :: bitsC ++ powBitsN (blkBitsL S_P) M ++ decBits r.(r1_midCode) ++
                     powBitsN (blkBitsL (blkKind r.(r1_bt))) r.(r1_kr) ++ decBits r.(r1_tlCode), [])
          (M_L LM_B, true :: bitsC ++ bitsARn 3 ++ bitsC ++
                     powBitsN (blkBitsL S_Q3) (M - r.(r1_need0) + r.(r1_add0)) ++ decBits r.(r1_outRestCode), []).
Proof.
  unfold check1Blk in h.
  destruct (isEmpty hints) eqn:hem; [discriminate |].
  assert (hne : hints <> []) by (destruct hints; [discriminate | intro hc; discriminate]).
  destruct (runSymSeq sufTbl true hints _) as [[[out0 aff] p1]|] eqn:hrun; try discriminate.
  destruct out0 as [|[| | | | | ] oa]; try discriminate.
  destruct oa as [|[| | | | | ] ob]; try discriminate.
  destruct ob as [|[| |[|[|[|]]]| | | ] oc]; try discriminate.
  destruct oc as [|[| | | | | ] rest0]; try discriminate.
  destruct p1; [| discriminate].
  destruct (splitAtSym S_Q3 false rest0) as [[beforeQ afterQ]|] eqn:hsp; try discriminate.
  destruct (encLTok beforeQ) as [bCode|] eqn:hb; try discriminate.
  destruct (encLTok afterQ) as [aCode|] eqn:ha; try discriminate.
  apply Bool.andb_true_iff in h; destruct h as [h heq4].
  apply Bool.andb_true_iff in h; destruct h as [h heq3].
  apply Bool.andb_true_iff in h; destruct h as [heq1 heq2].
  apply N.eqb_eq in heq1; apply N.eqb_eq in heq2; apply N.eqb_eq in heq3; apply N.eqb_eq in heq4.
  intros M hM.
  pose proof (proj2 (runSymSeq_sound hV hrun M 0 ltac:(lia) (N.le_refl 0)) hne) as hstep.
  replace (0 - 0) with 0 in hstep by lia.
  assert (hL0 : evalL M 0 (L_b1 :: L_C :: L_sym S_P false ::
      appendLTok (decLTok r.(r1_midCode)) (prependBlksLTok r.(r1_bt) r.(r1_kr) (decLTok r.(r1_tlCode)))) =
      true :: bitsC ++ powBitsN (blkBitsL S_P) M ++ decBits r.(r1_midCode) ++
      powBitsN (blkBitsL (blkKind r.(r1_bt))) r.(r1_kr) ++ decBits r.(r1_tlCode)).
  { cbn [evalL]; rewrite evalL_appendLTok, evalL_prependBlksLTok, !evalL_decLTok; repeat rewrite <- app_assoc; reflexivity. }
  set (M1 := M - aff.(aff_need) + aff.(aff_add)) in *.
  assert (hL1 : evalL M1 0 (L_b1 :: L_C :: L_A 2 :: L_C :: rest0) =
      true :: bitsC ++ bitsARn 3 ++ bitsC ++
      powBitsN (blkBitsL S_Q3) (M - r.(r1_need0) + r.(r1_add0)) ++ decBits r.(r1_outRestCode)).
  { cbn [evalL]; rewrite (splitAtSym_spec M1 0 hsp), (encLTok_evalL M1 0 hb), (encLTok_evalL M1 0 ha).
    rewrite heq1, heq2, !decBits_prependQ3, decBits_zero, app_nil_r.
    replace (powBitsN (blkBitsL S_Q3) preQ ++ powBitsN (blkBitsL S_Q3) M1 ++
             (powBitsN (blkBitsL S_Q3) postQ ++ decBits r.(r1_outRestCode)))
      with (powBitsN (blkBitsL S_Q3) (M - r.(r1_need0) + r.(r1_add0)) ++ decBits r.(r1_outRestCode)).
    - repeat rewrite <- app_assoc; reflexivity.
    - replace (M - r.(r1_need0) + r.(r1_add0)) with (preQ + M1 + postQ) by (unfold M1; lia).
      rewrite !powBitsN_add; repeat rewrite <- app_assoc; reflexivity. }
  rewrite hL0, hL1 in hstep; exact hstep.
Qed.

(* 2. RulePF & checkPF *)
Record RulePF := mkRPF {
  rpf_restCode : N;
  rpf_par : bool;
  rpf_bt : bool;
  rpf_mdCode : N;
  rpf_pc : N;
  rpf_need0 : N;
  rpf_addK : N;
  rpf_t1Code : N
}.

Definition checkPF (sufTbl : P32768 SufBucket) (r : RulePF) (preB postB : N) (hints : list N) : bool :=
  if isEmpty hints then false
  else if isABCode r.(rpf_mdCode) then
    let qPar := if r.(rpf_par) then [L_A 2; L_B] else [] in
    let w0 := L_b1 :: L_C :: L_A 2 :: L_C :: (qPar ++ L_sym S_Q3_2 false :: decLTok r.(rpf_restCode)) in
    match runSymSeq sufTbl false hints w0 with
    | Some (L_b1 :: L_C :: body, aff, 0) =>
        match splitAtSym (blkKind r.(rpf_bt)) false body with
        | Some (beforeB, afterB) =>
            match encLTok beforeB, encLTok afterB with
            | Some bCode, Some aCode =>
                let expBefore := prependP r.(rpf_pc) (prependCode r.(rpf_mdCode) (prependBlks r.(rpf_bt) preB 0)) in
                let expAfter := prependBlks r.(rpf_bt) postB r.(rpf_t1Code) in
                N.eqb bCode expBefore &&
                N.eqb aCode expAfter &&
                N.eqb aff.(aff_need) r.(rpf_need0) &&
                N.eqb (aff.(aff_add) + (preB + postB)) r.(rpf_addK)
            | _, _ => false
            end
        | None => false
        end
    | _ => false
    end
  else false.

Lemma checkPF_sound {sufTbl : P32768 SufBucket} (hV : ValidSufTbl sufTbl)
  {r : RulePF} {preB postB : N} {hints : list N}
  (h : checkPF sufTbl r preB postB hints = true) :
  (exists mdAB : list ABWord, decBits r.(rpf_mdCode) = evalABL mdAB) /\
  forall Nv : N, r.(rpf_need0) <= Nv ->
    RPlus (M_L LM_B, true :: bitsC ++ bitsARn 3 ++ bitsC ++
                     powBitsN (blkBitsL S_Q3) (2 * Nv + if r.(rpf_par) then 1 else 0) ++ decBits r.(rpf_restCode), [])
          (M_L LM_B, true :: bitsC ++ powBitsN (blkBitsL S_P) r.(rpf_pc) ++ decBits r.(rpf_mdCode) ++
                     powBitsN (blkBitsL (blkKind r.(rpf_bt))) (Nv - r.(rpf_need0) + r.(rpf_addK)) ++ decBits r.(rpf_t1Code), []).
Proof.
  unfold checkPF in h.
  destruct (isEmpty hints) eqn:hem; [discriminate |].
  assert (hne : hints <> []) by (destruct hints; [discriminate | intro hc; discriminate]).
  destruct (isABCode r.(rpf_mdCode)) eqn:hAB; [| discriminate].
  split; [exists (decAB r.(rpf_mdCode)); symmetry; exact (evalABL_decAB _ hAB) |].
  destruct (runSymSeq sufTbl false hints _) as [[[out0 aff] p1]|] eqn:hrun; try discriminate.
  destruct out0 as [|[| | | | | ] oa]; try discriminate.
  destruct oa as [|[| | | | | ] body]; try discriminate.
  destruct p1; [| discriminate].
  destruct (splitAtSym (blkKind r.(rpf_bt)) false body) as [[beforeB afterB]|] eqn:hsp; try discriminate.
  destruct (encLTok beforeB) as [bCode|] eqn:hb; try discriminate.
  destruct (encLTok afterB) as [aCode|] eqn:ha; try discriminate.
  apply Bool.andb_true_iff in h; destruct h as [h heq4].
  apply Bool.andb_true_iff in h; destruct h as [h heq3].
  apply Bool.andb_true_iff in h; destruct h as [heq1 heq2].
  apply N.eqb_eq in heq1; apply N.eqb_eq in heq2; apply N.eqb_eq in heq3; apply N.eqb_eq in heq4.
  intros Nv hN.
  pose proof (proj2 (runSymSeq_sound hV hrun Nv 0 ltac:(lia) (N.le_refl 0)) hne) as hstep.
  replace (0 - 0) with 0 in hstep by lia.
  assert (hL0 : evalL Nv 0 (L_b1 :: L_C :: L_A 2 :: L_C ::
      ((if r.(rpf_par) then [L_A 2; L_B] else []) ++ L_sym S_Q3_2 false :: decLTok r.(rpf_restCode))) =
      true :: bitsC ++ bitsARn 3 ++ bitsC ++
      powBitsN (blkBitsL S_Q3) (2 * Nv + if r.(rpf_par) then 1 else 0) ++ decBits r.(rpf_restCode)).
  { destruct r.(rpf_par); cbn [app evalL]; rewrite powBitsN_Q32_L_eq, evalL_decLTok.
    - rewrite powBitsN_succ; cbn [blkBitsL app]; repeat rewrite <- app_assoc; reflexivity.
    - replace (2 * Nv + 0) with (2 * Nv) by lia; repeat rewrite <- app_assoc; reflexivity. }
  set (N1 := Nv - aff.(aff_need) + aff.(aff_add)) in *.
  assert (hL1 : evalL N1 0 (L_b1 :: L_C :: body) =
      true :: bitsC ++ powBitsN (blkBitsL S_P) r.(rpf_pc) ++ decBits r.(rpf_mdCode) ++
      powBitsN (blkBitsL (blkKind r.(rpf_bt))) (Nv - r.(rpf_need0) + r.(rpf_addK)) ++ decBits r.(rpf_t1Code)).
  { cbn [evalL]; rewrite (splitAtSym_spec N1 0 hsp), (encLTok_evalL N1 0 hb), (encLTok_evalL N1 0 ha).
    rewrite heq1, heq2, decBits_prependP, (decBits_prependCode_ab _ _ hAB), (evalABL_decAB _ hAB),
            !decBits_prependBlks, decBits_zero, app_nil_r.
    replace (Nv - r.(rpf_need0) + r.(rpf_addK)) with (preB + N1 + postB) by (unfold N1; lia).
    rewrite !powBitsN_add; repeat rewrite <- app_assoc; reflexivity. }
  rewrite hL0, hL1 in hstep; exact hstep.
Qed.

(* 3. Rule2Blk & check2Blk *)
Record Rule2Blk := mkR2 {
  r2_x2 : bool;
  r2_kr : N;
  r2_tlCode : N;
  r2_isKind2 : bool;
  r2_bt : bool;
  r2_mdCode : N;
  r2_pc : N;
  r2_need0 : N;
  r2_add0 : N;
  r2_need1 : N;
  r2_addK : N;
  r2_t1Code : N
}.

Definition check2Blk (sufTbl : P32768 SufBucket) (r : Rule2Blk) (c1 c2 c3 c4 : N) (hints1 hints2 : list N) : bool :=
  if isEmpty hints1 then false
  else
    let qPar := if r.(r2_x2) then [L_A 2; L_B] else [] in
    let w0 := L_b1 :: L_C :: L_sym S_P false :: L_A 1 :: L_B ::
      (qPar ++ L_sym S_Q3_2 true :: L_A 3 :: L_B :: prependBlksLTok true r.(r2_kr) (decLTok r.(r2_tlCode))) in
    match runSymSeq sufTbl true hints1 w0 with
    | Some (w1, aff1, p1a) =>
        match runSymSeq sufTbl false hints2 w1 with
        | Some (L_b1 :: L_C :: body, aff2, p1b) =>
            let aff := affComp aff1 aff2 in
            let p1 := p1a + p1b in
            if negb r.(r2_isKind2) then
              if isABCode r.(r2_mdCode) then
                match splitAtSym S_P false body with
                | Some (prePToks, rest1) =>
                    match splitAtSym (blkKind r.(r2_bt)) true rest1 with
                    | Some (midToks, postToks) =>
                        match encLTok prePToks, encLTok midToks, encLTok postToks with
                        | Some cPre, Some cMid, Some cPost =>
                            let expMid := prependP c2 (prependCode r.(r2_mdCode) (prependBlks r.(r2_bt) c3 0)) in
                            N.eqb cPre (prependP c1 0) &&
                            N.eqb cMid expMid &&
                            N.eqb cPost (prependBlks r.(r2_bt) c4 r.(r2_t1Code)) &&
                            N.eqb aff.(aff_need) r.(r2_need0) &&
                            N.eqb (aff.(aff_add) + (c1 + c2)) r.(r2_add0) &&
                            N.eqb p1 r.(r2_need1) &&
                            N.eqb (c3 + c4) r.(r2_addK)
                        | _, _, _ => false
                        end
                    | None => false
                    end
                | None => false
                end
              else false
            else
              if r.(r2_bt) then
                match splitAtSym S_Q3 false body with
                | Some (preQToks, rest1) =>
                    match splitAtSym S_W5 true rest1 with
                    | Some (midToks, postToks) =>
                        match encLTok preQToks, encLTok midToks, encLTok postToks with
                        | Some cPre, Some cMid, Some cPost =>
                            let expPre := prependP r.(r2_pc) (prependAAB (prependQ3 c1 0)) in
                            let expMid := prependQ3 c2 (prependAAAAB (prependBlks true c3 0)) in
                            N.eqb cPre expPre &&
                            N.eqb cMid expMid &&
                            N.eqb cPost (prependBlks true c4 r.(r2_t1Code)) &&
                            N.eqb aff.(aff_need) r.(r2_need0) &&
                            N.eqb (aff.(aff_add) + (c1 + c2)) r.(r2_add0) &&
                            N.eqb p1 r.(r2_need1) &&
                            N.eqb (c3 + c4) r.(r2_addK)
                        | _, _, _ => false
                        end
                    | None => false
                    end
                | None => false
                end
              else false
        | _ => false
        end
    | None => false
    end.

Lemma check2Blk_sound {sufTbl : P32768 SufBucket} (hV : ValidSufTbl sufTbl)
  {r : Rule2Blk} {c1 c2 c3 c4 : N} {hints1 hints2 : list N}
  (h : check2Blk sufTbl r c1 c2 c3 c4 hints1 hints2 = true) :
  (r.(r2_isKind2) = false -> exists mdAB : list ABWord, decBits r.(r2_mdCode) = evalABL mdAB) /\
  (r.(r2_isKind2) = true -> r.(r2_bt) = true) /\
  forall M Nv : N, r.(r2_need0) <= M -> r.(r2_need1) <= Nv ->
    let s0 : StateX := (M_L LM_B, true :: bitsC ++ powBitsN (blkBitsL S_P) M ++
      (bitsA ++ bitsA ++ bitsB ++ powBitsN (blkBitsL S_Q3) (2 * Nv + if r.(r2_x2) then 1 else 0) ++ bitsARn 4 ++ bitsB) ++
      powBitsN (blkBitsL S_W5) r.(r2_kr) ++ decBits r.(r2_tlCode), []) in
    if r.(r2_isKind2) then
      RPlus s0 (M_L LM_B, true :: bitsC ++ powBitsN (blkBitsL S_P) r.(r2_pc) ++
        (bitsA ++ bitsA ++ bitsB ++ powBitsN (blkBitsL S_Q3) (M - r.(r2_need0) + r.(r2_add0)) ++ bitsARn 4 ++ bitsB) ++
        powBitsN (blkBitsL S_W5) (Nv - r.(r2_need1) + r.(r2_addK)) ++ decBits r.(r2_t1Code), [])
    else
      RPlus s0 (M_L LM_B, true :: bitsC ++ powBitsN (blkBitsL S_P) (M - r.(r2_need0) + r.(r2_add0)) ++
        decBits r.(r2_mdCode) ++ powBitsN (blkBitsL (blkKind r.(r2_bt))) (Nv - r.(r2_need1) + r.(r2_addK)) ++ decBits r.(r2_t1Code), []).
Proof.
  unfold check2Blk in h.
  destruct (isEmpty hints1) eqn:hem; [discriminate |].
  assert (hne : hints1 <> []) by (destruct hints1; [discriminate | intro hc; discriminate]).
  destruct (runSymSeq sufTbl true hints1 _) as [[[w1 aff1] p1a]|] eqn:hrun1; try discriminate.
  destruct (runSymSeq sufTbl false hints2 w1) as [[[out2 aff2] p1b]|] eqn:hrun2; try discriminate.
  destruct out2 as [|[| | | | | ] oa]; try discriminate.
  destruct oa as [|[| | | | | ] body]; try discriminate.
  set (aff := affComp aff1 aff2) in *.
  set (p1 := p1a + p1b) in *.
  assert (hrunBoth : forall M Nv : N, aff.(aff_need) <= M -> p1 <= Nv ->
    RPlus (M_L LM_B, true :: bitsC ++ powBitsN (blkBitsL S_P) M ++
      (bitsA ++ bitsA ++ bitsB ++ powBitsN (blkBitsL S_Q3) (2 * Nv + if r.(r2_x2) then 1 else 0) ++ bitsARn 4 ++ bitsB) ++
      powBitsN (blkBitsL S_W5) r.(r2_kr) ++ decBits r.(r2_tlCode), [])
      (M_L LM_B, evalL (M - aff.(aff_need) + aff.(aff_add)) (Nv - p1) (L_b1 :: L_C :: body), [])).
  { intros M Nv hM hN.
    destruct (affComp_spec aff1 aff2 M hM) as [hn1 [hn2 hEq0]].
    pose proof (proj2 (runSymSeq_sound hV hrun1 M Nv hn1 ltac:(unfold p1 in hN; lia)) hne) as hs1.
    pose proof (proj1 (runSymSeq_sound hV hrun2 (M - aff1.(aff_need) + aff1.(aff_add)) (Nv - p1a) hn2 ltac:(unfold p1 in hN; lia))) as hs2.
    replace (Nv - p1a - p1b) with (Nv - p1) in hs2 by (unfold p1; lia).
    rewrite hEq0 in hs2.
    pose proof (rPlus_trans_star hs1 hs2) as hplus.
    assert (hL0 : evalL M Nv (L_b1 :: L_C :: L_sym S_P false :: L_A 1 :: L_B ::
        ((if r.(r2_x2) then [L_A 2; L_B] else []) ++ L_sym S_Q3_2 true :: L_A 3 :: L_B ::
          prependBlksLTok true r.(r2_kr) (decLTok r.(r2_tlCode)))) =
        true :: bitsC ++ powBitsN (blkBitsL S_P) M ++
        (bitsA ++ bitsA ++ bitsB ++ powBitsN (blkBitsL S_Q3) (2 * Nv + if r.(r2_x2) then 1 else 0) ++ bitsARn 4 ++ bitsB) ++
        powBitsN (blkBitsL S_W5) r.(r2_kr) ++ decBits r.(r2_tlCode)).
    { destruct r.(r2_x2); cbn [app evalL blkKind]; rewrite evalL_prependBlksLTok, powBitsN_Q32_L_eq, evalL_decLTok.
      - rewrite powBitsN_succ; cbn [blkKind blkBitsL bitsARn bitsA bitsB app]; repeat rewrite <- app_assoc; reflexivity.
      - replace (2 * Nv + 0) with (2 * Nv) by lia; cbn [blkKind blkBitsL bitsARn bitsA bitsB app]; repeat rewrite <- app_assoc; reflexivity. }
    rewrite hL0 in hplus; exact hplus. }
  destruct r.(r2_isKind2) eqn:hk2; cbn [negb] in h.
  - (* isKind2 = true *)
    destruct r.(r2_bt) eqn:hbt; [| discriminate].
    destruct (splitAtSym S_Q3 false body) as [[preQToks rest1]|] eqn:hsp1; try discriminate.
    destruct (splitAtSym S_W5 true rest1) as [[midToks postToks]|] eqn:hsp2; try discriminate.
    destruct (encLTok preQToks) as [cPre|] eqn:hc1; try discriminate.
    destruct (encLTok midToks) as [cMid|] eqn:hc2; try discriminate.
    destruct (encLTok postToks) as [cPost|] eqn:hc3; try discriminate.
    apply Bool.andb_true_iff in h; destruct h as [h heq7].
    apply Bool.andb_true_iff in h; destruct h as [h heq6].
    apply Bool.andb_true_iff in h; destruct h as [h heq5].
    apply Bool.andb_true_iff in h; destruct h as [h heq4].
    apply Bool.andb_true_iff in h; destruct h as [h heq3].
    apply Bool.andb_true_iff in h; destruct h as [heq1 heq2].
    apply N.eqb_eq in heq1; apply N.eqb_eq in heq2; apply N.eqb_eq in heq3;
    apply N.eqb_eq in heq4; apply N.eqb_eq in heq5; apply N.eqb_eq in heq6; apply N.eqb_eq in heq7.
    split; [intro hc; discriminate | split; [intros _; reflexivity |]].
    intros M Nv hM hN; cbn zeta.
    pose proof (hrunBoth M Nv ltac:(lia) ltac:(lia)) as hstep.
    set (M1 := M - aff.(aff_need) + aff.(aff_add)) in *.
    set (N1 := Nv - p1) in *.
    assert (hOut : evalL M1 N1 (L_b1 :: L_C :: body) =
        true :: bitsC ++ powBitsN (blkBitsL S_P) r.(r2_pc) ++
        (bitsA ++ bitsA ++ bitsB ++ powBitsN (blkBitsL S_Q3) (M - r.(r2_need0) + r.(r2_add0)) ++ bitsARn 4 ++ bitsB) ++
        powBitsN (blkBitsL S_W5) (Nv - r.(r2_need1) + r.(r2_addK)) ++ decBits r.(r2_t1Code)).
    { cbn [evalL]; rewrite (splitAtSym_spec M1 N1 hsp1), (splitAtSym_spec M1 N1 hsp2),
        (encLTok_evalL M1 N1 hc1), (encLTok_evalL M1 N1 hc2), (encLTok_evalL M1 N1 hc3).
      rewrite heq1, heq2, heq3, decBits_prependP, decBits_prependAAB, !decBits_prependQ3,
              decBits_prependAAAAB, !decBits_prependBlks, decBits_zero, !app_nil_r.
      cbn [blkKind blkBitsL bitsARn bitsA bitsB app].
      replace (M - r.(r2_need0) + r.(r2_add0)) with (c1 + M1 + c2) by (unfold M1; lia).
      replace (Nv - r.(r2_need1) + r.(r2_addK)) with (c3 + N1 + c4) by (unfold N1; lia).
      rewrite !powBitsN_add; cbn [blkKind blkBitsL bitsARn bitsA bitsB app]; repeat rewrite <- app_assoc; reflexivity. }
    rewrite hOut in hstep; exact hstep.
  - (* isKind2 = false *)
    destruct (isABCode r.(r2_mdCode)) eqn:hAB; [| discriminate].
    destruct (splitAtSym S_P false body) as [[prePToks rest1]|] eqn:hsp1; try discriminate.
    destruct (splitAtSym (blkKind r.(r2_bt)) true rest1) as [[midToks postToks]|] eqn:hsp2; try discriminate.
    destruct (encLTok prePToks) as [cPre|] eqn:hc1; try discriminate.
    destruct (encLTok midToks) as [cMid|] eqn:hc2; try discriminate.
    destruct (encLTok postToks) as [cPost|] eqn:hc3; try discriminate.
    apply Bool.andb_true_iff in h; destruct h as [h heq7].
    apply Bool.andb_true_iff in h; destruct h as [h heq6].
    apply Bool.andb_true_iff in h; destruct h as [h heq5].
    apply Bool.andb_true_iff in h; destruct h as [h heq4].
    apply Bool.andb_true_iff in h; destruct h as [h heq3].
    apply Bool.andb_true_iff in h; destruct h as [heq1 heq2].
    apply N.eqb_eq in heq1; apply N.eqb_eq in heq2; apply N.eqb_eq in heq3;
    apply N.eqb_eq in heq4; apply N.eqb_eq in heq5; apply N.eqb_eq in heq6; apply N.eqb_eq in heq7.
    split; [intros _; exists (decAB r.(r2_mdCode)); symmetry; exact (evalABL_decAB _ hAB) |].
    split; [intro hc; discriminate |].
    intros M Nv hM hN; cbn zeta.
    pose proof (hrunBoth M Nv ltac:(lia) ltac:(lia)) as hstep.
    set (M1 := M - aff.(aff_need) + aff.(aff_add)) in *.
    set (N1 := Nv - p1) in *.
    assert (hOut : evalL M1 N1 (L_b1 :: L_C :: body) =
        true :: bitsC ++ powBitsN (blkBitsL S_P) (M - r.(r2_need0) + r.(r2_add0)) ++
        decBits r.(r2_mdCode) ++ powBitsN (blkBitsL (blkKind r.(r2_bt))) (Nv - r.(r2_need1) + r.(r2_addK)) ++
        decBits r.(r2_t1Code)).
    { cbn [evalL]; rewrite (splitAtSym_spec M1 N1 hsp1), (splitAtSym_spec M1 N1 hsp2),
        (encLTok_evalL M1 N1 hc1), (encLTok_evalL M1 N1 hc2), (encLTok_evalL M1 N1 hc3).
      rewrite heq1, heq2, heq3, !decBits_prependP, (decBits_prependCode_ab _ _ hAB), (evalABL_decAB _ hAB),
              !decBits_prependBlks, decBits_zero, !app_nil_r.
      replace (M - r.(r2_need0) + r.(r2_add0)) with (c1 + M1 + c2) by (unfold M1; lia).
      replace (Nv - r.(r2_need1) + r.(r2_addK)) with (c3 + N1 + c4) by (unfold N1; lia).
      rewrite !powBitsN_add; repeat rewrite <- app_assoc; reflexivity. }
    rewrite hOut in hstep; exact hstep.
Qed.

Local Opaque get16 get64 get256 get1024 get4096 get16384 get32768
  check1Blk checkPF check2Blk symRunLoop symSweepR symSweepL runSymSeq.

Ltac fast_lia :=
  repeat match goal with
  | x := _ |- _ => clearbody x
  end;
  repeat match goal with
  | H : ?T |- _ =>
      lazymatch T with
      | (_ <= _)%N => fail
      | (_ < _)%N => fail
      | (_ <= _)%nat => fail
      | (_ < _)%nat => fail
      | @eq N _ _ => fail
      | @eq nat _ _ => fail
      | not (@eq N _ _) => fail
      | not (@eq nat _ _) => fail
      | False => fail
      | _ => clear H
      end
  end;
  lia.

Ltac split_andb :=
  repeat match goal with
  | H : andb _ _ = true |- _ => apply Bool.andb_true_iff in H; destruct H
  end;
  repeat match goal with
  | H : N.eqb _ _ = true |- _ => apply N.eqb_eq in H
  | H : N.leb _ _ = true |- _ => apply N.leb_le in H
  | H : N.ltb _ _ = true |- _ => apply N.ltb_lt in H
  | H : Bool.eqb _ _ = true |- _ => apply Bool.eqb_prop in H
  end.

Lemma div2_decomp (x : N) :
  2 * (x / 2) + (if N.eqb (x mod 2) 1 then 1 else 0) = x.
Proof.
  pose proof (N.div_mod x 2 ltac:(lia)) as hdm.
  pose proof (N.mod_lt x 2 ltac:(lia)) as hlt.
  destruct (N.eqb (x mod 2) 1) eqn:heq;
    [apply N.eqb_eq in heq | apply N.eqb_neq in heq]; lia.
Qed.

Lemma div_mod_decomp (x d : N) (hd : 0 < d) :
  (x / d) * d + (x mod d) = x /\ x mod d < d.
Proof.
  assert (hne : d <> 0) by lia.
  pose proof (N.div_mod x d hne) as h1.
  pose proof (N.mod_lt x d hne) as h2.
  rewrite N.mul_comm in h1; split; lia.
Qed.

Lemma mul_phi_bound (q d p : N) (h : 12 * d <= p) : 12 * (q * d) <= q * p.
Proof. nia. Qed.

Definition unpackHintsL (ns : list N) : list N :=
  List.flat_map (unpackHintsFuel 12 4095 fuel_8) ns.

Definition unpackHints16L (ns : list N) : list N :=
  List.flat_map (unpackHintsFuel 16 65535 fuel_8) ns.

(* ========================================================================= *)
(* Section 5: Tail Engine — checkTailStep, checkWaySeg, wayHops, TC & Drain  *)
(* ========================================================================= *)

Definition tailTape (prefAB : list ABWord) (M : N) (bt : bool) (K tl : N) : StateX :=
  (M_L LM_B, true :: bitsC ++ powBitsN (blkBitsL S_P) M ++ evalABL prefAB ++
             powBitsN (blkBitsL (blkKind bt)) K ++ decBits tl, []).

Definition checkTailStep (sufTbl : P32768 SufBucket) (bt : bool) (tl borrow cut : N) : option (N * N) :=
  let w0 := prependBlks bt borrow tl in
  match peelABDigits (N.to_nat cut) w0 with
  | Some (pAB, suf) =>
      match lookupSuf sufTbl suf with
      | Some osuf =>
          let w1 := prependABWord pAB osuf in
          Some (stripBlks bt fuel_32 0 w1)
      | None => None
      end
  | None => None
  end.

Lemma checkTailStep_sound {sufTbl : P32768 SufBucket} (hV : ValidSufTbl sufTbl)
  {bt : bool} {tl borrow cut add tl' : N}
  (h : checkTailStep sufTbl bt tl borrow cut = Some (add, tl')) :
  forall (prefAB : list ABWord) (M K : N), borrow <= K ->
    RPlus (tailTape prefAB M bt K tl)
          (tailTape prefAB (M + 1) bt (K - borrow + add) tl').
Proof.
  unfold checkTailStep in h.
  set (w0 := prependBlks bt borrow tl) in *.
  destruct (peelABDigits (N.to_nat cut) w0) as [[pAB suf]|] eqn:hpeel; try discriminate.
  destruct (lookupSuf sufTbl suf) as [osuf|] eqn:hlook; try discriminate.
  set (w1 := prependABWord pAB osuf) in *.
  intros prefAB M K hK.
  set (bigAB := powListN (blkAB S_P) M ++ prefAB ++ powListN (blkAB (blkKind bt)) (K - borrow) ++ pAB).
  pose proof (lookupSuf_sound hV hlook bigAB) as hrun.
  assert (hbig : evalABL bigAB = powBitsN (blkBitsL S_P) M ++ evalABL prefAB ++
      powBitsN (blkBitsL (blkKind bt)) (K - borrow) ++ evalABL pAB).
  { unfold bigAB; rewrite !evalABL_append, !evalABL_powListN; repeat rewrite <- app_assoc; reflexivity. }
  assert (hIn : true :: bitsC ++ evalABL bigAB ++ decBits suf =
      true :: bitsC ++ powBitsN (blkBitsL S_P) M ++ evalABL prefAB ++
      powBitsN (blkBitsL (blkKind bt)) K ++ decBits tl).
  { rewrite hbig.
    assert (hw0 : evalABL pAB ++ decBits suf = powBitsN (blkBitsL (blkKind bt)) borrow ++ decBits tl)
      by (rewrite <- (peelABDigits_sound hpeel); unfold w0; rewrite decBits_prependBlks; reflexivity).
    replace K with ((K - borrow) + borrow) at 2 by lia.
    rewrite powBitsN_add; repeat rewrite <- app_assoc.
    rewrite hw0; repeat rewrite <- app_assoc; reflexivity. }
  assert (hOut : true :: bitsC ++ blkBitsL S_P ++ evalABL bigAB ++ decBits osuf =
      true :: bitsC ++ powBitsN (blkBitsL S_P) (M + 1) ++ evalABL prefAB ++
      powBitsN (blkBitsL (blkKind bt)) (K - borrow + add) ++ decBits tl').
  { rewrite hbig, powBitsN_succ.
    pose proof (stripBlks_sound bt fuel_32 0 w1) as hst; cbn zeta in hst; destruct hst as [hst _].
    destruct (stripBlks bt fuel_32 0 w1) as [add0 tl0] eqn:hstr.
    inversion h; subst add0 tl0; cbn [fst snd] in hst.
    replace (add - 0) with add in hst by lia.
    unfold w1 in hst; rewrite decBits_prependABWord in hst.
    rewrite powBitsN_add; repeat rewrite <- app_assoc.
    rewrite hst; repeat rewrite <- app_assoc; reflexivity. }
  unfold tailTape; rewrite <- hIn, <- hOut; exact hrun.
Qed.

Fixpoint checkWaySeg (sufTbl : P32768 SufBucket) (bt : bool)
  (hs : list N) (tl st : N) (aff : Aff) : option (N * N * Aff) :=
  match hs with
  | [] => Some (tl, st, aff)
  | h :: rest =>
      let borrow := N.modulo h 32 in
      let cut := N.div h 32 in
      match checkTailStep sufTbl bt tl borrow cut with
      | Some (add, tl') =>
          checkWaySeg sufTbl bt rest tl' (st + 1) (affComp aff (mkAff borrow add))
      | None => None
      end
  end.

Lemma checkWaySeg_sound_aux {sufTbl : P32768 SufBucket} (hV : ValidSufTbl sufTbl)
  {bt : bool} {hs : list N} {tl tl' st0 st : N} {aff0 aff : Aff}
  (h : checkWaySeg sufTbl bt hs tl st0 aff0 = Some (tl', st, aff)) :
  exists affD : Aff,
    st0 <= st /\
    aff = affComp aff0 affD /\
    (hs <> [] -> st0 < st) /\
    forall (prefAB : list ABWord) (M K : N), affD.(aff_need) <= K ->
      RStar (tailTape prefAB M bt K tl)
            (tailTape prefAB (M + (st - st0)) bt (K - affD.(aff_need) + affD.(aff_add)) tl') /\
      (hs <> [] ->
        RPlus (tailTape prefAB M bt K tl)
              (tailTape prefAB (M + (st - st0)) bt (K - affD.(aff_need) + affD.(aff_add)) tl')).
Proof.
  revert tl st0 aff0 h; induction hs as [|hd rem ih]; intros tl st0 aff0 h.
  - inversion h; subst.
    exists affId; split; [lia | split; [symmetry; apply affComp_id_right | split; [intro hc; congruence |]]].
    intros prefAB M K _; cbn [affId aff_need aff_add].
    replace (st - st) with 0 by lia; replace (M + 0) with M by lia; replace (K - 0 + 0) with K by lia.
    split; [apply rStar_refl | intro hc; congruence].
  - cbn [checkWaySeg] in h.
    set (borrow := N.modulo hd 32) in *.
    set (cut := N.div hd 32) in *.
    destruct (checkTailStep sufTbl bt tl borrow cut) as [[add1 tl1]|] eqn:h1; try discriminate.
    destruct (ih _ _ _ h) as [affR [hle [haff [_ hrun]]]].
    set (stepAff := mkAff borrow add1).
    exists (affComp stepAff affR).
    split; [lia | split; [rewrite haff; apply affComp_assoc | split; [intros _; lia |]]].
    intros prefAB M K hK.
    destruct (affComp_spec stepAff affR K hK) as [hn1 [hn2 hEqK]].
    pose proof (checkTailStep_sound hV h1 prefAB M K hn1) as hs1.
    pose proof (proj1 (hrun prefAB (M + 1) (K - stepAff.(aff_need) + stepAff.(aff_add)) hn2)) as hs2.
    replace (M + 1 + (st - (st0 + 1))) with (M + (st - st0)) in hs2 by lia.
    rewrite hEqK in hs2; cbn [stepAff aff_need aff_add] in hs2.
    pose proof (rPlus_trans_star hs1 hs2) as hp.
    split; [exact (rPlus_to_star hp) | intros _; exact hp].
Qed.

Lemma checkWaySeg_sound {sufTbl : P32768 SufBucket} (hV : ValidSufTbl sufTbl)
  {bt : bool} {hs : list N} {tl tl' st : N} {aff : Aff}
  (hne : hs <> [])
  (h : checkWaySeg sufTbl bt hs tl 0 affId = Some (tl', st, aff)) :
  0 < st /\
  forall (prefAB : list ABWord) (M K : N), aff.(aff_need) <= K ->
    RPlus (tailTape prefAB M bt K tl)
          (tailTape prefAB (M + st) bt (K - aff.(aff_need) + aff.(aff_add)) tl').
Proof.
  destruct (checkWaySeg_sound_aux hV h) as [affD [_ [haff [hpos hrun]]]].
  rewrite affComp_id_left in haff; subst affD.
  split; [exact (hpos hne) |].
  intros prefAB M K hK.
  pose proof (proj2 (hrun prefAB M K hK) hne) as hp.
  replace (st - 0) with st in hp by lia; exact hp.
Qed.

Record WayEntry := mkWay {
  we_bt : bool;
  we_tl : N;
  we_isAnc : bool;
  we_tcId : N;
  we_nextWid : N;
  we_steps : N;
  we_need : N;
  we_add : N
}.

Definition ValidWayEntry (wayTbl : P32768 WayEntry) (numWays wid : N) : Prop :=
  let w := get32768 wayTbl wid in
  let w' := get32768 wayTbl w.(we_nextWid) in
  w.(we_nextWid) < numWays /\
  w'.(we_bt) = w.(we_bt) /\
  0 < w.(we_steps) /\
  forall (prefAB : list ABWord) (M K : N), w.(we_need) <= K ->
    RPlus (tailTape prefAB M w.(we_bt) K w.(we_tl))
          (tailTape prefAB (M + w.(we_steps)) w.(we_bt) (K - w.(we_need) + w.(we_add)) w'.(we_tl)).

Definition ValidWayTbl (wayTbl : P32768 WayEntry) (numWays : N) : Prop :=
  forall wid : N, wid < numWays -> ValidWayEntry wayTbl numWays wid.

Definition checkWayEntry (sufTbl : P32768 SufBucket) (wayTbl : P32768 WayEntry) (numWays wid : N)
  (hints : list N) : bool :=
  if isEmpty hints then false
  else
    let w := get32768 wayTbl wid in
    if N.ltb w.(we_nextWid) numWays then
      let w' := get32768 wayTbl w.(we_nextWid) in
      if Bool.eqb w'.(we_bt) w.(we_bt) then
        match checkWaySeg sufTbl w.(we_bt) hints w.(we_tl) 0 affId with
        | Some (tl', st, aff) =>
            N.eqb tl' w'.(we_tl) && N.eqb st w.(we_steps) &&
            N.eqb aff.(aff_need) w.(we_need) && N.eqb aff.(aff_add) w.(we_add)
        | None => false
        end
      else false
    else false.

Lemma checkWayEntry_sound {sufTbl : P32768 SufBucket} (hV : ValidSufTbl sufTbl)
  {wayTbl : P32768 WayEntry} {numWays wid : N} {hints : list N}
  (h : checkWayEntry sufTbl wayTbl numWays wid hints = true) :
  ValidWayEntry wayTbl numWays wid.
Proof.
  unfold checkWayEntry in h.
  destruct (isEmpty hints) eqn:hem; [discriminate |].
  assert (hne : hints <> []) by (destruct hints; [discriminate | intro hc; discriminate]).
  set (w := get32768 wayTbl wid) in *.
  destruct (N.ltb w.(we_nextWid) numWays) eqn:hlt; [| discriminate].
  set (w' := get32768 wayTbl w.(we_nextWid)) in *.
  destruct (Bool.eqb w'.(we_bt) w.(we_bt)) eqn:hbt; [| discriminate].
  destruct (checkWaySeg sufTbl w.(we_bt) hints w.(we_tl) 0 affId) as [[[tl' st] aff]|] eqn:hseg; [| discriminate].
  split_andb.
  destruct (checkWaySeg_sound hV hne hseg) as [hpos hrun].
  unfold ValidWayEntry; fold w w'.
  split; [exact hlt | split; [exact hbt | split; [lia |]]].
  intros prefAB M K hK.
  pose proof (hrun prefAB M K ltac:(lia)) as hp.
  replace (w.(we_steps)) with st by lia.
  replace (K - w.(we_need) + w.(we_add)) with (K - aff.(aff_need) + aff.(aff_add)) by lia.
  replace (w'.(we_tl)) with tl' by lia.
  exact hp.
Qed.

Fixpoint checkWayList (sufTbl : P32768 SufBucket) (wayTbl : P32768 WayEntry) (numWays lo : N)
  (hsList : list (list N)) : bool :=
  match hsList with
  | [] => true
  | hp :: rest =>
      checkWayEntry sufTbl wayTbl numWays lo (unpackHintsL hp) &&
      checkWayList sufTbl wayTbl numWays (lo + 1) rest
  end.

Lemma checkWayList_sound {sufTbl : P32768 SufBucket} (hV : ValidSufTbl sufTbl)
  {wayTbl : P32768 WayEntry} {numWays lo : N} {hsList : list (list N)}
  (h : checkWayList sufTbl wayTbl numWays lo hsList = true) :
  forall wid : N, lo <= wid -> wid < lo + N.of_nat (length hsList) -> ValidWayEntry wayTbl numWays wid.
Proof.
  revert lo h; induction hsList as [|hp rest ih]; intros lo h wid h1 h2; [cbn in h2; lia |].
  cbn [checkWayList length] in h, h2.
  apply Bool.andb_true_iff in h; destruct h as [h0 hr].
  destruct (N.eq_dec wid lo) as [-> | hne].
  - exact (checkWayEntry_sound hV h0).
  - apply (ih (lo + 1) hr wid); lia.
Qed.

Fixpoint wayHopsAux (wayTbl : P32768 WayEntry) (h : nat) (wid st : N) (aff : Aff) : N * N * Aff :=
  match h with
  | 0%nat => (wid, st, aff)
  | S h' =>
      let w := get32768 wayTbl wid in
      wayHopsAux wayTbl h' w.(we_nextWid) (st + w.(we_steps))
        (affComp aff (mkAff w.(we_need) w.(we_add)))
  end.

Definition wayHops (wayTbl : P32768 WayEntry) (h wid : N) : N * N * Aff :=
  wayHopsAux wayTbl (N.to_nat h) wid 0 affId.

Lemma wayHopsAux_sound {wayTbl : P32768 WayEntry} {numWays : N} (hV : ValidWayTbl wayTbl numWays)
  (h : nat) (wid st0 : N) (aff0 : Aff) (hw : wid < numWays) :
  let res := wayHopsAux wayTbl h wid st0 aff0 in
  exists affD : Aff,
    fst (fst res) < numWays /\
    (get32768 wayTbl (fst (fst res))).(we_bt) = (get32768 wayTbl wid).(we_bt) /\
    st0 <= snd (fst res) /\
    snd res = affComp aff0 affD /\
    forall (prefAB : list ABWord) (M K : N), affD.(aff_need) <= K ->
      RStar (tailTape prefAB M (get32768 wayTbl wid).(we_bt) K (get32768 wayTbl wid).(we_tl))
            (tailTape prefAB (M + (snd (fst res) - st0)) (get32768 wayTbl wid).(we_bt)
              (K - affD.(aff_need) + affD.(aff_add)) (get32768 wayTbl (fst (fst res))).(we_tl)).
Proof.
  revert wid st0 aff0 hw; induction h as [|h ih]; intros wid st0 aff0 hw.
  - cbn [wayHopsAux fst snd].
    exists affId; split; [exact hw | split; [reflexivity | split; [lia | split; [symmetry; apply affComp_id_right |]]]].
    intros prefAB M K _; cbn [affId aff_need aff_add].
    replace (st0 - st0) with 0 by lia; replace (M + 0) with M by lia; replace (K - 0 + 0) with K by lia.
    apply rStar_refl.
  - cbn [wayHopsAux].
    set (w := get32768 wayTbl wid).
    destruct (hV wid hw) as [hnxt [hbt [_ hstep]]]; fold w in hnxt, hbt, hstep.
    set (stepAff := mkAff w.(we_need) w.(we_add)).
    destruct (ih w.(we_nextWid) (st0 + w.(we_steps)) (affComp aff0 stepAff) hnxt)
      as [affR [hdst [hbtR [hle [haff hrun]]]]].
    exists (affComp stepAff affR).
    split; [exact hdst | split; [rewrite hbtR; unfold w; exact hbt | split; [lia | split; [rewrite haff; apply affComp_assoc |]]]].
    intros prefAB M K hK.
    destruct (affComp_spec stepAff affR K hK) as [hn1 [hn2 hEqK]].
    pose proof (hstep prefAB M K hn1) as hs1.
    pose proof (hrun prefAB (M + w.(we_steps)) (K - w.(we_need) + w.(we_add)) hn2) as hs2.
    rewrite hbt in hs2.
    replace (M + w.(we_steps) + (snd (fst (wayHopsAux wayTbl h w.(we_nextWid) (st0 + w.(we_steps)) (affComp aff0 stepAff))) - (st0 + w.(we_steps))))
      with (M + (snd (fst (wayHopsAux wayTbl h w.(we_nextWid) (st0 + w.(we_steps)) (affComp aff0 stepAff))) - st0)) in hs2 by lia.
    cbn [stepAff aff_need aff_add] in hEqK; rewrite hEqK in hs2.
    exact (rPlus_to_star (rPlus_trans_star hs1 hs2)).
Qed.

Lemma wayHops_sound {wayTbl : P32768 WayEntry} {numWays : N} (hV : ValidWayTbl wayTbl numWays)
  {h wid : N} (hw : wid < numWays) :
  let res := wayHops wayTbl h wid in
  fst (fst res) < numWays /\
  (get32768 wayTbl (fst (fst res))).(we_bt) = (get32768 wayTbl wid).(we_bt) /\
  forall (prefAB : list ABWord) (M K : N), (snd res).(aff_need) <= K ->
    RStar (tailTape prefAB M (get32768 wayTbl wid).(we_bt) K (get32768 wayTbl wid).(we_tl))
          (tailTape prefAB (M + snd (fst res)) (get32768 wayTbl wid).(we_bt)
            (K - (snd res).(aff_need) + (snd res).(aff_add)) (get32768 wayTbl (fst (fst res))).(we_tl)).
Proof.
  unfold wayHops.
  destruct (wayHopsAux_sound hV (N.to_nat h) wid 0 affId hw) as [affD [h1 [h2 [_ [haff hrun]]]]].
  rewrite affComp_id_left in haff.
  split; [exact h1 | split; [exact h2 |]].
  intros prefAB M K hK; rewrite haff in hK |- *.
  pose proof (hrun prefAB M K hK) as hr.
  replace (snd (fst (wayHopsAux wayTbl (N.to_nat h) wid 0 affId)) - 0)
    with (snd (fst (wayHopsAux wayTbl (N.to_nat h) wid 0 affId))) in hr by lia.
  exact hr.
Qed.

Record TCEntry := mkTC {
  tc_bt : bool;
  tc_ancWid : N;
  tc_perHops : N;
  tc_per : N;
  tc_decK : N;
  tc_minK : N;
  tc_exitBase : N;
  tc_nk3Base : N
}.

Definition checkTC (wayTbl : P32768 WayEntry) (numWays : N) (tc : TCEntry) : bool :=
  let res := wayHops wayTbl tc.(tc_perHops) tc.(tc_ancWid) in
  N.ltb tc.(tc_ancWid) numWays &&
  N.ltb 0 tc.(tc_decK) &&
  Bool.eqb (get32768 wayTbl tc.(tc_ancWid)).(we_bt) tc.(tc_bt) &&
  N.eqb (fst (fst res)) tc.(tc_ancWid) &&
  N.eqb (snd (fst res)) tc.(tc_per) &&
  N.eqb (snd res).(aff_need) ((snd res).(aff_add) + tc.(tc_decK)) &&
  N.leb (snd res).(aff_need) (tc.(tc_minK) + tc.(tc_decK)) &&
  N.leb (12 * tc.(tc_decK)) tc.(tc_per).

Lemma checkTC_spec {wayTbl : P32768 WayEntry} {numWays : N} (hV : ValidWayTbl wayTbl numWays)
  {tc : TCEntry} (h : checkTC wayTbl numWays tc = true) :
  tc.(tc_ancWid) < numWays /\
  0 < tc.(tc_decK) /\
  (get32768 wayTbl tc.(tc_ancWid)).(we_bt) = tc.(tc_bt) /\
  12 * tc.(tc_decK) <= tc.(tc_per) /\
  forall (prefAB : list ABWord) (M K : N), tc.(tc_minK) + tc.(tc_decK) <= K ->
    RStar (tailTape prefAB M tc.(tc_bt) K (get32768 wayTbl tc.(tc_ancWid)).(we_tl))
          (tailTape prefAB (M + tc.(tc_per)) tc.(tc_bt) (K - tc.(tc_decK)) (get32768 wayTbl tc.(tc_ancWid)).(we_tl)).
Proof.
  unfold checkTC in h; split_andb.
  assert (hanc : tc.(tc_ancWid) < numWays) by assumption.
  destruct (wayHops_sound hV (h := tc.(tc_perHops)) hanc) as [_ [_ hrun]].
  repeat split; try assumption.
  intros prefAB M K hK.
  pose proof (hrun prefAB M K ltac:(lia)) as h1.
  replace (fst (fst (wayHops wayTbl tc.(tc_perHops) tc.(tc_ancWid)))) with tc.(tc_ancWid) in h1 by congruence.
  replace (snd (fst (wayHops wayTbl tc.(tc_perHops) tc.(tc_ancWid)))) with tc.(tc_per) in h1 by congruence.
  replace ((get32768 wayTbl tc.(tc_ancWid)).(we_bt)) with tc.(tc_bt) in h1 by congruence.
  replace (K - (snd (wayHops wayTbl tc.(tc_perHops) tc.(tc_ancWid))).(aff_need) +
               (snd (wayHops wayTbl tc.(tc_perHops) tc.(tc_ancWid))).(aff_add))
    with (K - tc.(tc_decK)) in h1 by lia.
  exact h1.
Qed.

Lemma tc_cycle_pow {wayTbl : P32768 WayEntry} {numWays : N} (hV : ValidWayTbl wayTbl numWays)
  {tc : TCEntry} (h : checkTC wayTbl numWays tc = true) (prefAB : list ABWord) (M q r : N) :
  RStar (tailTape prefAB M tc.(tc_bt) (tc.(tc_minK) + q * tc.(tc_decK) + r) (get32768 wayTbl tc.(tc_ancWid)).(we_tl))
        (tailTape prefAB (M + q * tc.(tc_per)) tc.(tc_bt) (tc.(tc_minK) + r) (get32768 wayTbl tc.(tc_ancWid)).(we_tl)).
Proof.
  destruct (checkTC_spec hV h) as [_ [_ [_ [_ hstep]]]].
  revert M; pattern q; apply N.peano_ind.
  - intros M; replace (0 * tc.(tc_decK)) with 0 by lia; replace (0 * tc.(tc_per)) with 0 by lia.
    replace (tc.(tc_minK) + 0 + r) with (tc.(tc_minK) + r) by lia; replace (M + 0) with M by lia.
    apply rStar_refl.
  - intros q' ih M.
    rewrite !N.mul_succ_l.
    pose proof (hstep prefAB M (tc.(tc_minK) + (q' * tc.(tc_decK) + tc.(tc_decK)) + r) ltac:(lia)) as h1.
    replace (tc.(tc_minK) + (q' * tc.(tc_decK) + tc.(tc_decK)) + r - tc.(tc_decK))
      with (tc.(tc_minK) + q' * tc.(tc_decK) + r) in h1 by lia.
    pose proof (ih (M + tc.(tc_per))) as h2.
    replace (M + tc.(tc_per) + q' * tc.(tc_per)) with (M + (q' * tc.(tc_per) + tc.(tc_per))) in h2 by lia.
    exact (rStar_trans h1 h2).
Qed.

Record TCExitEntry := mkTCEx {
  tce_hops : N;
  tce_steps : N;
  tce_kr : N;
  tce_exitWid : N
}.

Definition checkTCExit (wayTbl : P32768 WayEntry) (tc : TCEntry) (ex : TCExitEntry) (r : N) : bool :=
  let res := wayHops wayTbl ex.(tce_hops) tc.(tc_ancWid) in
  let K0 := tc.(tc_minK) + r in
  N.eqb (fst (fst res)) ex.(tce_exitWid) &&
  N.eqb (snd (fst res)) ex.(tce_steps) &&
  N.leb (snd res).(aff_need) K0 &&
  N.eqb (K0 - (snd res).(aff_need) + (snd res).(aff_add)) ex.(tce_kr).

Lemma tc_drain_and_exit {wayTbl : P32768 WayEntry} {numWays : N} (hV : ValidWayTbl wayTbl numWays)
  {tc : TCEntry} (hTC : checkTC wayTbl numWays tc = true)
  {ex : TCExitEntry} {r : N} (hEx : checkTCExit wayTbl tc ex r = true)
  (prefAB : list ABWord) (M q : N) :
  ex.(tce_exitWid) < numWays /\
  (get32768 wayTbl ex.(tce_exitWid)).(we_bt) = tc.(tc_bt) /\
  RStar (tailTape prefAB M tc.(tc_bt) (tc.(tc_minK) + q * tc.(tc_decK) + r) (get32768 wayTbl tc.(tc_ancWid)).(we_tl))
        (tailTape prefAB (M + q * tc.(tc_per) + ex.(tce_steps)) tc.(tc_bt) ex.(tce_kr) (get32768 wayTbl ex.(tce_exitWid)).(we_tl)).
Proof.
  destruct (checkTC_spec hV hTC) as [hanc [_ [hbt _]]].
  unfold checkTCExit in hEx; split_andb.
  destruct (wayHops_sound hV (h := ex.(tce_hops)) hanc) as [hdstLt [hbtOut hrun]].
  replace (fst (fst (wayHops wayTbl ex.(tce_hops) tc.(tc_ancWid)))) with ex.(tce_exitWid) in hdstLt, hbtOut by congruence.
  pose proof (tc_cycle_pow hV hTC prefAB M q r) as h1.
  pose proof (hrun prefAB (M + q * tc.(tc_per)) (tc.(tc_minK) + r) ltac:(lia)) as h2.
  replace (fst (fst (wayHops wayTbl ex.(tce_hops) tc.(tc_ancWid)))) with ex.(tce_exitWid) in h2 by congruence.
  replace (snd (fst (wayHops wayTbl ex.(tce_hops) tc.(tc_ancWid)))) with ex.(tce_steps) in h2 by congruence.
  replace (tc.(tc_minK) + r - (snd (wayHops wayTbl ex.(tce_hops) tc.(tc_ancWid))).(aff_need) +
            (snd (wayHops wayTbl ex.(tce_hops) tc.(tc_ancWid))).(aff_add))
    with ex.(tce_kr) in h2 by lia.
  rewrite hbt in h2.
  split; [exact hdstLt | split; [congruence | exact (rStar_trans h1 h2)]].
Qed.

Fixpoint wayRunConcreteAux (wayTbl : P32768 WayEntry) (tcTbl : P16 TCEntry)
  (fuel : nat) (wid st K : N) : option (bool * N * N * N) :=
  match fuel with
  | 0%nat => None
  | S f =>
      let w := get32768 wayTbl wid in
      if w.(we_isAnc) && N.ltb w.(we_tcId) 6 &&
         N.eqb (get16 tcTbl w.(we_tcId)).(tc_ancWid) wid &&
         Bool.eqb (get16 tcTbl w.(we_tcId)).(tc_bt) w.(we_bt) &&
         N.leb (get16 tcTbl w.(we_tcId)).(tc_minK) K then
        Some (true, w.(we_tcId), st, K)
      else if N.ltb K w.(we_need) then
        Some (false, wid, st, K)
      else
        wayRunConcreteAux wayTbl tcTbl f w.(we_nextWid) (st + w.(we_steps)) (K - w.(we_need) + w.(we_add))
  end.

Lemma wayRunConcreteAux_sound {wayTbl : P32768 WayEntry} {numWays : N} (hV : ValidWayTbl wayTbl numWays)
  {tcTbl : P16 TCEntry} {fuel : nat} {wid st0 K : N} {reachedTC : bool} {dst st ko : N}
  (hw : wid < numWays)
  (h : wayRunConcreteAux wayTbl tcTbl fuel wid st0 K = Some (reachedTC, dst, st, ko)) :
  st0 <= st /\
  (reachedTC = true ->
    dst < 6 /\
    (get16 tcTbl dst).(tc_bt) = (get32768 wayTbl wid).(we_bt) /\
    (get16 tcTbl dst).(tc_minK) <= ko /\
    forall (prefAB : list ABWord) (M : N),
      RStar (tailTape prefAB M (get32768 wayTbl wid).(we_bt) K (get32768 wayTbl wid).(we_tl))
            (tailTape prefAB (M + (st - st0)) (get16 tcTbl dst).(tc_bt) ko
              (get32768 wayTbl (get16 tcTbl dst).(tc_ancWid)).(we_tl))) /\
  (reachedTC = false ->
    dst < numWays /\
    (get32768 wayTbl dst).(we_bt) = (get32768 wayTbl wid).(we_bt) /\
    forall (prefAB : list ABWord) (M : N),
      RStar (tailTape prefAB M (get32768 wayTbl wid).(we_bt) K (get32768 wayTbl wid).(we_tl))
            (tailTape prefAB (M + (st - st0)) (get32768 wayTbl wid).(we_bt) ko (get32768 wayTbl dst).(we_tl))).
Proof.
  revert wid st0 K hw h; induction fuel as [|f ih]; intros wid st0 K hw h; [discriminate |].
  cbn [wayRunConcreteAux] in h.
  set (w := get32768 wayTbl wid) in *.
  destruct (w.(we_isAnc) && N.ltb w.(we_tcId) 6 &&
         N.eqb (get16 tcTbl w.(we_tcId)).(tc_ancWid) wid &&
         Bool.eqb (get16 tcTbl w.(we_tcId)).(tc_bt) w.(we_bt) &&
         N.leb (get16 tcTbl w.(we_tcId)).(tc_minK) K) eqn:hAnc.
  - inversion h; subst reachedTC dst st ko; split_andb.
    split; [lia | split; [| intro hc; discriminate]].
    intros _; repeat split; try assumption.
    intros prefAB M.
    replace ((get16 tcTbl w.(we_tcId)).(tc_ancWid)) with wid by congruence.
    replace ((get16 tcTbl w.(we_tcId)).(tc_bt)) with w.(we_bt) by congruence.
    replace (st0 - st0) with 0 by lia; replace (M + 0) with M by lia.
    apply rStar_refl.
  - destruct (N.ltb K w.(we_need)) eqn:hUf.
    + inversion h; subst reachedTC dst st ko.
      split; [lia | split; [intro hc; discriminate |]].
      intros _; split; [exact hw | split; [reflexivity |]].
      intros prefAB M; replace (st0 - st0) with 0 by lia; replace (M + 0) with M by lia; apply rStar_refl.
    + apply N.ltb_ge in hUf.
      destruct (hV wid hw) as [hnxt [hbt [_ hstep]]]; fold w in hnxt, hbt, hstep.
      destruct (ih _ _ _ hnxt h) as [hle [hT hF]].
      split; [lia | split].
      * intro hr; destruct (hT hr) as [h1 [h2 [h3 hrun]]].
        split; [exact h1 | split; [rewrite h2; unfold w; exact hbt | split; [exact h3 |]]].
        intros prefAB M.
        pose proof (hstep prefAB M K hUf) as hs1.
        pose proof (hrun prefAB (M + w.(we_steps))) as hs2.
        rewrite hbt in hs2.
        replace (M + w.(we_steps) + (st - (st0 + w.(we_steps)))) with (M + (st - st0)) in hs2 by lia.
        exact (rPlus_to_star (rPlus_trans_star hs1 hs2)).
      * intro hr; destruct (hF hr) as [h1 [h2 hrun]].
        split; [exact h1 | split; [rewrite h2; unfold w; exact hbt |]].
        intros prefAB M.
        pose proof (hstep prefAB M K hUf) as hs1.
        pose proof (hrun prefAB (M + w.(we_steps))) as hs2.
        rewrite hbt in hs2.
        replace (M + w.(we_steps) + (st - (st0 + w.(we_steps)))) with (M + (st - st0)) in hs2 by lia.
        exact (rPlus_to_star (rPlus_trans_star hs1 hs2)).
Qed.

(* ========================================================================= *)
(* Section 6: Global Invariant (`InInv`), Graph Closure, Stage A & `nonhalt` *)
(* ========================================================================= *)

Definition nk3MidAB (X : N) : list ABWord :=
  [AB_A; AB_A; AB_B] ++ powListN (blkAB S_Q3) X ++ [AB_A; AB_A; AB_A; AB_A; AB_B].

Lemma evalABL_nk3MidAB (X : N) :
  evalABL (nk3MidAB X) = bitsA ++ bitsA ++ bitsB ++ powBitsN (blkBitsL S_Q3) X ++ bitsARn 4 ++ bitsB.
Proof.
  unfold nk3MidAB; rewrite !evalABL_append, evalABL_powListN.
  cbn [evalABL bitsARn bitsA bitsB app]; repeat rewrite <- app_assoc; reflexivity.
Qed.

Definition mkNK3MidCode (X : N) : N :=
  prependAAB (prependQ3 X aaaabCode).

Lemma decBits_mkNK3MidCode (X : N) :
  decBits (mkNK3MidCode X) = evalABL (nk3MidAB X).
Proof.
  unfold mkNK3MidCode; rewrite decBits_prependAAB, decBits_prependQ3, decBits_aaaabCode, evalABL_nk3MidAB.
  repeat rewrite <- app_assoc; reflexivity.
Qed.

Record SKEntry := mkSK {
  ske_rule : Rule1Blk;
  ske_pfEvenIdx : N;
  ske_pfOddIdx : N
}.

Record PFEntry := mkPF {
  pfe_rule : RulePF;
  pfe_t1Wid : N;
  pfe_wayHopsCnt : N;
  pfe_dstTcId : N;
  pfe_isNK3 : bool;
  pfe_nk3X : N;
  pfe_dstMidId : N
}.

Record Rule2Entry := mkR2E {
  r2e_rule : Rule2Blk;
  r2e_t1Wid : N;
  r2e_wayHopsCnt : N;
  r2e_dstTcId : N;
  r2e_dstMidId : N
}.

Record ProofTables := mkPT {
  pt_numWays : N;
  pt_numMids : N;
  pt_numSK : N;
  pt_numPF : N;
  pt_numFmd : N;
  pt_sufTbl : P32768 SufBucket;
  pt_wayTbl : P32768 WayEntry;
  pt_tcTbl : P16 TCEntry;
  pt_tcExitTbl : P1024 TCExitEntry;
  pt_midTbl : P16 N;
  pt_midTCBits : P256 bool;
  pt_smallNK3Bits : P4096 bool;
  pt_skTbl : P4096 SKEntry;
  pt_skIdx : P4096 (list N);
  pt_pfTbl : P16384 PFEntry;
  pt_fmdTbl : P4096 Rule2Entry;
  pt_fmdIdx : P4096 (list N);
  pt_nk3ATbl : P256 Rule2Entry
}.

Definition invB : N := 4500.
Definition xMin : N := 1500.

Definition hasMidTC (td : ProofTables) (midId tcId : N) : bool :=
  N.ltb midId td.(pt_numMids) && N.ltb tcId 6 &&
  get256 td.(pt_midTCBits) (8 * midId + tcId).

Definition hasSmallNK3 (td : ProofTables) (tcId X : N) : bool :=
  (N.eqb tcId 1 || N.eqb tcId 4) && N.ltb X xMin &&
  get4096 td.(pt_smallNK3Bits) ((if N.eqb tcId 1 then 0 else 2048) + X).

Definition ValidSKEntry (sufTbl : P32768 SufBucket) (e : SKEntry) : Prop :=
  exists preQ postQ hints, check1Blk sufTbl e.(ske_rule) preQ postQ hints = true.

Definition ValidPFEntry (sufTbl : P32768 SufBucket) (e : PFEntry) : Prop :=
  exists preB postB hints, checkPF sufTbl e.(pfe_rule) preB postB hints = true.

Definition ValidRule2Entry (sufTbl : P32768 SufBucket) (e : Rule2Entry) : Prop :=
  exists c1 c2 c3 c4 hints1 hints2, check2Blk sufTbl e.(r2e_rule) c1 c2 c3 c4 hints1 hints2 = true.

Fixpoint checkSKList (sufTbl : P32768 SufBucket) (skTbl : P4096 SKEntry) (lo : N)
  (ws : list (N * N * list N)) : bool :=
  match ws with
  | [] => true
  | (preQ, postQ, hp) :: rest =>
      check1Blk sufTbl (get4096 skTbl lo).(ske_rule) preQ postQ (unpackHintsL hp) &&
      checkSKList sufTbl skTbl (lo + 1) rest
  end.

Lemma checkSKList_sound {sufTbl : P32768 SufBucket} {skTbl : P4096 SKEntry} {lo : N}
  {ws : list (N * N * list N)} (h : checkSKList sufTbl skTbl lo ws = true) :
  forall i : N, lo <= i -> i < lo + N.of_nat (length ws) -> ValidSKEntry sufTbl (get4096 skTbl i).
Proof.
  revert lo h; induction ws as [|[[preQ postQ] hp] rest ih]; intros lo h i h1 h2; [cbn in h2; lia |].
  cbn [checkSKList length] in h, h2.
  apply Bool.andb_true_iff in h; destruct h as [h0 hr].
  destruct (N.eq_dec i lo) as [-> | hne].
  - exists preQ, postQ, (unpackHintsL hp); exact h0.
  - apply (ih (lo + 1) hr i); lia.
Qed.

Fixpoint checkPFList (sufTbl : P32768 SufBucket) (pfTbl : P16384 PFEntry) (lo : N)
  (ws : list (N * N * list N)) : bool :=
  match ws with
  | [] => true
  | (preB, postB, hp) :: rest =>
      checkPF sufTbl (get16384 pfTbl lo).(pfe_rule) preB postB (unpackHintsL hp) &&
      checkPFList sufTbl pfTbl (lo + 1) rest
  end.

Lemma checkPFList_sound {sufTbl : P32768 SufBucket} {pfTbl : P16384 PFEntry} {lo : N}
  {ws : list (N * N * list N)} (h : checkPFList sufTbl pfTbl lo ws = true) :
  forall i : N, lo <= i -> i < lo + N.of_nat (length ws) -> ValidPFEntry sufTbl (get16384 pfTbl i).
Proof.
  revert lo h; induction ws as [|[[preB postB] hp] rest ih]; intros lo h i h1 h2; [cbn in h2; lia |].
  cbn [checkPFList length] in h, h2.
  apply Bool.andb_true_iff in h; destruct h as [h0 hr].
  destruct (N.eq_dec i lo) as [-> | hne].
  - exists preB, postB, (unpackHintsL hp); exact h0.
  - apply (ih (lo + 1) hr i); lia.
Qed.

Fixpoint checkFmdList (sufTbl : P32768 SufBucket) (fmdTbl : P4096 Rule2Entry) (lo : N)
  (ws : list (N * N * N * N * list N * list N)) : bool :=
  match ws with
  | [] => true
  | (c1, c2, c3, c4, hp1, hp2) :: rest =>
      check2Blk sufTbl (get4096 fmdTbl lo).(r2e_rule) c1 c2 c3 c4 (unpackHintsL hp1) (unpackHintsL hp2) &&
      checkFmdList sufTbl fmdTbl (lo + 1) rest
  end.

Lemma checkFmdList_sound {sufTbl : P32768 SufBucket} {fmdTbl : P4096 Rule2Entry} {lo : N}
  {ws : list (N * N * N * N * list N * list N)} (h : checkFmdList sufTbl fmdTbl lo ws = true) :
  forall i : N, lo <= i -> i < lo + N.of_nat (length ws) -> ValidRule2Entry sufTbl (get4096 fmdTbl i).
Proof.
  revert lo h; induction ws as [|[[[[[c1 c2] c3] c4] hp1] hp2] rest ih]; intros lo h i h1 h2; [cbn in h2; lia |].
  cbn [checkFmdList length] in h, h2.
  apply Bool.andb_true_iff in h; destruct h as [h0 hr].
  destruct (N.eq_dec i lo) as [-> | hne].
  - exists c1, c2, c3, c4, (unpackHintsL hp1), (unpackHintsL hp2); exact h0.
  - apply (ih (lo + 1) hr i); lia.
Qed.

Fixpoint checkNK3AList (sufTbl : P32768 SufBucket) (nk3ATbl : P256 Rule2Entry) (lo : N)
  (ws : list (N * N * N * N * list N * list N)) : bool :=
  match ws with
  | [] => true
  | (c1, c2, c3, c4, hp1, hp2) :: rest =>
      check2Blk sufTbl (get256 nk3ATbl lo).(r2e_rule) c1 c2 c3 c4 (unpackHintsL hp1) (unpackHintsL hp2) &&
      checkNK3AList sufTbl nk3ATbl (lo + 1) rest
  end.

Lemma checkNK3AList_sound {sufTbl : P32768 SufBucket} {nk3ATbl : P256 Rule2Entry} {lo : N}
  {ws : list (N * N * N * N * list N * list N)} (h : checkNK3AList sufTbl nk3ATbl lo ws = true) :
  forall i : N, lo <= i -> i < lo + N.of_nat (length ws) -> ValidRule2Entry sufTbl (get256 nk3ATbl i).
Proof.
  revert lo h; induction ws as [|[[[[[c1 c2] c3] c4] hp1] hp2] rest ih]; intros lo h i h1 h2; [cbn in h2; lia |].
  cbn [checkNK3AList length] in h, h2.
  apply Bool.andb_true_iff in h; destruct h as [h0 hr].
  destruct (N.eq_dec i lo) as [-> | hne].
  - exists c1, c2, c3, c4, (unpackHintsL hp1), (unpackHintsL hp2); exact h0.
  - apply (ih (lo + 1) hr i); lia.
Qed.

Record ValidTables (td : ProofTables) : Prop := mkVT {
  vt_suf : ValidSufTbl td.(pt_sufTbl);
  vt_way : ValidWayTbl td.(pt_wayTbl) td.(pt_numWays);
  vt_tc : forall i : N, i < 6 -> checkTC td.(pt_wayTbl) td.(pt_numWays) (get16 td.(pt_tcTbl) i) = true;
  vt_tcExit : forall i : N, i < 6 -> forall r : N, r < (get16 td.(pt_tcTbl) i).(tc_decK) ->
    checkTCExit td.(pt_wayTbl) (get16 td.(pt_tcTbl) i)
      (get1024 td.(pt_tcExitTbl) ((get16 td.(pt_tcTbl) i).(tc_exitBase) + r)) r = true;
  vt_mid : forall i : N, i < td.(pt_numMids) -> isABCode (get16 td.(pt_midTbl) i) = true;
  vt_sk : forall i : N, i < td.(pt_numSK) -> ValidSKEntry td.(pt_sufTbl) (get4096 td.(pt_skTbl) i);
  vt_pf : forall i : N, i < td.(pt_numPF) -> ValidPFEntry td.(pt_sufTbl) (get16384 td.(pt_pfTbl) i);
  vt_fmd : forall i : N, i < td.(pt_numFmd) -> ValidRule2Entry td.(pt_sufTbl) (get4096 td.(pt_fmdTbl) i);
  vt_nk3A : forall i : N, i < 100 -> ValidRule2Entry td.(pt_sufTbl) (get256 td.(pt_nk3ATbl) i)
}.
Arguments vt_suf {td} _.
Arguments vt_way {td} _.
Arguments vt_tc {td} _.
Arguments vt_tcExit {td} _.
Arguments vt_mid {td} _.
Arguments vt_sk {td} _.
Arguments vt_pf {td} _.
Arguments vt_fmd {td} _.
Arguments vt_nk3A {td} _.

Fixpoint checkAllFuel (p : N -> bool) (lo : N) (c : nat) : bool :=
  match c with
  | 0%nat => true
  | S c' => p lo && checkAllFuel p (lo + 1) c'
  end.

Lemma checkAllFuel_sound {p : N -> bool} {lo : N} {c : nat} (h : checkAllFuel p lo c = true) :
  forall i : N, lo <= i -> i < lo + N.of_nat c -> p i = true.
Proof.
  revert lo h; induction c as [|c ih]; intros lo h i h1 h2; [lia |].
  cbn [checkAllFuel] in h; apply Bool.andb_true_iff in h; destruct h as [h0 hr].
  destruct (N.eq_dec i lo) as [-> | hne]; [exact h0 | apply (ih (lo + 1) hr i); lia].
Qed.

Definition checkAllN (p : N -> bool) (lo cnt : N) : bool :=
  checkAllFuel p lo (N.to_nat cnt).

Lemma checkAllN_sound {p : N -> bool} {lo cnt : N} (h : checkAllN p lo cnt = true) :
  forall i : N, lo <= i -> i < lo + cnt -> p i = true.
Proof.
  intros i h1 h2; apply (checkAllFuel_sound h i h1); rewrite N2Nat.id; exact h2.
Qed.

Definition checkTCTblAndExits (td : ProofTables) : bool :=
  checkAllN (fun i =>
    let tc := get16 td.(pt_tcTbl) i in
    checkTC td.(pt_wayTbl) td.(pt_numWays) tc &&
    checkAllN (fun r =>
      checkTCExit td.(pt_wayTbl) tc (get1024 td.(pt_tcExitTbl) (tc.(tc_exitBase) + r)) r) 0 tc.(tc_decK)) 0 6 &&
  checkAllN (fun i => isABCode (get16 td.(pt_midTbl) i)) 0 td.(pt_numMids).

Lemma checkTCTblAndExits_sound {td : ProofTables} (h : checkTCTblAndExits td = true) :
  (forall i : N, i < 6 -> checkTC td.(pt_wayTbl) td.(pt_numWays) (get16 td.(pt_tcTbl) i) = true) /\
  (forall i : N, i < 6 -> forall r : N, r < (get16 td.(pt_tcTbl) i).(tc_decK) ->
    checkTCExit td.(pt_wayTbl) (get16 td.(pt_tcTbl) i)
      (get1024 td.(pt_tcExitTbl) ((get16 td.(pt_tcTbl) i).(tc_exitBase) + r)) r = true) /\
  (forall i : N, i < td.(pt_numMids) -> isABCode (get16 td.(pt_midTbl) i) = true).
Proof.
  unfold checkTCTblAndExits in h; apply Bool.andb_true_iff in h; destruct h as [hTCs hMids].
  repeat split.
  - intros i hi; pose proof (checkAllN_sound hTCs i (N.le_0_l _) hi) as h1.
    apply Bool.andb_true_iff in h1; exact (proj1 h1).
  - intros i hi r hr; pose proof (checkAllN_sound hTCs i (N.le_0_l _) hi) as h1.
    apply Bool.andb_true_iff in h1; exact (checkAllN_sound (proj2 h1) r (N.le_0_l _) hr).
  - intros i hi; exact (checkAllN_sound hMids i (N.le_0_l _) hi).
Qed.

Inductive InInv (td : ProofTables) : StateX -> Prop :=
  | InInv_midTC (midId tcId M K : N)
      (hMem : hasMidTC td midId tcId = true)
      (hK : (get16 td.(pt_tcTbl) tcId).(tc_minK) <= K)
      (hPhi : invB <= M + 12 * K) :
      InInv td (tailTape (decAB (get16 td.(pt_midTbl) midId)) M
        (get16 td.(pt_tcTbl) tcId).(tc_bt) K
        (get32768 td.(pt_wayTbl) (get16 td.(pt_tcTbl) tcId).(tc_ancWid)).(we_tl))
  | InInv_smallNK3 (tcId X M K : N)
      (hMem : hasSmallNK3 td tcId X = true)
      (hK : (get16 td.(pt_tcTbl) tcId).(tc_minK) <= K)
      (hPhi : invB <= M + 12 * K) :
      InInv td (tailTape (nk3MidAB X) M true K
        (get32768 td.(pt_wayTbl) (get16 td.(pt_tcTbl) tcId).(tc_ancWid)).(we_tl))
  | InInv_largeNK3 (tcId X M K : N)
      (hTC : tcId = 1 \/ tcId = 4)
      (hX : xMin <= X)
      (hK : (get16 td.(pt_tcTbl) tcId).(tc_minK) <= K)
      (hPhi : invB <= M + 12 * K) :
      InInv td (tailTape (nk3MidAB X) M true K
        (get32768 td.(pt_wayTbl) (get16 td.(pt_tcTbl) tcId).(tc_ancWid)).(we_tl)).

Definition skHash (bt : bool) (mdCode kr tlCode : N) : N :=
  N.modulo ((if bt then 1 else 0) + (131 * N.modulo mdCode 4093 + (17 * kr + N.modulo tlCode 4093))) 4093.

Definition fmdHash (x2 : bool) (kr tlCode : N) : N :=
  N.modulo ((if x2 then 1 else 0) + (17 * kr + N.modulo tlCode 4093)) 4093.

Fixpoint findIdxInList (p : N -> bool) (l : list N) : option N :=
  match l with
  | [] => None
  | i :: rest => if p i then Some i else findIdxInList p rest
  end.

Lemma findIdxInList_sound {p : N -> bool} {l : list N} {i : N}
  (h : findIdxInList p l = Some i) : p i = true.
Proof.
  induction l as [|x xs ih]; [discriminate |].
  cbn [findIdxInList] in h; destruct (p x) eqn:hx.
  - inversion h; subst; exact hx.
  - exact (ih h).
Qed.

Definition checkPFChain (td : ProofTables) (restCode : N) (par : bool) (pfI minN : N) : bool :=
  if N.ltb pfI td.(pt_numPF) then
    let pf := get16384 td.(pt_pfTbl) pfI in
    let res := wayHops td.(pt_wayTbl) pf.(pfe_wayHopsCnt) pf.(pfe_t1Wid) in
    let tc2 := get16 td.(pt_tcTbl) pf.(pfe_dstTcId) in
    let minK1 := (minN - pf.(pfe_rule).(rpf_need0)) + pf.(pfe_rule).(rpf_addK) in
    let minK2 := (minK1 - (snd res).(aff_need)) + (snd res).(aff_add) in
    N.eqb pf.(pfe_rule).(rpf_restCode) restCode &&
    Bool.eqb pf.(pfe_rule).(rpf_par) par &&
    N.leb pf.(pfe_rule).(rpf_need0) minN &&
    N.ltb pf.(pfe_t1Wid) td.(pt_numWays) &&
    N.eqb (get32768 td.(pt_wayTbl) pf.(pfe_t1Wid)).(we_tl) pf.(pfe_rule).(rpf_t1Code) &&
    Bool.eqb (get32768 td.(pt_wayTbl) pf.(pfe_t1Wid)).(we_bt) pf.(pfe_rule).(rpf_bt) &&
    N.ltb pf.(pfe_dstTcId) 6 &&
    N.eqb (fst (fst res)) tc2.(tc_ancWid) &&
    Bool.eqb tc2.(tc_bt) pf.(pfe_rule).(rpf_bt) &&
    N.leb (snd res).(aff_need) minK1 &&
    N.leb tc2.(tc_minK) minK2 &&
    N.leb invB (pf.(pfe_rule).(rpf_pc) + snd (fst res) + 12 * minK2) &&
    if pf.(pfe_isNK3) then
      Bool.eqb pf.(pfe_rule).(rpf_bt) true &&
      N.eqb pf.(pfe_rule).(rpf_mdCode) (mkNK3MidCode pf.(pfe_nk3X)) &&
      if N.ltb pf.(pfe_nk3X) xMin then hasSmallNK3 td pf.(pfe_dstTcId) pf.(pfe_nk3X)
      else (N.eqb pf.(pfe_dstTcId) 1 || N.eqb pf.(pfe_dstTcId) 4)
    else
      hasMidTC td pf.(pfe_dstMidId) pf.(pfe_dstTcId) &&
      N.eqb (get16 td.(pt_midTbl) pf.(pfe_dstMidId)) pf.(pfe_rule).(rpf_mdCode)
  else false.

Lemma checkPFChain_sound {td : ProofTables} (hV : ValidTables td)
  {restCode : N} {par : bool} {pfI minN : N}
  (h : checkPFChain td restCode par pfI minN = true) :
  forall Nv : N, minN <= Nv ->
    exists s' : StateX,
      RPlus (M_L LM_B, true :: bitsC ++ bitsARn 3 ++ bitsC ++
                       powBitsN (blkBitsL S_Q3) (2 * Nv + if par then 1 else 0) ++ decBits restCode, [])
            s' /\
      InInv td s'.
Proof.
  unfold checkPFChain in h.
  destruct (N.ltb pfI td.(pt_numPF)) eqn:hpfLt; [| discriminate].
  apply N.ltb_lt in hpfLt.
  set (pf := get16384 td.(pt_pfTbl) pfI) in *.
  set (res := wayHops td.(pt_wayTbl) pf.(pfe_wayHopsCnt) pf.(pfe_t1Wid)) in *.
  set (tc2 := get16 td.(pt_tcTbl) pf.(pfe_dstTcId)) in *.
  set (minK1 := (minN - pf.(pfe_rule).(rpf_need0)) + pf.(pfe_rule).(rpf_addK)) in *.
  set (minK2 := (minK1 - (snd res).(aff_need)) + (snd res).(aff_add)) in *.
  apply Bool.andb_true_iff in h; destruct h as [hBase hTgt].
  split_andb.
  destruct (hV.(vt_pf) pfI hpfLt) as [preB [postB [hints hchkPF]]]; fold pf in hchkPF.
  destruct (checkPF_sound hV.(vt_suf) hchkPF) as [_ hstepPF]; clear preB postB hints hchkPF.
  assert (ht1Lt : pf.(pfe_t1Wid) < td.(pt_numWays)) by assumption.
  destruct (wayHops_sound hV.(vt_way) (h := pf.(pfe_wayHopsCnt)) ht1Lt) as [_ [_ hway]]; fold res in hway.
  intros Nv hN.
  pose proof (hstepPF Nv ltac:(fast_lia)) as h1.
  replace (pf.(pfe_rule).(rpf_restCode)) with restCode in h1 by congruence.
  replace (pf.(pfe_rule).(rpf_par)) with par in h1 by congruence.
  set (K1 := Nv - pf.(pfe_rule).(rpf_need0) + pf.(pfe_rule).(rpf_addK)) in *.
  set (K2 := K1 - (snd res).(aff_need) + (snd res).(aff_add)) in *.
  assert (hK1ge : minK1 <= K1) by (unfold minK1, K1; fast_lia).
  assert (hK2ge : minK2 <= K2) by (clearbody minK1 K1; unfold minK2, K2; fast_lia).
  destruct pf.(pfe_isNK3) eqn:hnk.
  - apply Bool.andb_true_iff in hTgt; destruct hTgt as [hTgt1 hMem]; split_andb.
    pose proof (hway (nk3MidAB pf.(pfe_nk3X)) pf.(pfe_rule).(rpf_pc) K1 ltac:(clearbody minK1 minK2 K1 K2; fast_lia)) as h2; fold res K2 in h2.
    clearbody minK1 minK2 K1 K2.
    replace ((get32768 td.(pt_wayTbl) pf.(pfe_t1Wid)).(we_bt)) with true in h2 by congruence.
    replace ((get32768 td.(pt_wayTbl) pf.(pfe_t1Wid)).(we_tl)) with pf.(pfe_rule).(rpf_t1Code) in h2 by congruence.
    replace (fst (fst res)) with tc2.(tc_ancWid) in h2 by congruence.
    replace (pf.(pfe_rule).(rpf_mdCode)) with (mkNK3MidCode pf.(pfe_nk3X)) in h1 by congruence.
    replace (pf.(pfe_rule).(rpf_bt)) with true in h1 by congruence.
    rewrite decBits_mkNK3MidCode in h1.
    pose proof (rPlus_trans_star h1 h2) as hcomp.
    destruct (N.ltb pf.(pfe_nk3X) xMin) eqn:hxLt.
    + exists (tailTape (nk3MidAB pf.(pfe_nk3X)) (pf.(pfe_rule).(rpf_pc) + snd (fst res)) true K2
        (get32768 td.(pt_wayTbl) tc2.(tc_ancWid)).(we_tl)).
      split; [exact hcomp | subst tc2; refine (InInv_smallNK3 td pf.(pfe_dstTcId) pf.(pfe_nk3X) _ K2 hMem _ _); fast_lia].
    + apply N.ltb_ge in hxLt.
      apply Bool.orb_true_iff in hMem; destruct hMem as [htc1 | htc4];
        [apply N.eqb_eq in htc1 | apply N.eqb_eq in htc4].
      * exists (tailTape (nk3MidAB pf.(pfe_nk3X)) (pf.(pfe_rule).(rpf_pc) + snd (fst res)) true K2
          (get32768 td.(pt_wayTbl) tc2.(tc_ancWid)).(we_tl)).
        split; [exact hcomp | subst tc2; refine (InInv_largeNK3 td pf.(pfe_dstTcId) pf.(pfe_nk3X) _ K2 (or_introl htc1) hxLt _ _); fast_lia].
      * exists (tailTape (nk3MidAB pf.(pfe_nk3X)) (pf.(pfe_rule).(rpf_pc) + snd (fst res)) true K2
          (get32768 td.(pt_wayTbl) tc2.(tc_ancWid)).(we_tl)).
        split; [exact hcomp | subst tc2; refine (InInv_largeNK3 td pf.(pfe_dstTcId) pf.(pfe_nk3X) _ K2 (or_intror htc4) hxLt _ _); fast_lia].
  - apply Bool.andb_true_iff in hTgt; destruct hTgt as [hMem hmdEq]; apply N.eqb_eq in hmdEq.
    assert (hmidLt : pf.(pfe_dstMidId) < td.(pt_numMids)).
    { pose proof hMem as hm; unfold hasMidTC in hm; split_andb; assumption. }
    set (m := get16 td.(pt_midTbl) pf.(pfe_dstMidId)) in *.
    assert (hmAB : evalABL (decAB m) = decBits pf.(pfe_rule).(rpf_mdCode))
      by (rewrite (evalABL_decAB m (hV.(vt_mid) _ hmidLt)), hmdEq; reflexivity).
    pose proof (hway (decAB m) pf.(pfe_rule).(rpf_pc) K1 ltac:(clearbody minK1 minK2 K1 K2; fast_lia)) as h2; fold res K2 in h2.
    clearbody minK1 minK2 K1 K2.
    replace ((get32768 td.(pt_wayTbl) pf.(pfe_t1Wid)).(we_bt)) with tc2.(tc_bt) in h2 by congruence.
    replace ((get32768 td.(pt_wayTbl) pf.(pfe_t1Wid)).(we_tl)) with pf.(pfe_rule).(rpf_t1Code) in h2 by congruence.
    replace (fst (fst res)) with tc2.(tc_ancWid) in h2 by congruence.
    rewrite <- hmAB in h1.
    replace (pf.(pfe_rule).(rpf_bt)) with tc2.(tc_bt) in h1 by congruence.
    pose proof (rPlus_trans_star h1 h2) as hcomp.
    exists (tailTape (decAB m) (pf.(pfe_rule).(rpf_pc) + snd (fst res)) tc2.(tc_bt) K2
      (get32768 td.(pt_wayTbl) tc2.(tc_ancWid)).(we_tl)).
    split; [exact hcomp | subst m tc2; refine (InInv_midTC td pf.(pfe_dstMidId) pf.(pfe_dstTcId) _ K2 hMem _ _); fast_lia].
Qed.

Definition checkRule1Chain (td : ProofTables) (bt : bool) (mdCode kr tlCode minM : N) : bool :=
  let bucket := get4096 td.(pt_skIdx) (skHash bt mdCode kr tlCode) in
  match findIdxInList (fun i =>
    let sk := get4096 td.(pt_skTbl) i in
    N.ltb i td.(pt_numSK) &&
    Bool.eqb sk.(ske_rule).(r1_bt) bt &&
    N.eqb sk.(ske_rule).(r1_midCode) mdCode &&
    N.eqb sk.(ske_rule).(r1_kr) kr &&
    N.eqb sk.(ske_rule).(r1_tlCode) tlCode) bucket with
  | None => false
  | Some skI =>
      let sk := get4096 td.(pt_skTbl) skI in
      let minQ := (minM - sk.(ske_rule).(r1_need0)) + sk.(ske_rule).(r1_add0) in
      let minN := minQ / 2 in
      N.leb sk.(ske_rule).(r1_need0) minM &&
      checkPFChain td sk.(ske_rule).(r1_outRestCode) false sk.(ske_pfEvenIdx) minN &&
      checkPFChain td sk.(ske_rule).(r1_outRestCode) true sk.(ske_pfOddIdx) minN
  end.

Lemma checkRule1Chain_sound {td : ProofTables} (hV : ValidTables td)
  {bt : bool} {mdCode kr tlCode minM : N}
  (h : checkRule1Chain td bt mdCode kr tlCode minM = true)
  (prefAB : list ABWord) (hAB : evalABL prefAB = decBits mdCode) :
  forall M : N, minM <= M ->
    exists s' : StateX, RPlus (tailTape prefAB M bt kr tlCode) s' /\ InInv td s'.
Proof.
  unfold checkRule1Chain in h.
  destruct (findIdxInList _ _) as [skI|] eqn:hf; [| discriminate].
  pose proof (findIdxInList_sound hf) as hmatch; cbn beta in hmatch.
  apply Bool.andb_true_iff in h; destruct h as [h hOdd].
  apply Bool.andb_true_iff in h; destruct h as [hneed0 hEven].
  apply N.leb_le in hneed0; split_andb.
  set (sk := get4096 td.(pt_skTbl) skI) in *.
  assert (hskLt : skI < td.(pt_numSK)) by assumption.
  destruct (hV.(vt_sk) skI hskLt) as [preQ [postQ [hints hchk1]]]; fold sk in hchk1.
  intros M hM.
  pose proof (check1Blk_sound hV.(vt_suf) hchk1 M ltac:(fast_lia)) as h1; clear preQ postQ hints hchk1.
  replace (sk.(ske_rule).(r1_bt)) with bt in h1 by congruence.
  replace (sk.(ske_rule).(r1_midCode)) with mdCode in h1 by congruence.
  replace (sk.(ske_rule).(r1_kr)) with kr in h1 by congruence.
  replace (sk.(ske_rule).(r1_tlCode)) with tlCode in h1 by congruence.
  rewrite <- hAB in h1.
  set (Qv := M - sk.(ske_rule).(r1_need0) + sk.(ske_rule).(r1_add0)) in *.
  assert (hQge : minM - sk.(ske_rule).(r1_need0) + sk.(ske_rule).(r1_add0) <= Qv) by (unfold Qv; fast_lia).
  assert (hNge : (minM - sk.(ske_rule).(r1_need0) + sk.(ske_rule).(r1_add0)) / 2 <= Qv / 2)
    by (apply N.Div0.div_le_mono; exact hQge).
  pose proof (div2_decomp Qv) as hdiv2.
  destruct (N.eqb (Qv mod 2) 1) eqn:hpar.
  - destruct (checkPFChain_sound hV hOdd (Qv / 2) hNge) as [s' [h2 hInv]].
    rewrite hdiv2 in h2; exists s'; split; [exact (rPlus_trans h1 h2) | exact hInv].
  - destruct (checkPFChain_sound hV hEven (Qv / 2) hNge) as [s' [h2 hInv]].
    rewrite hdiv2 in h2; exists s'; split; [exact (rPlus_trans h1 h2) | exact hInv].
Qed.

Definition checkRule2Chain (td : ProofTables) (r2 : Rule2Entry) (exactM : bool) (minM minN : N) : bool :=
  let res := wayHops td.(pt_wayTbl) r2.(r2e_wayHopsCnt) r2.(r2e_t1Wid) in
  let tc2 := get16 td.(pt_tcTbl) r2.(r2e_dstTcId) in
  let minK1 := (minN - r2.(r2e_rule).(r2_need1)) + r2.(r2e_rule).(r2_addK) in
  let minK2 := (minK1 - (snd res).(aff_need)) + (snd res).(aff_add) in
  N.leb r2.(r2e_rule).(r2_need0) minM &&
  N.leb r2.(r2e_rule).(r2_need1) minN &&
  N.ltb r2.(r2e_t1Wid) td.(pt_numWays) &&
  N.eqb (get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_tl) r2.(r2e_rule).(r2_t1Code) &&
  Bool.eqb (get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_bt) r2.(r2e_rule).(r2_bt) &&
  N.ltb r2.(r2e_dstTcId) 6 &&
  N.eqb (fst (fst res)) tc2.(tc_ancWid) &&
  Bool.eqb tc2.(tc_bt) r2.(r2e_rule).(r2_bt) &&
  N.leb (snd res).(aff_need) minK1 &&
  N.leb tc2.(tc_minK) minK2 &&
  if r2.(r2e_rule).(r2_isKind2) then
    let minXout := (minM - r2.(r2e_rule).(r2_need0)) + r2.(r2e_rule).(r2_add0) in
    N.leb invB (r2.(r2e_rule).(r2_pc) + snd (fst res) + 12 * minK2) &&
    (N.eqb r2.(r2e_dstTcId) 1 || N.eqb r2.(r2e_dstTcId) 4) &&
    if exactM then
      if N.ltb minXout xMin then hasSmallNK3 td r2.(r2e_dstTcId) minXout else true
    else
      N.leb xMin minXout
  else
    let minMout := (minM - r2.(r2e_rule).(r2_need0)) + r2.(r2e_rule).(r2_add0) + snd (fst res) in
    N.leb invB (minMout + 12 * minK2) &&
    hasMidTC td r2.(r2e_dstMidId) r2.(r2e_dstTcId) &&
    N.eqb (get16 td.(pt_midTbl) r2.(r2e_dstMidId)) r2.(r2e_rule).(r2_mdCode).

Lemma checkRule2Chain_sound {td : ProofTables} (hV : ValidTables td)
  {r2 : Rule2Entry} (hR2 : ValidRule2Entry td.(pt_sufTbl) r2)
  {exactM : bool} {minM minN : N}
  (h : checkRule2Chain td r2 exactM minM minN = true) :
  forall M Nv : N, (if exactM then M = minM else minM <= M) -> minN <= Nv ->
    exists s' : StateX,
      RPlus (tailTape (nk3MidAB (2 * Nv + if r2.(r2e_rule).(r2_x2) then 1 else 0))
              M true r2.(r2e_rule).(r2_kr) r2.(r2e_rule).(r2_tlCode)) s' /\
      InInv td s'.
Proof.
  unfold checkRule2Chain in h.
  set (res := wayHops td.(pt_wayTbl) r2.(r2e_wayHopsCnt) r2.(r2e_t1Wid)) in *.
  set (tc2 := get16 td.(pt_tcTbl) r2.(r2e_dstTcId)) in *.
  set (minK1 := (minN - r2.(r2e_rule).(r2_need1)) + r2.(r2e_rule).(r2_addK)) in *.
  set (minK2 := (minK1 - (snd res).(aff_need)) + (snd res).(aff_add)) in *.
  apply Bool.andb_true_iff in h; destruct h as [hBase hTgt].
  split_andb.
  destruct hR2 as [c1 [c2 [c3 [c4 [h1s [h2s hchk2]]]]]].
  destruct (check2Blk_sound hV.(vt_suf) hchk2) as [_ [hk2Bt hstep2]]; clear c1 c2 c3 c4 h1s h2s hchk2.
  assert (ht1Lt : r2.(r2e_t1Wid) < td.(pt_numWays)) by assumption.
  destruct (wayHops_sound hV.(vt_way) (h := r2.(r2e_wayHopsCnt)) ht1Lt) as [_ [_ hway]]; fold res in hway.
  intros M Nv hM hN.
  assert (hMge : minM <= M) by (destruct exactM; fast_lia).
  pose proof (hstep2 M Nv ltac:(fast_lia) ltac:(fast_lia)) as h1; cbn zeta in h1.
  set (K1 := Nv - r2.(r2e_rule).(r2_need1) + r2.(r2e_rule).(r2_addK)) in *.
  set (K2 := K1 - (snd res).(aff_need) + (snd res).(aff_add)) in *.
  assert (hK1ge : minK1 <= K1) by (unfold minK1, K1; fast_lia).
  assert (hK2ge : minK2 <= K2) by (clearbody minK1 K1; unfold minK2, K2; fast_lia).
  assert (hStart : tailTape (nk3MidAB (2 * Nv + if r2.(r2e_rule).(r2_x2) then 1 else 0))
      M true r2.(r2e_rule).(r2_kr) r2.(r2e_rule).(r2_tlCode) =
      (M_L LM_B, true :: bitsC ++ powBitsN (blkBitsL S_P) M ++
        (bitsA ++ bitsA ++ bitsB ++ powBitsN (blkBitsL S_Q3) (2 * Nv + if r2.(r2e_rule).(r2_x2) then 1 else 0) ++ bitsARn 4 ++ bitsB) ++
        powBitsN (blkBitsL S_W5) r2.(r2e_rule).(r2_kr) ++ decBits r2.(r2e_rule).(r2_tlCode), [])).
  { unfold tailTape; rewrite evalABL_nk3MidAB; cbn [blkKind]; reflexivity. }
  rewrite hStart.
  destruct r2.(r2e_rule).(r2_isKind2) eqn:hk2.
  - pose proof (hk2Bt eq_refl) as hbtT.
    apply Bool.andb_true_iff in hTgt; destruct hTgt as [hTgt1 hXcond].
    apply Bool.andb_true_iff in hTgt1; destruct hTgt1 as [hphi htc14]; apply N.leb_le in hphi.
    assert (htcOr : r2.(r2e_dstTcId) = 1 \/ r2.(r2e_dstTcId) = 4).
    { apply Bool.orb_true_iff in htc14; destruct htc14 as [ha|hb];
      [apply N.eqb_eq in ha; left; exact ha | apply N.eqb_eq in hb; right; exact hb]. }
    set (Xout := M - r2.(r2e_rule).(r2_need0) + r2.(r2e_rule).(r2_add0)) in *.
    pose proof (hway (nk3MidAB Xout) r2.(r2e_rule).(r2_pc) K1 ltac:(clearbody minK1 minK2 K1 K2; fast_lia)) as h2; fold res K2 in h2.
    clearbody minK1 minK2 K1 K2.
    replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_bt)) with true in h2 by congruence.
    replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_tl)) with r2.(r2e_rule).(r2_t1Code) in h2 by congruence.
    replace (fst (fst res)) with tc2.(tc_ancWid) in h2 by congruence.
    assert (hMidEq : (M_L LM_B, true :: bitsC ++ powBitsN (blkBitsL S_P) r2.(r2e_rule).(r2_pc) ++
        (bitsA ++ bitsA ++ bitsB ++ powBitsN (blkBitsL S_Q3) Xout ++ bitsARn 4 ++ bitsB) ++
        powBitsN (blkBitsL S_W5) K1 ++ decBits r2.(r2e_rule).(r2_t1Code), []) =
        tailTape (nk3MidAB Xout) r2.(r2e_rule).(r2_pc) true K1 r2.(r2e_rule).(r2_t1Code)).
    { unfold tailTape; rewrite evalABL_nk3MidAB; cbn [blkKind]; reflexivity. }
    rewrite hMidEq in h1.
    pose proof (rPlus_trans_star h1 h2) as hcomp.
    destruct exactM; cbn zeta in hXcond.
    + subst M.
      destruct (N.ltb Xout xMin) eqn:hxLt.
      * unfold Xout in hxLt; rewrite hxLt in hXcond.
        exists (tailTape (nk3MidAB Xout) (r2.(r2e_rule).(r2_pc) + snd (fst res)) true K2
          (get32768 td.(pt_wayTbl) tc2.(tc_ancWid)).(we_tl)).
        split; [exact hcomp | subst tc2; refine (InInv_smallNK3 td r2.(r2e_dstTcId) Xout _ K2 hXcond _ _); clearbody Xout; fast_lia].
      * apply N.ltb_ge in hxLt; clearbody Xout.
        exists (tailTape (nk3MidAB Xout) (r2.(r2e_rule).(r2_pc) + snd (fst res)) true K2
          (get32768 td.(pt_wayTbl) tc2.(tc_ancWid)).(we_tl)).
        split; [exact hcomp | subst tc2; refine (InInv_largeNK3 td r2.(r2e_dstTcId) Xout _ K2 htcOr hxLt _ _); fast_lia].
    + apply N.leb_le in hXcond.
      assert (hXge : xMin <= Xout) by (unfold Xout; fast_lia); clearbody Xout.
      exists (tailTape (nk3MidAB Xout) (r2.(r2e_rule).(r2_pc) + snd (fst res)) true K2
        (get32768 td.(pt_wayTbl) tc2.(tc_ancWid)).(we_tl)).
      split; [exact hcomp | subst tc2; refine (InInv_largeNK3 td r2.(r2e_dstTcId) Xout _ K2 htcOr hXge _ _); fast_lia].
  - apply Bool.andb_true_iff in hTgt; destruct hTgt as [hTgt1 hmdEq].
    apply Bool.andb_true_iff in hTgt1; destruct hTgt1 as [hphi hMem].
    apply N.leb_le in hphi; apply N.eqb_eq in hmdEq.
    assert (hmidLt : r2.(r2e_dstMidId) < td.(pt_numMids)).
    { pose proof hMem as hm; unfold hasMidTC in hm; split_andb; assumption. }
    set (m := get16 td.(pt_midTbl) r2.(r2e_dstMidId)) in *.
    assert (hmAB : evalABL (decAB m) = decBits r2.(r2e_rule).(r2_mdCode))
      by (rewrite (evalABL_decAB m (hV.(vt_mid) _ hmidLt)), hmdEq; reflexivity).
    set (Mout := M - r2.(r2e_rule).(r2_need0) + r2.(r2e_rule).(r2_add0)) in *.
    assert (hMoutGe : (minM - r2.(r2e_rule).(r2_need0)) + r2.(r2e_rule).(r2_add0) <= Mout) by (unfold Mout; fast_lia).
    clearbody Mout.
    pose proof (hway (decAB m) Mout K1 ltac:(clearbody minK1 minK2 K1 K2; fast_lia)) as h2; fold res K2 in h2.
    clearbody minK1 minK2 K1 K2.
    replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_bt)) with tc2.(tc_bt) in h2 by congruence.
    replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_tl)) with r2.(r2e_rule).(r2_t1Code) in h2 by congruence.
    replace (fst (fst res)) with tc2.(tc_ancWid) in h2 by congruence.
    rewrite <- hmAB in h1.
    replace (r2.(r2e_rule).(r2_bt)) with tc2.(tc_bt) in h1 by congruence.
    pose proof (rPlus_trans_star h1 h2) as hcomp.
    exists (tailTape (decAB m) (Mout + snd (fst res)) tc2.(tc_bt) K2
      (get32768 td.(pt_wayTbl) tc2.(tc_ancWid)).(we_tl)).
    split; [exact hcomp | subst m tc2; cbn zeta in hphi; refine (InInv_midTC td r2.(r2e_dstMidId) r2.(r2e_dstTcId) _ K2 hMem _ _); fast_lia].
Qed.

Definition checkFmdOne (td : ProofTables) (x2 : bool) (M_fmd kr tlCode minN : N) : bool :=
  let bucket := get4096 td.(pt_fmdIdx) (fmdHash x2 kr tlCode) in
  match findIdxInList (fun i =>
    let fmd := get4096 td.(pt_fmdTbl) i in
    N.ltb i td.(pt_numFmd) &&
    Bool.eqb fmd.(r2e_rule).(r2_x2) x2 &&
    N.eqb fmd.(r2e_rule).(r2_kr) kr &&
    N.eqb fmd.(r2e_rule).(r2_tlCode) tlCode) bucket with
  | None => false
  | Some fi => checkRule2Chain td (get4096 td.(pt_fmdTbl) fi) true M_fmd minN
  end.

Definition checkFmdBoth (td : ProofTables) (M_fmd kr tlCode minN : N) : bool :=
  checkFmdOne td false M_fmd kr tlCode minN && checkFmdOne td true M_fmd kr tlCode minN.

Lemma checkFmdBoth_sound {td : ProofTables} (hV : ValidTables td)
  {M_fmd kr tlCode minN : N}
  (h : checkFmdBoth td M_fmd kr tlCode minN = true) :
  forall X_a : N, minN <= X_a / 2 ->
    exists s' : StateX, RPlus (tailTape (nk3MidAB X_a) M_fmd true kr tlCode) s' /\ InInv td s'.
Proof.
  unfold checkFmdBoth in h; apply Bool.andb_true_iff in h; destruct h as [hE hO].
  assert (hOne : forall x2 : bool, checkFmdOne td x2 M_fmd kr tlCode minN = true ->
    forall Nv : N, minN <= Nv ->
      exists s' : StateX, RPlus (tailTape (nk3MidAB (2 * Nv + if x2 then 1 else 0)) M_fmd true kr tlCode) s' /\ InInv td s').
  { intros x2 h1 Nv hN; unfold checkFmdOne in h1.
    destruct (findIdxInList _ _) as [fi|] eqn:hf; [| discriminate].
    pose proof (findIdxInList_sound hf) as hm; cbn beta in hm; split_andb.
    assert (hfiLt : fi < td.(pt_numFmd)) by assumption.
    destruct (checkRule2Chain_sound hV (hV.(vt_fmd) fi hfiLt) h1 M_fmd Nv eq_refl hN) as [s' [hstep hInv]].
    replace ((get4096 td.(pt_fmdTbl) fi).(r2e_rule).(r2_x2)) with x2 in hstep by congruence.
    replace ((get4096 td.(pt_fmdTbl) fi).(r2e_rule).(r2_kr)) with kr in hstep by congruence.
    replace ((get4096 td.(pt_fmdTbl) fi).(r2e_rule).(r2_tlCode)) with tlCode in hstep by congruence.
    exists s'; split; [exact hstep | exact hInv]. }
  intros X_a hXa.
  pose proof (div2_decomp X_a) as hdiv2.
  destruct (N.eqb (X_a mod 2) 1) eqn:hpar.
  - rewrite <- hdiv2; exact (hOne true hO (X_a / 2) hXa).
  - rewrite <- hdiv2; exact (hOne false hE (X_a / 2) hXa).
Qed.

Definition checkMidTCR (td : ProofTables) (midId tcId r : N) : bool :=
  let m := get16 td.(pt_midTbl) midId in
  let tc := get16 td.(pt_tcTbl) tcId in
  let ex := get1024 td.(pt_tcExitTbl) (tc.(tc_exitBase) + r) in
  let ew := get32768 td.(pt_wayTbl) ex.(tce_exitWid) in
  let cost := 12 * (tc.(tc_minK) + r) in
  N.leb cost invB &&
  checkRule1Chain td tc.(tc_bt) m ex.(tce_kr) ew.(we_tl) ((invB - cost) + ex.(tce_steps)).

Definition checkMidTCRange (td : ProofTables) (midId tcId lo cnt : N) : bool :=
  checkAllN (checkMidTCR td midId tcId) lo cnt.

Definition checkMidTCGraph (td : ProofTables) : bool :=
  checkAllN (fun midId =>
    checkAllN (fun tcId =>
      if hasMidTC td midId tcId then
        checkMidTCRange td midId tcId 0 (get16 td.(pt_tcTbl) tcId).(tc_decK)
      else true) 0 6) 0 td.(pt_numMids).

Lemma checkMidTCGraph_sound {td : ProofTables} (h : checkMidTCGraph td = true) :
  forall midId tcId : N, hasMidTC td midId tcId = true ->
    forall r : N, r < (get16 td.(pt_tcTbl) tcId).(tc_decK) -> checkMidTCR td midId tcId r = true.
Proof.
  intros midId tcId hMem r hr.
  pose proof hMem as hm; unfold hasMidTC in hm; split_andb.
  assert (hmidLt : midId < td.(pt_numMids)) by assumption.
  assert (htcLt : tcId < 6) by assumption.
  unfold checkMidTCGraph in h.
  pose proof (checkAllN_sound h midId (N.le_0_l _) hmidLt) as h1; cbn beta in h1.
  pose proof (checkAllN_sound h1 tcId (N.le_0_l _) htcLt) as h2; cbn beta in h2.
  rewrite hMem in h2.
  exact (checkAllN_sound h2 r (N.le_0_l _) hr).
Qed.

Definition checkLargeNK3TC (td : ProofTables) (tcId : N) : bool :=
  let tc := get16 td.(pt_tcTbl) tcId in
  Bool.eqb tc.(tc_bt) true &&
  checkAllN (fun r =>
    let ex := get1024 td.(pt_tcExitTbl) (tc.(tc_exitBase) + r) in
    let ew := get32768 td.(pt_wayTbl) ex.(tce_exitWid) in
    let cost := 12 * (tc.(tc_minK) + r) in
    let minM := (invB - cost) + ex.(tce_steps) in
    let i0 := tc.(tc_nk3Base) + 2 * r in
    let i1 := i0 + 1 in
    let r0 := get256 td.(pt_nk3ATbl) i0 in
    let r1 := get256 td.(pt_nk3ATbl) i1 in
    N.leb cost invB &&
    N.ltb i1 100 &&
    Bool.eqb r0.(r2e_rule).(r2_x2) false &&
    N.eqb r0.(r2e_rule).(r2_kr) ex.(tce_kr) &&
    N.eqb r0.(r2e_rule).(r2_tlCode) ew.(we_tl) &&
    Bool.eqb r1.(r2e_rule).(r2_x2) true &&
    N.eqb r1.(r2e_rule).(r2_kr) ex.(tce_kr) &&
    N.eqb r1.(r2e_rule).(r2_tlCode) ew.(we_tl) &&
    checkRule2Chain td r0 false minM (xMin / 2) &&
    checkRule2Chain td r1 false minM (xMin / 2)) 0 tc.(tc_decK).

Definition checkLargeNK3Graph (td : ProofTables) : bool :=
  checkLargeNK3TC td 1 && checkLargeNK3TC td 4.

Definition checkSmallNK3One (td : ProofTables) (tcId X : N) : bool :=
  let tc := get16 td.(pt_tcTbl) tcId in
  Bool.eqb tc.(tc_bt) true &&
  if N.ltb X 18 then
    checkAllN (fun r =>
      let ex := get1024 td.(pt_tcExitTbl) (tc.(tc_exitBase) + r) in
      let ew := get32768 td.(pt_wayTbl) ex.(tce_exitWid) in
      let cost := 12 * (tc.(tc_minK) + r) in
      N.leb cost invB &&
      checkRule1Chain td true (mkNK3MidCode X) ex.(tce_kr) ew.(we_tl) ((invB - cost) + ex.(tce_steps))) 0 tc.(tc_decK)
  else
    let Nv := X / 2 in
    let x2 := N.eqb (X mod 2) 1 in
    checkAllN (fun r =>
      let ex := get1024 td.(pt_tcExitTbl) (tc.(tc_exitBase) + r) in
      let ew := get32768 td.(pt_wayTbl) ex.(tce_exitWid) in
      let cost := 12 * (tc.(tc_minK) + r) in
      let minM := (invB - cost) + ex.(tce_steps) in
      let idx := tc.(tc_nk3Base) + (2 * r + if x2 then 1 else 0) in
      let r2 := get256 td.(pt_nk3ATbl) idx in
      let K1 := (Nv - r2.(r2e_rule).(r2_need1)) + r2.(r2e_rule).(r2_addK) in
      N.leb cost invB &&
      N.ltb idx 100 &&
      Bool.eqb r2.(r2e_rule).(r2_x2) x2 &&
      N.eqb r2.(r2e_rule).(r2_kr) ex.(tce_kr) &&
      N.eqb r2.(r2e_rule).(r2_tlCode) ew.(we_tl) &&
      N.leb r2.(r2e_rule).(r2_need0) minM &&
      N.leb r2.(r2e_rule).(r2_need1) Nv &&
      N.ltb r2.(r2e_t1Wid) td.(pt_numWays) &&
      N.eqb (get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_tl) r2.(r2e_rule).(r2_t1Code) &&
      Bool.eqb (get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_bt) r2.(r2e_rule).(r2_bt) &&
      match wayRunConcreteAux td.(pt_wayTbl) td.(pt_tcTbl) fuel_2048 r2.(r2e_t1Wid) 0 K1 with
      | None => false
      | Some (reachedTC, dst, st, ko) =>
          let minM1 := (minM - r2.(r2e_rule).(r2_need0)) + r2.(r2e_rule).(r2_add0) in
          if negb r2.(r2e_rule).(r2_isKind2) then
            if reachedTC then
              hasMidTC td r2.(r2e_dstMidId) dst &&
              N.eqb (get16 td.(pt_midTbl) r2.(r2e_dstMidId)) r2.(r2e_rule).(r2_mdCode) &&
              N.leb invB (minM1 + st + 12 * ko)
            else
              let dw := get32768 td.(pt_wayTbl) dst in
              checkRule1Chain td r2.(r2e_rule).(r2_bt) r2.(r2e_rule).(r2_mdCode) ko dw.(we_tl) (minM1 + st)
          else
            if reachedTC then
              let tc2 := get16 td.(pt_tcTbl) dst in
              let q2 := (ko - tc2.(tc_minK)) / tc2.(tc_decK) in
              let rem2 := (ko - tc2.(tc_minK)) mod tc2.(tc_decK) in
              let ex2 := get1024 td.(pt_tcExitTbl) (tc2.(tc_exitBase) + rem2) in
              let ew2 := get32768 td.(pt_wayTbl) ex2.(tce_exitWid) in
              let M_fmd := r2.(r2e_rule).(r2_pc) + st + q2 * tc2.(tc_per) + ex2.(tce_steps) in
              checkFmdBoth td M_fmd ex2.(tce_kr) ew2.(we_tl) (minM1 / 2)
            else
              let dw := get32768 td.(pt_wayTbl) dst in
              let M_fmd := r2.(r2e_rule).(r2_pc) + st in
              checkFmdBoth td M_fmd ko dw.(we_tl) (minM1 / 2)
      end) 0 tc.(tc_decK).

Definition checkSmallNK3Range (td : ProofTables) (tcId lo cnt : N) : bool :=
  checkAllN (fun X => if hasSmallNK3 td tcId X then checkSmallNK3One td tcId X else true) lo cnt.

Lemma checkSmallNK3Range_sound {td : ProofTables} {tcId lo cnt : N}
  (h : checkSmallNK3Range td tcId lo cnt = true) :
  forall X : N, lo <= X -> X < lo + cnt -> hasSmallNK3 td tcId X = true -> checkSmallNK3One td tcId X = true.
Proof.
  intros X h1 h2 hMem.
  pose proof (checkAllN_sound h X h1 h2) as hc; cbn beta in hc.
  rewrite hMem in hc; exact hc.
Qed.

Lemma inInv_progress {td : ProofTables} (hV : ValidTables td)
  (hMidG : forall midId tcId : N, hasMidTC td midId tcId = true ->
    forall r : N, r < (get16 td.(pt_tcTbl) tcId).(tc_decK) -> checkMidTCR td midId tcId r = true)
  (hLargeG : checkLargeNK3Graph td = true)
  (hSmallG : forall tcId X : N, hasSmallNK3 td tcId X = true -> checkSmallNK3One td tcId X = true) :
  forall s : StateX, InInv td s -> exists s' : StateX, RPlus s s' /\ InInv td s'.
Proof.
  intros s hs; destruct hs as [midId tcId M K hMem hK hPhi | tcId X M K hMem hK hPhi | tcId X M K hTC14 hX hK hPhi].
  - (* midTC *)
    pose proof hMem as hmt; unfold hasMidTC in hmt; split_andb.
    assert (hmidLt : midId < td.(pt_numMids)) by assumption.
    assert (htcLt : tcId < 6) by assumption.
    set (m := get16 td.(pt_midTbl) midId) in *.
    set (tc := get16 td.(pt_tcTbl) tcId) in *.
    pose proof (hV.(vt_tc) tcId htcLt) as hTC; fold tc in hTC.
    destruct (checkTC_spec hV.(vt_way) hTC) as [_ [hdecPos [_ [hphiSlope _]]]].
    set (q := (K - tc.(tc_minK)) / tc.(tc_decK)).
    set (r := (K - tc.(tc_minK)) mod tc.(tc_decK)).
    destruct (div_mod_decomp (K - tc.(tc_minK)) tc.(tc_decK) hdecPos) as [hqeq hrLt]; fold q r in hqeq, hrLt.
    clearbody q r.
    assert (hKeq : tc.(tc_minK) + q * tc.(tc_decK) + r = K) by fast_lia.
    pose proof (hV.(vt_tcExit) tcId htcLt r hrLt) as hTCEx; fold tc in hTCEx.
    pose proof (tc_drain_and_exit hV.(vt_way) hTC hTCEx (decAB m) M q) as hDrain.
    rewrite hKeq in hDrain; destruct hDrain as [_ [_ hDrainStar]].
    pose proof (hMidG midId tcId hMem r hrLt) as hg3.
    unfold checkMidTCR in hg3; fold m tc in hg3; apply Bool.andb_true_iff in hg3; destruct hg3 as [hcost hR1]; apply N.leb_le in hcost.
    pose proof (hV.(vt_mid) midId hmidLt) as hmidV; fold m in hmidV.
    pose proof (evalABL_decAB m hmidV) as hmAB.
    pose proof (mul_phi_bound q tc.(tc_decK) tc.(tc_per) hphiSlope) as hq12.
    set (ex := get1024 td.(pt_tcExitTbl) (tc.(tc_exitBase) + r)) in *.
    destruct (checkRule1Chain_sound hV hR1 (decAB m) hmAB (M + q * tc.(tc_per) + ex.(tce_steps)) ltac:(fast_lia))
      as [s' [hstep hInv]].
    exists s'; split; [exact (rStar_trans_plus hDrainStar hstep) | exact hInv].
  - (* smallNK3 *)
    assert (hTC14 : tcId = 1 \/ tcId = 4).
    { pose proof hMem as hm; unfold hasSmallNK3 in hm; apply Bool.andb_true_iff in hm; destruct hm as [hm _].
      apply Bool.andb_true_iff in hm; destruct hm as [hm _]; apply Bool.orb_true_iff in hm.
      destruct hm as [ha|hb]; [apply N.eqb_eq in ha; left; exact ha | apply N.eqb_eq in hb; right; exact hb]. }
    assert (htcLt : tcId < 6) by (destruct hTC14; fast_lia).
    set (tc := get16 td.(pt_tcTbl) tcId) in *.
    pose proof (hV.(vt_tc) tcId htcLt) as hTC; fold tc in hTC.
    destruct (checkTC_spec hV.(vt_way) hTC) as [_ [hdecPos [_ [hphiSlope _]]]].
    set (q := (K - tc.(tc_minK)) / tc.(tc_decK)).
    set (r := (K - tc.(tc_minK)) mod tc.(tc_decK)).
    destruct (div_mod_decomp (K - tc.(tc_minK)) tc.(tc_decK) hdecPos) as [hqeq hrLt]; fold q r in hqeq, hrLt.
    clearbody q r.
    assert (hKeq : tc.(tc_minK) + q * tc.(tc_decK) + r = K) by fast_lia.
    pose proof (hSmallG tcId X hMem) as hGs.
    unfold checkSmallNK3One in hGs; apply Bool.andb_true_iff in hGs; destruct hGs as [hbtT hBody].
    apply Bool.eqb_prop in hbtT; fold tc in hbtT, hBody.
    pose proof (hV.(vt_tcExit) tcId htcLt r hrLt) as hTCEx; fold tc in hTCEx.
    pose proof (tc_drain_and_exit hV.(vt_way) hTC hTCEx (nk3MidAB X) M q) as hDrain.
    rewrite hKeq, hbtT in hDrain; destruct hDrain as [_ [_ hDrainStar]].
    set (ex := get1024 td.(pt_tcExitTbl) (tc.(tc_exitBase) + r)) in *.
    set (Mex := M + q * tc.(tc_per) + ex.(tce_steps)) in *.
    pose proof (mul_phi_bound q tc.(tc_decK) tc.(tc_per) hphiSlope) as hq12.
    assert (hMge : invB - 12 * (tc.(tc_minK) + r) + ex.(tce_steps) <= Mex) by (unfold Mex; fast_lia).
    destruct (N.ltb X 18) eqn:hX18.
    + pose proof (checkAllN_sound hBody r (N.le_0_l _) hrLt) as hGr; cbn beta in hGr; fold ex in hGr.
      apply Bool.andb_true_iff in hGr; destruct hGr as [_ hR1].
      destruct (checkRule1Chain_sound hV hR1 (nk3MidAB X) (eq_sym (decBits_mkNK3MidCode X)) Mex hMge)
        as [s' [hstep hInv]].
      exists s'; split; [exact (rStar_trans_plus hDrainStar hstep) | exact hInv].
    + pose proof (checkAllN_sound hBody r (N.le_0_l _) hrLt) as hGr; cbn beta in hGr; fold ex in hGr.
      set (Nv := X / 2) in *.
      set (x2 := N.eqb (X mod 2) 1) in *.
      set (idx := tc.(tc_nk3Base) + (2 * r + if x2 then 1 else 0)) in *.
      set (r2 := get256 td.(pt_nk3ATbl) idx) in *.
      set (minM := (invB - 12 * (tc.(tc_minK) + r)) + ex.(tce_steps)) in *; fold minM in hMge.
      set (K1 := (Nv - r2.(r2e_rule).(r2_need1)) + r2.(r2e_rule).(r2_addK)) in *.
      apply Bool.andb_true_iff in hGr; destruct hGr as [hGrBase hWayRun]; split_andb.
      assert (hidxLt : idx < 100) by assumption.
      assert (ht1Lt : r2.(r2e_t1Wid) < td.(pt_numWays)) by assumption.
      destruct (hV.(vt_nk3A) idx hidxLt) as [c1 [c2 [c3 [c4 [h1s [h2s hchk2]]]]]]; fold r2 in hchk2.
      destruct (check2Blk_sound hV.(vt_suf) hchk2) as [hNotK2AB [hk2Bt hstep2]]; clear c1 c2 c3 c4 h1s h2s hchk2.
      pose proof (div2_decomp X) as hXeq; fold Nv x2 in hXeq.
      pose proof (hstep2 Mex Nv ltac:(fast_lia) ltac:(fast_lia)) as h1; cbn zeta in h1; fold K1 in h1.
      assert (hStart : tailTape (nk3MidAB X) Mex true ex.(tce_kr) (get32768 td.(pt_wayTbl) ex.(tce_exitWid)).(we_tl) =
          (M_L LM_B, true :: bitsC ++ powBitsN (blkBitsL S_P) Mex ++
            (bitsA ++ bitsA ++ bitsB ++ powBitsN (blkBitsL S_Q3) (2 * Nv + if r2.(r2e_rule).(r2_x2) then 1 else 0) ++ bitsARn 4 ++ bitsB) ++
            powBitsN (blkBitsL S_W5) r2.(r2e_rule).(r2_kr) ++ decBits r2.(r2e_rule).(r2_tlCode), [])).
      { replace (r2.(r2e_rule).(r2_x2)) with x2 by congruence.
        replace (r2.(r2e_rule).(r2_kr)) with ex.(tce_kr) by congruence.
        replace (r2.(r2e_rule).(r2_tlCode)) with (get32768 td.(pt_wayTbl) ex.(tce_exitWid)).(we_tl) by congruence.
        rewrite hXeq; unfold tailTape; rewrite evalABL_nk3MidAB; cbn [blkKind]; reflexivity. }
      rewrite <- hStart in h1.
      destruct (wayRunConcreteAux td.(pt_wayTbl) td.(pt_tcTbl) fuel_2048 r2.(r2e_t1Wid) 0 K1)
        as [[[[reachedTC dst] st] ko]|] eqn:hWR; [| discriminate].
      destruct (wayRunConcreteAux_sound hV.(vt_way) ht1Lt hWR) as [_ [hWrT hWrF]].
      set (minM1 := (minM - r2.(r2e_rule).(r2_need0)) + r2.(r2e_rule).(r2_add0)) in *.
      destruct r2.(r2e_rule).(r2_isKind2) eqn:hk2; cbn [negb] in hWayRun.
      * (* isKind2 = true *)
        pose proof (hk2Bt eq_refl) as hr2Bt.
        set (Xa := Mex - r2.(r2e_rule).(r2_need0) + r2.(r2e_rule).(r2_add0)) in *.
        assert (hXage : minM1 <= Xa) by (unfold minM1, Xa; fast_lia).
        assert (hXaDiv : minM1 / 2 <= Xa / 2) by (apply N.Div0.div_le_mono; exact hXage).
        assert (hMidEq : (M_L LM_B, true :: bitsC ++ powBitsN (blkBitsL S_P) r2.(r2e_rule).(r2_pc) ++
            (bitsA ++ bitsA ++ bitsB ++ powBitsN (blkBitsL S_Q3) Xa ++ bitsARn 4 ++ bitsB) ++
            powBitsN (blkBitsL S_W5) K1 ++ decBits r2.(r2e_rule).(r2_t1Code), []) =
            tailTape (nk3MidAB Xa) r2.(r2e_rule).(r2_pc) true K1 r2.(r2e_rule).(r2_t1Code)).
        { unfold tailTape; rewrite evalABL_nk3MidAB; cbn [blkKind]; reflexivity. }
        rewrite hMidEq in h1.
        destruct reachedTC eqn:hrc.
        -- destruct (hWrT eq_refl) as [hdstLt6 [hbt2 [hkoMin hway2]]].
           pose proof (hway2 (nk3MidAB Xa) r2.(r2e_rule).(r2_pc)) as h2.
           rewrite N.sub_0_r in h2.
           replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_bt)) with true in hbt2, h2 by congruence.
           replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_tl)) with r2.(r2e_rule).(r2_t1Code) in h2 by congruence.
           rewrite hbt2 in h2.
           set (tc2 := get16 td.(pt_tcTbl) dst) in *.
           pose proof (hV.(vt_tc) dst hdstLt6) as hTC2; fold tc2 in hTC2.
           destruct (checkTC_spec hV.(vt_way) hTC2) as [_ [hdec2Pos _]].
           set (q2 := (ko - tc2.(tc_minK)) / tc2.(tc_decK)) in *.
           set (rem2 := (ko - tc2.(tc_minK)) mod tc2.(tc_decK)) in *.
           destruct (div_mod_decomp (ko - tc2.(tc_minK)) tc2.(tc_decK) hdec2Pos) as [hq2eq hrem2Lt]; fold q2 rem2 in hq2eq, hrem2Lt.
           clearbody q2 rem2.
           assert (hkoEq : tc2.(tc_minK) + q2 * tc2.(tc_decK) + rem2 = ko) by fast_lia.
           pose proof (hV.(vt_tcExit) dst hdstLt6 rem2 hrem2Lt) as hTCEx2; fold tc2 in hTCEx2.
           pose proof (tc_drain_and_exit hV.(vt_way) hTC2 hTCEx2
             (nk3MidAB Xa) (r2.(r2e_rule).(r2_pc) + st) q2) as hDrain2.
           rewrite hkoEq, hbt2 in hDrain2; destruct hDrain2 as [_ [_ hDrain2Star]].
           destruct (checkFmdBoth_sound hV hWayRun Xa hXaDiv) as [s' [h3 hInv]].
           exists s'; split; [exact (rStar_trans_plus hDrainStar (rPlus_trans (rPlus_trans_star (rPlus_trans_star h1 h2) hDrain2Star) h3)) | exact hInv].
        -- destruct (hWrF eq_refl) as [_ [_ hway2]].
           pose proof (hway2 (nk3MidAB Xa) r2.(r2e_rule).(r2_pc)) as h2.
           rewrite N.sub_0_r in h2.
           replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_bt)) with true in h2 by congruence.
           replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_tl)) with r2.(r2e_rule).(r2_t1Code) in h2 by congruence.
           destruct (checkFmdBoth_sound hV hWayRun Xa hXaDiv) as [s' [h3 hInv]].
           exists s'; split; [exact (rStar_trans_plus hDrainStar (rPlus_trans (rPlus_trans_star h1 h2) h3)) | exact hInv].
      * (* isKind2 = false *)
        set (M1 := Mex - r2.(r2e_rule).(r2_need0) + r2.(r2e_rule).(r2_add0)) in *.
        assert (hM1ge : minM1 <= M1) by (unfold minM1, M1; fast_lia).
        clearbody minM1 M1.
        destruct reachedTC eqn:hrc.
        -- apply Bool.andb_true_iff in hWayRun; destruct hWayRun as [hWayRun1 hphi2].
           apply Bool.andb_true_iff in hWayRun1; destruct hWayRun1 as [hMem2 hmdEq].
           apply N.eqb_eq in hmdEq; apply N.leb_le in hphi2.
           assert (hmidLt : r2.(r2e_dstMidId) < td.(pt_numMids)).
           { pose proof hMem2 as hm; unfold hasMidTC in hm; split_andb; assumption. }
           set (m2 := get16 td.(pt_midTbl) r2.(r2e_dstMidId)) in *.
           assert (hmAB : evalABL (decAB m2) = decBits r2.(r2e_rule).(r2_mdCode))
             by (rewrite (evalABL_decAB m2 (hV.(vt_mid) _ hmidLt)), hmdEq; reflexivity).
           destruct (hWrT eq_refl) as [_ [hbt2 [hkoMin hway2]]].
           pose proof (hway2 (decAB m2) M1) as h2.
           rewrite N.sub_0_r in h2.
           replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_bt)) with r2.(r2e_rule).(r2_bt) in hbt2, h2 by congruence.
           replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_tl)) with r2.(r2e_rule).(r2_t1Code) in h2 by congruence.
           rewrite <- hmAB in h1.
           pose proof (rStar_trans_plus hDrainStar (rPlus_trans_star h1 h2)) as hcomp.
           exists (tailTape (decAB m2) (M1 + st) (get16 td.(pt_tcTbl) dst).(tc_bt) ko
             (get32768 td.(pt_wayTbl) (get16 td.(pt_tcTbl) dst).(tc_ancWid)).(we_tl)).
           split; [exact hcomp | subst m2; exact (InInv_midTC td r2.(r2e_dstMidId) dst (M1 + st) ko hMem2 hkoMin ltac:(fast_lia))].
        -- destruct (hWrF eq_refl) as [_ [_ hway2]].
           destruct (hNotK2AB eq_refl) as [mdAB hmdAB].
           pose proof (hway2 mdAB M1) as h2.
           replace (st - 0) with st in h2 by fast_lia.
           replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_bt)) with r2.(r2e_rule).(r2_bt) in h2 by congruence.
           replace ((get32768 td.(pt_wayTbl) r2.(r2e_t1Wid)).(we_tl)) with r2.(r2e_rule).(r2_t1Code) in h2 by congruence.
           rewrite hmdAB in h1.
           destruct (checkRule1Chain_sound hV hWayRun mdAB (eq_sym hmdAB) (M1 + st) ltac:(fast_lia))
             as [s' [h3 hInv]].
           exists s'; split; [exact (rStar_trans_plus hDrainStar (rPlus_trans (rPlus_trans_star h1 h2) h3)) | exact hInv].
  - (* largeNK3 *)
    assert (htcLt : tcId < 6) by (destruct hTC14; fast_lia).
    set (tc := get16 td.(pt_tcTbl) tcId) in *.
    pose proof (hV.(vt_tc) tcId htcLt) as hTC; fold tc in hTC.
    destruct (checkTC_spec hV.(vt_way) hTC) as [_ [hdecPos [_ [hphiSlope _]]]].
    set (q := (K - tc.(tc_minK)) / tc.(tc_decK)).
    set (r := (K - tc.(tc_minK)) mod tc.(tc_decK)).
    destruct (div_mod_decomp (K - tc.(tc_minK)) tc.(tc_decK) hdecPos) as [hqeq hrLt]; fold q r in hqeq, hrLt.
    clearbody q r.
    assert (hKeq : tc.(tc_minK) + q * tc.(tc_decK) + r = K) by fast_lia.
    unfold checkLargeNK3Graph in hLargeG; apply Bool.andb_true_iff in hLargeG.
    assert (hGtc : checkLargeNK3TC td tcId = true)
      by (destruct hTC14 as [-> | ->]; [exact (proj1 hLargeG) | exact (proj2 hLargeG)]).
    unfold checkLargeNK3TC in hGtc; apply Bool.andb_true_iff in hGtc; destruct hGtc as [hbtT hGrAll].
    apply Bool.eqb_prop in hbtT; fold tc in hbtT, hGrAll.
    pose proof (checkAllN_sound hGrAll r (N.le_0_l _) hrLt) as hGr; cbn beta in hGr.
    set (ex := get1024 td.(pt_tcExitTbl) (tc.(tc_exitBase) + r)) in *.
    set (i0 := tc.(tc_nk3Base) + 2 * r) in *.
    set (i1 := i0 + 1) in *.
    apply Bool.andb_true_iff in hGr; destruct hGr as [hGr hCh1].
    apply Bool.andb_true_iff in hGr; destruct hGr as [hGr hCh0]; split_andb.
    pose proof (hV.(vt_tcExit) tcId htcLt r hrLt) as hTCEx; fold tc ex in hTCEx.
    pose proof (tc_drain_and_exit hV.(vt_way) hTC hTCEx (nk3MidAB X) M q) as hDrain.
    rewrite hKeq, hbtT in hDrain; destruct hDrain as [_ [_ hDrainStar]].
    set (Mex := M + q * tc.(tc_per) + ex.(tce_steps)) in *.
    pose proof (mul_phi_bound q tc.(tc_decK) tc.(tc_per) hphiSlope) as hq12.
    assert (hMge : (invB - 12 * (tc.(tc_minK) + r)) + ex.(tce_steps) <= Mex) by (unfold Mex; fast_lia).
    assert (hNge : xMin / 2 <= X / 2) by (apply N.Div0.div_le_mono; exact hX).
    pose proof (div2_decomp X) as hdiv2.
    assert (hi1Lt : i1 < 100) by assumption.
    assert (hi0Lt : i0 < 100) by (unfold i1 in hi1Lt; fast_lia).
    destruct (N.eqb (X mod 2) 1) eqn:hpar.
    + destruct (checkRule2Chain_sound hV (hV.(vt_nk3A) i1 hi1Lt) hCh1 Mex (X / 2) hMge hNge) as [s' [hstep hInv]].
      replace ((get256 td.(pt_nk3ATbl) i1).(r2e_rule).(r2_x2)) with true in hstep by congruence.
      replace ((get256 td.(pt_nk3ATbl) i1).(r2e_rule).(r2_kr)) with ex.(tce_kr) in hstep by congruence.
      replace ((get256 td.(pt_nk3ATbl) i1).(r2e_rule).(r2_tlCode)) with (get32768 td.(pt_wayTbl) ex.(tce_exitWid)).(we_tl) in hstep by congruence.
      rewrite hdiv2 in hstep.
      exists s'; split; [exact (rStar_trans_plus hDrainStar hstep) | exact hInv].
    + destruct (checkRule2Chain_sound hV (hV.(vt_nk3A) i0 hi0Lt) hCh0 Mex (X / 2) hMge hNge) as [s' [hstep hInv]].
      replace ((get256 td.(pt_nk3ATbl) i0).(r2e_rule).(r2_x2)) with false in hstep by congruence.
      replace ((get256 td.(pt_nk3ATbl) i0).(r2e_rule).(r2_kr)) with ex.(tce_kr) in hstep by congruence.
      replace ((get256 td.(pt_nk3ATbl) i0).(r2e_rule).(r2_tlCode)) with (get32768 td.(pt_wayTbl) ex.(tce_exitWid)).(we_tl) in hstep by congruence.
      rewrite hdiv2 in hstep.
      exists s'; split; [exact (rStar_trans_plus hDrainStar hstep) | exact hInv].
Qed.

Fixpoint stripPCountNat (k : nat) (xs : list LTok) : option (list LTok) :=
  match k with
  | 0%nat => Some xs
  | S k' =>
      match xs with
      | L_A 0 :: L_B :: L_B :: ys => stripPCountNat k' ys
      | _ => None
      end
  end.

Definition stripPCount (k : N) (xs : list LTok) : option (list LTok) :=
  stripPCountNat (N.to_nat k) xs.

Lemma stripPCount_spec {k : N} {xs rest : list LTok} (h : stripPCount k xs = Some rest) :
  evalL 0 0 xs = powBitsN (blkBitsL S_P) k ++ evalL 0 0 rest.
Proof.
  unfold stripPCount, powBitsN in *.
  revert xs rest h; induction (N.to_nat k) as [|m ih]; intros xs rest h.
  - inversion h; subst; reflexivity.
  - destruct xs as [|[| |[|ka]| | | ] x1]; try discriminate.
    destruct x1 as [|[| | | | | ] x2]; try discriminate.
    destruct x2 as [|[| | | | | ] ys]; try discriminate.
    cbn [stripPCountNat] in h.
    cbn [evalL powBits blkBitsL bitsARn bitsA bitsB app]; rewrite (ih _ _ h); reflexivity.
Qed.

Definition checkStageA (td : ProofTables) (midId tcId M135 startWid hWay : N)
  (hints0p segHintsp : list N)
  (r1 : Rule1Blk) (preQ postQ : N) (r1Hintsp : list N)
  (pf : RulePF) (preB postB : N) (pfHintsp : list N) : bool :=
  let hints0 := unpackHintsL hints0p in
  let segHints := unpackHints16L segHintsp in
  let r1Hints := unpackHintsL r1Hintsp in
  let pfHints := unpackHintsL pfHintsp in
  let m := get16 td.(pt_midTbl) midId in
  let tc := get16 td.(pt_tcTbl) tcId in
  let sw := get32768 td.(pt_wayTbl) startWid in
  hasMidTC td midId tcId &&
  N.ltb startWid td.(pt_numWays) &&
  Bool.eqb tc.(tc_bt) false &&
  Bool.eqb sw.(we_bt) false &&
  N.eqb m q3Code &&
  negb (isEmpty segHints) &&
  match symRunLoop false fuel_2048 (symSweepR false fuel_16384 true [] []) with
  | Some (w1, mkAff 0 0, 0) =>
      match runSymSeq td.(pt_sufTbl) false hints0 w1 with
      | Some (L_b1 :: L_C :: body, mkAff 0 0, 0) =>
          match stripPCount M135 body with
          | Some (L_A 1 :: L_B :: L_B :: tailToks) =>
              match encLTok tailToks with
              | Some tl135 =>
                  match checkWaySeg td.(pt_sufTbl) false segHints tl135 0 affId with
                  | Some (tl787, st787, aff787) =>
                      let M787 := M135 + st787 in
                      let Qv := (M787 - r1.(r1_need0)) + r1.(r1_add0) in
                      let Nv := Qv / 2 in
                      let par := N.eqb (Qv mod 2) 1 in
                      let M0 := pf.(rpf_pc) in
                      let K0 := (Nv - pf.(rpf_need0)) + pf.(rpf_addK) in
                      let res := wayHops td.(pt_wayTbl) hWay startWid in
                      let M1 := M0 + snd (fst res) in
                      let K1 := (K0 - (snd res).(aff_need)) + (snd res).(aff_add) in
                      N.eqb aff787.(aff_need) 0 &&
                      N.leb r1.(r1_need0) M787 &&
                      check1Blk td.(pt_sufTbl) r1 preQ postQ r1Hints &&
                      Bool.eqb r1.(r1_bt) false &&
                      N.eqb r1.(r1_midCode) aabbCode &&
                      N.eqb r1.(r1_kr) aff787.(aff_add) &&
                      N.eqb r1.(r1_tlCode) tl787 &&
                      N.leb r1.(r1_need0) M787 &&
                      checkPF td.(pt_sufTbl) pf preB postB pfHints &&
                      N.eqb pf.(rpf_restCode) r1.(r1_outRestCode) &&
                      Bool.eqb pf.(rpf_par) par &&
                      N.leb pf.(rpf_need0) Nv &&
                      Bool.eqb pf.(rpf_bt) false &&
                      N.eqb pf.(rpf_mdCode) q3Code &&
                      N.eqb pf.(rpf_t1Code) sw.(we_tl) &&
                      N.eqb (fst (fst res)) tc.(tc_ancWid) &&
                      N.leb (snd res).(aff_need) K0 &&
                      N.leb tc.(tc_minK) K1 &&
                      N.leb invB (M1 + 12 * K1)
                  | None => false
                  end
              | None => false
              end
          | _ => false
          end
      | _ => false
      end
  | _ => false
  end.

Lemma checkStageA_sound {td : ProofTables} (hV : ValidTables td)
  {midId tcId M135 startWid hWay : N}
  {hints0p segHintsp : list N}
  {r1 : Rule1Blk} {preQ postQ : N} {r1Hintsp : list N}
  {pf : RulePF} {preB postB : N} {pfHintsp : list N}
  (h : checkStageA td midId tcId M135 startWid hWay hints0p segHintsp r1 preQ postQ r1Hintsp pf preB postB pfHintsp = true) :
  exists s0 : StateX, RStar (M_R RM_A, [], []) s0 /\ InInv td s0.
Proof.
  unfold checkStageA in h.
  set (hints0 := unpackHintsL hints0p) in *.
  set (segHints := unpackHints16L segHintsp) in *.
  set (r1Hints := unpackHintsL r1Hintsp) in *.
  set (pfHints := unpackHintsL pfHintsp) in *.
  set (m := get16 td.(pt_midTbl) midId) in *.
  set (tc := get16 td.(pt_tcTbl) tcId) in *.
  set (sw := get32768 td.(pt_wayTbl) startWid) in *.
  apply Bool.andb_true_iff in h; destruct h as [hHdr hMatch].
  apply Bool.andb_true_iff in hHdr; destruct hHdr as [hHdr hsegNe].
  apply Bool.andb_true_iff in hHdr; destruct hHdr as [hHdr hmEq].
  apply Bool.andb_true_iff in hHdr; destruct hHdr as [hHdr hswBt].
  apply Bool.andb_true_iff in hHdr; destruct hHdr as [hHdr htcBt].
  apply Bool.andb_true_iff in hHdr; destruct hHdr as [hMem hswLt].
  apply N.ltb_lt in hswLt; apply Bool.eqb_prop in htcBt; apply Bool.eqb_prop in hswBt; apply N.eqb_eq in hmEq.
  assert (hne : segHints <> []) by (destruct segHints; [discriminate | intro hc; discriminate]).
  destruct (symRunLoop false fuel_2048 (symSweepR false fuel_16384 true [] []))
    as [[[w1 [n0a a0a]] p1a]|] eqn:hinit; [| discriminate].
  destruct n0a; [| discriminate]; destruct a0a; [| discriminate]; destruct p1a; [| discriminate].
  pose proof (symRunLoop_sound (symSweepR_sound false fuel_16384 true [] []) hinit 0 0 (N.le_refl 0) (N.le_refl 0)) as hstep0.
  cbn [aff_need aff_add evalL evalR] in hstep0; replace (0 - 0 + 0) with 0 in hstep0 by lia; replace (0 - 0) with 0 in hstep0 by lia.
  destruct (runSymSeq td.(pt_sufTbl) false hints0 w1) as [[[out1 [n0b a0b]] p1b]|] eqn:hseq; [| discriminate].
  destruct out1 as [|[| | | | | ] out1']; try discriminate.
  destruct out1' as [|[| | | | | ] body]; try discriminate.
  destruct n0b; [| discriminate]; destruct a0b; [| discriminate]; destruct p1b; [| discriminate].
  pose proof (proj1 (runSymSeq_sound hV.(vt_suf) hseq 0 0 (N.le_refl 0) (N.le_refl 0))) as hstep1.
  cbn [aff_need aff_add] in hstep1; replace (0 - 0 + 0) with 0 in hstep1 by lia; replace (0 - 0) with 0 in hstep1 by lia.
  destruct (stripPCount M135 body) as [srem|] eqn:hstripP; [| discriminate].
  destruct srem as [|[| |[|[|]]| | | ] srem1]; try discriminate.
  destruct srem1 as [|[| | | | | ] srem2]; try discriminate.
  destruct srem2 as [|[| | | | | ] tailToks]; try discriminate.
  destruct (encLTok tailToks) as [tl135|] eqn:henc; [| discriminate].
  destruct (checkWaySeg td.(pt_sufTbl) false segHints tl135 0 affId) as [[[tl787 st787] aff787]|] eqn:hseg; [| discriminate].
  set (M787 := M135 + st787) in *.
  set (Qv := (M787 - r1.(r1_need0)) + r1.(r1_add0)) in *.
  set (Nv := Qv / 2) in *.
  set (par := N.eqb (Qv mod 2) 1) in *.
  set (K0 := (Nv - pf.(rpf_need0)) + pf.(rpf_addK)) in *.
  set (res := wayHops td.(pt_wayTbl) hWay startWid) in *.
  set (M1 := pf.(rpf_pc) + snd (fst res)) in *.
  set (K1 := (K0 - (snd res).(aff_need)) + (snd res).(aff_add)) in *.
  (* Extract check1Blk and checkPF hypotheses cleanly before split_andb *)
  repeat match goal with
  | H : andb _ _ = true |- _ => apply Bool.andb_true_iff in H; destruct H
  end.
  split_andb.
  assert (h135Eq : (M_L LM_B, evalL 0 0 (L_b1 :: L_C :: body), []) =
      tailTape [AB_A; AB_A; AB_B; AB_B] M135 false 0 tl135).
  { unfold tailTape; cbn [evalL]; rewrite (stripPCount_spec hstripP).
    cbn [evalL evalABL powBitsN powBits bitsARn bitsA bitsB app]; rewrite (encLTok_sound henc).
    repeat rewrite <- app_assoc; reflexivity. }
  rewrite h135Eq in hstep1.
  pose proof (proj2 (checkWaySeg_sound hV.(vt_suf) hne hseg) [AB_A; AB_A; AB_B; AB_B] M135 0 ltac:(fast_lia)) as hstep2.
  replace (0 - aff787.(aff_need) + aff787.(aff_add)) with aff787.(aff_add) in hstep2 by fast_lia; fold M787 in hstep2.
  match goal with H : check1Blk _ _ _ _ _ = true |- _ => rename H into hr1Chk end.
  match goal with H : checkPF _ _ _ _ _ = true |- _ => rename H into hpfChk end.
  pose proof (check1Blk_sound hV.(vt_suf) hr1Chk M787 ltac:(clearbody M787 Qv Nv K0 M1 K1; fast_lia)) as hstep3; fold Qv in hstep3.
  pose proof (proj2 (checkPF_sound hV.(vt_suf) hpfChk) Nv ltac:(clearbody M787 Qv Nv K0 M1 K1; fast_lia)) as hstep4; fold K0 in hstep4.
  clear hr1Chk hpfChk.
  replace (r1.(r1_midCode)) with aabbCode in hstep3 by congruence.
  replace (r1.(r1_bt)) with false in hstep3 by congruence.
  replace (r1.(r1_kr)) with aff787.(aff_add) in hstep3 by congruence.
  replace (r1.(r1_tlCode)) with tl787 in hstep3 by congruence.
  rewrite decBits_aabbCode in hstep3.
  pose proof (div2_decomp Qv) as hQeq; fold Nv par in hQeq.
  replace (pf.(rpf_par)) with par in hstep4 by congruence.
  rewrite hQeq in hstep4.
  replace (pf.(rpf_restCode)) with r1.(r1_outRestCode) in hstep4 by congruence.
  replace (pf.(rpf_mdCode)) with q3Code in hstep4 by congruence.
  replace (pf.(rpf_bt)) with false in hstep4 by congruence.
  replace (pf.(rpf_t1Code)) with sw.(we_tl) in hstep4 by congruence.
  assert (hmidLt : midId < td.(pt_numMids)) by (pose proof hMem as hm; unfold hasMidTC in hm; split_andb; assumption).
  pose proof (hV.(vt_mid) midId hmidLt) as hmidV; fold m in hmidV.
  assert (hmAB : evalABL (decAB m) = decBits q3Code)
    by (rewrite (evalABL_decAB m hmidV), hmEq; reflexivity).
  rewrite <- hmAB in hstep4.
  destruct (wayHops_sound hV.(vt_way) (h := hWay) hswLt) as [_ [_ hway]]; fold sw res in hway.
  pose proof (hway (decAB m) pf.(rpf_pc) K0 ltac:(clearbody K0; fast_lia)) as hstep5; fold M1 K1 in hstep5.
  clearbody M787 Qv Nv K0 M1 K1.
  rewrite hswBt in hstep5.
  replace (fst (fst res)) with tc.(tc_ancWid) in hstep5 by congruence.
  pose proof (rPlus_to_star (rPlus_trans_star hstep0 hstep1)) as h01.
  pose proof (rPlus_trans (rPlus_trans hstep2 hstep3) hstep4) as h234.
  pose proof (rStar_trans (rPlus_to_star (rStar_trans_plus h01 h234)) hstep5) as hcomp.
  rewrite <- htcBt in hcomp.
  exists (tailTape (decAB m) M1 tc.(tc_bt) K1 (get32768 td.(pt_wayTbl) tc.(tc_ancWid)).(we_tl)).
  split; [exact hcomp | subst m tc; exact (InInv_midTC td midId tcId M1 K1 hMem ltac:(fast_lia) ltac:(fast_lia))].
Qed.

Lemma range_glue {P : N -> Prop} {lo mid hi : N}
  (h1 : forall i : N, lo <= i -> i < mid -> P i)
  (h2 : forall i : N, mid <= i -> i < hi -> P i) :
  forall i : N, lo <= i -> i < hi -> P i.
Proof.
  intros i hlo hhi.
  destruct (N.ltb i mid) eqn:hlt.
  - apply N.ltb_lt in hlt; exact (h1 i hlo hlt).
  - apply N.ltb_ge in hlt; exact (h2 i hlt hhi).
Qed.

Lemma notHalt_of_reach {td : ProofTables} (hV : ValidTables td)
  (hMidG : forall midId tcId : N, hasMidTC td midId tcId = true ->
    forall r : N, r < (get16 td.(pt_tcTbl) tcId).(tc_decK) -> checkMidTCR td midId tcId r = true)
  (hLargeG : checkLargeNK3Graph td = true)
  (hSmallG : forall tcId X : N, hasSmallNK3 td tcId X = true -> checkSmallNK3One td tcId X = true)
  (hReach : exists s0 : StateX, RStar (M_R RM_A, [], []) s0 /\ InInv td s0) :
  ~ halts tm c0.
Proof.
  destruct hReach as [s0 [hR hInv0]].
  rewrite <- encode_init.
  refine (multistep_nonhalt tm _ (encode s0) hR _).
  exact (progress_nonhalt_cond tm StateX s0 encode (InInv td)
    (inInv_progress hV hMidG hLargeG hSmallG) hInv0).
Qed.

