Local Transparent get16 get64 get256 get1024 get4096 get16384 get32768 check1Blk checkPF check2Blk symRunLoop symSweepR symSweepL runSymSeq.

Declare Scope rawbs_scope.
Delimit Scope rawbs_scope with rawbs.
Inductive RawBS : Type := mkRBS (bs : list Byte.byte).
Definition unRBS (r : RawBS) : list Byte.byte := match r with mkRBS bs => bs end.
String Notation RawBS mkRBS unRBS : rawbs_scope.
Inductive STree : Type := STLeaf (s : RawBS) | STNode (l r : STree).

Local Definition shift6Add (acc v : N) : N := N.lor (N.shiftl acc 6) v.
Local Definition shift4Add (acc v : N) : N := N.lor (N.shiftl acc 4) v.
Local Definition clsByte (b : Byte.byte) : nat * N :=
  match b with
  | Byte.x21 => (0%nat, 0)
  | Byte.x23 => (0%nat, 1)
  | Byte.x24 => (0%nat, 2)
  | Byte.x25 => (0%nat, 3)
  | Byte.x26 => (0%nat, 4)
  | Byte.x27 => (0%nat, 5)
  | Byte.x28 => (0%nat, 6)
  | Byte.x29 => (0%nat, 7)
  | Byte.x2a => (0%nat, 8)
  | Byte.x2b => (0%nat, 9)
  | Byte.x2c => (0%nat, 10)
  | Byte.x2d => (0%nat, 11)
  | Byte.x2e => (0%nat, 12)
  | Byte.x30 => (0%nat, 13)
  | Byte.x31 => (0%nat, 14)
  | Byte.x32 => (0%nat, 15)
  | Byte.x33 => (0%nat, 16)
  | Byte.x34 => (0%nat, 17)
  | Byte.x35 => (0%nat, 18)
  | Byte.x36 => (0%nat, 19)
  | Byte.x37 => (0%nat, 20)
  | Byte.x38 => (0%nat, 21)
  | Byte.x39 => (0%nat, 22)
  | Byte.x3a => (0%nat, 23)
  | Byte.x3b => (0%nat, 24)
  | Byte.x3c => (0%nat, 25)
  | Byte.x3d => (0%nat, 26)
  | Byte.x3e => (0%nat, 27)
  | Byte.x3f => (0%nat, 28)
  | Byte.x40 => (0%nat, 29)
  | Byte.x41 => (0%nat, 30)
  | Byte.x42 => (0%nat, 31)
