Local Fixpoint decBytesRec (s : list Byte.byte) (acc : N) (revCur : list N) (revRecs : list (list N)) :
  N * list N * list (list N) :=
  match s with
  | [] => (acc, revCur, revRecs)
  | c :: rest =>
      match clsByte c with
      | (0%nat, v) => decBytesRec rest (shift6Add acc v) revCur revRecs
      | (1%nat, v) => decBytesRec rest 0 (shift4Add acc v :: revCur) revRecs
      | _ => decBytesRec rest 0 [] (List.rev_append revCur [] :: revRecs)
      end
  end.

Local Fixpoint decTreeAux (t : STree) (st : N * list N * list (list N)) : N * list N * list (list N) :=
  match t with
  | STLeaf (mkRBS s) => let '(a, rc, rr) := st in decBytesRec s a rc rr
  | STNode l r => decTreeAux r (decTreeAux l st)
  end.

Local Definition decTreeRecs (t : STree) : list (list N) :=
  let '(_, _, rr) := decTreeAux t (0, [], []) in List.rev_append rr [].

Local Definition bP0 {A} (d : A) (xs : list A) : A * list A := match xs with x :: r => (x, r) | [] => (d, []) end.
Local Definition bP1 {A} (d : A) (xs : list A) : P4 A * list A := let (c0, r0) := bP0 d xs in let (c1, r1) := bP0 d r0 in let (c2, r2) := bP0 d r1 in let (c3, r3) := bP0 d r2 in (P4C c0 c1 c2 c3, r3).
Local Definition bP2 {A} (d : A) (xs : list A) : P16 A * list A := let (c0, r0) := bP1 d xs in let (c1, r1) := bP1 d r0 in let (c2, r2) := bP1 d r1 in let (c3, r3) := bP1 d r2 in (P4C c0 c1 c2 c3, r3).
Local Definition bP3 {A} (d : A) (xs : list A) : P64 A * list A := let (c0, r0) := bP2 d xs in let (c1, r1) := bP2 d r0 in let (c2, r2) := bP2 d r1 in let (c3, r3) := bP2 d r2 in (P4C c0 c1 c2 c3, r3).
Local Definition bP4 {A} (d : A) (xs : list A) : P256 A * list A := let (c0, r0) := bP3 d xs in let (c1, r1) := bP3 d r0 in let (c2, r2) := bP3 d r1 in let (c3, r3) := bP3 d r2 in (P4C c0 c1 c2 c3, r3).
Local Definition bP5 {A} (d : A) (xs : list A) : P1024 A * list A := let (c0, r0) := bP4 d xs in let (c1, r1) := bP4 d r0 in let (c2, r2) := bP4 d r1 in let (c3, r3) := bP4 d r2 in (P4C c0 c1 c2 c3, r3).
Local Definition bP6 {A} (d : A) (xs : list A) : P4096 A * list A := let (c0, r0) := bP5 d xs in let (c1, r1) := bP5 d r0 in let (c2, r2) := bP5 d r1 in let (c3, r3) := bP5 d r2 in (P4C c0 c1 c2 c3, r3).
Local Definition bP7 {A} (d : A) (xs : list A) : P16384 A * list A := let (c0, r0) := bP6 d xs in let (c1, r1) := bP6 d r0 in let (c2, r2) := bP6 d r1 in let (c3, r3) := bP6 d r2 in (P4C c0 c1 c2 c3, r3).
Local Definition buildP32768 {A} (d : A) (xs : list A) : P32768 A := let (h0, r0) := bP7 d xs in let (h1, _) := bP7 d r0 in P2C h0 h1.

Local Definition nzB (x : N) : bool := negb (N.eqb x 0).
Local Fixpoint mkSufB (ns : list N) (acc : SufBucket) : SufBucket :=
  match ns with s :: o :: r => mkSufB r (SBC s o acc) | _ => acc end.
Local Definition defWay : WayEntry := mkWay false 0 false 0 0 0 0 0.
Local Definition decWay (ns : list N) : WayEntry :=
  match ns with [b0; tl; b2; tc; nw; st; nd; ad] => mkWay (nzB b0) tl (nzB b2) tc nw st nd ad | _ => defWay end.
Local Definition defTC : TCEntry := mkTC false 0 0 0 0 0 0 0.
Local Definition decTC (ns : list N) : TCEntry :=
  match ns with [b0; a; ph; pr; dk; mk; eb; nb] => mkTC (nzB b0) a ph pr dk mk eb nb | _ => defTC end.
Local Definition defTCEx : TCExitEntry := mkTCEx 0 0 0 0.
Local Definition decTCEx (ns : list N) : TCExitEntry :=
  match ns with [a; b; c; d] => mkTCEx a b c d | _ => defTCEx end.
Local Definition defR1 : Rule1Blk := mkR1 false 0 0 0 0 0 0.
Local Definition decR1 (ns : list N) : Rule1Blk :=
  match ns with [b0; mc; kr; tc; oc; n0; a0] => mkR1 (nzB b0) mc kr tc oc n0 a0 | _ => defR1 end.
Local Definition defSK : SKEntry := mkSK defR1 0 0.
Local Definition decSK (ns : list N) : SKEntry :=
  match ns with [b0; mc; kr; tc; oc; n0; a0; pe; po] => mkSK (mkR1 (nzB b0) mc kr tc oc n0 a0) pe po | _ => defSK end.
Local Definition defRPF : RulePF := mkRPF 0 false false 0 0 0 0 0.
Local Definition decRPF (ns : list N) : RulePF :=
  match ns with [rc; p; b; mc; pc; n0; ak; t1] => mkRPF rc (nzB p) (nzB b) mc pc n0 ak t1 | _ => defRPF end.
Local Definition defPF : PFEntry := mkPF defRPF 0 0 0 false 0 0.
Local Definition decPF (ns : list N) : PFEntry :=
  match ns with [rc; p; b; mc; pc; n0; ak; t1; w1; wh; dt; ink; nx; dm] => mkPF (mkRPF rc (nzB p) (nzB b) mc pc n0 ak t1) w1 wh dt (nzB ink) nx dm | _ => defPF end.
Local Definition defR2 : Rule2Blk := mkR2 false 0 0 false false 0 0 0 0 0 0 0.
Local Definition defR2E : Rule2Entry := mkR2E defR2 0 0 0 0.
Local Definition decR2E (ns : list N) : Rule2Entry :=
  match ns with [x2; kr; tc; k2; bt; mc; pc; n0; a0; n1; ak; t1; w1; wh; dt; dm] => mkR2E (mkR2 (nzB x2) kr tc (nzB k2) (nzB bt) mc pc n0 a0 n1 ak t1) w1 wh dt dm | _ => defR2E end.
Local Definition decPairW (ns : list N) : N * N * list N :=
  match ns with a :: b :: hp => (a, b, hp) | _ => (0, 0, []) end.
Local Fixpoint decQuadW (rs : list (list N)) : list (N * N * N * N * list N * list N) :=
  match rs with
  | (c1 :: c2 :: c3 :: c4 :: hp1) :: hp2 :: rest => (c1, c2, c3, c4, hp1, hp2) :: decQuadW rest
  | _ => []
  end.

