Local Definition tbl_suf : P32768 SufBucket := buildP32768 SBN (List.map (fun ns => mkSufB ns SBN) (decTreeRecs tree_suf)).
Local Definition tbl_way : P32768 WayEntry := buildP32768 defWay (List.map decWay (decTreeRecs tree_way)).
Local Definition tbl_tc : P16 TCEntry := fst (bP2 defTC (List.map decTC (decTreeRecs tree_tc))).
Local Definition tbl_tcex : P1024 TCExitEntry := fst (bP5 defTCEx (List.map decTCEx (decTreeRecs tree_tcex))).
Local Definition tbl_mid : P16 N := fst (bP2 0 (List.map (fun ns => List.hd 0 ns) (decTreeRecs tree_mid))).
Local Definition tbl_midtc : P256 bool := fst (bP4 false (List.map nzB (List.hd [] (decTreeRecs tree_midtc)))).
Local Definition tbl_snk3 : P4096 bool := fst (bP6 false (List.map nzB (List.hd [] (decTreeRecs tree_snk3)))).
Local Definition tbl_sk : P4096 SKEntry := fst (bP6 defSK (List.map decSK (decTreeRecs tree_sk))).
Local Definition tbl_skidx : P4096 (list N) := fst (bP6 [] (decTreeRecs tree_skidx)).
Local Definition tbl_pf : P16384 PFEntry := fst (bP7 defPF (List.map decPF (decTreeRecs tree_pf))).
Local Definition tbl_fmd : P4096 Rule2Entry := fst (bP6 defR2E (List.map decR2E (decTreeRecs tree_fmd))).
Local Definition tbl_fmdidx : P4096 (list N) := fst (bP6 [] (decTreeRecs tree_fmdidx)).
Local Definition tbl_nk3a : P256 Rule2Entry := fst (bP4 defR2E (List.map decR2E (decTreeRecs tree_nk3a))).

Local Definition proofTables : ProofTables := mkPT 7632 3 3652 6322 1566 tbl_suf tbl_way tbl_tc tbl_tcex tbl_mid tbl_midtc tbl_snk3 tbl_sk tbl_skidx tbl_pf tbl_fmd tbl_fmdidx tbl_nk3a.

Local Definition ws_way : list (list N) := decTreeRecs tree_wh_way.
Local Definition ws_sk : list (N * N * list N) := List.map decPairW (decTreeRecs tree_wh_sk).
Local Definition ws_pf : list (N * N * list N) := List.map decPairW (decTreeRecs tree_wh_pf).
Local Definition ws_fmd : list (N * N * N * N * list N * list N) := decQuadW (decTreeRecs tree_wh_fmd).
Local Definition ws_nk3a : list (N * N * N * N * list N * list N) := decQuadW (decTreeRecs tree_wh_nk3a).
Local Definition sa_recs : list (list N) := decTreeRecs tree_stageA.
Local Definition sa_r1 : Rule1Blk := decR1 (List.nth 0 sa_recs []).
Local Definition sa_pf : RulePF := decRPF (List.nth 1 sa_recs []).
Local Definition sa_h0 : list N := List.nth 2 sa_recs [].
Local Definition sa_seg : list N := List.nth 3 sa_recs [].
Local Definition sa_r1h : list N := List.nth 4 sa_recs [].
Local Definition sa_pfh : list N := List.nth 5 sa_recs [].

Local Definition checkAllWith (td : ProofTables)
  (wWay : list (list N)) (wSK wPF : list (N * N * list N))
  (wFmd wNK3A : list (N * N * N * N * list N * list N))
  (sr1 : Rule1Blk) (spf : RulePF) (sh0 sseg sr1h spfh : list N) : bool :=
  N.eqb (N.of_nat (List.length wWay)) 7632 &&
  N.eqb (N.of_nat (List.length wSK)) 3652 &&
  N.eqb (N.of_nat (List.length wPF)) 6322 &&
  N.eqb (N.of_nat (List.length wFmd)) 1566 &&
  N.eqb (N.of_nat (List.length wNK3A)) 100 &&
  checkAllN (fun i => checkSufBucket (get32768 td.(pt_sufTbl) i)) 0 sufPrime &&
  checkWayList td.(pt_sufTbl) td.(pt_wayTbl) td.(pt_numWays) 0 wWay &&
  checkTCTblAndExits td &&
  checkSKList td.(pt_sufTbl) td.(pt_skTbl) 0 wSK &&
  checkPFList td.(pt_sufTbl) td.(pt_pfTbl) 0 wPF &&
  checkFmdList td.(pt_sufTbl) td.(pt_fmdTbl) 0 wFmd &&
  checkNK3AList td.(pt_sufTbl) td.(pt_nk3ATbl) 0 wNK3A &&
  checkMidTCGraph td &&
  checkLargeNK3Graph td &&
  checkSmallNK3Range td 1 0 xMin &&
  checkSmallNK3Range td 4 0 xMin &&
  checkStageA td 0 0 16 2960 85 sh0 sseg sr1 1 0 sr1h spf 4 0 spfh.

Local Lemma cert_all : checkAllWith proofTables ws_way ws_sk ws_pf ws_fmd ws_nk3a sa_r1 sa_pf sa_h0 sa_seg sa_r1h sa_pfh = true.
Proof. vm_cast_no_check (eq_refl true). Qed.

Local Opaque tbl_suf tbl_way tbl_tc tbl_tcex tbl_mid tbl_midtc tbl_snk3 tbl_sk tbl_skidx tbl_pf tbl_fmd tbl_fmdidx tbl_nk3a ws_way ws_sk ws_pf ws_fmd ws_nk3a sa_r1 sa_pf sa_h0 sa_seg sa_r1h sa_pfh.

Theorem nonhalt : ~ halts tm c0.
Proof.
  pose proof cert_all as hAll; unfold checkAllWith in hAll.
  repeat match goal with H : andb _ _ = true |- _ => apply Bool.andb_true_iff in H; destruct H end.
  repeat match goal with H : N.eqb _ _ = true |- _ => apply N.eqb_eq in H end.
  match goal with H : N.of_nat (length ws_way) = _ |- _ => rename H into hLWay end.
  match goal with H : N.of_nat (length ws_sk) = _ |- _ => rename H into hLSK end.
  match goal with H : N.of_nat (length ws_pf) = _ |- _ => rename H into hLPF end.
  match goal with H : N.of_nat (length ws_fmd) = _ |- _ => rename H into hLFmd end.
  match goal with H : N.of_nat (length ws_nk3a) = _ |- _ => rename H into hLNK3A end.
  match goal with H : checkAllN _ 0 sufPrime = true |- _ =>
    assert (hSuf : ValidSufTbl proofTables.(pt_sufTbl)) by
      (intros i hi; apply (checkAllN_sound H i (N.le_0_l i)); rewrite N.add_0_l; exact hi) end.
  match goal with H : checkWayList _ _ _ 0 ws_way = true |- _ =>
    pose proof (checkWayList_sound hSuf H) as hWay0 end.
  assert (hWay : ValidWayTbl proofTables.(pt_wayTbl) proofTables.(pt_numWays)) by
    (intros wid hw; apply (hWay0 wid (N.le_0_l wid)); rewrite N.add_0_l, hLWay; exact hw).
  match goal with H : checkTCTblAndExits _ = true |- _ =>
    destruct (checkTCTblAndExits_sound H) as [hTC [hTCEx hMid]] end.
  match goal with H : checkSKList _ _ 0 ws_sk = true |- _ =>
    pose proof (checkSKList_sound H) as hSK0 end.
  match goal with H : checkPFList _ _ 0 ws_pf = true |- _ =>
    pose proof (checkPFList_sound H) as hPF0 end.
  match goal with H : checkFmdList _ _ 0 ws_fmd = true |- _ =>
    pose proof (checkFmdList_sound H) as hFmd0 end.
  match goal with H : checkNK3AList _ _ 0 ws_nk3a = true |- _ =>
    pose proof (checkNK3AList_sound H) as hNK3A0 end.
  assert (hVT : ValidTables proofTables).
  { refine (mkVT proofTables hSuf hWay hTC hTCEx hMid _ _ _ _); intros i hi;
      [apply (hSK0 i (N.le_0_l i)); rewrite N.add_0_l, hLSK; exact hi |
       apply (hPF0 i (N.le_0_l i)); rewrite N.add_0_l, hLPF; exact hi |
       apply (hFmd0 i (N.le_0_l i)); rewrite N.add_0_l, hLFmd; exact hi |
       apply (hNK3A0 i (N.le_0_l i)); rewrite N.add_0_l, hLNK3A; exact hi]. }
  match goal with H : checkSmallNK3Range _ 1 0 xMin = true |- _ => rename H into hSnk1 end.
  match goal with H : checkSmallNK3Range _ 4 0 xMin = true |- _ => rename H into hSnk4 end.
  assert (hSmallG : forall tcId X : N, hasSmallNK3 proofTables tcId X = true -> checkSmallNK3One proofTables tcId X = true).
  { intros tcId X hMem; pose proof hMem as hm; unfold hasSmallNK3 in hm.
    apply Bool.andb_true_iff in hm; destruct hm as [hm _].
    apply Bool.andb_true_iff in hm; destruct hm as [htc hxLt]; apply N.ltb_lt in hxLt.
    assert (hxLt0 : X < 0 + xMin) by (rewrite N.add_0_l; exact hxLt).
    apply Bool.orb_true_iff in htc; destruct htc as [h1 | h4];
      [apply N.eqb_eq in h1; subst tcId; exact (checkSmallNK3Range_sound hSnk1 X (N.le_0_l X) hxLt0 hMem) |
       apply N.eqb_eq in h4; subst tcId; exact (checkSmallNK3Range_sound hSnk4 X (N.le_0_l X) hxLt0 hMem)]. }
  match goal with H : checkMidTCGraph _ = true |- _ => rename H into hMidG end.
  match goal with H : checkLargeNK3Graph _ = true |- _ => rename H into hLargeG end.
  match goal with H : checkStageA _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ = true |- _ => rename H into hStgA end.
  exact (notHalt_of_reach hVT (checkMidTCGraph_sound hMidG) hLargeG hSmallG (checkStageA_sound hVT hStgA)).
Qed.
